-- =====================================================================
--  ขั้นที่ 59: ข้อมูลจากฉลากยาสหรัฐฯ (openFDA drug label · ข้อมูลสาธารณะ ภาษาอังกฤษ) ของยา รพ.สต. · รันซ้ำได้ · เพิ่มอย่างเดียว
--   https://open.fda.gov/apis/drug/label/ · หัวข้อ: ข้อบ่งใช้ ขนาดยา ข้อห้ามใช้ คำเตือน อาการไม่พึงประสงค์ ยาตีกัน กลุ่มพิเศษ ยาเกินขนาด การเก็บรักษา (ตัดยาว ≤2,500 ตัวอักษร/หัวข้อ)
--   ไฟล์นี้สร้างด้วย tools/nlem/fda_labels.py (อย่าแก้มือ) · ใครก็อ่านได้ · ผู้ดูแลดึงใหม่/แก้/ลบได้ (ตั้งค่า › ฐานข้อมูลยา)
--   local_drugs.fda_key → drug_fda_labels.key · ใส่ข้อมูลแบบไม่ทับที่ผู้ดูแลแก้แล้ว
-- =====================================================================

create table if not exists public.drug_fda_labels (
  id          int generated always as identity primary key,
  key         text not null unique check (char_length(key) between 1 and 200),   -- <ชื่อสามัญ>|<ช่องทางให้ยา>[|<ชื่อการค้า>]
  generic     text not null,
  route       text not null default '',
  brand       text,
  title       text not null default '',
  set_id      text,                    -- ฉลากเต็มที่ DailyMed
  effective   text,                    -- วันที่ปรับปรุงฉลาก YYYYMMDD
  sections    jsonb not null default '[]' check (jsonb_typeof(sections) = 'array' and octet_length(sections::text) <= 60000),
  fetched_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
alter table public.drug_fda_labels enable row level security;
drop policy if exists dfda_read on public.drug_fda_labels;
drop policy if exists dfda_admin on public.drug_fda_labels;
create policy dfda_read on public.drug_fda_labels for select using (true);
create policy dfda_admin on public.drug_fda_labels for all to authenticated using (public.is_admin()) with check (public.is_admin());
revoke all on public.drug_fda_labels from anon, authenticated;
grant select on public.drug_fda_labels to anon, authenticated;
grant insert, update, delete on public.drug_fda_labels to authenticated;
grant all on public.drug_fda_labels to service_role;

alter table public.local_drugs add column if not exists fda_key text check (fda_key is null or char_length(fda_key) <= 200);

insert into public.drug_fda_labels (key, generic, route, brand, title, set_id, effective, sections)
select x.key, x.generic, x.route, x.brand, x.title, x.set_id, x.effective, x.sections
  from jsonb_to_recordset($fda$[
{"key":"acetaminophen|ORAL","generic":"acetaminophen","route":"ORAL","brand":null,"title":"EXTRA STRENGTH PAIN RELEIF","set_id":"0392db17-c4f3-424b-9dee-549fc5df61c5","effective":"20260129","sections":[{"title":"ข้อบ่งใช้","body":"• temporarily relieves minor aches and pains due to: • the common cold • headache • backache • minor pain of arthritis • toothache • muscular aches • premenstrual and menstrual cramps • temporarily reduces fever"},{"title":"ขนาดยาและวิธีใช้","body":"• do not take more than directed (see overdose warning) adults and children 12 years and over: • take 2 caplets every 6 hours while symptoms last • do not take more than 6 caplets in 24 hours, unless directed by a doctor • do not use for more than 10 days unless directed by a doctor children under 12 years: ask a doctor"},{"title":"ข้อห้ามใช้","body":"• with any other drug containing acetaminophen (prescription or nonprescription). If you are not sure whether a drug contains acetaminophen, ask a doctor or pharmacist. • if you are allergic to acetaminophen or any of the inactive ingredients in this product"},{"title":"คำเตือนและข้อควรระวัง","body":"Liver Warning: This product contains acetaminophen. Severe liver damage may occur if you take • more than 4,000 mg of acetaminophen in 24 hours • with other drugs containing acetaminophen • 3 or more alcoholic drinks every day while using this product Allergy alert: acetaminophen may cause severe skin reactions. Symptoms may include: •skin reddening•blisters•rash If a skin reaction occurs, stop use and seek medical help right away. disease warfarin • pain gets worse or lasts more than 10 days • fever gets worse or lasts more than 3 days • new symptoms occur • redness or swelling is present • These could be signs of a serious condition."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"ask a health professional before use."},{"title":"การได้รับยาเกินขนาด","body":"Overdose Warning In case of overdose, get medical help or contact a Poison Control Center right away. (1-800-222-1222) Quick medical attention is critical for adults as well as for children even if you do not notice any signs or symptoms."},{"title":"การเก็บรักษา","body":"Other information • store between 20-25°C (68-77°F)"}]},
{"key":"albendazole|ORAL","generic":"albendazole","route":"ORAL","brand":null,"title":"Albendazole","set_id":"06b5eefc-0b95-4862-b9b6-770063f2adf0","effective":"20190930","sections":[{"title":"ข้อบ่งใช้","body":"Albendazole is an anthelmintic drug indicated for: Treatment of parenchymal neurocysticercosis due to active lesions caused by larval forms of the pork tapeworm, Taenia solium . ( 1.1 ) Treatment of cystic hydatid disease of the liver, lung, and peritoneum, caused by the larval form of the dog tapeworm, Echinococcus granulosus . ( 1.2 ) 1.1 Neurocysticercosis Albendazole is indicated for the treatment of parenchymal neurocysticercosis due to active lesions caused by larval forms of the pork tapeworm, Taenia solium . 1.2 Hydatid Disease Albendazole is indicated for the treatment of cystic hydatid disease of the liver, lung, and peritoneum, caused by the larval form of the dog tapeworm, Echinococcus granulosus ."},{"title":"ขนาดยาและวิธีใช้","body":"Patients weighing 60 kg or greater, 400 mg twice daily; less than 60 kg, 15 mg/kg/day in divided doses twice daily (maximum total daily dose 800 mg). Albendazole tablets should be taken with food. ( 2 ) Hydatid disease: 28-day cycle followed by 14-day albendazole-free interval for a total of 3 cycles. ( 2 ) Neurocysticercosis: 8 to 30 days. ( 2 ) See additional important information in the Full Prescribing Information. ( 2 ) 2.1 Dosage Dosing of albendazole will vary depending upon the indication. Albendazole tablets may be crushed or chewed and swallowed with a drink of water. Albendazole tablets should be taken with food [see Clinical Pharmacology (12.3) ] . Table 1: Albendazole Dosage Indication Patient Weight Dose Duration Hydatid Disease 60 kg or greater 400 mg twice daily, with meals 28-day cycle followed by a 14-day albendazole-free interval, for a total of 3 cycles Less than 60 kg 15 mg/kg/day given in divided doses twice daily with meals (maximum total daily dose 800 mg) Neurocysticercosis 60 kg or greater 400 mg twice daily, with meals 8 to 30 days Less than 60 kg 15 mg/kg/day given in divided doses twice daily with meals (maximum total daily dose 800 mg) 2.2 Concomitant Medication to Avoid Adverse Reactions Patients being treated for neurocysticercosis should receive appropriate steroid and anticonvulsant therapy as required. Oral or intravenous corticosteroids should be considered to prevent cerebral hypertensive episodes during the first week of treatment [see Warnings and Precautions (5.3) ] . 2.3 Monitoring for Safety Before and During Treatment Monitor blood counts at the beginning of each 28-day cycle of therapy, and every 2 weeks while on therapy with albendazole in all patients [see Warnings and Precautions (5.1) ] . Monitor liver enzymes (transaminases) at the beginning of each 28-day cycle of therapy, and at least every 2 weeks during treatment with albendazole in all patients [see Warnings and Precautions (5.5) ] . Obtain a pregnancy test in women of reproductive potential prior to therapy [see Warnings and Precautions (5.2) ] ."},{"title":"ข้อห้ามใช้","body":"Albendazole is contraindicated in patients with known hypersensitivity to the benzimidazole class of compounds or any components of albendazole. Patients with known hypersensitivity to the benzimidazole class of compounds or any components of albendazole."},{"title":"คำเตือนและข้อควรระวัง","body":"Bone Marrow Suppression: Fatalities have been reported due to bone marrow suppression; monitor blood counts in all patients at the beginning of each 28-day cycle of therapy, and every 2 weeks while on therapy. Discontinue albendazole if clinically significant changes in blood counts occur. ( 5.1 , 5.4 ) Embryo-fetal Toxicity: Obtain pregnancy test in women of reproductive potential prior to therapy and avoid usage in pregnant women except in clinical circumstances where no alternative management is appropriate. Discontinue therapy if pregnancy occurs and apprise patient of potential hazard to the fetus. ( 5.2 ) Risk of Neurologic Symptoms: Neurocysticercosis patients may experience cerebral hypertensive episodes, seizures or focal neurologic deficits after initiation of therapy; begin appropriate steroid and anticonvulsant therapy. ( 5.3 ) Risk of Retinal Damage in Retinal Cysticercosis: Cases of retinal involvement have been reported; examine the patient for the presence of retinal lesions before initiating therapy for neurocysticercosis. ( 5.4 ) Hepatic Effects. Elevations of liver enzymes may occur. Monitor liver enzymes before the start of each treatment cycle and at least every 2 weeks while on albendazole therapy and discontinue if clinically significant elevations occur. ( 5.5 ) 5.1 Bone Marrow Suppression Fatalities associated with the use of albendazole have been reported due to granulocytopenia or pancytopenia. Albendazole may cause bone marrow suppression, aplastic anemia, and agranulocytosis. Monitor blood counts at the beginning of each 28-day cycle of therapy, and every 2 weeks while on therapy with albendazole in all patients. Patients with liver disease and patients with hepatic echinococcosis are at increased risk for bone marrow suppression and warrant more frequent monitoring of blood counts. Discontinue albendazole if clinically significant decreases in blood cell counts occur. 5.2 Embryo-fetal Toxicity Albendazole may cause fetal harm and should not be used in pregnant women except in clinical circumstances where no alternative management is appropriate. Obtain pregnancy test prior to prescribing albendazole to women of reproductive potential. Advise women of reproductive potential to use effective birth control for the duration of albendazole therapy and for one month after end of therapy. …"},{"title":"อาการไม่พึงประสงค์","body":"1% or greater in hydatid disease: abnormal liver function tests, abdominal pain, nausea/vomiting, reversible alopecia, headache, dizziness/vertigo, fever. ( 6.1 ) Adverse reactions 1% or greater in neurocysticercosis: headache, nausea/vomiting, raised intracranial pressure, meningeal signs. ( 6.1 ) To report SUSPECTED ADVERSE REACTIONS, contact Amneal Pharmaceuticals at 1-877-835-5472 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch. 6.1 Clinical Trials Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical trials of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in practice. The adverse reaction profile of albendazole differs between hydatid disease and neurocysticercosis. Adverse reactions occurring with a frequency of 1% or greater in either disease are described in Table 2 below. These symptoms were usually mild and resolved without treatment. Treatment discontinuations were predominantly due to leukopenia (0.7%) or hepatic abnormalities (3.8% in hydatid disease). The following incidence reflects adverse reactions that were reported to be at least possibly or probably related to albendazole. T able 2: Adverse Reaction Incidence 1% or Greater in Hydatid Disease and Neurocysticercosis A dverse Reaction H ydatid Disease N eurocysticercosis G astrointestinal Abdominal Pain 6 0 Nausea 4 6 Vomiting 4 6 G eneral disorders and administration site conditions Fever 1 0 Investigations Elevated Hepatic Enzymes 16 less than 1 N ervous system disorders Dizziness 1 less than 1 Headache 1 11 Meningeal Signs 0 1 Raised Intracranial Pressure 0 2 Vertigo 1 less than 1 Skin and subcutaneous tissue disorders Reversible Alopecia 2 less than 1 The following adverse events were observed at an incidence of less than 1%: Blood and Lymphatic System Disorders: There have been reports of leukopenia, granulocytopenia, pancytopenia, agranulocytosis, or thrombocytopenia [see Warnings and Precautions (5.1) ] . Immune System Disorders: Hypersensitivity reactions, including rash and urticaria. 6.2 Postmarketing Experience The following adverse reactions have been identified during post-approval use of albendazole. Because these reactions are reported voluntarily from a population of uncertain size, it is not always possible to reliably estimate their frequency or establish a causal relationship to drug exposure. …"},{"title":"Drug interaction","body":"Dexamethasone: Steady-state trough concentrations of albendazole sulfoxide were about 56% higher when dexamethasone was coadministered with each dose of albendazole. ( 7.1 ) Praziquantel: In the fed state increased mean maximum plasma concentration and area under the curve of albendazole sulfoxide by about 50% in healthy subjects. ( 7.2 ) Cimetidine: Increased albendazole sulfoxide concentrations in bile and cystic fluid by about 2-fold in hydatid cyst patients. ( 7.3 ) Theophylline: Albendazole induces cytochrome P450 1A in human hepatoma cells; therefore, it is recommended that plasma concentrations of theophylline be monitored during and after treatment. ( 5.5 , 7.4 ) 7.1 Dexamethasone Steady-state trough concentrations of albendazole sulfoxide were about 56% higher when 8 mg dexamethasone was co-administered with each dose of albendazole (15 mg/kg/day) in 8 neurocysticercosis patients. 7.2 Praziquantel In the fed state, praziquantel (40 mg/kg) increased mean maximum plasma concentration and area under the curve of albendazole sulfoxide by about 50% in healthy subjects (n = 10) compared with a separate group of subjects (n = 6) given albendazole alone. Mean T max and mean plasma elimination half-life of albendazole sulfoxide were unchanged. The pharmacokinetics of praziquantel were unchanged following co-administration with albendazole (400 mg). 7.3 Cimetidine Albendazole sulfoxide concentrations in bile and cystic fluid were increased (about 2-fold) in hydatid cyst patients treated with cimetidine (10 mg/kg/day) (n = 7) compared with albendazole (20 mg/kg/day) alone (n = 12). Albendazole sulfoxide plasma concentrations were unchanged 4 hours after dosing. 7.4 Theophylline Following a single dose of albendazole (400 mg), the pharmacokinetics of theophylline (aminophylline 5.8 mg/kg infused over 20 minutes) were unchanged. Albendazole induces cytochrome P450 1A in human hepatoma cells; therefore, it is recommended that plasma concentrations of theophylline be monitored during and after treatment."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary There are limited data on use of albendazole in pregnant women to inform a drug-associated risk of major birth defects and miscarriage. In published studies, single-dose albendazole exposure during pregnancy did not show evidence of an increased risk of adverse maternal or fetal outcomes; however, this finding cannot be extrapolated to multiple-dose exposures ( see Data ). In animal reproductive studies, oral administration of albendazole during gestation caused embryotoxicity and skeletal malformations in pregnant rats (at oral doses of 0.10 times and 0.32 times the recommended human dose based on body surface area in mg/m 2 ) and pregnant rabbits (at oral doses of 0.60 times the recommended human dose based on body surface area in mg/m 2 ). Albendazole was also associated with maternal toxicity in rabbits (at doses of 0.60 times the recommended human dose based on body surface area in mg/m 2 ) ( see Data ). Albendazole should be used during pregnancy only if the potential benefit justifies the potential risk to the fetus. Albendazole should not be used in pregnant women except in clinical circumstances where no alternative management is appropriate. If a patient becomes pregnant while taking this drug, albendazole should be discontinued immediately. If pregnancy occurs while taking this drug, the patient should be apprised of the potential hazard to the fetus. The estimated background risk of major birth defects and miscarriage for the indicated population is unknown. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2 to 4% and 15 to 20%, respectively. Data Human Data A Cochrane review could not provide sufficient evidence of the impact of antihelminthics (including albendazole) on the pregnancy outcomes of low birthweight, perinatal mortality and preterm birth. In a large trial of about 2507 women, albendazole use during the second or third trimester of pregnancy had no overall effect on birth weight, perinatal mortality, or congenital anomalies. With a limited sample size and single-does exposure, another study could not rule out a two-fold increased risk of major malformations [4.7% vs. 2.2%; OR 2.2 (95% confidence interval (CI) 0.5 to 10.1); p = 0.26]. Animal Data Albendazole has been shown to be teratogenic (to cause embryotoxicity and skeletal malformations) in pregnant rats and rabbits. …"},{"title":"การได้รับยาเกินขนาด","body":"In case of overdosage, symptomatic therapy and general supportive measures are recommended."},{"title":"การเก็บรักษา","body":"16.2 Storage and Handling Store at 20° to 25°C (68° to 77°F) [See USP Controlled Room Temperature]."}]},
{"key":"albuterol sulfate|ORAL","generic":"albuterol sulfate","route":"ORAL","brand":null,"title":"albuterol sulfate","set_id":"87b8cd3c-2849-4b50-b63e-9ea379165c07","effective":"20260316","sections":[{"title":"ข้อบ่งใช้","body":"Albuterol tablets are indicated for the relief of bronchospasm in adults and children 6 years of age and older with reversible obstructive airway disease."},{"title":"ขนาดยาและวิธีใช้","body":"The following dosages of albuterol tablets are expressed in terms of albuterol base. Usual Dosage Adults and Children Over 12 Years of Age The usual starting dosage for adults and children 12 years and older is 2 or 4 mg three or four times a day. Children 6 to 12 Years of Age The usual starting dosage for children 6 to 12 years of age is 2 mg three or four times a day. Dosage Adjustment Adults and Children Over 12 Years of Age For adults and children 12 years and older, a dosage above 4 mg four times a day should be used only when the patient fails to respond. If a favorable response does not occur with the 4 mg initial dosage, it should be cautiously increased stepwise up to a maximum of 8 mg four times a day as tolerated. Children 6 to 12 Years of Age Who Fail to Respond to the Initial Starting Dosage of 2 mg Four Times a Day For children from 6 to 12 years of age who fail to respond to the initial starting dosage of 2 mg four times a day, the dosage may be cautiously increased stepwise, but not to exceed 24 mg/day (given in divided doses). Elderly Patients and Those Sensitive to Beta-adrenergic Stimulators An initial dosage of 2 mg three or four times a day is recommended for elderly patients and for those with a history of unusual sensitivity to beta-adrenergic stimulators. If adequate bronchodilation is not obtained, dosage may be increased gradually to as much as 8 mg three or four times a day. The total daily dose should not exceed 32 mg in adults and children 12 years and older."},{"title":"ข้อห้ามใช้","body":"Albuterol tablets are contraindicated in patients with a history of hypersensitivity to albuterol, or any of its components."},{"title":"คำเตือนและข้อควรระวัง","body":"Paradoxical Bronchospasm Albuterol tablets can produce paradoxical bronchospasm, which may be life threatening. If paradoxical bronchospasm occurs, albuterol tablets should be discontinued immediately and alternative therapy instituted. Cardiovascular Effects Albuterol tablets, like all other beta-adrenergic agonists, can produce a clinically significant cardiovascular effect in some patients as measured by pulse rate, blood pressure, and/or symptoms. Although such effects are uncommon after administration of albuterol tablets at recommended doses, if they occur, the drug may need to be discontinued. In addition, beta-agonists have been reported to produce electrocardiogram (ECG) changes, such as flattening of the T wave, prolongation of the QTc interval, and ST segment depression. The clinical significance of these findings is unknown. Therefore, albuterol tablets, like all sympathomimetic amines, should be used with caution in patients with cardiovascular disorders, especially coronary insufficiency, cardiac arrhythmias, and hypertension. Deterioration of Asthma Asthma may deteriorate acutely over a period of hours or chronically over several days or longer. If the patient needs more doses of albuterol tablets than usual, this may be a marker of destabilization of asthma and requires reevaluation of the patient and treatment regimen, giving special consideration to the possible need for anti-inflammatory treatment, e.g., corticosteroids. Use of Anti-Inflammatory Agents The use of beta-adrenergic agonist bronchodilators alone may not be adequate to control asthma in many patients. Early consideration should be given to adding anti-inflammatory agents, e.g., corticosteroids. Immediate Hypersensitivity Reactions Immediate hypersensitivity reactions may occur after administration of albuterol, as demonstrated by rare cases of urticaria, angioedema, rash, bronchospasm, and oropharyngeal edema. Albuterol, like other beta-adrenergic agonists, can produce a significant cardiovascular effect in some patients, as measured by pulse rate, blood pressure, symptoms, and/or electrocardiographic changes. Rarely, erythema multiforme and Stevens-Johnson syndrome have been associated with the administration of oral albuterol sulfate in children. …"},{"title":"อาการไม่พึงประสงค์","body":"In clinical trials, the most frequent adverse reactions to albuterol tablets were: Percent Incidence of Adverse Reactions Reaction Percent Incidence Central nervous system Nervous 20% Tremor 20% Headache 7% Sleeplessness 2% Weakness 2% Dizziness 2% Drowsiness <1% Restlessness <1% Irritability <1% Cardiovascular Tachycardia 5% Palpitations 5% Chest discomfort <1% Flushing <1% Musculoskeletal Muscle cramps 3% Gastrointestinal Nausea 2% Genitourinary Difficulty in micturition <1% Rare cases of urticaria, angioedema, rash, bronchospasm, and oropharyngeal edema have been reported after the use of albuterol. In addition, albuterol, like other sympathomimetic agents, can cause adverse reactions such as hypertension, angina, vomiting, vertigo, central nervous system stimulation, unusual taste, and drying or irritation of the oropharynx. The reactions are generally transient in nature, and it is usually not necessary to discontinue treatment with albuterol tablets. In selected cases, however, dosage may be reduced temporarily; after the reaction has subsided, dosage should be increased in small increments to the optimal dosage."},{"title":"Drug interaction","body":"The concomitant use of albuterol tablets and other oral sympathomimetic agents is not recommended since such combined use may lead to deleterious cardiovascular effects. This recommendation does not preclude the judicious use of an aerosol bronchodilator of the adrenergic stimulant type in patients receiving albuterol tablets. Such concomitant use, however, should be individualized and not given on a routine basis. If regular coadministration is required, then alternative therapy should be considered. Monoamine Oxidase Inhibitors or Tricyclic Antidepressants Albuterol should be administered with extreme caution to patients being treated with monoamine oxidase inhibitors or tricyclic antidepressants, or within 2 weeks of discontinuation of such agents, because the action of albuterol on the vascular system may be potentiated. Beta-Blockers Beta-adrenergic receptor blocking agents not only block the pulmonary effect of beta-agonists, such as albuterol tablets, but may produce severe bronchospasm in asthmatic patients. Therefore, patients with asthma should not normally be treated with beta-blockers. However, under certain circumstances, e.g., as prophylaxis after myocardial infarction, there may be no acceptable alternatives to the use of beta-adrenergic blocking agents in patients with asthma. In this setting, cardioselective beta-blockers could be considered, although they should be administered with caution. Diuretics The ECG changes and/or hypokalemia that may result from the administration of nonpotassium-sparing diuretics (such as loop or thiazide diuretics) can be acutely worsened by beta-agonists, especially when the recommended dose of the beta-agonist is exceeded. Although the clinical significance of these effects is not known, caution is advised in the coadministration of beta-agonists with nonpotassium-sparing diuretics. Digoxin Mean decreases of 16% to 22% in serum digoxin levels were demonstrated after single-dose intravenous and oral administration of albuterol, respectively, to normal volunteers who had received digoxin for 10 days. The clinical significance of these findings for patients with obstructive airway disease who are receiving albuterol and digoxin on a chronic basis is unclear. Nevertheless, it would be prudent to carefully evaluate the serum digoxin levels in patients who are currently receiving digoxin and albuterol."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Teratogenic Effects. Pregnancy Category C Albuterol has been shown to be teratogenic in mice. A study in CD-1 mice at subcutaneous (sc) doses of 0.025, 0.25, and 2.5 mg/kg, (approximately 3/1000, 3/100, and 3/10 times, respectively, the maximum recommended daily oral dose for adults on a mg/m 2 basis), showed cleft palate formation in 5 of 111 (4.5%) fetuses at 0.25 mg/kg and in 10 of 108 (9.3%) fetuses at 2.5 mg/kg. The drug did not induce cleft palate formation at the lowest dose, 0.025 mg/kg. Cleft palate also occurred in 22 of 72 (30.5%) fetuses from females treated with 2.5 mg/kg of isoproterenol (positive control) subcutaneously (approximately 3/10 times the maximum recommended daily oral dose for adults on a mg/m 2 basis). A reproduction study in Stride Dutch rabbits revealed cranioschisis in 7 of 19 (37%) fetuses when albuterol was administered orally at a 50 mg/kg dose (approximately 25 times the maximum recommended daily oral dose for adults on a mg/m 2 basis). There are no adequate and well-controlled studies in pregnant women. Albuterol should be used during pregnancy only if the potential benefit justifies the potential risk to the fetus. During worldwide marketing experience, various congenital anomalies, including cleft palate and limb defects, have been rarely reported in the offspring of patients being treated with albuterol. Some of the mothers were taking multiple medications during their pregnancies. No consistent pattern of defects can be discerned, and a relationship between albuterol use and congenital anomalies has not been established. It is not known whether this drug is excreted in human milk. Because of the potential for tumorigenicity shown for albuterol in animal studies, a decision should be made whether to discontinue nursing or to discontinue the drug, taking into account the importance of the drug to the mother. Safety and effectiveness in children below 6 years of age have not been established."},{"title":"การได้รับยาเกินขนาด","body":"The expected symptoms with overdosage are those of excessive beta-adrenergic stimulation and/or occurrence or exaggeration of any of the symptoms listed under ADVERSE REACTIONS , e.g., seizures, angina, hypertension or hypotension, tachycardia with rates up to 200 beats/min, arrhythmias, nervousness, headache, tremor, dry mouth, palpitation, nausea, dizziness, fatigue, malaise, and sleeplessness. Hypokalemia may also occur. As with all sympathomimetic medications, cardiac arrest and even death may be associated with abuse of albuterol tablets. Treatment consists of discontinuation of albuterol tablets together with appropriate symptomatic therapy. The judicious use of a cardioselective beta-receptor blocker may be considered, bearing in mind that such medication can produce bronchospasm. There is insufficient evidence to determine if dialysis is beneficial for overdosage of albuterol tablets. The oral median lethal dose of albuterol sulfate in mice is greater than 2000 mg/kg (approximately 250 times the maximum recommended daily oral dose for adults on a mg/m 2 basis, or, approximately 200 times the maximum recommended daily oral dose for children on a mg/m 2 basis). In mature rats, the subcutaneous (sc) median lethal dose of albuterol sulfate is approximately 450 mg/kg (approximately 110 times the maximum recommended daily oral dose for adults on a mg/m 2 basis or, approximately 90 times the maximum recommended daily oral dose for children on a mg/m 2 basis). In small young rats, the subcutaneous median lethal dose is approximately 2000 mg/kg (approximately 500 times the maximum recommended daily oral dose for adults on a mg/m 2 basis, or, approximately 400 times the maximum recommended daily oral dose for children on a mg/m 2 basis)."},{"title":"การเก็บรักษา","body":"Store at 20° to 25°C (68° to 77°F). [See USP Controlled Room Temperature] DISPENSE IN TIGHT, LIGHT-RESISTANT CONTAINER."}]},
{"key":"albuterol sulfate|RESPIRATORY (INHALATION)","generic":"albuterol sulfate","route":"RESPIRATORY (INHALATION)","brand":null,"title":"Albuterol Sulfate","set_id":"285a656c-f77f-4e77-b0a8-a0e9c901803f","effective":"20260406","sections":[{"title":"ข้อบ่งใช้","body":"Albuterol inhalation solution is indicated for the relief of bronchospasm in patients 2 to 12 years of age with asthma (reversible obstructive airway disease)."},{"title":"ขนาดยาและวิธีใช้","body":"The usual starting dosage for patients 2 to 12 years of age is 1.25 mg (0.042%) or 0.63 mg (0.021%) of albuterol inhalation solution administered 3 or 4 times daily, as needed, by nebulization. More frequent administration is not recommended. To administer 1.25 mg or 0.63 mg of albuterol, use the entire contents of one unit-dose vial (3 mL of 0.042% [1.25 mg] or 3 mL of 0.021% [0.63 mg] inhalation solution) by nebulization. Adjust nebulizer flow rate to deliver albuterol inhalation solution over 5 to 15 minutes. The use of albuterol inhalation solution can be continued as medically indicated to control recurring bouts of bronchospasm. During this time most patients gain optimum benefit from regular use of the inhalation solution. Patients 6 to 12 years of age with more severe asthma (baseline FEV 1 less than 60% predicted), weight > 40 kg, or patients 11 to 12 years of age may achieve a better initial response with the 1.25 mg dose. Albuterol inhalation solution has not been studied in the setting of acute attacks of bronchospasm. A 2.5 mg dose of albuterol provided by a higher concentration product (2.5 mg albuterol per 3 mL) may be more appropriate for treating acute exacerbations, particularly in children 6 years old and above. If a previously effective dosage regimen fails to provide the usual relief, medical advice should be sought immediately, as this is often a sign of seriously worsening asthma which would require reassessment of therapy. The drug compatibility (physical and chemical), clinical efficacy and safety of albuterol inhalation solution, when mixed with other drugs in a nebulizer have not been established. The safety and efficacy of albuterol inhalation solution have been established in clinical trials when administered using the Pari LC Plus™ nebulizer and Pari PRONEB™ compressor. The safety and efficacy of albuterol inhalation solution when administered with other nebulizer systems have not been established. Albuterol inhalation solution should be administered via jet nebulizer connected to an air compressor with adequate air flow, equipped with a mouthpiece or suitable face mask."},{"title":"ข้อห้ามใช้","body":"Albuterol inhalation solution is contraindicated in patients with a history of hypersensitivity to any of its components."},{"title":"คำเตือนและข้อควรระวัง","body":"PARADOXICAL BRONCHOSPASM As with other inhaled beta-adrenergic agonists, albuterol inhalation solution can produce paradoxical bronchospasm, which may be life-threatening. If paradoxical bronchospasm occurs, albuterol inhalation solution should be discontinued immediately and alternative therapy instituted. It should be noted that paradoxical bronchospasm, when associated with inhaled formulations, frequently occurs with the first use of a new canister or vial. USE OF ANTI-INFLAMMATORY AGENTS The use of beta-adrenergic bronchodilators alone may not be adequate to control asthma in many patients. Early consideration should be given to adding anti-inflammatory agents (e.g., corticosteroids). DETERIORATION OF ASTHMA Asthma may deteriorate acutely over a period of hours or chronically over several days or longer. If the patient needs more doses of albuterol inhalation solution than usual, this may be a marker of destabilization of asthma and requires reevaluation of the patient and the treatment regimen, giving special consideration of the possible need for anti-inflammatory treatment (e.g., corticosteroids). Fatalities have been reported in association with excessive use of inhaled sympathomimetic drugs and with the home use of nebulizers. It is, therefore, essential that the physician instruct the patient in the need for further evaluation, if his/her asthma becomes worse. CARDIOVASCULAR EFFECTS Albuterol inhalation solution, like other beta-adrenergic agonists, can produce a clinically significant cardiovascular effect in some patients as measured by pulse rate, blood pressure, and/or symptoms. Although such effects are uncommon for albuterol inhalation solution at recommended doses, if they occur, the drug may need to be discontinued. In addition, beta-agonists have been reported to produce ECG changes, such as flattening of the T-wave, prolongation of the QTc interval, and ST segment depression. The clinical significance of these findings is unknown. Therefore, albuterol inhalation solution, like all other sympathomimetic amines, should be used with caution in patients with cardiovascular disorders, especially coronary insufficiency, cardiac arrhythmias, and hypertension. IMMEDIATE HYPERSENSITIVITY REACTIONS Immediate hypersensitivity reactions may occur after administration of albuterol as demonstrated by rare cases of urticaria, angioedema, rash, bronchospasm, and oropharyngeal edema. …"},{"title":"อาการไม่พึงประสงค์","body":"Clinical Trial Experience: Adverse events reported in >1% of patients receiving albuterol sulfate and more frequently than in patients receiving placebo in a four-week double-blind study are listed in the following table. Table 1: Adverse Events with an Incidence of >1% of Patients Receiving Albuterol Inhalation Solution and Greater than Placebo (expressed as % of treatment group) 1.25 mg (0.042%) Albuterol Inhalation Solution (n = 115) 0.63 mg (0.021%) Albuterol Inhalation Solution (n = 117) Placebo (n = 117) Asthma Exacerbation 13 11.1 8.5 Otitis Media 4.3 0.9 0 Allergic Reaction 0.9 3.4 1.7 Gastroenteritis 0.9 3.4 0.9 Cold Symptoms 0 3.4 1.7 Flu Syndrome 2.6 2.6 1.7 Lymphadenopathy 2.6 0.9 1.7 Skin/Appendage Infection 1.7 0 0 Urticaria 1.7 0.9 0 Migraine 0.9 1.7 0 Chest Pain 0.9 1.7 0 Bronchitis 0.9 1.7 0.9 Nausea 1.7 0.9 0.9 There was one case of ST segment depression in the 1.25 mg (0.042%) albuterol inhalation solution treatment group. No clinically relevant laboratory abnormalities related to albuterol inhalation solution administration were seen in this study. Postmarketing Experience: Metabolic acidosis has been reported after the use of albuterol inhalation solution. Because this reaction is reported voluntarily from a population of uncertain size, it is not always possible to reliably estimate its frequency or establish a causal relationship to drug exposure."},{"title":"Drug interaction","body":"Other short-acting sympathomimetic aerosol bronchodilators or epinephrine should not be used concomitantly with albuterol inhalation solution. Albuterol inhalation solution should be administered with extreme caution to patients being treated with monoamine oxidase inhibitors or tricyclic antidepressants or within 2 weeks of discontinuation of such agents, since the action of albuterol on the vascular system may be potentiated. Beta-receptor blocking agents not only block the pulmonary effect of beta-agonists, such as albuterol inhalation solution, but may produce severe bronchospasm in asthmatic patients. Therefore, patients with asthma should not normally be treated with beta-blockers. However, under certain circumstances (e.g., prophylaxis after myocardial infarction), there may be no acceptable alternatives to the use of beta-adrenergic blocking agents in patients with asthma. In this setting, cardioselective beta-blockers should be considered, although they should be administered with caution. The ECG changes and/or hypokalemia that may result from the administration of non-potassium sparing diuretics (such as loop or thiazide diuretics) can be acutely worsened by beta-agonists, especially when the dose of the beta-agonist is exceeded. Although the clinical significance of these effects is unknown, caution is advised in the co-administration of beta-agonists with non-potassium sparing diuretics. Mean decreases of 16% to 22% in serum digoxin levels were demonstrated after single dose intravenous and oral administration of albuterol, respectively, to normal volunteers who had received digoxin for 10 days. The clinical significance of these findings for patients with obstructive airway disease who are receiving albuterol and digoxin on a chronic basis is unclear. Nevertheless, it would be prudent to carefully evaluate the serum digoxin levels in patients who are currently receiving digoxin and albuterol."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Teratogenic Effects Pregnancy Category C Albuterol has been shown to be teratogenic in mice. A study in CD-1 mice given albuterol subcutaneously showed cleft palate formation in 5 of 111 (4.5%) fetuses at 0.25 mg/kg (less than the maximum recommended daily inhalation dose of albuterol sulfate on a mg/m 2 basis) and cleft palate formation in 10 of 108 (9.3%) fetuses at 2.5 mg/kg (approximately equal to the maximum recommended daily inhalation dose of albuterol sulfate on a mg/m 2 basis). The drug did not induce cleft palate formation when administered subcutaneously at a dose of 0.025 mg/kg (less than the maximum recommended daily inhalation dose of albuterol sulfate on a mg/m 2 basis). Cleft palate formation also occurred in 23 of 72 (30.5%) fetuses from females treated subcutaneously with 2.5 mg/kg isoproterenol (positive control). A reproduction study in Stride rabbits revealed cranioschisis in 7 of 19 (37%) fetuses when albuterol sulfate was administered orally at 50 mg/kg (approximately 60 times the maximum recommended daily inhalation dose of albuterol sulfate on a mg/m 2 basis). A study in which pregnant rats were dosed with radiolabelled albuterol sulfate demonstrated that drug-related material was transferred from the maternal circulation to the fetus. There are no adequate and well-controlled studies of the use of albuterol sulfate in pregnant women. Albuterol should be used during pregnancy only if the potential benefit justifies the potential risk to the fetus. During worldwide marketing experience, various congenital anomalies, including cleft palate and limb defects, have been reported in the offspring of patients being treated with albuterol. Some of the mothers were taking multiple medications during their pregnancies. Because no consistent pattern of defects can be discerned, a relationship between albuterol use and congenital anomalies has not been established. It is not known whether this drug is excreted in human milk. Because of the potential for tumorigenicity shown for albuterol in some animal studies, a decision should be made whether to discontinue nursing or to discontinue the drug, taking into account the importance of the drug to the mother. Safety and effectiveness of albuterol inhalation solution 1.25 mg (0.042%) and 0.63 mg (0.021%) have been established in pediatric patients between the ages of 2 and 12 years. …"},{"title":"การได้รับยาเกินขนาด","body":"The expected symptoms with overdosage are those of excessive beta-adrenergic stimulation and/or occurrence or exaggeration of symptoms such as seizures, angina, hypertension or hypotension, tachycardia with rates up to 200 beats per minute, arrhythmias, nervousness, headache, tremor, dry mouth, palpitation, nausea, dizziness, fatigue, malaise, insomnia, and exaggeration of the pharmacological effects listed in ADVERSE REACTIONS . Hypokalemia may also occur. As with all sympathomimetic aerosol medications, cardiac arrest and even death may be associated with abuse of albuterol inhalation solution. Treatment consists of discontinuation of albuterol inhalation solution together with appropriate symptomatic therapy. The judicious use of a cardioselective beta-receptor blocker may be considered, bearing in mind that such medication can produce bronchospasm. There is insufficient evidence to determine if dialysis is beneficial for overdosage of albuterol inhalation solution. The oral median lethal dose of albuterol in mice is greater than 2000 mg/kg (approximately 580 times the maximum recommended daily inhalation dose of albuterol on a mg/m 2 basis). The subcutaneous median lethal dose of albuterol in mature rats and small young rats is approximately 450 mg/kg and 2000 mg/kg, respectively (approximately 260 and 1200 times the maximum recommended daily inhalation dose of albuterol on a mg/m 2 basis). The inhalation median lethal dose has not been determined in animals."},{"title":"การเก็บรักษา","body":"Store between 20°C to 25°C (68°F to 77°F), excursions permitted to 15°C to 30°C (59°F to 86°F) [see USP Controlled Room Temperature]. Protect from light and excessive heat. Store unit-dose vials in protective foil pouch at all times. Once removed from the foil pouch, use vial within one week. Discard the vial if the solution is not colorless. Keep out of the reach of children. Rx Only Manufactured By: Nephron Pharmaceuticals Corporation West Columbia, SC 29172 STORING YOUR MEDICINE Store albuterol inhalation solution between 20°C to 25°C (68°F to 77°F) [ See USP Controlled Room Temperature]. Vials should be protected from light before use, therefore keep unused vials in the foil pouch. Once removed use within one week. Discard the vial if the solution is not colorless. Keep out of reach of children. Do not use after the expiration date printed on the vial."}]},
{"key":"allopurinol|ORAL","generic":"allopurinol","route":"ORAL","brand":null,"title":"Allopurinol","set_id":"005048dd-844f-468c-bf56-1a09727e3477","effective":"20240708","sections":[{"title":"ข้อบ่งใช้","body":"Allopurinol tablets are indicated for: The management of adults with signs and symptoms of primary or secondary gout (acute attacks, tophi, joint destruction, uric acid lithiasis, and/or nephropathy) The management of adult and pediatric patients with leukemia, lymphoma and solid tumor malignancies who are receiving cancer therapy which causes elevations of serum and urinary uric acid levels The management of adult patients with recurrent calcium oxalate calculi whose daily uric acid excretion exceeds 800 mg/day in male patients and 750 mg/day in female patients, despite lifestyle changes (such as reduction of dietary sodium, non-dairy animal protein, oxylate rich foods, refined sugars and increases in oral fluids and fruits and vegetables) Limitations of Use Allopurinol tablets are not recommended for the treatment of asymptomatic hyperuricemia. Allopurinol tablets are a xanthine oxidase inhibitor indicated for the management of: Adult patients with signs and symptoms of primary or secondary gout (acute attacks, tophi, joint destruction, uric acid lithiasis, and/or nephropathy) ( 1 ) Adult and pediatric patients with leukemia, lymphoma and solid tumor malignancies who are receiving cancer therapy which causes elevations of serum and urinary uric acid levels ( 1 ) Adult patients with recurrent calcium oxalate calculi whose daily uric acid excretion exceeds 800 mg/day in male patients and 750 mg/day in female patients, despite lifestyle changes ( 1 ) Limitations of Use Allopurinol tablets are not recommended for the treatment of asymptomatic hyperuricemia. ( 1 )"},{"title":"ขนาดยาและวิธีใช้","body":"Gout : Prior to initiating treatment assess serum uric acid level, complete blood count, chemistry panel, liver and kidney function tests. Prophylactic treatment for gout flares is recommended. ( 2.1 , 2.2 ) Patients with normal kidney function: Initial dosage is 100 mg orally daily. Increase by 100 mg weekly increments until serum uric acid of 6 mg/dl or less is reached (maximum 800 mg daily). ( 2.3 ) Patients with impaired kidney function: The initial dosage is 50 mg orally daily. Follow recommendations for titration in patients with renal impairment until target serum uric acid level is reached. ( 2.6 ) See complete information in the Full Prescribing Information (FPI). Hyperuricemia Associated with Cancer Therapy : The recommended dosage is: Adults: 300 mg to 800 mg orally daily. Pediatric patients: 100 mg/m 2 orally every 8 hours to 12 hours (10 mg/kg/day, maximum 800 mg/day) See complete information in the FPI. ( 2.4 , 2.6 ) Recurrent Calcium Oxalate Calculi : The recommended initial dosage in patients with normal kidney function is 200 mg to 300 mg orally daily. ( 2.5 ) Dosage in Patients with Renal Impairment: See FPI for dosage modifications in patients with renal impairment. ( 2.6 ) 2.1 Recommended Testing Prior to Treatment Initiation Prior to initiating treatment with allopurinol tablets in patients with gout, assess the following baseline tests: serum uric acid level, complete blood count, chemistry panel, liver function tests (serum alanine aminotransferase [ALT], aspartate aminotransferase [AST], alkaline phosphatase, and total bilirubin), kidney function tests (serum creatinine and eGFR). 2.2 Recommended Prophylaxis for Gout Flares Gout flares may occur after initiation of allopurinol tablets due to changing serum uric acid levels resulting in mobilization of urate from tissue deposits. Flare prophylaxis with colchicine or an anti- inflammatory agent according to practice guidelines is recommended upon initiation of allopurinol tablets. While adjusting the dosage of allopurinol tablets in patients who are being treated with colchicine and/or anti-inflammatory agents, continue flare prophylaxis drugs until serum uric acid has been normalized and the patient has been free of gout flares for several months. If a gout flare occurs during allopurinol tablets treatment, allopurinol tablets need not be discontinued. Manage the gout flare concurrently, as appropriate for the individual patient [see Warnings and Precautions ( 5.2 )]. …"},{"title":"ข้อห้ามใช้","body":"Allopurinol tablets are contraindicated in patients with a history of hypersensitivity reaction to allopurinol or to any of the ingredients of allopurinol tablets. Known hypersensitivity to allopurinol or to any of the ingredients of allopurinol tablets."},{"title":"คำเตือนกรอบดำ","body":"BOXED WARNING"},{"title":"คำเตือนและข้อควรระวัง","body":"Skin Rash and Hypersensitivity: Allopurinol has been associated with serious and sometimes fatal dermatological reactions. Discontinue allopurinol tablets at the first appearance of skin rash or other signs of hypersensitivity reaction. ( 5.1 ) Gout Flares: May occur during initiation of treatment. Concurrent prophylactic treatment with colchicine or anti-inflammatory agents is recommended. ( 5.2 ) Nephrotoxicity: Allopurinol may affect kidney function. Patients with decreased kidney function require lower doses of allopurinol tablets. ( 5.3 ) Hepatoxicity: Cases of reversible hepatotoxicity have occurred. If signs and symptoms of hepatotoxicity develop, evaluate liver function. ( 5.4 ) Myelosuppression: Bone marrow suppression has been reported with allopurinol. ( 5.5 ) Potential Effect on Driving and Use of Machinery: Drowsiness, somnolence and dizziness have been reported in patients taking allopurinol tablets. ( 5.6 ) 5.1 Skin Rash and Hypersensitivity Serious and sometimes fatal dermatologic reactions, including toxic epidermal necrolysis (TEN), Stevens-Johnson syndrome (SJS), and drug reaction with eosinophilia and systemic symptoms (DRESS) have been reported in patients taking allopurinol [see Adverse Reactions ( 6 )] . These reactions occur in approximately 5 in 10,000 (0.05%) patients taking allopurinol. Other serious hypersensitivity reactions that have been reported include exfoliative, urticarial and purpuric lesions, generalized vasculitis, and irreversible hepatotoxicity. Discontinue allopurinol tablets permanently at the first appearance of skin rash or other signs which may indicate a hypersensitivity reaction. The HLA-B*58:01 allele is a genetic marker for severe skin reactions indicative of hypersensitivity to allopurinol. Patients who carry the HLA-B*58:01 allele are at a higher risk of allopurinol hypersensitivity syndrome (AHS), but hypersensitivity reactions have been reported in patients who do not carry this allele. The frequency of this allele is higher in individuals of African, Asian (e.g., Han Chinese, Korean, Thai), and Native Hawaiian/Pacific Islander ancestry [see Clinical Pharmacology ( 12.5 )] . The use of allopurinol tablets is not recommended in HLA- B*58:01 positive patients unless the benefits clearly outweigh the risks. Consider screening for HLA-B*5801 before starting treatment with allopurinol tablets in patients from populations in which the prevalence of this HLA-B*5801 allele is known to be high. …"},{"title":"อาการไม่พึงประสงค์","body":"The following clinically significant adverse reactions are described elsewhere in the labeling: Skin Rash and Hypersensitivity [see Warnings and Precautions ( 5.1 )] Nephrotoxicity [see Warnings and Precautions ( 5.3 )] Hepatoxicity [see Warnings and Precautions ( 5.4 )] Myelosuppression [see Warnings and Precautions ( 5.5 )] Potential Effect on Driving and Use of Machinery [see Warnings and Precautions ( 5.6 )] The following adverse reactions associated with the use of allopurinol tablets were identified in literature, unpublished clinical trials or postmarketing reports. Because some of these reactions were reported voluntarily from a population of uncertain size, it is not always possible to reliably estimate their frequency or establish a causal relationship to drug exposure. The most frequent adverse reaction to allopurinol tablets is skin rash. Most Common Adverse Reactions (≥ 1%) Gastrointestinal : Diarrhea, nausea, alkaline phosphatase increase, AST/ALT increase. Metabolic and Nutritional : Acute attacks of gout. Skin and Appendages : Rash, maculopapular rash. Less Common Adverse Reactions (< 1%) Body As a Whole : Ecchymosis, fever, headache, malaise. Cardiovascular : Necrotizing angiitis, vasculitis, pericarditis, peripheral vascular disease, thrombophlebitis, bradycardia, vasodilation. Gastrointestinal : Hepatic necrosis, granulomatous hepatitis, hepatomegaly, hyperbilirubinemia, cholestatic jaundice, vomiting, intermittent abdominal pain, gastritis, dyspepsia, hemorrhagic pancreatitis, gastrointestinal bleeding, stomatitis, salivary gland swelling, hyperlipidemia, tongue edema, anorexia. Hemic and Lymphatic: Thrombocytopenia, eosinophilia, leukocytosis, leukopenia, aplastic anemia, agranulocytosis, eosinophilic fibrohistiocytic lesion of bone marrow, pancytopenia, prothrombin decrease, anemia, hemolytic anemia, reticulocytosis, lymphadenopathy, lymphocytosis. Musculoskeletal: Myopathy, arthralgias, myalgia. Nervous: Peripheral neuropathy, neuritis, paresthesia, somnolence, optic neuritis, confusion, dizziness, vertigo, foot drop, decrease in libido, depression, amnesia, tinnitus, asthenia, insomnia. Respiratory: Epistaxis, bronchospasm, asthma, pharyngitis, rhinitis. …"},{"title":"Drug interaction","body":"The following drugs may increase the risk of serious skin reactions: bendamustine, thiazide diuretics, ampicillin and amoxicillin. ( 7.1 ) Capecitabine: Avoid concomitant use. ( 7.2 ) Mercaptopurine or Azathioprine: Reduce mercaptopurine or azathioprine dose as recommended in the respective prescribing information. ( 7.2 ) Pegloticase: Discontinue and refrain from initiating treatment with allopurinol tablets. ( 7.2 ) See FPI for complete list of significant drug interactions. ( 7.2 ) 7.1 Drugs Known to Affect the Occurrence of Skin Rash and Hypersensitivity Concomitant use of the following drugs may increase the risk of skin rash, which may be severe: bendamustine, thiazide diuretics, ampicillin and amoxicillin. Renal impairment may further increase risk with concomitant use of thiazide diuretics [see Warnings and Precautions ( 5.1 , 5.2 ) and Clinical Pharmacology ( 12.2 )] . Monitor kidney function and reduce the dose of allopurinol tablets in patients with concomitant thiazide diuretic use and impaired renal function [see Dosage and Administration ( 2.6 ), Warnings and Precautions ( 5.1 )]. Discontinue allopurinol tablets at the first appearance of skin rash or other signs which may indicate a hypersensitivity reaction when use concomitantly with these drugs [see Warnings and Precautions ( 5.1 )] . 7.2 Drugs Known to Have Clinically Important Drug Interactions with Allopurinol Tablets Table 3: Interventions for Clinically Important Drug Interactions with Allopurinol Tablets Capecitabine Clinical Impact Concomitant use with allopurinol may decrease concentration of capecitabine’s active metabolites, which may decrease capecitabine efficacy. Intervention Avoid the use of allopurinol tablets during treatment with capecitabine. Chlorpropamide Clinical Impact Allopurinol tablets prolong the half-life of chlorpropamide as both compete for renal tubular excretion. In patients with renal insufficiency, the risk of hypoglycemia may be increased due to this mechanism. Intervention Monitor patients with renal insufficiency for hypoglycemia when administering chlorpropamide and allopurinol tablets concomitantly. Cyclosporine Clinical Impact Concomitant use of allopurinol increases cyclosporine concentrations, which may increase the risk of adverse reactions. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Based on findings in animals, allopurinol tablets may cause fetal harm when administered to a pregnant woman. Adverse developmental outcomes have been described in exposed animals (see Data). Allopurinol and its metabolite oxypurinol have been shown to cross the placenta following administration of maternal allopurinol. Available limited published data on allopurinol use in pregnant women do not demonstrate a clear pattern or increase in frequency of adverse developmental outcomes. Among approximately 50 pregnancies described in published literature, 2 infants with major congenital malformations have been reported with following maternal allopurinol exposure. Advise pregnant women of the potential risk to a fetus. All pregnancies have a background risk of birth defect, loss, or other adverse outcomes. The background risk of major birth defects and miscarriage for the indicated population is unknown. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2% to 4% and 15% to 20%, respectively. Data Human Data Experience with allopurinol tablets during human pregnancy has been limited partly because women of reproductive age rarely require treatment with allopurinol tablets. A case report published in 2011 described the outcome of a full-term pregnancy in a 35-year-old woman who had recurrent kidney stones since age 18 who took allopurinol throughout the pregnancy. The child had multiple complex birth defects and died at 8 days of life. A second report in 2013 provided data on 31 prospectively ascertained pregnancies involving mothers exposed to allopurinol for varying durations during the first trimester. The overall rate of major fetal malformations and spontaneous abortions was reported to be within the normal expected range; however, one child had severe malformations similar to those described in the cited earlier case report. Animal Data There was no evidence of fetotoxicity or teratogenicity in rats or rabbits treated during the period of organogenesis with oral allopurinol at doses up to 200 mg/kg/day and up to 100 mg/kg/day, respectively (about 2.4 times the human dose on a mg/m 2 basis). …"},{"title":"การได้รับยาเกินขนาด","body":"In the management of overdosage there is no specific antidote for allopurinol tablets. Both allopurinol tablets and oxipurinol are dialyzable; however, the usefulness of hemodialysis or peritoneal dialysis in the management of an overdose of allopurinol tablets is unknown."}]},
{"key":"amitriptyline hydrochloride|ORAL","generic":"amitriptyline hydrochloride","route":"ORAL","brand":null,"title":"Amitriptyline Hydrochloride","set_id":"35aa7ab3-321a-97f7-e063-6294a90a91e2","effective":"20260630","sections":[{"title":"ข้อบ่งใช้","body":"For the relief of symptoms of depression. Endogenous depression is more likely to be alleviated than are other depressive states."},{"title":"ขนาดยาและวิธีใช้","body":"Oral Dosage Dosage should be initiated at a low level and increased gradually, noting carefully the clinical response and any evidence of intolerance. Initial Dosage for Adults For outpatients, 75 mg of amitriptyline hydrochloride a day in divided doses is usually satisfactory. If necessary, this may be increased to a total of 150 mg per day. Increases are made preferably in the late afternoon and/or bedtime doses. A sedative effect may be apparent before the antidepressant effect is noted, but an adequate therapeutic effect may take as long as 30 days to develop. An alternate method of initiating therapy in outpatients is to begin with 50 mg to 100 mg amitriptyline hydrochloride at bedtime. This may be increased by 25 or 50 mg as necessary in the bedtime dose to a total of 150 mg per day. Hospitalized patients may require 100 mg a day initially. This can be increased gradually to 200 mg a day if necessary. A small number of hospitalized patients may need as much as 300 mg a day. Adolescent and Elderly Patients In general, lower dosages are recommended for these patients. Ten mg 3 times a day with 20 mg at bedtime may be satisfactory in adolescent and elderly patients who do not tolerate higher dosages. Maintenance The usual maintenance dosage of amitriptyline hydrochloride is 50 to 100 mg per day. In some patients, 40 mg per day is sufficient. For maintenance therapy, the total daily dosage may be given in a single dose, preferably at bedtime. When satisfactory improvement has been reached, dosage should be reduced to the lowest amount that will maintain relief of symptoms. It is appropriate to continue maintenance therapy 3 months or longer to lessen the possibility of relapse. Usage in Pediatric Patients In view of the lack of experience with the use of this drug in pediatric patients, it is not recommended at the present time for patients under 12 years of age. Plasma Levels Because of the wide variation in the absorption and distribution of tricyclic antidepressants in body fluids, it is difficult to directly correlate plasma levels and therapeutic effect. However, determination of plasma levels may be useful in identifying patients who appear to have toxic effects and may have excessively high levels, or those in whom lack of absorption or noncompliance is suspected. …"},{"title":"ข้อห้ามใช้","body":"Amitriptyline hydrochloride is contraindicated in patients who have shown prior hypersensitivity to it. It should not be given concomitantly with monoamine oxidase inhibitors. Hyperpyretic crises, severe convulsions, and deaths have occurred in patients receiving tricyclic antidepressant and monoamine oxidase inhibiting drugs simultaneously. When it is desired to replace a monoamine oxidase inhibitor with amitriptyline hydrochloride, a minimum of 14 days should be allowed to elapse after the former is discontinued. Amitriptyline hydrochloride should then be initiated cautiously with gradual increase in dosage until optimum response is achieved. Amitriptyline hydrochloride should not be given with cisapride due to the potential for increased QT interval and increased risk for arrhythmia. This drug is not recommended for use during the acute recovery phase following myocardial infarction."},{"title":"คำเตือนกรอบดำ","body":"Suicidality and Antidepressant Drugs Antidepressants increased the risk compared to placebo of suicidal thinking and behavior (suicidality) in children, adolescents and young adults in short-term studies of major depressive disorder (MDD) and other psychiatric disorders. Anyone considering the use of amitriptyline hydrochloride tablets or any other antidepressant in a child, adolescent, or young adult must balance this risk with the clinical need. Short-term studies did not show an increase in the risk of suicidality with antidepressants compared to placebo in adults beyond age 24; there was a reduction in risk with antidepressants compared to placebo in adults aged 65 and older. Depression and certain other psychiatric disorders are themselves associated with increases in the risk of suicide. Patients of all ages who are started on antidepressant therapy should be monitored appropriately and observed closely for clinical worsening, suicidality, or unusual changes in behavior. Families and caregivers should be advised of the need for close observation and communication with the prescriber. Amitriptyline hydrochloride tablets are not approved for use in pediatric patients [see WARNINGS: Clinical Worsening and Suicide Risk , PRECAUTIONS: Information for Patients and PRECAUTIONS: Pediatric Use ]."},{"title":"คำเตือนและข้อควรระวัง","body":"Clinical Worsening and Suicide Risk Patients with major depressive disorder (MDD), both adult and pediatric, may experience worsening of their depression and/or the emergence of suicidal ideation and behavior (suicidality) or unusual changes in behavior, whether or not they are taking antidepressant medications, and this risk may persist until significant remission occurs. Suicide is a known risk of depression and certain other psychiatric disorders, and these disorders themselves are the strongest predictors of suicide. There has been a long-standing concern, however, that antidepressants may have a role in inducing worsening of depression and the emergence of suicidality in certain patients during the early phases of treatment. Pooled analyses of short-term placebo-controlled trials of antidepressant drugs (SSRIs and others) showed that these drugs increase the risk of suicidal thinking and behavior (suicidality) in children, adolescents, and young adults (ages 18 to 24) with major depressive disorder (MDD) and other psychiatric disorders. Short-term studies did not show an increase in the risk of suicidality with antidepressants compared to placebo in adults beyond age 24; there was a reduction with antidepressants compared to placebo in adults aged 65 and older. The pooled analyses of placebo-controlled trials in children and adolescents with MDD, obsessive compulsive disorder (OCD), or other psychiatric disorders included a total of 24 short-term trials of 9 antidepressant drugs in over 4,400 patients. The pooled analyses of placebo-controlled trials in adults with MDD or other psychiatric disorders included a total of 295 short-term trials (median duration of 2 months) of 11 antidepressant drugs in over 77,000 patients. There was considerable variation in risk of suicidality among drugs, but a tendency toward an increase in the younger patients for almost all drugs studied. There were differences in absolute risk of suicidality across the different indications, with the highest incidence in MDD. The risk differences (drug vs. placebo), however, were relatively stable within age strata and across indications. These risk differences (drug-placebo difference in the number of cases of suicidality per 1,000 patients treated) are provided in Table 1. …"},{"title":"อาการไม่พึงประสงค์","body":"Within each category the following adverse reactions are listed in order of decreasing severity. Included in the listing are a few adverse reactions which have not been reported with this specific drug. However, pharmacological similarities among the tricyclic antidepressant drugs require that each of the reactions be considered when amitriptyline is administered. Cardiovascular: Myocardial infarction; stroke; non-specific ECG changes and changes in AV conduction; heart block; arrhythmias; hypotension, particularly orthostatic hypotension; syncope; hypertension; tachycardia; palpitation. CNS and Neuromuscular: Coma; seizures; hallucinations; delusions; confusional states; disorientation; incoordination; ataxia; tremors; peripheral neuropathy; numbness, tingling and paresthesias of the extremities; extrapyramidal symptoms including abnormal involuntary movements and tardive dyskinesia; dysarthria; disturbed concentration; excitement; anxiety; insomnia; restlessness; nightmares; drowsiness; dizziness; weakness; fatigue; headache; syndrome of inappropriate ADH (antidiuretic hormone) secretion; tinnitus; alteration in EEG patterns. Anticholinergic: Paralytic ileus, hyperpyrexia; urinary retention, dilatation of the urinary tract; constipation; blurred vision, disturbance of accommodation, increased ocular pressure, mydriasis; dry mouth. Allergic: Skin rash; urticaria; photosensitization; edema of face and tongue. Hematologic: Bone marrow depression including agranulocytosis, leukopenia, thrombocytopenia; purpura; eosinophilia. Gastrointestinal: Rarely hepatitis (including altered liver function and jaundice); nausea; epigastric distress; vomiting; anorexia; stomatitis; peculiar taste; diarrhea; parotid swelling; black tongue. Endocrine: Testicular swelling and gynecomastia in the male; breast enlargement and galactorrhea in the female; increased or decreased libido; impotence; elevation and lowering of blood sugar levels. Other: Alopecia; edema; weight gain or loss; urinary frequency; increased perspiration. Withdrawal Symptoms After prolonged administration, abrupt cessation of treatment may produce nausea, headache, and malaise. Gradual dosage reduction has been reported to produce, within two weeks, transient symptoms including irritability, restlessness, and dream and sleep disturbance. These symptoms are not indicative of addiction. …"},{"title":"Drug interaction","body":"Topiramate Some patients may experience a large increase in amitriptyline concentration in the presence of topiramate and any adjustments in amitriptyline dose should be made according to the patient's clinical response and not on the basis of plasma levels. Drugs Metabolized by P450 2D6 The biochemical activity of the drug metabolizing isozyme cytochrome P450 2D6 (debrisoquin hydroxylase) is reduced in a subset of the Caucasian population (about 7% to 10% of Caucasians are so called \"poor metabolizers\"); reliable estimates of the prevalence of reduced P450 2D6 isozyme activity among Asian, African and other populations are not yet available. Poor metabolizers have higher than expected plasma concentrations of tricyclic antidepressants (TCAs) when given usual doses. Depending on the fraction of drug metabolized by P450 2D6, the increase in plasma concentration may be small, or quite large (8-fold increase in plasma AUC of the TCA). In addition, certain drugs inhibit the activity of this isozyme and make normal metabolizers resemble poor metabolizers. An individual who is stable on a given dose of TCA may become abruptly toxic when given one of these inhibiting drugs as concomitant therapy. The drugs that inhibit cytochrome P450 2D6 include some that are not metabolized by the enzyme (quinidine; cimetidine) and many that are substrates for P450 2D6 (many other antidepressants, phenothiazines, and the Type 1C antiarrhythmics propafenone and flecainide). While all the selective serotonin reuptake inhibitors (SSRIs), e.g., fluoxetine, sertraline, and paroxetine, inhibit P450 2D6, they may vary in the extent of inhibition. The extent to which SSRI-TCA interactions may pose clinical problems will depend on the degree of inhibition and the pharmacokinetics of the SSRI involved. Nevertheless, caution is indicated in the coadministration of TCAs with any of the SSRIs and also in switching from one class to the other. Of particular importance, sufficient time must elapse before initiating TCA treatment in a patient being withdrawn from fluoxetine, given the long half-life of the parent and active metabolite (at least 5 weeks may be necessary). Concomitant use of tricyclic antidepressants with drugs that can inhibit cytochrome P450 2D6 may require lower doses than usually prescribed for either the tricyclic antidepressant or the other drug. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Usage in Pregnancy Teratogenic effects were not observed in mice, rats, or rabbits when amitriptyline was given orally at doses of 2 to 40 mg/kg/day (up to 13 times the maximum recommended human dose Based on a maximum recommended amitriptyline dose of 150 mg/day or 3 mg/kg/day for a 50 kg patient. ). Studies in the literature have shown amitriptyline to be teratogenic in mice and hamsters when given by various routes of administration at doses of 28 to 100 mg/kg/day (9 to 33 times the maximum recommended human dose), producing multiple malformations. Another study in the rat reported that an oral dose of 25 mg/kg/day (8 times the maximum recommended human dose) produced delays in ossification of fetal vertebral bodies without other signs of embryotoxicity. In rabbits, an oral dose of 60 mg/kg/day (20 times the maximum recommended human dose) was reported to cause incomplete ossification of cranial bones. Amitriptyline has been shown to cross the placenta. Although a causal relationship has not been established, there have been a few reports of adverse events, including CNS effects, limb deformities, or developmental delay, in infants whose mothers had taken amitriptyline during pregnancy. There are no adequate and well-controlled studies in pregnant women. Amitriptyline hydrochloride should be used during pregnancy only if the potential benefit to the mother justifies the potential risk to the fetus. Amitriptyline is excreted into breast milk. In one report in which a patient received amitriptyline 100 mg/day while nursing her infant, levels of 83 to 141 ng/mL were detected in mother's serum. Levels of 135 to 151 ng/mL were found in the breast milk, but no trace of the drug could be detected in the infant's serum. Because of the potential for serious adverse reactions in nursing infants from amitriptyline, a decision should be made whether to discontinue nursing or to discontinue the drug, taking into account the importance of the drug to the mother. Safety and effectiveness in the pediatric population have not been established [see BOX WARNING and WARNINGS: Clinical Worsening and Suicide Risk ]. Anyone considering the use of amitriptyline in a child or adolescent must balance the potential risks with the clinical need. Clinical experience has not identified differences in responses between elderly and younger patients. …"},{"title":"การได้รับยาเกินขนาด","body":"Deaths may occur from overdosage with this class of drugs. Multiple drug ingestion (including alcohol) is common in deliberate tricyclic antidepressant overdose. As the management is complex and changing, it is recommended that the physician contact a poison control center for current information on treatment. Signs and symptoms of toxicity develop rapidly after tricyclic antidepressant overdose; therefore, hospital monitoring is required as soon as possible. Manifestations Critical manifestations of overdose include: cardiac dysrhythmias, severe hypotension, convulsions, and CNS depression, including coma. Changes in the electrocardiogram particularly in QRS axis or width, are clinically significant indicators of tricyclic antidepressant toxicity. In addition, a rightward axis shift in the terminal QRS complex together with a prolonged QT interval and sinus tachycardia are specific and sensitive indicators of first-generation tricyclic overdose. The absence of these findings is not exclusionary. Prolonged PR interval, ST-T wave changes, ventricular tachycardia and fibrillation may also occur. Other signs of overdose may include: impaired myocardial contractility, confusion, disturbed concentration, transient visual hallucinations, dilated pupils, disorders of ocular motility, agitation, hyperactive reflexes polyradiculoneuropathy, stupor, drowsiness, muscle rigidity, vomiting, hypothermia, hyperpyrexia, or any of the symptoms listed under ADVERSE REACTIONS. Management General Obtain an ECG and immediately initiate cardiac monitoring. Protect the patient's airway, establish an intravenous line and initiate gastric decontamination. A minimum of six hours of observation with cardiac monitoring and observation for signs of CNS or respiratory depression, hypotension, cardiac dysrhythmias and/or conduction blocks, and seizures is necessary. If signs of toxicity occur at any time during the period, extended monitoring is required. There are case reports of patients succumbing to fatal dysrhythmias late after overdose; these patients had clinical evidence of significant poisoning prior to death and most received inadequate gastrointestinal decontamination. Monitoring of plasma drug levels should not guide management of the patient. Gastrointestinal Decontamination All patients suspected of tricyclic antidepressant overdose should receive gastrointestinal decontamination. This should include, large volume gastric lavage followed by activated charcoal. …"},{"title":"การเก็บรักษา","body":"Store amitriptyline hydrochloride tablets in a well-closed container. Store at 20° to 25°C (68° to 77°F) [see USP Controlled Room Temperature]. Protect from light. Dispense in a tight, light-resistant container as defined in the USP using a child-resistant closure."}]},
{"key":"amlodipine besylate|ORAL","generic":"amlodipine besylate","route":"ORAL","brand":null,"title":"Amlodipine Besylate","set_id":"003dd1ec-16f8-4f96-b6a8-c4689d35892a","effective":"20260420","sections":[{"title":"ข้อบ่งใช้","body":"Amlodipine besylate tablets are calcium channel blocker and may be used alone or in combination with other antihypertensive and antianginal agents for the treatment of: •Hypertension ( 1.1 ) о Amlodipine besylate tablets are indicated for the treatment of hypertension, to lower blood pressure. Lowering blood pressure reduces the risk of fatal and nonfatal cardiovascular events, primarily strokes and myocardial infarctions. •Coronary Artery Disease ( 1.2 ) о Chronic Stable Angina о Vasospastic Angina (Prinzmetal's or Variant Angina) о Angiographically Documented Coronary Artery Disease in patients without heart failure or an ejection fraction < 40% 1.1 Hypertension Amlodipine besylate tablets are indicated for the treatment of hypertension, to lower blood pressure. Lowering blood pressure reduces the risk of fatal and nonfatal cardiovascular events, primarily strokes and myocardial infarctions. These benefits have been seen in controlled trials of antihypertensive drugs from a wide variety of pharmacologic classes including amlodipine besylate. Control of high blood pressure should be part of comprehensive cardiovascular risk management, including, as appropriate, lipid control, diabetes management, antithrombotic therapy, smoking cessation, exercise, and limited sodium intake. Many patients will require more than one drug to achieve blood pressure goals. For specific advice on goals and management, see published guidelines, such as those of the National High Blood Pressure Education Program's Joint National Committee on Prevention, Detection, Evaluation, and Treatment of High Blood Pressure (JNC). Numerous antihypertensive drugs, from a variety of pharmacologic classes and with different mechanisms of action, have been shown in randomized controlled trials to reduce cardiovascular morbidity and mortality, and it can be concluded that it is blood pressure reduction, and not some other pharmacologic property of the drugs, that is largely responsible for those benefits. The largest and most consistent cardiovascular outcome benefit has been a reduction in the risk of stroke, but reductions in myocardial infarction and cardiovascular mortality also have been seen regularly. Elevated systolic or diastolic pressure causes increased cardiovascular risk, and the absolute risk increase per mmHg is greater at higher blood pressures, so that even modest reductions of severe hypertension can provide substantial benefit. …"},{"title":"ขนาดยาและวิธีใช้","body":"•Adult recommended starting dose: 5 mg once daily with maximum dose 10 mg once daily. ( 2.1 ) о Small, fragile, or elderly patients, or patients with hepatic insufficiency may be started on 2.5 mg once daily. ( 2.1 ) •Pediatric starting dose: 2.5 mg to 5 mg once daily. ( 2.2 ) Important Limitation : Doses in excess of 5 mg daily have not been studied in pediatric patients. ( 2.2 ) 2.1 Adults The usual initial antihypertensive oral dose of amlodipine besylate tablet is 5 mg once daily and the maximum dose is 10 mg once daily. Small, fragile, or elderly patients, or patients with hepatic insufficiency may be started on 2.5 mg once daily and this dose may be used when adding amlodipine besylate tablet to other antihypertensive therapy. Adjust dosage according to blood pressure goals. In general, wait 7 to 14 days between titration steps. Titrate more rapidly, however, if clinically warranted, provided the patient is assessed frequently. Angina The recommended dose for chronic stable or vasospastic angina is 5 to 10 mg, with the lower dose suggested in the elderly and in patients with hepatic insufficiency. Most patients will require 10 mg for adequate effect. Coronary artery disease The recommended dose range for patients with coronary artery disease is 5 to 10 mg once daily. In clinical studies, the majority of patients required 10 mg [see CLINICAL STUDIES (14.4) ] . 2.2 Children The effective antihypertensive oral dose in pediatric patients ages 6 to 17 years is 2.5 mg to 5 mg once daily. Doses in excess of 5 mg daily have not been studied in pediatric patients [see CLINICAL PHARMACOLOGY (12.4) , CLINICAL STUDIES (14.1) ] ."},{"title":"ข้อห้ามใช้","body":"Known sensitivity to amlodipine ( 4 ) Amlodipine besylate tablets are contraindicated in patients with known sensitivity to amlodipine."},{"title":"คำเตือนและข้อควรระวัง","body":"Symptomatic hypotension is possible, particularly in patients with severe aortic stenosis. However, acute hypotension is unlikely. ( 5.1 ) Worsening angina and acute myocardial infarction can develop after starting or increasing the dose of amlodipine, particularly in patients with severe obstructive coronary artery disease. ( 5.2 ) Titrate slowly in patients with severe hepatic impairment. ( 5.3 ) 5.1 Hypotension Symptomatic hypotension is possible, particularly in patients with severe aortic stenosis. Because of the gradual onset of action, acute hypotension is unlikely. 5.2 Increased Angina or Myocardial Infarction Worsening angina and acute myocardial infarction can develop after starting or increasing the dose of amlodipine, particularly in patients with severe obstructive coronary artery disease. 5.3 Patients with Hepatic Failure Because amlodipine besylate is extensively metabolized by the liver and the plasma elimination half-life (t 1/2 ) is 56 hours in patients with impaired hepatic function, titrate slowly when administering amlodipine besylate to patients with severe hepatic impairment."},{"title":"อาการไม่พึงประสงค์","body":"Most common adverse reaction to amlodipine is edema which occurred in a dose related manner. Other adverse experiences not dose related but reported with an incidence >1.0% are fatigue, nausea, abdominal pain, and somnolence. ( 6 ) To report SUSPECTED ADVERSE REACTIONS, contact Lupin Pharmaceuticals, Inc. at 1-800-399-2561 or www.lupinpharmaceuticals.com or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch. 6.1 Clinical Trials Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical trials of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in practice. Amlodipine has been evaluated for safety in more than 11,000 patients in U.S. and foreign clinical trials. In general, treatment with amlodipine was well-tolerated at doses up to 10 mg daily. Most adverse reactions reported during therapy with amlodipine were of mild or moderate severity. In controlled clinical trials directly comparing amlodipine (N=1730) at doses up to 10 mg to placebo (N=1250), discontinuation of amlodipine because of adverse reactions was required in only about 1.5% of patients and was not significantly different from placebo (about 1%). The most commonly reported side effects more frequent than placebo are reflected in the table below. The incidence (%) of side effects that occurred in a dose related manner are as follows: Amlodipine Placebo 2 . 5 mg N = 275 5 mg N = 296 10 mg N = 268 N = 520 Edema 1.8 3.0 10.8 0.6 Dizziness 1.1 3.4 3.4 1.5 Flushing 0.7 1.4 2.6 0.0 Palpitation 0.7 1.4 4.5 0.6 Other adverse reactions that were not clearly dose related but were reported with an incidence greater than 1.0% in placebo-controlled clinical trials include the following: Amlodipine (%) (N=1730) Placebo (%) (N=1250) Fatigue 4.5 2.8 Nausea 2.9 1.9 Abdominal Pain 1.6 0.3 Somnolence 1.4 0.6 For several adverse experiences that appear to be drug and dose related, there was a greater incidence in women than men associated with amlodipine treatment as shown in the following table: Amlodipine Placebo Male =% ( N = 1218 ) Female =% ( N = 512 ) Male =% ( N = 914 ) Female …"},{"title":"Drug interaction","body":"Do not exceed doses greater than 20 mg daily of simvastatin. ( 7.2 ) 7.1 Impact of Other Drugs on Amlodipine CYP3A Inhibitors Co-administration with CYP3A inhibitors (moderate and strong) results in increased systemic exposure to amlodipine and may require dose reduction. Monitor for symptoms of hypotension and edema when amlodipine is co-administered with CYP3A inhibitors to determine the need for dose adjustment [see CLINICAL PHARMACOLOGY ( 12.3 )] . CYP3A Inducers No information is available on the quantitative effects of CYP3A inducers on amlodipine. Blood pressure should be closely monitored when amlodipine is co-administered with CYP3A inducers. Sildenafil Monitor for hypotension when sildenafil is co-administered with amlodipine [see CLINICAL PHARMACOLOGY ( 12.2 )] . 7.2 Impact of Amlodipine on Other Drugs Simvastatin Co-administration of simvastatin with amlodipine increases the systemic exposure of simvastatin. Limit the dose of simvastatin in patients on amlodipine to 20 mg daily [see CLINICAL PHARMACOLOGY ( 12.3 )] . Immunosuppressants Amlodipine may increase the systemic exposure of cyclosporine or tacrolimus when co-administered. Frequent monitoring of trough blood levels of cyclosporine and tacrolimus is recommended and adjust the dose when appropriate [see CLINICAL PHARMACOLOGY ( 12.3 )] ."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary The limited available data based on post-marketing reports with amlodipine use in pregnant women are not sufficient to inform a drug-associated risk for major birth defects and miscarriage. There are risks to the mother and fetus associated with poorly controlled hypertension in pregnancy [see Clinical Considerations] . In animal reproduction studies, there was no evidence of adverse developmental effects when pregnant rats and rabbits were treated orally with amlodipine maleate during organogenesis at doses approximately 10 and 20-times the maximum recommended human dose (MRHD), respectively. However for rats, litter size was significantly decreased (by about 50%) and the number of intrauterine deaths was significantly increased (about 5-fold). Amlodipine has been shown to prolong both the gestation period and the duration of labor in rats at this dose [see Data]. The estimated background risk of major birth defects and miscarriage for the indicated population is unknown. All pregnancies have a background risk of birth defect, loss or other adverse outcomes. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2% to 4% and 15% to 20%, respectively. Clinical Considerations: Disease-associated maternal and/or embryo/fetal risk Hypertension in pregnancy increases the maternal risk for pre-eclampsia, gestational diabetes, premature delivery, and delivery complications (e.g., need for cesarean section and post-partum hemorrhage). Hypertension increases the fetal risk for intrauterine growth restriction and intrauterine death. Pregnant women with hypertension should be carefully monitored and managed accordingly. Data: Animal Data No evidence of teratogenicity or other embryo/fetal toxicity was found when pregnant rats and rabbits were treated orally with amlodipine maleate at doses up to 10 mg amlodipine/kg/day (approximately 10 and 20 times the MRHD based on body surface area, respectively) during their respective periods of major organogenesis. However for rats, litter size was significantly decreased (by about 50%) and the number of intrauterine deaths was significantly increased (about 5-fold)in rats receiving amlodipine maleate at a dose equivalent to 10 mg amlodipine/kg/day for 14 days before mating and throughout mating and gestation. …"},{"title":"การได้รับยาเกินขนาด","body":"might be expected to cause excessive peripheral vasodilation with marked hypotension and possibly a reflex tachycardia. In humans, experience with intentional overdosage of amlodipine is limited. Single oral doses of amlodipine maleate equivalent to 40 mg amlodipine/kg and 100 mg amlodipine/kg in mice and rats, respectively, caused deaths. Single oral amlodipine maleate doses equivalent to 4 or more mg amlodipine/kg or higher in dogs (11 or more times the maximum recommended human dose on a mg/m 2 basis) caused a marked peripheral vasodilation and hypotension. If massive overdose should occur, initiate active cardiac and respiratory monitoring. Frequent blood pressure measurements are essential. Should hypotension occur, provide cardiovascular support including elevation of the extremities and the judicious administration of fluids. If hypotension remains unresponsive to these conservative measures, consider administration of vasopressors (such as phenylephrine) with attention to circulating volume and urine output. As amlodipine is highly protein bound, hemodialysis is not likely to be of benefit."}]},
{"key":"amoxicillin|ORAL","generic":"amoxicillin","route":"ORAL","brand":null,"title":"Amoxicillin","set_id":"0ce05282-995c-461e-b807-facb1fcbb405","effective":"20260119","sections":[{"title":"ข้อบ่งใช้","body":"Adults and Pediatric Patients • Upper Respiratory Tract Infections of the Ear, Nose, and Throat: Amoxicillin for oral suspension is indicated in the treatment of infections due to susceptible (ONLY β-lactamase-negative) isolates of Streptococcus species. (α- and β-hemolytic isolates only), Streptococcus pneumoniae , Staphylococcus spp., or Haemophilus influenzae . • Infections of the Genitourinary Tract: Amoxicillin for oral suspension is indicated in the treatment of infections due to susceptible (ONLY β-lactamase-negative) isolates of Escherichia coli , Proteus mirabilis , or Enterococcus faecalis . • Infections of the Skin and Skin Structure: Amoxicillin for oral suspension is indicated in the treatment of infections due to susceptible (ONLY β-lactamase-negative) isolates of Streptococcus spp. (α- and β-hemolytic isolates only), Staphylococcus spp., or E. coli . • Infections of the Lower Respiratory Tract: Amoxicillin for oral suspension is indicated in the treatment of infections due to susceptible (ONLY β-lactamase-negative) isolates of Streptococcus spp. (α- and β-hemolytic isolates only), S. pneumoniae , Staphylococcus spp., or H. influenzae . Adult Patients Only • Helicobacter pylori Infection and Duodenal Ulcer Disease: Triple therapy for Helicobacter pylori (H. pylori) with clarithromycin and lansoprazole: Amoxicillin, in combination with clarithromycin plus lansoprazole as triple therapy, is indicated for the treatment of patients with H. pylori infection and duodenal ulcer disease (active or 1-year history of a duodenal ulcer) to eradicate H. pylori . Eradication of H. pylori has been shown to reduce the risk of duodenal ulcer recurrence. Dual therapy for H. pylori with lansoprazole: Amoxicillin, in combination with lansoprazole delayed-release capsules as dual therapy, is indicated for the treatment of patients with H. pylori infection and duodenal ulcer disease (active or 1-year history of a duodenal ulcer) who are either allergic or intolerant to clarithromycin or in whom resistance to clarithromycin is known or suspected. (See the clarithromycin package insert, MICROBIOLOGY.) Eradication of H. pylori has been shown to reduce the risk of duodenal ulcer recurrence. Usage To reduce the development of drug-resistant bacteria and maintain the effectiveness of amoxicillin and other antibacterial drugs, amoxicillin should be used only to treat infections that are proven or strongly suspected to be caused by bacteria. …"},{"title":"ขนาดยาและวิธีใช้","body":"• In Adults, 750 to 1750 mg/day in divided doses every 8 to 12 hours. • In Pediatric Patients over 3 Months of Age, 20 to 45 mg/kg/day in divided doses every 8 to 12 hours. Refer to full prescribing information for specific dosing regimens. ( 2.2 , ) • The upper dose for neonates and infants aged 3 months or younger is 30 mg/kg/day divided every 12 hours. () • Dosing for H. pylori Infection (in Adults): Triple therapy: 1 gram amoxicillin, 500 mg clarithromycin, and 30 mg lansoprazole, all given twice daily (every 12 hours) for 14 days. Dual therapy: 1 gram amoxicillin and 30 mg lansoprazole, each given three times daily (every 8 hours) for 14 days. () • Reduce the dose in patients with severe renal impairment (GFR greater than 30 mL/min). () 2.1 Important Administration Instructions To minimize the potential for gastrointestinal intolerance, amoxicillin should be taken at the start of a meal. 2.2 Dosage for Adults and Pediatric Patients Aged 3 Months (12 weeks) and Older • Treatment should be continued for a minimum of 48 to 72 hours beyond the time that the patient becomes asymptomatic, or evidence of bacterial eradication has been obtained. • It is recommended that there be at least 10 days’ treatment for any infection caused by Streptococcus pyogenes to prevent the occurrence of acute rheumatic fever. • In some infections, therapy may be required for several weeks. It may be necessary to continue clinical and/or bacteriological follow-up for several months after cessation of therapy. Table 1. Dosage Recommendations for Adult and Pediatric Patients Aged 3 Months (12 weeks) and Older Infection Severity a Recommended Dosage for Adults and Pediatric Patients Aged 3 Months and Older and Weight Greater than 40 kg Recommended Dosage for Pediatric Patients Aged 3 Months and Older and Weight Less than 40 kg Ear/Nose/Throat Skin/Skin Structure Genitourinary Tract Mild/Moderate 500 mg every 12 hours or 250 mg every 8 hours 25 mg/kg/day in divided doses every 12 hours or 20 mg/kg/day in divided doses every 8 hours Severe 875 mg every 12 hours or 500 mg every 8 hours 45 mg/kg/day in divided doses every 12 hours or 40 mg/kg/day in divided doses every 8 hours Lower Respirato …"},{"title":"ข้อห้ามใช้","body":"Amoxicillin is contraindicated in patients who have experienced a serious hypersensitivity reaction (e.g., anaphylaxis or Stevens-Johnson syndrome) to amoxicillin or to other β-lactam antibacterial drugs (e.g., penicillins and cephalosporins). • History of a serious hypersensitivity reaction (e.g., anaphylaxis or Stevens-Johnson syndrome) to amoxicillin or to other beta-lactams (e.g., penicillins or cephalosporins). ()"},{"title":"คำเตือนและข้อควรระวัง","body":"• Anaphylactic reactions: Serious and occasionally fatal anaphylactic reactions have been reported in patients on penicillin therapy, including amoxicillin. Discontinue amoxicillin if a reaction occurs. () • Severe cutaneous adverse reactions (SCAR): Monitor closely. Discontinue if rash progresses. () • Drug-induced enterocolitis syndrome (DIES) has been reported with amoxicillin use. If this occurs, discontinue amoxicillin for oral suspension and institute appropriate therapy. ( Error! Hyperlink reference not valid. ) • Clostridioides difficile -associated diarrhea (CDAD) (ranging from mild diarrhea to fatal colitis): Evaluate if diarrhea occurs. () 5.1 Anaphylactic Reactions Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported in patients on penicillin therapy including amoxicillin. Although anaphylaxis is more frequent following parenteral therapy, it has occurred in patients on oral penicillins. These reactions are more likely to occur in individuals with a history of penicillin hypersensitivity and/or a history of sensitivity to multiple allergens. There have been reports of individuals with a history of penicillin hypersensitivity who have experienced severe reactions when treated with cephalosporins. Before initiating therapy with amoxicillin, careful inquiry should be made regarding previous hypersensitivity reactions to penicillins, cephalosporins, or other allergens. If an allergic reaction occurs, amoxicillin should be discontinued, and appropriate therapy instituted. 5.2 Severe Cutaneous Adverse Reactions Amoxicillin may cause severe cutaneous adverse reactions (SCAR), such as Stevens-Johnson syndrome (SJS), toxic epidermal necrolysis (TEN), drug reaction with eosinophilia and systemic symptoms (DRESS), and acute generalized exanthematous pustulosis (AGEP). If patients develop skin rash they should be monitored closely, and amoxicillin discontinued if lesions progress. 5.3 Drug-Induced Enterocolitis Syndrome (DIES) Drug-induced enterocolitis syndrome (DIES) has been reported with amoxicillin use [see Adverse Reactions ( 6.2 )] , with most cases occurring in pediatric patients ≤18 years of age. DIES is a non-IgE mediated hypersensitivity reaction characterized by protracted vomiting occurring 1 to 4 hours after drug ingestion in the absence of skin or respiratory symptoms. …"},{"title":"อาการไม่พึงประสงค์","body":"The following are discussed in more detail in other sections of the labeling: • Anaphylactic reactions [see Warnings and Precautions ( )] • Severe Cutaneous Adverse Reactions [see Warnings and Precautions ( )] • Drug-Induced Enterocolitis Syndrome (DIES) [see Warnings and Precautions ( )] • Clostridioides difficile -Associated Diarrhea (CDAD) [see Warnings and Precautions ( )] The most common adverse reactions (greater than 1%) observed in clinical trials of amoxicillin for oral suspension were diarrhea, rash, vomiting, and nausea. () To report SUSPECTED ADVERSE REACTIONS, contact Hikma Pharmaceuticals USA Inc. at 1-877-233-2001 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch. 6.1 Clinical Trials Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical trials of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in practice. The most common adverse reactions (greater than 1%) observed in clinical trials of amoxicillin capsules, tablets or oral suspension were diarrhea, rash, vomiting, and nausea. Triple therapy: The most frequently reported adverse events for patients who received triple therapy (amoxicillin/clarithromycin/ lansoprazole) were diarrhea (7%), headache (6%), and taste perversion (5%). Dual therapy: The most frequently reported adverse events for patients who received double therapy amoxicillin/lansoprazole were diarrhea (8%) and headache (7%). For more information on adverse reactions with clarithromycin or lansoprazole, refer to the Adverse Reactions section of their package inserts. 6.2 Postmarketing Experience In addition to adverse events reported from clinical trials, the following events have been identified during postmarketing use of penicillins. Because they are reported voluntarily from a population of unknown size, estimates of frequency cannot be made. These events have been chosen for inclusion due to a combination of their seriousness, frequency of reporting, or potential causal connection to amoxicillin. • Infections and Infestations: Mucocutaneous candidiasis. • Gastrointestinal: Drug-induced enterocolitis syndrome (DIES), black hairy tongue, and hemorrhagic/pseudomembranous colitis. …"},{"title":"Drug interaction","body":"• Coadministration with probenecid is not recommended. () • Concomitant use of amoxicillin and oral anticoagulants may increase the prolongation of prothrombin time. () • Coadministration with allopurinol increases the risk of rash. () • Amoxicillin may reduce the efficacy of oral contraceptives. () 7.1 Probenecid Probenecid decreases the renal tubular secretion of amoxicillin. Concurrent use of amoxicillin and probenecid may result in increased and prolonged blood levels of amoxicillin. 7.2 Oral Anticoagulants Abnormal prolongation of prothrombin time (increased international normalized ratio [INR]) has been reported in patients receiving amoxicillin and oral anticoagulants. Appropriate monitoring should be undertaken when anticoagulants are prescribed concurrently. Adjustments in the dose of oral anticoagulants may be necessary to maintain the desired level of anticoagulation. 7.3 Allopurinol The concurrent administration of allopurinol and amoxicillin increases the incidence of rashes in patients receiving both drugs as compared to patients receiving amoxicillin alone. It is not known whether this potentiation of amoxicillin rashes is due to allopurinol or the hyperuricemia present in these patients. 7.4 Oral Contraceptives Amoxicillin may affect the intestinal flora, leading to lower estrogen reabsorption and reduced efficacy of combined oral estrogen/progesterone contraceptives. 7.5 Other Antibacterials Chloramphenicol, macrolides, sulfonamides, and tetracyclines may interfere with the bactericidal effects of penicillin. This has been demonstrated in vitro ; however, the clinical significance of this interaction is not well documented. 7.6 Effects on Laboratory Tests High urine concentrations of ampicillin may result in false-positive reactions when testing for the presence of glucose in urine using CLINITEST ® , Benedict’s Solution, or Fehling’s Solution. Since this effect may also occur with amoxicillin, it is recommended that glucose tests based on enzymatic glucose oxidase reactions (such as CLINISTIX ® ) be used. Following administration of ampicillin or amoxicillin to pregnant women, a transient decrease in plasma concentration of total conjugated estriol, estriol-glucuronide, conjugated estrone, and estradiol has been noted."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Teratogenic Effects: Reproduction studies have been performed in mice and rats at doses up to 2000 mg/kg (3 and 6 times the 3 g human dose, based on body surface area). There was no evidence of harm to the fetus due to amoxicillin. There are, however, no adequate and well-controlled studies in pregnant women. Because animal reproduction studies are not always predictive of human response, amoxicillin should be used during pregnancy only if clearly needed. 8.3 Nursing Mothers Penicillins have been shown to be excreted in human milk. Amoxicillin use by nursing mothers may lead to sensitization of infants. Caution should be exercised when amoxicillin is administered to a nursing woman. 8.4 Pediatric Use The safety and effectiveness of amoxicillin for the treatment of upper respiratory tract infections, and infections of the genitourinary tract, skin and skin structure and lower respiratory tract have been established in pediatric patients. The safety and effectiveness of amoxicillin for the treatment of H. Pylori infection have not been established in pediatric patients. Because of incompletely developed renal function in neonates and young infants, the elimination of amoxicillin may be delayed. Dosing of amoxicillin should be modified in pediatric patients 12 weeks or younger (3 months or younger) [see Dosage and Administration ( )] . 8.5 Geriatric Use An analysis of clinical studies of amoxicillin was conducted to determine whether subjects aged 65 and over respond differently from younger subjects. These analyses have not identified differences in responses between the elderly and younger patients, but a greater sensitivity of some older individuals cannot be ruled out. This drug is known to be substantially excreted by the kidney, and the risk of toxic reactions to this drug may be greater in patients with impaired renal function. Because elderly patients are more likely to have decreased renal function, care should be taken in dose selection, and it may be useful to monitor renal function."},{"title":"การได้รับยาเกินขนาด","body":"In case of overdosage, discontinue amoxicillin, treat symptomatically, and institute supportive measures as required. A prospective study of 51 pediatric patients at a poison-control center suggested that overdosages of less than 250 mg/kg of amoxicillin are not associated with significant clinical symptoms. Interstitial nephritis resulting in oliguric renal failure has been reported in a small number of patients after overdosage with amoxicillin 1 . Crystalluria, in some cases leading to renal failure, has also been reported after amoxicillin overdosage in adult and pediatric patients. In case of overdosage, adequate fluid intake and diuresis should be maintained to reduce the risk of amoxicillin crystalluria. Renal impairment appears to be reversible with cessation of drug administration. High blood levels may occur more readily in patients with impaired renal function because of decreased renal clearance of amoxicillin. Amoxicillin may be removed from circulation by hemodialysis."}]},
{"key":"aspirin|ORAL","generic":"aspirin","route":"ORAL","brand":null,"title":"Aspirin","set_id":"055d8420-c189-4a9e-acdc-21627935c8eb","effective":"20260625","sections":[{"title":"ข้อบ่งใช้","body":"temporarily relieves: minor pain of arthritis headache muscle pain menstrual pain toothache pain and fever of colds"},{"title":"ขนาดยาและวิธีใช้","body":"do not take more than directed drink a full glass of water with each dose adults and children 12 years and over: take 1 or 2 tablets every 4 hours or 3 tablets every 6 hours not to exceed 12 tablets in 24 hours unless directed by a doctor children under 12 years: do not use unless directed by a doctor"},{"title":"ข้อห้ามใช้","body":"if you are allergic to aspirin or any other pain reliever/fever reducer if you have ever had an allergic reaction to this product or any of its ingredients"},{"title":"คำเตือนและข้อควรระวัง","body":"Reye’s syndrome: Children and teenagers who have or are recovering from chicken pox or flu-like symptoms should not use this product. When using this product, if changes in behavior with nausea and vomiting occur, consult a doctor because these symptoms could be an early sign of Reye's syndrome, a rare but serious illness. Allergy alert: Aspirin may cause a severe allergic reaction, which may include: facial swelling shock hives asthma (wheezing) Stomach bleeding warning: This product contains an NSAID, which may cause severe stomach bleeding. The chance is higher if you are age 60 or older take a blood thinning (anticoagulant) or steroid drug take other drugs containing prescription or nonprescription NSAIDs [aspirin, ibuprofen, naproxen, or others] take more or for a longer time than directed have had stomach ulcers or bleeding problems have 3 or more alcoholic drinks every day while using this product Do not use if you are allergic to aspirin or any other pain reliever/fever reducer if you have ever had an allergic reaction to this product or any of its ingredients Ask a doctor before use if you are taking a diuretic stomach bleeding warning applies to you you have a history of stomach problems, such as heartburn you have high blood pressure, heart disease, liver cirrhosis, or kidney disease you have asthma Ask a doctor or pharmacist before use if you are taking a prescription drug for gout diabetes arthritis Stop use and ask a doctor if an allergic reaction occurs. Seek medical help right away. you experience any of the following signs of stomach bleeding: feel faint vomit blood have bloody or black stools have stomach pain that does not get better ringing in the ears or a loss of hearing occurs pain gets worse or lasts more than 10 days fever gets worse or lasts more than 3 days redness or swelling is present new symptoms occur These could be signs of a serious condition. If pregnant or breast-feeding, ask a health professional before use. It is especially important not to use aspirin at 20 weeks or later in pregnancy unless definitely directed to do so by a doctor because it may cause problems in the unborn child or complications during delivery. Keep out of reach of children. In case of overdose, get medical help or contact a Poison Control Center right away. problems, such as heartburn you have high blood pressure, heart disease, liver cirrhosis, or kidney disease you have asthma arthritis occurs. Seek medical help right away. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"ask a health professional before use. It is especially important not to use aspirin at 20 weeks or later in pregnancy unless definitely directed to do so by a doctor because it may cause problems in the unborn child or complications during delivery."},{"title":"การเก็บรักษา","body":"Other information use by expiration date on package store at 25°C (77°F); excursions permitted between 15°-30°C (59°-86°F)"}]},
{"key":"calamine|TOPICAL","generic":"calamine","route":"TOPICAL","brand":null,"title":"Calamine","set_id":"90d9d908-57ea-4062-ade0-8a4888939c91","effective":"20260129","sections":[{"title":"ข้อบ่งใช้","body":"dries the oozing and weeping of poison: ivy oak sumac"},{"title":"ขนาดยาและวิธีใช้","body":"shake well before using apply as needed"},{"title":"คำเตือนและข้อควรระวัง","body":"For external use only eyes 7 days or clear up and occur again within a few days"},{"title":"อาการไม่พึงประสงค์","body":"ADVERSE REACTION Distributed By AmerisourceBergen 1 West First Avenue Conshohocken, PA 19428 Questions or Concerns? www.mygnp.com SATISFACTION GUARANTEED GOOD NEIGHBOR PHARMACY BRAND PRODUCTS"}]},
{"key":"chlorpheniramine maleate|ORAL","generic":"chlorpheniramine maleate","route":"ORAL","brand":null,"title":"Aller-chlor","set_id":"04ca3806-72be-47d4-9fea-5b0dee087683","effective":"20260708","sections":[{"title":"ข้อบ่งใช้","body":"temporarily relieves these symptoms due to hay fever or other upper respiratory allergies: sneezing runny nose itchy, watery eyes itching of the nose or throat"},{"title":"ขนาดยาและวิธีใช้","body":"take every 4 to 6 hours, or as directed by a doctor adults and children 12 years and over 1 tablet. Do not exceed 6 tablets in 24 hours. children 6 to under 12 years 1/2 tablet (break tablet in half). Do not exceed 3 whole tablets in 24 hours. children under 6 years do not use"},{"title":"ข้อห้ามใช้","body":"to make a child sleepy."},{"title":"คำเตือนและข้อควรระวัง","body":"Do not use to make a child sleepy. Ask a doctor before use if you have glaucoma a breathing problem such as emphysema or chronic bronchitis difficulty in urination due to enlargement of the prostate gland Ask a doctor or pharmacist before use if you are taking sedatives or tranquilizers. When using this product drowsiness may occur avoid alcoholic beverages excitability may occur, especially in children use caution when driving a motor vehicle or operating machinery alcohol, sedatives, and tranquilizers may increase drowsiness If pregnant or breast-feeding, ask a health professional before use. Keep out of reach of children. In case of overdose, get medical help or contact a Poison Control Center right away. gland tranquilizers. occur, especially in children use caution when driving a motor vehicle or operating machinery alcohol, sedatives, and tranquilizers may increase drowsiness"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"ask a health professional before use."},{"title":"การเก็บรักษา","body":"Other information store at 25ºC (77ºF); excursions permitted between 15º-30ºC (59º-86ºF) protect from excessive moisture use by expiration date on package"}]},
{"key":"clotrimazole|TOPICAL","generic":"clotrimazole","route":"TOPICAL","brand":null,"title":"Clotrimazole","set_id":"116be3a8-9a57-4b4a-a873-98a4ce83bcf7","effective":"20250206","sections":[{"title":"ข้อบ่งใช้","body":"Clotrimazole cream USP is indicated for the topical treatment of candidiasis due to Candida albicans and tinea versicolor due to Malassezia furfur. Clotrimazole is also available as a nonprescription item which is indicated for the topical treatment of the following dermal infections: tinea pedis, tinea cruris, and tinea corporis due to Trichophyton rubrum,Trichophyton mentagrophytes , Epidermophyton floccosum , and Microsporum canis."},{"title":"ขนาดยาและวิธีใช้","body":"Gently massage sufficient clotrimazole cream into the affected and surrounding skin areas twice a day, in the morning and evening. Clinical improvement, with relief of pruritis, usually occurs within the first week of treatment with clotrimazole cream. If the patient shows no clinical improvement after four weeks of treatment with clotrimazole cream, the diagnosis should be reviewed."},{"title":"ข้อห้ามใช้","body":"Clotrimazole cream is contraindicated in individuals sensitive to its components."},{"title":"คำเตือนและข้อควรระวัง","body":"Clotrimazole cream is not for ophthalmic use. General: If irritation or sensitivity develops with the use of clotrimazole cream, treatment should be discontinued and appropriate therapy instituted. Information for Patients : The patient should be advised to: • Use the medication for the full treatment time even though the symptoms may have improved. Notify the physician if there is no improvement after four weeks of treatment. • Inform the physician if the area of application shows signs of increased irritation (redness, itching, burning, blistering, swelling, oozing) indicative of possible sensitization. • Avoid the use of occlusive wrappings or dressings. • Avoid sources of infection or reinfection. Laboratory Tests If there is lack of response to clotrimazole cream, appropriate microbiological studies should be repeated to confirm the diagnosis and rule out other pathogens before instituting another course of antimycotic therapy. Drug Interactions Synergism or antagonism between clotrimazole and nystatin, or amphotericin B, or flucytosine against strains of C. albicans has not been reported. Carcinogenesis, Mutagenesis, Impairment of Fertility An 18-month oral dosing study with clotrimazole in rats has not revealed any carcinogenic effect. In tests for mutagenesis, chromosomes of the spermatophores of Chinese hamsters which had been exposed to clotrimazole were examined for structural changes during the metaphase. Prior to testing, the hamsters had received five oral clotrimazole doses of 100 mg/kg body weight. The results of this study showed that clotrimazole had no mutagenic effect. Usage in Pregnancy: Pregnancy Category B The disposition of 14 C-clotrimazole has been studied in humans and animals. Clotrimazole is very poorly absorbed following dermal application or intravaginal administration to humans. (See CLINICAL PHARMACOLOGY ) In clinical trials, use of vaginally applied clotrimazole in pregnant women in their second and third trimesters has not been associated with ill effects. There are, however, no adequate and well-controlled studies in pregnant women during the first trimester of pregnancy. Studies in pregnant rats with intravaginal doses up to 100 mg/kg have revealed no evidence of harm to the fetus due to clotrimazole. …"},{"title":"อาการไม่พึงประสงค์","body":"The following adverse reactions have been reported in connection with the use of this product: erythema, stinging, blistering, peeling, edema, pruritis, urticaria, burning, and general irritation of the skin."},{"title":"Drug interaction","body":"Synergism or antagonism between clotrimazole and nystatin, or amphotericin B, or flucytosine against strains of C. albicans has not been reported."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Usage in Pregnancy: Pregnancy Category B The disposition of 14 C-clotrimazole has been studied in humans and animals. Clotrimazole is very poorly absorbed following dermal application or intravaginal administration to humans. (See CLINICAL PHARMACOLOGY ) In clinical trials, use of vaginally applied clotrimazole in pregnant women in their second and third trimesters has not been associated with ill effects. There are, however, no adequate and well-controlled studies in pregnant women during the first trimester of pregnancy. Studies in pregnant rats with intravaginal doses up to 100 mg/kg have revealed no evidence of harm to the fetus due to clotrimazole. High oral doses of clotrimazole in rats and mice ranging from 50 to 120 mg/kg resulted in embroyotoxicity (possible secondary to maternal toxicity), impairment of mating, decreased litter size and number of viable young and decreased pup survival to weaning. However, clotrimazole was not teratogenic in mice, rabbits and rats at oral doses up to 200, 180 and 100 mg/kg, respectively. Oral absorption in the rat amounts to approximately 90% of the administered dose. Because animal reproduction studies are not always predictive of human response, this drug should be used only if clearly indicated during the first trimester of pregnancy. It is not known whether this drug is excreted in human milk, caution should be exercised when clotrimazole is used by a nursing woman. Safety and effectiveness in children have been established for clotrimazole when used as indicated and in the recommended dosage."},{"title":"การได้รับยาเกินขนาด","body":"Acute overdosage with topical application of clotrimazole is unlikely and would not be expected to lead to a life-threatening situation."},{"title":"การเก็บรักษา","body":"Store between 2 o - 30 o C (36 o -86 o F)."}]},
{"key":"colchicine|ORAL","generic":"colchicine","route":"ORAL","brand":null,"title":"Gloperba","set_id":"467cd83f-d695-4040-9434-10e80b4271da","effective":"20241101","sections":[{"title":"ข้อบ่งใช้","body":"® (colchicine) Oral Solution is indicated for prophylaxis of gout flares in adults. GLOPERBA is indicated for prophylaxis of gout flares in adults ( 1 ). Limitations of use: The safety and effectiveness of GLOPERBA for acute treatment of gout flares during prophylaxis has not been studied. GLOPERBA is not an analgesic medication and should not be used to treat pain from other causes ( 1 ). Limitations of use: The safety and effectiveness of GLOPERBA for acute treatment of gout flares during prophylaxis has not been studied. GLOPERBA is not an analgesic medication and should not be used to treat pain from other causes."},{"title":"ขนาดยาและวิธีใช้","body":"0.6 mg (5 mL) once or twice daily. Maximum dose 1.2 mg/day. ( 2.1 ) GLOPERBA is administered orally, without regard to meals ( 2.1 ) 2.1 Gout Prophylaxis For prophylaxis of gout flares, the recommended dosage of GLOPERBA is 0.6 mg (5 mL) once or twice daily. The maximum dose is 1.2 mg/day. GLOPERBA is administered orally, without regard to meals."},{"title":"ข้อห้ามใช้","body":"Patients with renal or hepatic impairment should not be given GLOPERBA in conjunction with drugs that inhibit both CYP3A4 and P-gp [see Drug Interactions (7) ]. Combining these dual inhibitors with colchicine in patients with renal or hepatic impairment has resulted in life threatening or fatal colchicine toxicity. Patients with both renal and hepatic impairment should not be given GLOPERBA. Patients with renal or hepatic impairment should not be given GLOPERBA in conjunction with drugs that inhibit both CYP3A4 and P-gp ( 4 ). Patients with both renal and hepatic impairment should not be given GLOPERBA ( 4 )."},{"title":"คำเตือนและข้อควรระวัง","body":"Fatal overdoses have been reported with colchicine in adults and children. Keep GLOPERBA out of the reach of children ( 5.1 , 10 ). Blood dyscrasias: myelosuppression, leukopenia, granulocytopenia, thrombocytopenia and aplastic anemia have been reported ( 5.2 ). Monitor for toxicity and, if present, consider lowering the dose, temporary interruption or discontinuation of colchicine ( 5.2 , 5.3 , 5.4 , 6 , 10 ). Drug interaction with CYP3A4 and P-gp inhibitors: Co-administration of colchicine with dual CYP3A4 and P-gp inhibitors has resulted in life threatening interactions and death ( 5.3 , 7 ). Neuromuscular toxicity: Myotoxicity including rhabdomyolysis may occur, especially in combination with other drugs known to cause this effect. Consider lowering the dose, temporary interruption or discontinuation of GLOPERBA ( 5.4 , 6 ). 5.1 Fatal Overdose Fatal overdoses, both accidental and intentional, have been reported in adults and children who have ingested colchicine [see Overdosage (10) ]. GLOPERBA should be kept out of the reach of children. 5.2 Blood Dyscrasias Myelosuppression, leukopenia, granulocytopenia, thrombocytopenia, pancytopenia and aplastic anemia have been reported with colchicine used in therapeutic doses. 5.3 Drug Interactions Because colchicine is a substrate for both the CYP3A4 metabolizing enzyme and the P-gp efflux transporter, inhibition of either of these pathways may lead to colchicine related toxicity. Inhibition of both CYP3A4 and P-gp by dual inhibitors (i.e., clarithromycin) has been reported to produce life threatening or fatal colchicine toxicity due to significant increases in systemic colchicine levels. Therefore, concomitant use of GLOPERBA with inhibitors of both CYP3A4 and P-gp should be avoided. If treatment with colchicine is necessary, a reduced daily dose should be considered and the patient should be closely monitored for colchicine toxicity [see Drug Interactions (7) ]. Use of GLOPERBA in conjunction with drugs that inhibit both CYP3A4 and P-gp is contraindicated in patients with renal or hepatic impairment [see Contraindications (4) ]. 5.4 Neuromuscular Toxicity Colchicine induced neuromuscular toxicity and rhabdomyolysis have been reported with chronic treatment in therapeutic doses, especially in combination with other drugs known to cause this effect. Patients with impaired renal function and elderly patients, even those with normal renal and hepatic function, are at increased risk. …"},{"title":"อาการไม่พึงประสงค์","body":"Gastrointestinal disorders are the most common adverse reactions with colchicine. These disorders are often the first signs of toxicity and may indicate that the colchicine dose needs to be reduced or therapy stopped. These disorders include diarrhea, nausea, vomiting, and abdominal pain. Colchicine has been reported to cause neuromuscular toxicity, which may present as muscle pain or weakness [see Warnings and Precautions (5.4) ] . Toxic manifestations associated with colchicine include myelosuppression, disseminated intravascular coagulation and injury to cells in the renal, hepatic, circulatory and central nervous systems. These toxicities most often occur with excessive accumulation or overdosage [see Overdosage (10) ] . The following adverse reactions have been reported with colchicine. These adverse reactions have been generally reversible upon interrupting treatment or lowering the dose of colchicine. Neurological: sensory motor neuropathy Dermatological: alopecia, maculopapular rash, purpura, rash Digestive: abdominal cramping, abdominal pain, diarrhea, lactose intolerance, nausea, vomiting Hematological: leukopenia, granulocytopenia, thrombocytopenia, pancytopenia, aplastic anemia Hepatobiliary: elevated AST, elevated ALT Musculoskeletal: myopathy, elevated CPK, myotonia, muscle weakness, muscle pain, rhabdomyolysis Reproductive: azoospermia, oligospermia The most commonly reported adverse reactions with colchicine are gastrointestinal symptoms, including diarrhea, nausea, vomiting, and abdominal pain ( 6 ). To report SUSPECTED ADVERSE REACTIONS, contact SCILEX Pharmaceuticals, Inc. at 1-866-SCILEX3 or FDA at 1-800-FDA-1088 (www.fda.gov/medwatch)."},{"title":"Drug interaction","body":"Colchicine is a substrate of the CYP3A4 metabolizing enzyme and the P-glycoprotein (P-gp) efflux transporter. Fatal drug interactions have been reported when colchicine is administered with clarithromycin, a dual inhibitor of CYP3A4 and P-glycoprotein. Toxicities have also been reported when colchicine is administered with inhibitors of CYP3A4 that may not be potent inhibitors of P-gp (e.g., grapefruit juice, erythromycin, verapamil), or inhibitors of P-gp that may not be potent inhibitors of CYP3A4 (e.g., cyclosporine). Patients with renal or hepatic impairment should not be given GLOPERBA with drugs that inhibit both CYP3A4 and P-glycoprotein [see Contraindications (4) ] . Combining these dual inhibitors with GLOPERBA in patients with renal and hepatic impairment has resulted in life threatening or fatal colchicine toxicity. Physicians should ensure that patients are suitable candidates for treatment with GLOPERBA and remain alert for signs and symptoms of toxic reactions associated with increased colchicine exposure due to drug interactions. Signs and symptoms of colchicine toxicity should be evaluated promptly and, if toxicity is suspected, consider lowering the dose, interruption or discontinuation of GLOPERBA. Co-administration of CYP3A4 or P-gp inhibitors or inhibitors of both CYP3A4 and P-gp (e.g., clarithromycin or cyclosporine) have been reported to lead to colchicine toxicity. The potential for drug-drug interactions must be considered prior to and during therapy ( 7 ). Concomitant use of GLOPERBA and inhibitors of both CYP3A4 and P-gp should be avoided if possible. If co-administration with a CYP3A4 and P-gp inhibitor is required, the patients' dose of colchicine may need to be reduced or interrupted, and the patient should be monitored carefully for colchicine toxicity ( 7 ). 7.1 CYP3A4 The concomitant use of GLOPERBA and CYP3A4 inhibitors (e.g., clarithromycin, ketoconazole, grapefruit juice, erythromycin, verapamil, etc.) should be avoided due to the potential for serious and life threatening toxicity [see Warnings and Precautions (5.3) and Clinical Pharmacology (12.3) ] . If co-administration of GLOPERBA and a CYP3A4 inhibitor is necessary, the dose of GLOPERBA should be adjusted by either reducing the daily dose or reducing the dose frequency, and the patient should be monitored carefully for colchicine toxicity [see Clinical Pharmacology (12.3) ]. 7.2 P-Glycoprotein The concomitant use of GLOPERBA and inhibitors of P-glycoprotein (e.g. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Available human data from published literature on colchicine use in pregnancy over several decades have not identified any drug associated risks for major birth defects, miscarriage, or adverse maternal or fetal outcomes (see Data ). Although animal reproduction and development studies were not conducted with GLOPERBA, published animal reproduction and development studies indicate that colchicine causes embryofetal toxicity and altered postnatal development at exposures within or above the clinical therapeutic range. The estimated background risk of major birth defects and miscarriage for the indicated population is unknown. All pregnancies have a background risk of birth defect, loss or other adverse outcomes. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2 to 4% and 15 to 20%, respectively. Data Available data from published observational studies, case series, and case reports over several decades do not suggest an increased risk for major birth defects or miscarriage in pregnant women with rheumatic diseases (such as rheumatoid arthritis, Behçet's disease, or familial Mediterranean fever (FMF)) treated with colchicine at therapeutic doses during pregnancy. Limitations of these data include the lack of randomization and inability to control for confounders such as underlying maternal disease and maternal use of concomitant medications. 8.4 Pediatric Use Gout is rare in pediatric patients; safety and effectiveness of GLOPERBA in pediatric patients has not been established. 8.5 Geriatric Use Because of the increased incidence of decreased renal function in the elderly population, and the higher incidence of other co-morbid conditions in the elderly population requiring the use of other medications, reducing the dosage of colchicine when elderly patients are treated with colchicine should be carefully considered [see Clinical Pharmacology (12.3) ] ."},{"title":"การได้รับยาเกินขนาด","body":"The dose of colchicine that would induce significant toxicity for an individual is unknown. Fatalities have occurred after ingestion of a dose as low as 7 mg over a four day period, while other patients have survived after ingesting more than 60 mg. A review of 150 patients who overdosed on colchicine found that those who ingested less than 0.5 mg/kg survived and tended to have milder adverse reactions such as gastrointestinal symptoms, whereas those who took 0.5 to 0.8 mg/kg had more severe adverse reactions, including myelosuppression. There was 100% mortality in those who ingested more than 0.8 mg/kg. The first stage of acute colchicine toxicity typically begins within 24 hours of ingestion and includes gastrointestinal symptoms such as abdominal pain, nausea, vomiting, diarrhea and significant fluid loss, leading to volume depletion. Peripheral leukocytosis may also be seen. Life threatening complications occur during the second stage, which occurs 24 to 72 hours after drug administration, attributed to multiorgan failure and its consequences. Death is usually a result of respiratory depression and cardiovascular collapse. If the patient survives, recovery of multiorgan injury may be accompanied by rebound leukocytosis and alopecia starting about one week after the initial ingestion. Treatment of colchicine poisoning should begin with gastric lavage and measures to prevent shock. Otherwise, treatment is symptomatic and supportive. No specific antidote is known. Colchicine is not effectively removed by hemodialysis [see Clinical Pharmacology (12.3) ] ."},{"title":"การเก็บรักษา","body":"16.2 Storage Store at 20°-25°C (68° - 77°F); excursions permitted to 15°-30°C (59°-86°F). [See USP Controlled Room Temperature.]"}]},
{"key":"cyproheptadine hydrochloride|ORAL","generic":"cyproheptadine hydrochloride","route":"ORAL","brand":null,"title":"Cyproheptadine Hydrochloride","set_id":"81d9523f-f945-4410-8b71-8b5fea48a3da","effective":"20220224","sections":[{"title":"ข้อบ่งใช้","body":"Perennial and seasonal allergic rhinitis Vasomotor rhinitis Allergic conjunctivitis due to inhalant allergens and foods Mild, uncomplicated allergic skin manifestations of urticaria and angioedema Amelioration of allergic reactions to blood or plasma Cold urticaria Dermatographism As therapy for anaphylactic reactions adjunctive to epinephrine and other standard measures after the acute manifestations have been controlled."},{"title":"ขนาดยาและวิธีใช้","body":"DOSAGE SHOULD BE INDIVIDUALIZED ACCORDING TO THE NEEDS AND THE RESPONSE OF THE PATIENT. Each 5 mL of Cyproheptadine Hydrochloride Oral Solution contains 2 mg of Cyproheptadine hydrochloride. Although intended primarily for administration to children, the oral solution is also used for administration to adults who cannot swallow tablets. Children The total daily dosage for children may be calculated on the basis of body weight or body area using approximately 0.25 mg/kg/day (0.11 mg/lb/day) or 8 mg per square meter of body surface (8 mg/m 2 ). Age 2 to 6 years The usual dose is 2 mg (one teaspoonful) two or three times a day, adjusted as necessary to the size and response of the patient. The dose is not to exceed 12 mg a day. Age 7 to 14 years The usual dose is 4 mg (two teaspoonsful) two or three times a day, adjusted as necessary to the size and response of the patient. The dose is not to exceed 16 mg a day. Adults The total daily dose for adults should not exceed 0.5 mg/kg/day (0.23 mg/lb/day). The therapeutic range is 4 to 20 mg a day, with the majority of patients requiring 12 to 16 mg a day. An occasional patient may require as much as 32 mg a day for adequate relief. It is suggested that dosage be initiated with 4 mg (two teaspoonsful) three times a day and adjusted according to the size and response of the patient."},{"title":"ข้อห้ามใช้","body":"Newborn or Premature Infants This drug should not be used in newborn or premature infants. Nursing Mothers Because of the higher risk of antihistamines for infants generally and for newborns and prematures in particular, antihistamine therapy is contraindicated in nursing mothers. Other Conditions Hypersensitivity to cyproheptadine and other drugs of similar chemical structure Monoamine oxidase inhibitor therapy (see Drug Interactions ) Angle-closure glaucoma Stenosing peptic ulcer Symptomatic prostatic hypertrophy Bladder neck obstruction Pyloroduodenal obstruction Elderly, debilitated patients"},{"title":"คำเตือนและข้อควรระวัง","body":"Children Overdosage of antihistamines, particularly in infants and children, may produce hallucinations, central nervous system depression, convulsions and death. Antihistamines may diminish mental alertness; conversely, particularly in the young child, they may occasionally produce excitation. CNS Depressants Antihistamines may have additive effects with alcohol and other CNS depressants, e.g., hypnotics, sedatives, tranquilizers, antianxiety agents. Activities Requiring Mental Alertness Patients should be warned about engaging in activities requiring mental alertness and motor coordination, such as driving a car or operating machinery. Antihistamines are more likely to cause dizziness, sedation and hypotension in elderly patients. General Cyproheptadine has an atropine-like action and, therefore, should be used with caution in patients with: History of bronchial asthma Increased intraocular pressure Hyperthyroidism Cardiovascular disease Hypertension Information for Patients Antihistamines may diminish mental alertness; conversely, particularly in the young child, they may occasionally produce excitation. Patients should be warned about engaging in activities requiring mental alertness and motor coordination, such as driving a car or operating machinery. Drug Interactions MAO inhibitors prolong and intensify the anticholinergic effects of antihistamines. Antihistamines may have additive effects with alcohol and other CNS depressants, e.g., hypnotics, sedatives, tranquilizers, antianxiety agents. Carcinogenesis, Mutagenesis, Impairment of Fertility Long-term carcinogenic studies have not been done with cyproheptadine. Cyproheptadine had no effect on fertility in a two-litter study in rats or a two-generation study in mice at about 10 times the human dose. Cyproheptadine did not produce chromosome damage in human lymphocytes or fibroblasts in vitro ; high doses (10- 4 M) were cytotoxic. Cyproheptadine did not have any mutagenic effect in the Ames microbial mutagen test; concentrations of above 500 mcg/plate inhibited bacterial growth. Pregnancy Pregnancy Category B Reproduction studies have been performed in rabbits, mice and rats at oral or subcutaneous doses up to 32 times the maximum recommended human oral dose and have revealed no evidence of impaired fertility or harm to the fetus due to cyproheptadine. …"},{"title":"อาการไม่พึงประสงค์","body":"Adverse reactions which have been reported with the use of antihistamines are as follows: Central Nervous System: Sedation and sleepiness (often transient), dizziness, disturbed coordination, confusion, restlessness, excitation, nervousness, tremor, irritability, insomnia, paresthesias, neuritis, convulsions, euphoria, hallucinations, hysteria, faintness. Integumentary: Allergic manifestation of rash and edema, excessive perspiration, urticaria, photosensitivity. Special Senses: Acute labyrinthitis, blurred vision, diplopia, vertigo, tinnitus. Cardiovascular: Hypotension, palpitation, tachycardia, extrasystoles, anaphylactic shock. Hematologic: Hemolytic anemia, leukopenia, agranulocytosis, thrombocytopenia. Digestive System: Dryness of mouth, epigastric distress, anorexia, nausea, vomiting, diarrhea, constipation, jaundice. Genitourinary: Urinary frequency, difficult urination, urinary retention, early menses. Respiratory: Dryness of nose and throat, thickening of bronchial secretions, tightness of chest and wheezing, nasal stuffiness. Miscellaneous: Fatigue, chills, headache, increased appetite/weight gain. To report SUSPECTED ADVERSE REACTIONS, contact Patrin Pharma at 1-800-936-3088 or FDA at 1-800-FDA-1088."},{"title":"Drug interaction","body":"MAO inhibitors prolong and intensify the anticholinergic effects of antihistamines. Antihistamines may have additive effects with alcohol and other CNS depressants, e.g., hypnotics, sedatives, tranquilizers, antianxiety agents."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Pregnancy Category B Reproduction studies have been performed in rabbits, mice and rats at oral or subcutaneous doses up to 32 times the maximum recommended human oral dose and have revealed no evidence of impaired fertility or harm to the fetus due to cyproheptadine. Cyproheptadine has been shown to be fetotoxic in rats when given by intraperitoneal injection in doses four times the maximum recommended human oral dose. Two studies in pregnant women, however, have not shown that cyproheptadine increases the risk of abnormalities when administered during the first, second and third trimesters of pregnancy. No teratogenic effects were observed in any of the newborns. Nevertheless, because the studies in humans cannot rule out the possibility of harm, cyproheptadine should be used during pregnancy only if clearly needed. It is not known whether this drug is excreted in human milk. Because many drugs are excreted in human milk, and because of the potential for serious adverse reactions in nursing infants from cyproheptadine, a decision should be made whether to discontinue nursing or to discontinue the drug, taking into account the importance of the drug to the mother (see CONTRAINDICATIONS ). Safety and effectiveness in pediatric patients below the age of two years have not been established. (See CONTRAINDICATIONS, Newborn or Premature Infants , and WARNINGS, Children .)"},{"title":"การได้รับยาเกินขนาด","body":"Antihistamine overdosage reactions may vary from central nervous system depression to stimulation especially in children. Also, atropine-like signs and symptoms (dry mouth; fixed, dilated pupils; flushing, etc.) as well as gastrointestinal symptoms may occur. If vomiting has not occurred spontaneously, the patient should be induced to vomit with syrup of ipecac. If the patient is unable to vomit, perform gastric lavage followed by activated charcoal. Isotonic or 1/2 isotonic saline is the lavage of choice. Precautions against aspiration must be taken especially in infants and children. When life-threatening CNS signs and symptoms are present, intravenous physostigmine salicylate may be considered. Dosage and frequency of administration are dependent on age, clinical response and recurrence after response. (See package circulars for physostigmine products.) Saline cathartics, as milk of magnesia, by osmosis draw water into the bowel and, therefore, are valuable for their action in rapid dilution of bowel content. Stimulants should not be used. Vasopressors may be used to treat hypotension. The oral LD 50 of cyproheptadine is 123 mg/kg, and 295 mg/kg in the mouse and rat, respectively."},{"title":"การเก็บรักษา","body":"Store at 20-25°C (68-77°F). Excursion permitted 15-30°C (59-86°F) [see USP Controlled Room Temperature]. Dispense in a tight, light-resistant container as defined in the USP. NDC#39328-544-16 473 mL (16 FL. OZ.)"}]},
{"key":"dexamethasone sodium phosphate|INTRAVENOUS","generic":"dexamethasone sodium phosphate","route":"INTRAVENOUS","brand":null,"title":"Dexamethasone Sodium Phosphate","set_id":"0277cc0a-2fd4-4605-a310-b613be84ee26","effective":"20260122","sections":[{"title":"ข้อบ่งใช้","body":"INDICATIONS A. Intravenous or intramuscular administration. When oral therapy is not feasible and the strength, dosage form, and route of administration of the drug reasonably lend the preparation to the treatment of the condition, those products labeled for intravenous or intramuscular use are indicated as follows: 1. Endocrine disorders Primary or secondary adrenocortical insufficiency (hydrocortisone or cortisone is the drug of choice; synthetic analogs may be used in conjunction with mineralocorticoids where applicable; in infancy, mineralocorticoid supplementation is of particular importance) Acute adrenocortical insufficiency (hydrocortisone or cortisone is the drug of choice; mineralocorticoid supplementation may be necessary, particularly when synthetic analogs are used) Preoperatively, and in the event of serious trauma or illness, in patients with known adrenal insufficiency or when adrenocortical reserve is doubtful Shock unresponsive to conventional therapy if adrenocortical insufficiency exists or is suspected Congenital adrenal hyperplasia Nonsuppurative thyroiditis Hypercalcemia associated with cancer 2. Rheumatic disorders As adjunctive therapy for short-term administration (to tide the patient over an acute episode or exacerbation) in: Post-traumatic osteoarthritis Synovitis of osteoarthritis Rheumatoid arthritis, including juvenile rheumatoid arthritis (selected cases may require low-dose maintenance therapy) Acute and subacute bursitis Epicondylitis Acute nonspecific tenosynovitis Acute gouty arthritis Psoriatic arthritis Ankylosing spondylitis 3. Collagen diseases During an exacerbation or as maintenance therapy in selected cases of: Systemic lupus erythematosus Acute rheumatic carditis 4. Dermatologic diseases Pemphigus Severe erythema multiforme (Stevens-Johnson Syndrome) Exfoliative dermatitis Bullous dermatitis herpetiformis Severe seborrheic dermatitis Severe psoriasis Mycosis fungoides 5. Allergic states Control of severe or incapacitating allergic conditions intractable to adequate trials of conventional treatment in: Bronchial asthma Contact dermatitis Atopic dermatitis Serum sickness Seasonal or perennial allergic rhinitis Drug hypersensitivity reactions Urticarial transfusion reactions Acute noninfectious laryngeal edema (epinephrine is the drug of first choice) 6. …"},{"title":"ขนาดยาและวิธีใช้","body":"A. Intravenous or intramuscular administration. The initial dosage of Dexamethasone Sodium Phosphate Injection may vary from 0.50 mg/day to 9.0 mg/day depending on the specific disease entity being treated. In situations of less severity, lower doses will generally suffice while in selected patients higher initial doses may be required. Usually the parenteral dosage ranges are one-third to one-half the oral dose given every 12 hours. However, in certain overwhelming, acute, life-threatening situations, administration of dosages exceeding the usual dosages may be justified and may be in multiples of the oral dosages. For the treatment of unresponsive shock high pharmacologic doses of this product are currently recommended. Reported regimens range from 1 to 6 mg/kg of body weight as a single intravenous injection to 40 mg initially followed by repeat intravenous injection every 2 to 6 hours while shock persists. For the treatment of cerebral edema in adults an initial intravenous dose of 10 mg is recommended followed by 4 mg intramuscularly every six hours until maximum response has been noted. This regimen may be continued for several days postoperatively in patients requiring brain surgery. Oral dexamethasone, 1 to 3 mg t.i.d., should be given as soon as possible and dosage tapered off over a period of five to seven days. Nonoperative cases may require continuous therapy to remain free of symptoms of increased intracranial pressure. The smallest effective dose should be used in children, preferably orally. This may approximate 0.2 mg/kg/24 hours in divided doses. In treatment of acute exacerbations of multiple sclerosis daily doses of 200 mg of prednisolone for a week followed by 80 mg every other day or 4–8 mg dexamethasone every other day for 1 month have been shown to be effective. The initial dosage should be maintained or adjusted until a satisfactory response is noted. If after a reasonable period of time there is a lack of satisfactory clinical response, Dexamethasone Sodium Phosphate Injection should be discontinued and the patient transferred to other appropriate therapy. It should be emphasized that dosage requirements are variable and must be individualized on the basis of the disease under treatment and the response of the patient. …"},{"title":"ข้อห้ามใช้","body":"Systemic fungal infections."},{"title":"คำเตือนและข้อควรระวัง","body":"Serious Neurologic Adverse Reactions with Epidural Administration Serious neurologic events, some resulting in death, have been reported with epidural injection of corticosteroids. Specific events reported include, but are not limited to, spinal cord infarction, paraplegia, quadriplegia, cortical blindness, and stroke. These serious neurologic events have been reported with and without use of fluoroscopy. The safety and effectiveness of epidural administration of corticosteroids have not been established, and corticosteroids are not approved for this use. In patients on corticosteroid therapy subject to any unusual stress, increased dosage of rapidly acting corticosteroids before, during and after the stressful situation is indicated. Immunosuppression and Increased Risk of Infection Corticosteroids, including Dexamethasone Sodium Phosphate, suppress the immune system and increase the risk of infection with any pathogen, including viral, bacterial, fungal, protozoan, or helminthic pathogens. Corticosteroids can: Reduce resistance to new infections Exacerbate existing infections Increase the risk of disseminated infections Increase the risk of reactivation or exacerbation of latent infections Mask some signs of infection Corticosteroid-associated infections can be mild but can be severe and at times fatal. The rate of infectious complications increases with increasing corticosteroid dosages. Monitor for the development of infection and consider Dexamethasone Sodium Phosphate withdrawal or dosage reduction as needed. Tuberculosis If Dexamethasone Sodium Phosphate is used to treat a condition in patients with latent tuberculosis or tuberculin reactivity, tuberculosis may occur. Closely monitor such patients for reactivation. During prolonged therapy, patients with latent tuberculosis or tuberculin reactivity should receive chemoprophylaxis. Varicella Zoster and Measles Viral Infections Varicella and measles can have a serious or even fatal course in non-immune patients taking corticosteroids, including Dexamethasone Sodium Phosphate. In corticosteroid-treated patients who have not had these diseases or are non- immune, particular care should be taken to avoid exposure to varicella and measles: If a Dexamethasone Sodium Phosphate -treated patient is exposed to varicella, prophylaxis with varicella zoster immune globulin may be indicated. If varicella develops, treatment with antiviral agents may be considered. …"},{"title":"อาการไม่พึงประสงค์","body":"Fluid and electrolyte disturbances: Sodium retention Fluid retention Congestive heart failure in susceptible patients Potassium loss Hypokalemic alkalosis Hypertension Musculoskeletal: Muscle weakness Steroid myopathy Loss of muscle mass Osteoporosis Vertebral compression fractures Aseptic necrosis of femoral and humeral heads Pathologic fracture of long bones Gastrointestinal: Peptic ulcer with possible subsequent perforation and hemorrhage Pancreatitis Abdominal distention Ulcerative esophagitis Dermatological: Impaired wound healing Thin fragile skin Facial erythema Increased sweating May suppress reactions to skin tests Petechiae and ecchymoses Neurological: Convulsions Increased intracranial pressure with papilledema (pseudotumor cerebri) usually after treatment Vertigo Headache Ophthalmic: Posterior subcapsular cataracts Increased intraocular pressure Glaucoma Endocrine: Menstrual irregularities Development of cushingoid state Suppression of growth in children Secondary adrenocortical and pituitary unresponsiveness, particularly in times of stress, as in trauma, surgery, or illness Decreased carbohydrate tolerance Manifestations of latent diabetes mellitus Increased requirements for insulin or oral hypoglycemic agents in diabetics Metabolic: Negative nitrogen balance due to protein catabolism Miscellaneous: Hyperpigmentation or hypopigmentation Subcutaneous and cutaneous atrophy Sterile abscess Postinjection flare following intra-articular use Charcot-like arthropathy Itching, burning, tingling in the ano-genital region"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Usage in Pregnancy Since adequate human reproduction studies have not been done with corticosteroids, use of these drugs in pregnancy, nursing mothers or women of childbearing potential requires that the possible benefits of the drug be weighed against the potential hazards to the mother and embryo or fetus. Infants born of mothers who have received substantial doses of corticosteroids during pregnancy should be carefully observed for signs of hypoadrenalism. Average and large doses of cortisone or hydrocortisone can cause elevation of blood pressure, salt and water retention, and increased excretion of potassium. These effects are less likely to occur with the synthetic derivatives except when used in large doses. Patients with a stressed myocardium should be observed carefully and the drug administered slowly since premature ventricular contractions may occur with rapid administration. Dietary salt restriction and potassium supplementation may be necessary. All corticosteroids increase calcium excretion. While on corticosteroid therapy patients should not be vaccinated against smallpox. Other immunization procedures should not be undertaken in patients who are on corticosteroids, especially in high doses, because of possible hazards of neurological complications and lack of antibody response. The use of Dexamethasone Sodium Phosphate Injection in active tuberculosis should be restricted to those cases of fulminating or disseminated tuberculosis in which the corticosteroid is used for the management of the disease in conjunction with an appropriate anti-tuberculosis regimen. If corticosteroids are indicated in patients with latent tuberculosis or tuberculin reactivity, close observation is necessary as reactivation of the disease may occur. During prolonged corticosteroid therapy, these patients should receive chemoprophylaxis. Because rare instances of anaphylactoid reactions have occurred in patients receiving parenteral corticosteroid therapy, appropriate precautionary measures should be taken prior to administration, especially when the patient has a history of allergy to any drug. Dexamethasone Sodium Phosphate Injection contains sodium sulfite, a sulfite that may cause allergic type reactions including anaphylactic symptoms and life-threatening or less severe asthmatic episodes in certain susceptible people. The overall prevalence of sulfite sensitivity in the general population is unknown and probably low. …"},{"title":"การเก็บรักษา","body":"Storage Protect from light: Keep covered in carton until time of use. Store at 20° to 25°C (68° to 77°F), excursions permitted to 15° to 30°C (59° to 86°F) [See USP Controlled Room Temperature]. Avoid freezing. Do not use if solution is hazy or has a precipitate. Do not autoclave. To report SUSPECTED ADVERSE REACTIONS, contact Hikma Pharmaceuticals USA Inc. at 1-877-845-0689, or the FDA at 1-800-FDA-1088 or www.fda.gov/medwatch. For Product Inquiry call 1-877-845-0689. Manufactured by: Hikma Pharmaceuticals USA Inc. Berkeley Heights, NJ 07922 USA Revised December 2024 462-331-09"}]},
{"key":"dextromethorphan hydrobromide|ORAL","generic":"dextromethorphan hydrobromide","route":"ORAL","brand":null,"title":"MUCINEX INSTASOOTHE COUGH","set_id":"0d99237c-0b52-0af6-e063-6394a90aba14","effective":"20260803","sections":[{"title":"ข้อบ่งใช้","body":"temporarily: ■ relieves cough due to minor throat and bronchial irritation as may occur with the common cold or inhaled irritants ■ helps reduce the intensity of coughing"},{"title":"ขนาดยาและวิธีใช้","body":"Label"},{"title":"คำเตือนและข้อควรระวัง","body":"Do Not Use ■ if you are now taking a prescription monoamine oxidase inhibitor (MAOI) (certain drugs for depression, psychiatric, or emotional conditions, or Parkinson’s disease), or for 2 weeks after stopping the MAOI drug. If you do not know if your prescription drug contains an MAOI, ask a doctor or pharmacist before taking this product. Ask a doctor before use if you have ■ persistent or chronic cough such as occurs with smoking, asthma, or emphysema ■ cough that occurs with too much phlegm (mucus) Stop use and ask a doctor if cough lasts more than 7 days, comes back, or occurs with fever, rash, or persistent headache. These could be signs of a serious condition. If pregnant or breastfeeding, ask a health professional before use."}]},
{"key":"dextrose monohydrate and sodium chloride|INTRAVENOUS","generic":"dextrose monohydrate and sodium chloride","route":"INTRAVENOUS","brand":null,"title":"Dextrose and Sodium Chloride","set_id":"99c6a1a9-cadf-435b-a332-ccc189afdfa9","effective":"20260416","sections":[{"title":"ข้อบ่งใช้","body":"Intravenous solutions containing dextrose and sodium chloride are indicated for parenteral replenishment of fluid, minimal carbohydrate calories, and sodium chloride as required by the clinical condition of the patient."},{"title":"ขนาดยาและวิธีใช้","body":"The dose is dependent upon the age, weight and clinical condition of the patient. As reported in the literature, the dosage and constant infusion rate of intravenous dextrose must be selected with caution in pediatric patients, particularly neonates and low birth weight infants, because of the increased risk of hyperglycemia/hypoglycemia. Parenteral drug products should be inspected visually for particulate matter and discoloration prior to administration, whenever solution and container permit. See PRECAUTIONS . Drug Interactions Additives may be incompatible. Consult with pharmacist, if available. When introducing additives, use aseptic technique, mix thoroughly and do not store."},{"title":"ข้อห้ามใช้","body":"None known."},{"title":"คำเตือนและข้อควรระวัง","body":"Solutions containing sodium ions should be used with great care, if at all, in patients with congestive heart failure, severe renal insufficiency and in clinical states in which there exists edema with sodium retention. Excessive administration of potassium-free solutions may result in significant hypokalemia. In patients with diminished renal function, administration of solutions containing sodium ions may result in sodium retention. The intravenous administration of these solutions can cause fluid and/or solute overloading resulting in dilution of serum electrolyte concentrations, overhydration, congested states or pulmonary edema. The risk of dilutional states is inversely proportional to the electrolyte concentrations of administered parenteral solutions. The risk of solute overload causing congested states with peripheral and pulmonary edema is directly proportional to the electrolyte concentrations of such solutions. Clinical evaluation and periodic laboratory determinations are necessary to monitor changes in fluid balance, electrolyte concentrations and acid-base balance during prolonged parenteral therapy or whenever the condition of the patient warrants such evaluation. Solutions containing dextrose should be used with caution in patients with known subclinical or overt diabetes mellitus. Caution must be exercised in the administration of parenteral fluids, especially those containing sodium ions to patients receiving corticosteroids or corticotropin. Do not administer unless solution is clear and container is undamaged. Discard unused portion. Pregnancy Category C. Animal reproduction studies have not been conducted with dextrose or sodium chloride. It is also not known whether dextrose or sodium chloride can cause fetal harm when administered to a pregnant woman or can affect reproduction capacity. Dextrose or sodium chloride should be given to a pregnant woman only if clearly needed. Pediatric Use. The safety and effectiveness in the pediatric population are based on the similarity of the clinical conditions of the pediatric and adult populations. In neonates or very small infants, the volume of fluid may affect fluid and electrolyte balance. Frequent monitoring of serum glucose concentrations is required when dextrose is prescribed to pediatric patients, particularly neonates and low birth weight infants. …"},{"title":"อาการไม่พึงประสงค์","body":"Reactions which may occur because of the solution or the technique of administration include febrile response, infection at the site of injection, venous thrombosis or phlebitis extending from the site of injection, extravasation and hypervolemia. If an adverse reaction does occur, discontinue the infusion, evaluate the patient, institute appropriate therapeutic countermeasures and save the remainder of the fluid for examination if deemed necessary."},{"title":"Drug interaction","body":"Additives may be incompatible. Consult with pharmacist, if available. When introducing additives, use aseptic technique, mix thoroughly and do not store."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Category C. Animal reproduction studies have not been conducted with dextrose or sodium chloride. It is also not known whether dextrose or sodium chloride can cause fetal harm when administered to a pregnant woman or can affect reproduction capacity. Dextrose or sodium chloride should be given to a pregnant woman only if clearly needed. Pediatric Use. The safety and effectiveness in the pediatric population are based on the similarity of the clinical conditions of the pediatric and adult populations. In neonates or very small infants, the volume of fluid may affect fluid and electrolyte balance. Frequent monitoring of serum glucose concentrations is required when dextrose is prescribed to pediatric patients, particularly neonates and low birth weight infants. In very low birth weight infants, excessive or rapid administration of dextrose injection may result in increased serum osmolality and possible intracerebral hemorrhage. Geriatric Use. An evaluation of current literature revealed no clinical experience identifying differences in response between elderly and younger patients. In general, dose selection for an elderly patient should be cautious, usually starting at the low end of the dosing range, reflecting the greater frequency of decreased hepatic, renal, or cardiac function, and of concomitant disease or other drug therapy. Sodium ions are known to be substantially excreted by the kidney, and the risk of toxic reactions may be greater in patients with impaired renal function. Because elderly patients are more likely to have decreased renal function, care should be taken in dose selection, and it may be useful to monitor renal function."},{"title":"การได้รับยาเกินขนาด","body":"In the event of overhydration or solute overload, re-evaluate the patient and institute appropriate corrective measures. See WARNINGS , PRECAUTIONS , and ADVERSE REACTIONS ."}]},
{"key":"dextrose monohydrate|INTRAVENOUS","generic":"dextrose monohydrate","route":"INTRAVENOUS","brand":null,"title":"Dextrose","set_id":"3b8f2692-4371-4f1a-95af-b41842131fdd","effective":"20260313","sections":[{"title":"ข้อบ่งใช้","body":"Dextrose Injection is indicated as source of water and calories. Dextrose Injection is indicated as a source of water and calories. ( 1 )"},{"title":"ขนาดยาและวิธีใช้","body":"Only for intravenous infusion. ( 2.1 ) See full prescribing information for information on preparation, administration, dosing considerations and instructions for use. ( 2.1 , 2.2 , 2.3 ) 2.1 Important Administration Instructions Dextrose Injection is intended for intravenous use. Peripheral administration of 5% dextrose is generally acceptable, however, consider central vein when administering more than 5% dextrose or with an osmolarity of at least 900 mOsm/L or when there is peripheral vein irritation, phlebitis, and/or associated pain [see Warnings and Precautions ( 5.3 )] . Do not administer Dextrose Injection simultaneously with blood products through the same administration set because of the possibility of pseudoagglutination or hemolysis. To prevent air embolism, use a non-vented infusion set or close the vent on a vented set, avoid multiple connections, do not connect flexible containers in series, fully evacuate residual gas in the container prior to administration, do not pressurize the flexible container to increase flow rates, and if administration is controlled by a pumping device, turn off pump before the container runs dry. Prior to infusion, visually inspect the diluted dextrose solution for particulate matter. The solution should be clear and there should be no precipitates. Do not administer unless solution is clear and container is undamaged. Use of a final filter is recommended during administration of parenteral solutions, where possible. 2.2 Recommended Dosage The choice of dextrose concentration, rate and volume depends on the age, weight, clinical and metabolic conditions of the patient and concomitant therapy. Electrolyte supplementation may be indicated according to the clinical needs of the patient. The administration rate should be governed, especially for premature infants with low birth weight, during the first few days of therapy, by the patient's tolerance to dextrose. Increase the infusion rate gradually as indicated by frequent monitoring of blood glucose concentrations [see Warnings and Precautions ( 5.1 ), Use in Specific Populations ( 8.4 )] . 2.3 Instructions for Use Check flexible container solution composition, lot number, and expiry date. Prior to administration, visually inspect for particulate matter and discoloration. The intact port caps provides visual tamper evidence. Do not use if a port cap is prematurely removed. Do not remove solution container from its overwrap until immediately before use. …"},{"title":"ข้อห้ามใช้","body":"The use of Dextrose Injection is contraindicated in patients with: Clinically significant hyperglycemia [see Warnings and Precautions ( 5.1 )] . Known hypersensitivity to dextrose [see Warnings and Precautions ( 5.2 )] . Clinically significant hyperglycemia. ( 4 ) Known hypersensitivity to dextrose. ( 4 )"},{"title":"คำเตือนและข้อควรระวัง","body":"Hyperglycemia or Hyperosmolar Hyperglycemic State : Monitor blood glucose and administer insulin as needed. ( 5.1 ) Hypersensitivity Reactions : Monitor for signs and symptoms and discontinue infusion if reactions occur. ( 5.2 ) Vein Damage and Thrombosis : Consider central vein when administering more than 5% dextrose or with an osmolarity of at least 900 mOsm/L or when there is peripheral vein irritation, phlebitis, and/or associated pain. ( 2.2 , 5.3 ) Hyponatremia : Avoid in patients with or at risk for hyponatremia. If use cannot be avoided, monitor serum sodium concentrations. ( 5.4 ) Electrolyte Imbalance and Fluid Overload : Avoid in patients with or at risk for fluid and/or solute overloading. If use cannot be avoided, monitor daily fluid balance, electrolyte concentrations, and acid-base balance, as needed and especially during prolonged use. ( 5.5 ) Refeeding Syndrome : Monitor severely undernourished patients and slowly increase nutrient intake. ( 5.6 ) 5.1 Hyperglycemia and Hyperosmolar Hyperglycemic State The use of dextrose infusions in patients with impaired glucose tolerance may worsen hyperglycemia. Administration of dextrose at a rate exceeding the patient's utilization rate may lead to hyperglycemia, coma, and death. Hyperglycemia is associated with an increase in serum osmolality, resulting in osmotic diuresis, dehydration and electrolyte losses [see Warnings and Precautions ( 5.5 )] . Patients with underlying CNS disease and renal impairment who receive dextrose infusions, may be at greater risk of developing hyperosmolar hyperglycemic state. Monitor blood glucose levels and treat hyperglycemia to maintain levels within normal limits while administering Dextrose Injection. Insulin may be administered or adjusted to maintain optimal blood glucose levels during Dextrose Injection administration. 5.2 Hypersensitivity Reactions Hypersensitivity and infusion reactions, including anaphylaxis, have been reported with Dextrose Injection [see Adverse Reactions ( 6 )] . Stop infusion immediately and treat patient accordingly if signs or symptoms of a hypersensitivity reaction develop. Appropriate therapeutic countermeasures must be instituted as clinically indicated. …"},{"title":"อาการไม่พึงประสงค์","body":"The following adverse reactions associated with the use of dextrose injection were identified in clinical trials or postmarketing reports. Because these reactions were reported voluntarily from a population of uncertain size, it is not always possible to estimate their frequency, reliably, or to establish a causal relationship to drug exposure. The following clinically significant adverse reactions are described elsewhere in the labeling: Hyperglycemia and hyperosmolar hyperglycemic state [see Warnings and Precautions ( 5.1 )] Hypersensitivity Reactions : anaphylaxis, pruritus, bronchospasm, cyanosis, angioedema, hypotension, pyrexia, chills, and rash [see Warnings and Precautions ( 5.2 )] Infusion Site Reactions : infusion site phlebitis, infusion site erythema, vein damage and thrombosis, and infusion site thrombophlebitis [see Warnings and Precautions ( 5.3 )] Hyponatremia and hyponatremic encephalopathy [see Warnings and Precautions ( 5.4 )] Electrolyte imbalance, fluid overload and hypervolemia [see Warnings and Precautions ( 5.5 )] Refeeding syndrome [see Warnings and Precautions ( 5.6 )] Pulmonary vascular precipitates The most common adverse reactions are, hyperglycemia, hypersensitivity reactions, hyponatremia, infection both systemic and at the injection site, vein thrombosis or phlebitis, and electrolyte imbalance. ( 6 ) To report SUSPECTED ADVERSE REACTIONS, contact Fresenius Kabi USA, LLC at 1-800-551-7176 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch."},{"title":"Drug interaction","body":"Other Products that Affect Glycemic Control, Vasopressin or Fluid and/or Electrolyte Balance : Monitor blood glucose concentrations, fluid balance, serum electrolyte concentrations and acid-base balance. ( 7.1 ) 7.1 Other Products that Affect Glycemic Control, Vasopressin or Fluid and/or Electrolyte Balance Dextrose Injection can affect glycemic control, vasopressin and fluid and/or electrolyte balance [see Warnings and Precautions ( 5.1 , 5.4 , 5.5 )] . Monitor blood glucose concentrations, fluid balance, serum electrolyte concentrations and acid-base balance when using Dextrose Injection in patients treated with other substances that affect glycemic control, vasopressin or fluid and/or electrolyte balance."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Appropriate administration of Dextrose Injection during pregnancy is not expected to cause adverse developmental outcomes, including congenital malformations. Animal reproduction studies have not been conducted with injectable dextrose solutions. The estimated background risk of major birth defects and miscarriage for the indicated population is unknown. All pregnancies have a background risk of birth defect, loss, or other adverse outcomes. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2 to 4% and 15 to 20%, respectively. 8.4 Pediatric Use The safety profile of Dextrose Injection in pediatric patients is similar to adults. Neonates, especially premature infants with low birth weight, are at increased risk of developing hypo- or hyperglycemia and therefore need close monitoring during treatment with intravenous glucose infusions to ensure adequate glycemic control in order to avoid potential long-term adverse effects. Closely monitor plasma electrolyte concentrations in pediatric patients who may have impaired ability to regulate fluids and electrolytes. In very low birth weight infants, excessive or rapid administration of Dextrose Injection may result in increased serum osmolality and risk of intracerebral hemorrhage. Children (including neonates and older children) are at increased risk of developing hyponatremia as well as for developing hyponatremic encephalopathy [see Warnings and Precautions ( 5.4 )] . 8.5 Geriatric Use Clinical studies of Dextrose Injection did not include sufficient numbers of subjects aged 65 and over to determine whether they respond differently from younger subjects. Elderly patients are at increased risk of developing hyponatremia as well as for developing hyponatremic encephalopathy [see Warnings and Precautions ( 5.4 )] . Other reported clinical experience has not identified differences in responses between the elderly and younger patients. In general, dose selection for an elderly patient should be cautious, usually starting at the low end of the dosing range, reflecting the greater frequency of decreased hepatic, renal, or cardiac function, and of concomitant disease or other drug therapy. Dextrose is known to be substantially excreted by the kidney, and the risk of toxic reactions to this drug may be greater in patients with impaired renal function. …"},{"title":"การได้รับยาเกินขนาด","body":"An increased infusion rate of Dextrose Injection or administration of dextrose solutions can cause hyperglycemia, hyperosmolality, and adverse effects on water and electrolyte balance [see Warnings and Precautions ( 5.1 , 5.5 )]. Severe hyperglycemia and severe dilutional hyponatremia, and their complications, can be fatal. Discontinue infusion, reduce dose and institute appropriate corrective measures such as administration of exogenous insulin. Discontinue infusion and institute appropriate corrective measures in the event of overhydration or solute overload during therapy, with particular attention to CNS, respiratory and cardiovascular systems. If over-exposure occurs, call your Poison Control Center at 1-800-222-1222 for current information on the management of poisoning or overdosage."},{"title":"การเก็บรักษา","body":"STORE AT: 20° to 25 °C ( 68° to 77° F) [see USP Controlled Room Temperature]; brief exposure up to 40°C/104°F does not adversely affect the product. The container closure is not made with natural rubber latex. Non-PVC, Non-DEHP, Sterile."}]},
{"key":"diclofenac sodium|ORAL","generic":"diclofenac sodium","route":"ORAL","brand":null,"title":"Diclofenac Sodium Delayed Release","set_id":"0cefb675-c54e-44eb-b35c-38354b77eddd","effective":"20260206","sections":[{"title":"ข้อบ่งใช้","body":"Carefully consider the potential benefits and risks of diclofenac sodium delayed-release tablets and other treatment options before deciding to use diclofenac. Use the lowest effective dose for the shortest duration consistent with individual patient treatment goals ( see WARNINGS; Gastrointestinal Bleeding, Ulceration, and Perforation ). Diclofenac is indicated: For relief of the signs and symptoms of osteoarthritis For relief of the signs and symptoms of rheumatoid arthritis For acute or long-term use in the relief of signs and symptoms of ankylosing spondylitis"},{"title":"ขนาดยาและวิธีใช้","body":"Carefully consider the potential benefits and risks of diclofenac sodium delayed-release tablets and other treatment options before deciding to use diclofenac. Use the lowest effective dose for the shortest duration consistent with individual patient treatment goals (see WARNINGS; Gastrointestinal Bleeding, Ulceration, and Perforation ) . After observing the response to initial therapy with diclofenac, the dose and frequency should be adjusted to suit an individual patient's needs. For the relief of osteoarthritis, the recommended dosage is 100-150 mg/day in divided doses (50 mg twice a day or three times a day, or 75 mg twice a day). For the relief of rheumatoid arthritis, the recommended dosage is 150-200 mg/day in divided doses (50 mg three times a day. or four times a day, or 75 mg twice a day.). For the relief of ankylosing spondylitis, the recommended dosage is 100-125 mg/day, administered as 25 mg four times a day, with an extra 25-mg dose at bedtime if necessary."},{"title":"ข้อห้ามใช้","body":"Diclofenac sodium delayed-release tablets are contraindicated in the following patients: Known hypersensitivity (e.g., anaphylactic reactions and serious skin reactions) to diclofenac or any components of the drug product ( see WARNINGS; Anaphylactic Reactions , Serious Skin Reactions ). History of asthma, urticaria, or other allergic-type reactions after taking aspirin or other NSAIDs. Severe, sometimes fatal, anaphylactic reactions to NSAIDs have been reported in such patients ( see WARNINGS; Anaphylactic Reaction , Exacerbation of Asthma Related to Aspirin Sensitivity ). In the setting of coronary artery bypass graft (CABG) surgery ( see Warnings; Cardiovascular Thrombotic Events )."},{"title":"คำเตือนกรอบดำ","body":"WARNING: RISK OF SERIOUS CARDIOVASCULAR AND GASTROINTESTINAL EVENTS Cardiovascular Thrombotic Events Nonsteroidal anti-inflammatory drugs (NSAIDs) cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction and stroke, which can be fatal. This risk may occur early in treatment and may increase with duration of use (see WARNINGS ). Diclofenac sodium delayed-release tablets are contraindicated in the setting of coronary artery bypass graft (CABG) surgery (see CONTRAINDICATIONS , WARNINGS ). Gastrointestinal Bleeding, Ulceration, And Perforation NSAIDs cause an increased risk of serious gastrointestinal (GI) adverse events including bleeding, ulceration, and perforation of the stomach or intestines, which can be fatal. These events can occur at any time during use and without warning symptoms. Elderly patients and patients with a prior history of peptic ulcer disease and/or GI bleeding are at greater risk for serious GI events (see WARNINGS )."},{"title":"คำเตือนและข้อควรระวัง","body":"Cardiovascular Thromboic Events Clinical trials of several COX-2 selective and nonselective NSAIDs of up to three years duration have shown an increased risk of serious cardiovascular (CV) thrombotic events, including myocardial infarction (MI), and stroke, which can be fatal. Based on available data, it is unclear that the risk for CV thrombotic events is similar for all NSAIDs. The relative increase in serious CV thrombotic events over baseline conferred by NSAID use appears to be similar in those with and without known CV disease or risk factors for CVdisease. However, patients with known CV disease or risk factors had a higher absolute incidence of excess serious CV thrombotic events, due to their increased baseline rate. Some observational studies found that this increased risk of serious CV thrombotic events began as early as the first weeks of treatment. The increase in CV thrombotic risk has been observed most consistently at higher doses. To minimize the potential risk for an adverse CV event in NSAID-treated patients, use the lowest effective dose for the shortest duration possible. Physicians and patients should remain alert for the development of such events, throughout the entire treatment course, even in the absence of previous CV symptoms. Patients should be informed about the symptoms of serious CV events and the There is no consistent evidence that concurrent use of aspirin mitigates the increased risk of serious CV thrombotic events associated with NSAID use. The concurrent use of aspirin and an NSAID, such as diclofenac, increases the risk of serious gastrointestinal (GI) events (see WARNINGS; Gastrointestinal Bleeding, Ulceration, and Perforation ). Status Post Coronary Artery Bypass Graft (CABG) Surgery Two large, controlled, clinical trials of a COX-2 selective NSAID for the treatment of pain in the first 10 -14 days following CABG surgery found an increased incidence of myocardial infarction and stroke. NSAIDs are contraindicated in the setting of CABG (see CONTRAINDICATIONS ). Post-MI Patients Observational studies conducted in the Danish National Registry have demonstrated that patients treated with NSAIDs in the post-MI period were at increased risk of reinfarction, CV-related death, and all-cause mortality beginning in the first week of treatment. …"},{"title":"อาการไม่พึงประสงค์","body":"SECTION The following adverse reactions are discussed in greater detail in other sections of the labeling: Cardiovascular Thrombotic Events (see WARNINGS ) GI Bleeding, Ulceration and Perforation (see WARNINGS ) Hepatotoxicity (see WARNINGS ) Hypertension (see WARNINGS ) Heart Failure and Edema (see WARNINGS ) Renal Toxicity and Hyperkalemia (see WARNINGS ) Anaphylactic Reactions (see WARNINGS ) Serious Skin Reactions (see WARNINGS ) Hematologic Toxicity (see WARNINGS ) Clinical Trials Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical trials of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in practice. In patients taking diclofenac sodium delayed-release tablets, or other NSAIDs, the most frequently reported adverse experiences occurring in approximately 1%-10% of patients are: Gastrointestinal experiences including: abdominal pain, constipation, diarrhea, dyspepsia, flatulence, gross bleeding/perforation, heartburn, nausea, GI ulcers (gastric/duodenal) and vomiting. Abnormal renal function, anemia, dizziness, edema, elevated liver enzymes, headaches, increased bleeding time, pruritus, rashes and tinnitus. Additional adverse experiences reported occasionally include: Body as a Whole: fever, infection, sepsis Cardiovascular System : congestive heart failure, hypertension, tachycardia, syncope Digestive System: dry mouth, esophagitis, gastric/peptic ulcers, gastritis, gastrointestinal bleeding, glossitis, hematemesis, hepatitis, jaundice Hemic and Lymphatic System : ecchymosis, eosinophilia, leukopenia, melena, purpura, rectal bleeding, stomatitis, thrombocytopenia Metabolic and Nutritional : weight changes Nervous System : anxiety, asthenia, confusion, depression, dream abnormalities, drowsiness, insomnia,malaise, nervousness, paresthesia, somnolence, tremors, vertigo Respiratory System : asthma, dyspnea Skin and Appendages : alopecia, photosensitivity, sweating increased Special Senses : blurred vision Urogenital System : cystitis, dysuria, hematuria, interstitial nephritis, oliguria/ polyuria, proteinuria, re …"},{"title":"Drug interaction","body":"See Table 2 for clinically significant drug interactions with diclofenac. Table 2: Clinically Significant Drug Interactions with Diclofenac Drugs That Interfere with Hemostasis Clinical Impact: Diclofenac and anticoagulants such as warfarin have a synergistic effect on bleeding. The concomitant use of diclofenac and anticoagulants have an increased risk of serious bleeding compared to the use of either drug alone. Serotonin release by platelets plays an important role in hemostasis. Case-control and cohort epidemiological studies showed that concomitant use of drugs that interfere with serotonin reuptake and an NSAID may potentiate the risk of bleeding more than an NSAID alone. Intervention: Monitor patients with concomitant use of diclofenac with anticoagulants (e.g., warfarin), antiplatelet agents (e.g., aspirin), selective serotonin reuptake inhibitors (SSRIs), and serotonin norepinephrine reuptake inhibitors (SNRIs) for signs of bleeding ( see PRECAUTIONS ; Hematological Toxicity ). Aspirin Clinical Impact: Controlled clinical studies showed that the concomitant use of NSAIDs and analgesic doses of aspirin does not produce any greater therapeutic effect than the use of NSAIDs alone. In a clinical study, the concomitant use of an NSAID and aspirin was associated with a significantly increased incidence of GI adverse reactions as compared to use of the NSAID alone (see WARNINGS; Gastrointestinal Bleeding, Ulceration, and Perforation ) . Intervention: Concomitant use of diclofenac and analgesic doses of aspirin is not generally recommended because of the increased risk of bleeding ( see PRECAUTIONS: Hematological Toxicity ). Diclofenac is not a substitute for low dose aspirin for cardiovascular protection. ACE Inhibitors, Angiotensin Receptor Blockers, and Beta-Blockers Clinical Impact: NSAIDs may diminish the antihypertensive effect of angiotensin converting enzyme (ACE) inhibitors, angiotensin receptor blockers (ARBs), or beta-blockers (including propranolol). In patients who are elderly, volume-depleted (including those on diuretic therapy), or have renal impairment, co-administration of an NSAID with ACE inhibitors or ARBs may result in deterioration of renal function, including possible acute renal failure. These effects are usually reversible Intervention: During concomitant use of diclofenac and ACE-inhibitors, ARBs, or betablockers, monitor blood pressure to ensure that the desired blood pressure is obtained. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Section Risk Summary Use of NSAIDs, including diclofenac, can cause premature closure of the fetal ductus arteriosusand fetal renal dysfunction leading to oligohydramnios and, in some cases, neonatal renal impairment. Because of these risks, limit dose and duration of Diclofenac Sodium use between about 20 and 30 weeks of gestation, and avoid Diclofenac Sodium use at about 30 weeks of gestation and later in pregnancy. Premature Closure of Fetal Ductus Arteriosus Use of NSAIDs, including Diclofenac Sodium, at about 30 weeks gestation or later in pregnancy increases the risk of premature closure of the fetal ductus arteriosus. Oligohydramnios/Neonatal Renal Impairment Use of NSAIDs at about 20 weeks gestation or later in pregnancy has been associated with cases of fetal renal dysfunction leading to oligohydramnios, and in some cases, neonatal renal impairment. Data from observational studies regarding other potential embryofetal risks of NSAID use in women in the first or second trimesters of pregnancy are inconclusive. In animal reproduction studies, no evidence of teratogenicity was observed in mice, rats or rabbits given diclofenac during the period of organogenesis at doses up to approximately 0.5 and 1 times, respectively, the maximum recommended human dose (MRHD) of diclofenac sodium delayedrelease, 200mg/day, despite the presence of maternal and fetal toxicity at these doses (see Data ). The estimated background risk of major birth defects and miscarriage for the indicated population(s) is unknown. All pregnancies have a background risk of birth defect, loss, or other adverse outcomes. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2-4% and 15-20%, respectively. [see WARNINGS; Fetal Toxicity ]. Clinical Considerations Fetal/Neonatal Adverse Reactions Premature Closure of Fetal Ductus Arteriosus: Avoid use of NSAIDs in women at about 30 weeks gestation and later in pregnancy, because NSAIDs, including Diclofenac Sodium, can cause premature closure of the fetal ductus arteriosus (see WARNINGS; Fetal Toxicity ). Oligohydramnios/Neonatal Renal Impairment If an NSAID is necessary at about 20 weeks gestation or later in pregnancy, limit the use to the lowest effective dose and shortest duration possible. If Diclofenac Sodium treatment extends beyond 48 hours, consider monitoring with ultrasound for oligohydramnios. …"},{"title":"การได้รับยาเกินขนาด","body":"Symptoms following acute NSAID overdosages have been typically limited to lethargy, drowsiness, nausea, vomiting, and epigastric pain, which have been generally reversible with supportive care. Gastrointestinal bleeding has occurred. Hypertension, acute renal failure, respiratory depression and coma have occurred, but were rare. (see WARNINGS; Cardiovascular Thrombotic Events , Gastrointestinal Bleeding, Ulceration, and Perforation , Hypertension , Renal Toxicity and Hyperkalemia ) . Manage patients with symptomatic and supportive care following an NSAID overdosage. There are no specific antidotes. Consider emesis and/or activated charcoal (60 to 100 grams in adults, 1 to 2 grams per kg of body weight in pediatric patients) and/or osmotic cathartic in symptomatic patients seen within four hours of ingestion or in patients with a large overdose (5 to 10 times the recommended dosage). Forced diuresis, alkalinization of urine, hemodialysis, or hemoperfusion may not be useful due to high protein binding. For additional information about overdosage treatment contact a poison control center (1-800-222-1222)."}]},
{"key":"dicloxacillin sodium|ORAL","generic":"dicloxacillin sodium","route":"ORAL","brand":null,"title":"DICLOXACILLIN SODIUM","set_id":"58e6ee7a-8237-ec66-e063-6394a90a5cae","effective":"20260813","sections":[{"title":"ข้อบ่งใช้","body":"To reduce the development of drug-resistant bacteria and maintain the effectiveness of dicloxacillin sodium capsules and other antibacterial drugs, dicloxacillin sodium capsules should be used only to treat or prevent infections that are proven or strongly suspected to be caused by susceptible bacteria. When culture and susceptibility information are available, they should be considered in selecting or modifying antibacterial therapy. In the absence of such data, local epidemiology and susceptibility patterns may contribute to the empiric selection of therapy. Dicloxacillin sodium capsules are indicated in the treatment of infections caused by penicillinase-producing staphylococci which have demonstrated susceptibility to the drug. Cultures and susceptibility tests should be performed initially to determine the causative organisms and their sensitivity to the drug (see CLINICAL PHARMACOLOGY – Susceptibility Testing ) . Dicloxacillin sodium capsules may be used to initiate therapy in suspected cases of resistant staphylococcal infections prior to the availability of laboratory test results. The penicillinase-resistant penicillins should not be used in infections caused by organisms susceptible to penicillin G. If the susceptibility tests indicate that the infection is due to an organism other than a resistant staphylococcus, therapy should not be continued with a penicillinase-resistant penicillin."},{"title":"ขนาดยาและวิธีใช้","body":"Concurrent administration of the penicillinase-resistant penicillins and probenecid increases and prolongs serum penicillin levels. Probenecid decreases the apparent volume of distribution and slows the rate of excretion by competitively inhibiting renal tubular secretion of penicillin. Penicillin-probenecid therapy is generally limited to those infections where very high serum levels of penicillin are necessary. Oral preparations of the penicillinase-resistant penicillins should not be used as initial therapy in serious, life-threatening infections (see PRECAUTIONS - General ). Oral therapy with the penicillinase-resistant penicillins may be used to follow up the previous use of a parenteral agent as soon as the clinical condition warrants. RECOMMENDED DOSAGES FOR DICLOXACILLIN SODIUM IN MILD TO MODERATE AND SEVERE INFECTIONS 1. Patients weighing less than 40 kg (88 lbs) DRUG ADULTS CHILDREN Mild to Moderate Severe Mild to Moderate Severe Dicloxacillin 125 mg every 6 hours 250 mg every 6 hours 12.5 mg/kg/day 1 in equally divided doses every 6 hours 25 mg/kg/day 1 in equally divided doses every 6 hours Dicloxacillin is best absorbed when taken on an empty stomach, and should be administered at least 1 hour before or 2 hours after meals. Dicloxacillin sodium capsules should be taken with at least 4 fluid ounces (120 mL) of water and should not be taken in the supine position or immediately before going to bed (see PRECAUTIONS )."},{"title":"ข้อห้ามใช้","body":"Dicloxacillin sodium capsules are contraindicated in persons who have shown hypersensitivity to any of the penicillins or any component of the formulations."},{"title":"คำเตือนและข้อควรระวัง","body":"Serious and occasionally fatal hypersensitivity (anaphylactic shock with collapse) reactions have occurred in patients receiving penicillin. The incidence of anaphylactic shock in all penicillin-treated patients is between 0.015% and 0.04%. Anaphylactic shock resulting in death has occurred in approximately 0.002% of the patients treated. Although anaphylaxis is more frequent following a parenteral administration, it has occurred in patients receiving oral penicillins. When penicillin therapy is indicated, it should be initiated only after a comprehensive patient drug and allergy history has been obtained. If an allergic reaction occurs, dicloxacillin should be discontinued and appropriate therapy instituted. Individuals with a history of penicillin hypersensitivity may also experience allergic reactions when treated with a cephalosporin. Clostridium difficile associated diarrhea (CDAD) has been reported with use of nearly all antibacterial agents, including dicloxacillin sodium, and may range in severity from mild diarrhea to fatal colitis. Treatment with antibacterial agents alters the normal flora of the colon leading to overgrowth of C. difficile . C. difficile produces toxins A and B which contribute to the development of CDAD. Hypertoxin producing strains of C. difficile cause increased morbidity and mortality, as these infections can be refractory to antimicrobial therapy and may require colectomy. CDAD must be considered in all patients who present with diarrhea following antibiotic use. Careful medical history is necessary since CDAD has been reported to occur over two months after the administration of antibacterial agents. If CDAD is suspected or confirmed, ongoing antibiotic use not directed against C. difficile may need to be discontinued. Appropriate fluid and electrolyte management, protein supplementation, antibiotic treatment of C. difficile , and surgical evaluation should be instituted as clinically indicated. General Prescribing dicloxacillin sodium capsules in the absence of a proven or strongly suspected bacterial infection or a prophylactic indication is unlikely to provide benefit to the patient and increases the risk of the development of drug-resistant bacteria. Dicloxacillin should generally not be administered to patients with a history of sensitivity to any penicillin. Penicillin should be used with caution in individuals with histories of significant allergies and/or asthma. …"},{"title":"อาการไม่พึงประสงค์","body":"Hypersensitive Reactions The reported incidence of allergic reactions to penicillin ranges from 0.7% to 10% (see WARNINGS ). Sensitization is usually the result of treatment, but some individuals have had immediate reactions to penicillin when first treated. In such cases, it is thought that the patients may have had prior exposure to the drug via trace amounts present in milk and vaccines. Two types of allergic reactions to penicillin are noted clinically, immediate and delayed. Immediate reactions usually occur within 20 minutes of administration and range in severity from urticaria and pruritus to angioneurotic edema, laryngospasm, bronchospasm, hypotension, vascular collapse and death. Such immediate anaphylactic reactions are very rare (see WARNINGS ) and usually occur after parenteral therapy, but have occurred in patients receiving oral therapy. Another type of immediate reaction, an accelerated reaction, may occur between 20 minutes and 48 hours after administration and may include urticaria, pruritus and fever. Although laryngeal edema, laryngospasm and hypotension occasionally occur, fatality is uncommon. Delayed allergic reactions to penicillin therapy usually occur after 48 hours and sometimes as late as two to four weeks after initiation of therapy. Manifestations of this type of reaction include serum sicknesslike symptoms (i.e., fever, malaise, urticaria, myalgia, arthralgia, abdominal pain) and various skin rashes. Gastrointestinal Reactions Nausea, vomiting, diarrhea, stomatitis, black or hairy tongue and other symptoms of gastrointestinal irritation may occur, especially during oral penicillin therapy. Pseudomembranous colitis has been reported with the use of dicloxacillin. Therefore, it is important to consider its diagnosis in patients who develop diarrhea in association with dicloxacillin use. Reports have been received during postmarketing surveillance of esophageal burning, esophagitis, and esophageal ulceration, particularly after ingestion of dicloxacillin capsules with an insufficient quantity of water and/or before going to bed (see PRECAUTIONS and DOSAGE AND ADMINISTRATION ). Nervous System Reactions Neurotoxic reactions similar to those observed with penicillin G (e.g., lethargy, confusion, twitching, multifocal myoclonus, localized or generalized epileptiform seizures) may occur with large intravenous doses of the penicillinase-resistant penicillins, especially with patients with renal insufficiency. …"},{"title":"Drug interaction","body":"Tetracycline, a bacteriostatic antibiotic, may antagonize the bactericidal effect of penicillin and concurrent use of these drugs should be avoided. Probenecid administered concomitantly with penicillins increases and prolongs serum penicillin levels (see DOSAGE AND ADMINISTRATION ). Penicillinase-resistant penicillins, like other penicillins, are physically and/or chemically incompatible with aminoglycosides and can inactivate the drugs in vitro. In vitro mixing of penicillins and aminoglycosides should be avoided during concomitant therapy and the drugs should be administered separately. Penicillins can inactivate aminoglycosides in vitro in serum samples from patients receiving both drugs, which could produce falsely decreased results in serum aminoglycoside assays of the serum samples. Dicloxacillin may reduce the anticoagulant response to dicumarol and warfarin. Careful monitoring of prothrombin times is suggested during concomitant therapy, and dosage of the anticoagulant should be adjusted as required. The mechanism of this possible interaction is unclear, but may be due to hepatic enzyme induction."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Reproduction studies performed in the mouse, rat and rabbit have revealed no evidence of impaired fertility or harm to the fetus due to the penicillinase-resistant penicillins. Human experience with the penicillins during pregnancy has not shown any positive evidence of adverse effects on the fetus. There are, however, no adequate or well-controlled studies in pregnant women showing conclusively that harmful effects of these drugs on the fetus can be excluded. Because animal reproduction studies are not always predictive of human response, this drug should be used during pregnancy only if clearly needed. Penicillins are excreted in breast milk. Caution should be exercised when penicillins are administered to a nursing woman. Because of incompletely developed renal function in newborns, penicillinase-resistant penicillins (especially methicillin) may not be completely excreted, with abnormally high blood levels resulting. Frequent monitoring of blood levels is advisable in this group, with dosage adjustments when necessary. All newborns treated with penicillins should be monitored closely for clinical and laboratory evidence of toxic or adverse effects (see DOSAGE AND ADMINISTRATION ). Experience in the neonatal period is limited. Therefore a dose for the newborn is not recommended. Clinical studies of dicloxacillin sodium capsules did not include sufficient numbers of subjects aged 65 and over to determine whether they respond differently from younger subjects. Other reported clinical experience has not identified differences in responses between the elderly and younger patients. In general, dose selection for an elderly patient should be cautious, usually starting at the low end of the dosing range, reflecting the greater frequency of decreased hepatic, renal, or cardiac function, and of concomitant disease or other drug therapy."}]},
{"key":"dicyclomine hydrochloride|ORAL","generic":"dicyclomine hydrochloride","route":"ORAL","brand":null,"title":"DICYCLOMINE HYDROCHLORIDE","set_id":"029baf6d-4e85-48fd-9efc-158fe0f629bb","effective":"20260120","sections":[{"title":"ข้อบ่งใช้","body":"Dicyclomine hydrochloride capsules are indicated for the treatment of patients with functional bowel/irritable bowel syndrome. Dicyclomine hydrochloride capsules are an antispasmodic and anticholinergic (antimuscarinic) agent indicated for the treatment of functional bowel/irritable bowel syndrome ( 1 )"},{"title":"ขนาดยาและวิธีใช้","body":"Dosage must be adjusted to individual patient needs. Dosage for dicyclomine hydrochloride capsules must be adjusted to individual patient needs ( 2 ). If a dose is missed, patients should continue the normal dosing schedule ( 2 ). Oral in adults ( 2.1 ): Starting dose: 20 mg four times a day. After a week treatment with the starting dose, the dose may be escalated to 40 mg four times a day, unless side effects limit dosage escalation Discontinue dicyclomine hydrochloride if efficacy not achieved or side effects require doses less than 80 mg per day after two weeks of treatment 2.1 Oral Dosage and Administration in Adults The recommended initial dose is 20 mg four times a day. After one week treatment with the initial dose, the dose may be increased to 40 mg four times a day unless side effects limit dosage escalation. If efficacy is not achieved within 2 weeks or side effects require doses below 80 mg per day, the drug should be discontinued. Documented safety data are not available for doses above 80 mg daily for periods longer than 2 weeks."},{"title":"ข้อห้ามใช้","body":"Dicyclomine hydrochloride is contraindicated in infants less than 6 months of age [see Use in Specific Populations (8.4) ], nursing mothers [see Use in Specific Populations (8.3) ], and in patients with: unstable cardiovascular status in acute hemorrhage myasthenia gravis [see Warnings and Precautions (5.4) ] glaucoma [see Adverse Reactions (6.3) and Drug Interactions (7.1) ] obstructive uropathy [see Warnings and Precautions (5.8) ] obstructive disease of the gastrointestinal tract [see Warnings and Precautions (5.5) ] severe ulcerative colitis [see Warnings and Precautions (5.7) ] reflux esophagitis Infants less than 6 months of age ( 4 ) Nursing mothers ( 4 ) Unstable cardiovascular status in acute hemorrhage ( 4 ) Myasthenia gravis ( 4 ) Glaucoma ( 4 ) Obstructive uropathy ( 4 ) Obstructive disease of the gastrointestinal tract ( 4 ) Severe ulcerative colitis ( 4 ) Reflux esophagitis ( 4 )"},{"title":"คำเตือนและข้อควรระวัง","body":"Cardiovascular conditions : worsening of conditions ( 5.2 ) Peripheral and central nervous system : heat prostration can occur with drug use (fever and heat stroke due to decreased sweating); drug should be discontinued and supportive measures instituted ( 5.3 ) Psychosis and delirium have been reported in patients sensitive to anticholinergic drugs (such as elderly patients and/or in patients with mental illness): signs and symptoms resolve within 12 to 24 hours after discontinuation of dicyclomine hydrochloride ( 5.3 ) Myasthenia Gravis : overdose may lead to muscular weakness and paralysis. Dicyclomine hydrochloride should be given to patients with myasthenia gravis only to reduce adverse muscarinic effects of an anticholinesterase ( 5.4 ) Incomplete intestinal obstruction : diarrhea may be an early symptom especially in patients with ileostomy or colostomy. Treatment with dicyclomine hydrochloride would be inappropriate and possibly fatal ( 5.5 ) Salmonella dysenteric patients : due to risk of toxic megacolon ( 5.6 ) Ulcerative colitis : Dicyclomine hydrochloride should be used with caution in these patients; large doses may suppress intestinal motility or aggravate the serious complications of toxic megacolon ( 5.7 ) Prostatic hypertrophy : Dicyclomine hydrochloride should be used with caution in these patients; may lead to urinary retention ( 5.8 ) Hepatic and renal disease : should be used with caution ( 5.9 ) Geriatric : use with caution in elderly who may be more susceptible to dicyclomine hydrochloride’s adverse events ( 5.10 ) 5.2 Cardiovascular Conditions Dicyclomine hydrochloride needs to be used with caution in conditions characterized by tachyarrhythmia such as thyrotoxicosis, congestive heart failure and in cardiac surgery, where they may further accelerate the heart rate. Investigate any tachycardia before administration of dicyclomine hydrochloride. Care is required in patients with coronary heart disease, as ischemia and infarction may be worsened, and in patients with hypertension [see Adverse Reactions (6.3) ]. 5.3 Peripheral and Central Nervous System The peripheral effects of dicyclomine hydrochloride are a consequence of their inhibitory effect on muscarinic receptors of the autonomic nervous system. …"},{"title":"อาการไม่พึงประสงค์","body":"The pattern of adverse effects seen with dicyclomine is mostly related to its pharmacological actions at muscarinic receptors [see Clinical Pharmacology (12) ]. They are a consequence of the inhibitory effect on muscarinic receptors within the autonomic nervous system. These effects are dose-related and are usually reversible when treatment is discontinued. The most serious adverse reactions reported with dicyclomine hydrochloride include cardiovascular and central nervous system symptoms [see Warnings and Precautions (5.2 , 5.3) ]. The most serious adverse reactions include cardiovascular and central nervous system symptoms. The most common adverse reactions (> 5% of patients) are dizziness, dry mouth, vision blurred, nausea, somnolence, asthenia and nervousness ( 6 ) To report SUSPECTED ADVERSE REACTIONS, contact Rising Pharma Holdings, Inc. at 1-844-874-7464 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch. 6.1 Clinical Trials Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical trials of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in practice. The data described below reflect exposure in controlled clinical trials involving over 100 patients treated for functional bowel/irritable bowel syndrome with dicyclomine hydrochloride at initial doses of 160 mg daily (40 mg four times a day) In these trials most of the side effects were typically anticholinergic in nature and were reported by 61% of the patients. Table 1 presents adverse reactions ( MedDRA 13.0 preferred terms) by decreasing order of frequency in a side-by-side comparison with placebo. Table 1: Adverse reactions experienced in controlled clinical trials with decreasing order of frequency MedDRA Preferred Term Dicyclomine Hydrochloride (40 mg four times a day) % Placebo % Dry Mouth 33 5 Dizziness 40 5 Vision blurred 27 2 Nausea 14 6 Somnolence 9 1 Asthenia 7 1 Nervousness 6 2 Nine percent (9%) of patients were discontinued from dicyclomine hydrochloride because of one or more of these side effects (compared with 2% in the placebo group). In 41% of the patients with side effects, side effects disappeared or were tolerated at the 160 mg daily dose without reduction. …"},{"title":"Drug interaction","body":"Antiglaucoma agents : anticholinergics antagonize antiglaucoma agents and may increase intraoccular pressure ( 7 ) Anticholinergic agents : may affect the gastrointestinal absorption of various drugs; may also increase certain actions or side effects of other anticholinergic drugs ( 7 ) Antacids : interfere with the absorption of anticholinergic agents ( 7 ) 7.1 Antiglaucoma Agents Anticholinergics antagonize the effects of antiglaucoma agents. Anticholinergic drugs in the presence of increased intraocular pressure may be hazardous when taken concurrently with agents such as corticosteroids. Use of dicyclomine hydrochloride in patients with glaucoma is not recommended [see Contraindications (4) ]. 7.2 Other Drugs with Anticholinergic Activity The following agents may increase certain actions or side effects of anticholinergic drugs including dicyclomine hydrochloride: amantadine, antiarrhythmic agents of Class I (e.g., quinidine), antihistamines, antipsychotic agents (e.g., phenothiazines), benzodiazepines, MAO inhibitors, narcotic analgesics (e.g., meperidine), nitrates and nitrites, sympathomimetic agents, tricyclic antidepressants, and other drugs having anticholinergic activity. 7.3 Other Gastrointestinal Motility Drugs Interaction with other gastrointestinal motility drugs may antagonize the effects of drugs that alter gastrointestinal motility, such as metoclopramide. 7.4 Effect of Antacids Because antacids may interfere with the absorption of anticholinergic agents including dicyclomine hydrochloride, simultaneous use of these drugs should be avoided. 7.5 Effect on Absorption of Other Drugs Anticholinergic agents may affect gastrointestinal absorption of various drugs by affecting on gastrointestinal motility, such as slowly dissolving dosage forms of digoxin; increased serum digoxin concentration may result. 7.6 Effect on Gastric Acid Secretion The inhibiting effects of anticholinergic drugs on gastric hydrochloric acid secretion are antagonized by agents used to treat achlorhydria and those used to test gastric secretion."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Adequate and well-controlled studies have not been conducted with dicyclomine hydrochloride in pregnant women at the recommended doses of 80 to 160 mg/day. However, epidemiologic studies did not show an increased risk of structural malformations among babies born to women who took products containing dicyclomine hydrochloride at doses up to 40 mg/day during the first trimester of pregnancy. Reproduction studies have been performed in rats and rabbits at doses up to 33 times the maximum recommended human dose based on 160 mg/day (3 mg/kg) and have revealed no evidence of harm to the fetus due to dicyclomine. Because animal reproduction studies are not always predictive of human response, this drug should be used during pregnancy only if clearly needed. 8.3 Nursing Mothers Dicyclomine hydrochloride is contraindicated in women who are breastfeeding. Dicyclomine hydrochloride is excreted in human milk. Because of the potential for serious adverse reactions in breast-fed infants from dicyclomine hydrochloride, a decision should be made whether to discontinue nursing or to discontinue the drug, taking into account the importance of the drug to the mother [see Use in Specific Populations (8.4) ]. 8.4 Pediatric Use Safety and effectiveness in pediatric patients have not been established. Dicyclomine hydrochloride is contraindicated in infants less than 6 months of age [see Contraindications (4)] . There are published cases reporting that the administration of dicyclomine hydrochloride to infants has been followed by serious respiratory symptoms (dyspnea, shortness of breath, breathlessness, respiratory collapse, apnea and asphyxia), seizures, syncope, pulse rate fluctuations, muscular hypotonia, and coma, and death, however; no causal relationship has been established. 8.5 Geriatric Use Clinical studies of dicyclomine hydrochloride did not include sufficient numbers of subjects aged 65 and over to determine whether they respond differently from younger subjects. Other reported clinical experience has not identified differences in responses between the elderly and younger patients. In general, dose selection for an elderly patient should be cautious, usually starting at the low end of the dosing range in adults, reflecting the greater frequency of decreased hepatic, renal, or cardiac function, and of concomitant disease or other drug therapy. …"},{"title":"การได้รับยาเกินขนาด","body":"In case of an overdose, patients should contact a physician, poison control center (1-800-222-1222), or emergency room. The signs and symptoms of overdosage include: headache; nausea; vomiting; blurred vision; dilated pupils; hot, dry skin; dizziness; dryness of the mouth; difficulty in swallowing; and CNS stimulation including convulsion. A curare-like action may occur (i.e., neuromuscular blockade leading to muscular weakness and possible paralysis). One reported event included a 37-year-old who reported numbness on the left side, cold fingertips, blurred vision, abdominal and flank pain, decreased appetite, dry mouth, and nervousness following ingestion of 320 mg daily (four 20 mg tablets four times daily). These events resolved after discontinuing the dicyclomine. The acute oral LD 50 of the drug is 625 mg/kg in mice. The amount of drug in a single dose that is ordinarily associated with symptoms of overdosage or that is likely to be life-threatening, has not been defined. The maximum human oral dose recorded was 600 mg by mouth in a 10-month-old child and approximately 1500 mg in an adult, each of whom survived. In three of the infants who died following administration of dicyclomine hydrochloride [see Warnings and Precautions (5.1) ], the blood concentrations of drug were 200, 220, and 505 ng/mL. It is not known if dicyclomine hydrochloride is dialyzable. Treatment should consist of gastric lavage, emetics, and activated charcoal. Sedatives (e.g., short-acting barbiturates, benzodiazepines) may be used for management of overt signs of excitement. If indicated, an appropriate parenteral cholinergic agent may be used as an antidote."}]},
{"key":"dimenhydrinate|ORAL","generic":"dimenhydrinate","route":"ORAL","brand":null,"title":"Motion Sickness Relief","set_id":"00a327c6-6b86-4702-8c04-55c405c1404c","effective":"20260723","sections":[{"title":"ข้อบ่งใช้","body":"for prevention and treatment of these symptoms associated with motion sickness: nausea vomiting dizziness"},{"title":"ขนาดยาและวิธีใช้","body":"do not take more than directed to prevent motion sickness, the first dose should be taken one-half to one hour before starting activity to prevent or treat motion sickness, see below: adults and children 12 years and over ■ take 1 to 2 tablets every 4-6 hours ■ do not take more than 8 tablets in 24 hours, or as directed by a doctor children 6 to under 12 years ■ give 1/2 to 1 tablet every 6-8 hours ■ do not give more than 3 tablets in 24 hours, or as directed by a doctor children 2 to under 6 years ■ give 1/2 tablet every 6-8 hours ■ do not give more than 1 1/2 tablets in 24 hours, or as directed by a doctor"},{"title":"ข้อห้ามใช้","body":"for children under 2 years of age unless directed by a doctor."},{"title":"คำเตือนและข้อควรระวัง","body":"Do not use for children under 2 years of age unless directed by a doctor. Ask a doctor before use if you have glaucoma a breathing problem such as emphysema or chronic bronchitis difficulty in urination due to enlargement of the prostate gland Ask a doctor or pharmacist before use if you are taking sedatives or tranquilizers. When using this product marked drowsiness may occur alcohol, sedatives, and tranquilizers may increase drowsiness avoid alcoholic beverages use caution when driving a motor vehicle or operating machinery If pregnant or breast-feeding, ask a health professional before use. Keep out of reach of children. In case of overdose, get medical help or contact a Poison Control Center right away. gland tranquilizers. alcohol, sedatives, and tranquilizers may increase drowsiness avoid alcoholic beverages use caution when driving a motor vehicle or operating machinery"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"ask a health professional before use."},{"title":"การเก็บรักษา","body":"Other information each tablet contains: calcium 35 mg TAMPER EVIDENT: DO NOT USE IF OUTER PACKAGE IS OPENED OR BLISTER IS TORN OR BROKEN store at 25°C (77°F); excursions permitted between 15°-30°C (59°-86°F) protect from moisture see end flap for expiration date and lot number"}]},
{"key":"doxazosin mesylate|ORAL","generic":"doxazosin mesylate","route":"ORAL","brand":null,"title":"Doxazosin","set_id":"f6c9856e-9154-f349-e053-6294a90a9f2c","effective":"20260119","sections":[{"title":"ข้อบ่งใช้","body":"Doxazosin tablets are an alpha 1 adrenergic antagonist indicated for: ( 1 ) Signs and symptoms of Benign Prostatic Hyperplasia (BPH) Treatment of Hypertension 1.1 Benign Prostatic Hyperplasia (BPH) Doxazosin tablets are indicated for the treatment of the signs and symptoms of BPH. 1.2 Hypertension Doxazosin tablets are indicated for the treatment of hypertension, to lower blood pressure. Lowering blood pressure reduces the risk of fatal and nonfatal cardiovascular events, primarily strokes and myocardial infarctions. These benefits have been seen in controlled trials of antihypertensive drugs from a wide variety of pharmacologic classes, including this drug. Control of high blood pressure should be part of comprehensive cardiovascular risk management, including, as appropriate, lipid control, diabetes management, antithrombotic therapy, smoking cessation, exercise, and limited sodium intake. Many patients will require more than one drug to achieve blood pressure goals. For specific advice on goals and management, see published guidelines, such as those of the National High Blood Pressure Education Program's Joint National Committee on Prevention, Detection, Evaluation, and Treatment of High Blood Pressure (JNC). Numerous antihypertensive drugs, from a variety of pharmacologic classes and with different mechanisms of action, have been shown in randomized controlled trials to reduce cardiovascular morbidity and mortality, and it can be concluded that it is blood pressure reduction, and not some other pharmacologic property of the drugs, that is largely responsible for those benefits. The largest and most consistent cardiovascular outcome benefit has been a reduction in the risk of stroke, but reductions in myocardial infarction and cardiovascular mortality also have been seen regularly. Elevated systolic or diastolic pressure causes increased cardiovascular risk, and the absolute risk increase per mmHg is greater at higher blood pressures, so that even modest reductions of severe hypertension can provide substantial benefit. Relative risk reduction from blood pressure reduction is similar across populations with varying absolute risk, so the absolute benefit is greater in patients who are at higher risk independent of their hypertension (for example, patients with diabetes or hyperlipidemia), and such patients would be expected to benefit from more aggressive treatment to a lower blood pressure goal. …"},{"title":"ขนาดยาและวิธีใช้","body":"For the treatment of BPH: Initiate therapy at 1 mg once daily. Dose may be titrated at 1 to 2 week intervals, up to 8 mg once daily. ( 2.2 ) For the treatment of hypertension: Initiate therapy at 1 mg once daily. Dose may be titrated as needed, up to 16 mg once daily. ( 2.3 ) 2.1 Dosing Information Following the initial dose and with each dose increase of doxazosin tablets, monitor blood pressure for at least 6 hours following administration. If doxazosin tablets administration is discontinued for several days, therapy should be restarted using the initial dosing regimen. 2.2 Benign Prostatic Hyperplasia The recommended initial dosage of doxazosin tablets is 1 mg given once daily either in the morning or evening. Depending on the individual patient's urodynamics and BPH symptomatology, the dose may be titrated at 1 to 2 week intervals to 2 mg, and thereafter to 4 mg and 8 mg once daily. The maximum recommended dose for BPH is 8 mg once daily. Routinely monitor blood pressure in these patients. 2.3 Hypertension The initial dosage of doxazosin tablets is 1 mg given once daily. Daily dosage may be doubled up 16 mg once daily, as needed, to achieve the desired reduction in blood pressure."},{"title":"ข้อห้ามใช้","body":"The use of doxazosin tablets is contraindicated in patients with a hypersensitivity to doxazosin, other quinazolines (e.g., prazosin, terazosin), or any of its components. Hypersensitivity to doxazosin, other quinazolines, or any other ingredient in doxazosin tablets. ( 4 )"},{"title":"คำเตือนและข้อควรระวัง","body":"Postural hypotension with or without syncope may occur. ( 5.1 ) Risk of Intraoperative Floppy Iris Syndrome during cataract surgery. ( 5.2 ) Screen for the presence of prostate cancer prior to treatment for BPH and at regular intervals afterwards. ( 5.3 ) 5.1 Postural Hypotension Postural hypotension with or without symptoms (e.g., dizziness) may develop within a few hours following administration of doxazosin tablets. However, infrequently, symptomatic postural hypotension has also been reported later than a few hours after dosing. As with other alpha-blockers, there is a potential for syncope, especially after the initial dose or after an increase in dosage strength. Advise patient how to avoid symptoms resulting from postural hypotension and what measures to take should they develop. Concomitant administration of doxazosin tablets with a PDE-5 inhibitor can result in additive blood pressure lowering effects and symptomatic hypotension. 5.2 Cataract Surgery Intraoperative Floppy Iris Syndrome (IFIS) has been observed during cataract surgery in some patients on or previously treated with alpha 1 blockers. This variant of small pupil syndrome is characterized by the combination of a flaccid iris that billows in response to intraoperative irrigation currents, progressive intraoperative miosis despite preoperative dilation with standard mydriatic drugs, and potential prolapse of the iris toward the phacoemulsification incisions. The patient's surgeon should be prepared for possible modifications to their surgical technique, such as the utilization of iris hooks, iris dilator rings, or viscoelastic substances. There does not appear to be a benefit of stopping alpha 1 blocker therapy prior to cataract surgery. 5.3 Prostate Cancer Carcinoma of the prostate causes many of the symptoms associated with BPH and the two disorders frequently co-exist. Carcinoma of the prostate should therefore be ruled out prior to commencing therapy with doxazosin tablets for the treatment of BPH. 5.4 Priapism Alpha 1 antagonists, including doxazosin, have been associated with priapism (painful penile erection, sustained for hours and unrelieved by sexual intercourse or masturbation). This condition can lead to permanent impotence if not promptly treated."},{"title":"อาการไม่พึงประสงค์","body":"The most commonly reported adverse reactions from clinical trials are fatigue, malaise, hypotension, and dizziness. ( 6.1 ) To report SUSPECTED ADVERSE REACTIONS, contact Upsher-Smith Laboratories, LLC at 1-855-899-9180 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch. 6.1 Clinical Trials Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical trials of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in practice. Benign Prostatic Hyperplasia (BPH) The incidence of adverse events has been ascertained from worldwide clinical trials in 965 BPH patients. The incidence rates presented below (Table 2) are based on combined data from seven placebo-controlled trials involving once-daily administration of doxazosin tablets in doses of 1 mg to 16 mg in hypertensives and 0.5 mg to 8 mg in normotensives. Adverse reactions occurring more than 1% more frequently in BPH patients treated with doxazosin tablets versus placebo are summarized in Table 1. Table 1. Adverse Reactions Occurring more than 1% More Frequently in BPH Patients Treated with Doxazosin Tablets versus Placebo BODY SYSTEM Doxazosin tablets N=665 Placebo N=300 NERVOUS SYSTEM DISORDERS Dizziness Includes vertigo 15.6% 9.0% Somnolence 3.0% 1.0% CARDIAC DISORDERS Hypotension 1.7% 0% RESPIRATORY, THORACIC AND MEDIASTINAL DISORDERS Dyspnoea 2.6% 0.3% GASTROINTESTINAL DISORDERS Dry Mouth 1.4% 0.3% GENERAL DISORDERS AND ADMINISTRATION SITE CONDITIONS Fatigue 8.0% 1.7% Oedema 2.7% 0.7% Other adverse reactions occurring less than 1% more frequently in BPH patients treated with doxazosin tablets versus placebo but plausibly related to doxazosin tablets include: palpitations. Hypertension Doxazosin tablets have been administered to approximately 4000 hypertensive patients in clinical trials, of whom 1679 were included in the hypertension clinical development program. In placebo-controlled studies, adverse events occurred in 49% and 40% of patients in the doxazosin and placebo groups, respectively, and led to discontinuation in 2% of patients in each group. Adverse reactions occurring more than 1% more frequently in hypertensive patients treated with doxazosin tablets versus placebo are summarized in Table 1. Postural effects and edema appeared to be dose-related. …"},{"title":"Drug interaction","body":"Strong cytochrome P450 (CYP) 3A inhibitors may increase exposure to doxazosin and increased risk of hypotension. ( 7.1 ) Concomitant administration of doxazosin tablets with a phosphodiesterase-5 (PDE-5) inhibitor can result in additive blood pressure lowering effects and symptomatic hypotension. ( 7.2 ) 7.1 CYP3A Inhibitors In vitro studies suggest that doxazosin is a substrate of CYP3A4. Strong CYP3A inhibitors may increase exposure to doxazosin. Monitor blood pressure and for symptoms of hypotension when doxazosin tablets are used concomitantly with strong CYP3A inhibitors [see Clinical Pharmacology (12.3) ] . 7.2 Phosphodiesterase-5 (PDE-5) Inhibitors Concomitant administration of doxazosin tablets with a phosphodiesterase-5 (PDE-5) inhibitor can result in additive blood pressure lowering effects and symptomatic hypotension. Monitor blood pressure and for symptoms of hypotension [see Warnings and Precautions (5.1) ] ."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary The limited available data with doxazosin tablets in pregnant women are not sufficient to inform a drug-associated risk for major birth defects and miscarriage. However, untreated hypertension during pregnancy can result in increased maternal risks [see Clinical Considerations ] . In animal reproduction studies, no adverse developmental effects were observed when doxazosin was orally administered to pregnant rabbits and rats during the period of organogenesis at doses of up to 41 mg/kg and 20 mg/kg, respectively (exposures in rabbits and rats were 10 and 4 times, respectively, the human AUC exposures with a 12 mg/day therapeutic dose). A dosage regimen of 82 mg/kg/day in the rabbit was associated with reduced fetal survival [see Data ]. The estimated background risk of major birth defects and miscarriage for the indicated population is unknown. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2% to 4% and 15% to 20%, respectively. Clinical Considerations Disease-Associated Maternal and/or Embryo/Fetal Risk Hypertension in pregnancy increases the maternal risk for pre-eclampsia, gestational diabetes, premature delivery, and delivery complications (e.g., need for cesarean section, and post-partum hemorrhage). Hypertension increases the fetal risk for intrauterine growth restriction and intrauterine death. Data Animal Data Radioactivity was found to cross the placenta following oral administration of labelled doxazosin to pregnant rats. Studies in pregnant rabbits and rats at daily oral doses of up to 41 mg/kg and 20 mg/kg, respectively (plasma drug concentrations of 10 and 4 times, respectively, the human AUC exposures with a 12 mg/day therapeutic dose), have revealed no evidence of adverse developmental effects. A dosage regimen of 82 mg/kg/day in the rabbit was associated with reduced fetal survival. In peri- and postnatal studies in rats, postnatal development at maternal doses of 40 mg/kg/day or 50 mg/kg/day of doxazosin (about 8 times human AUC exposure with a 12 mg/day therapeutic dose) was delayed, as evidenced by slower body weight gain and slightly later appearance of anatomical features and reflexes. 8.4 Pediatric Use The safety and effectiveness of doxazosin have not been established in children. …"},{"title":"การได้รับยาเกินขนาด","body":"Experience with doxazosin tablets overdosage is limited. Two adolescents, who each intentionally ingested 40 mg doxazosin tablets with diclofenac or acetaminophen, were treated with gastric lavage with activated charcoal and made full recoveries. A two-year-old child who accidently ingested 4 mg doxazosin tablets was treated with gastric lavage and remained normotensive during the five-hour emergency room observation period. A six-month-old child accidentally received a crushed 1 mg tablet of doxazosin tablets and was reported to have been drowsy. A 32-year-old female with chronic renal failure, epilepsy, and depression intentionally ingested 60 mg doxazosin tablets (blood level = 0.9 mcg/mL; normal values in hypertensives = 0.02 mcg/mL); death was attributed to a grand mal seizure resulting from hypotension. A 39-year-old female who ingested 70 mg doxazosin tablets, alcohol, and Dalmane ® (flurazepam) developed hypotension which responded to fluid therapy. The oral LD 50 of doxazosin is greater than 1000 mg/kg in mice and rats. The most likely manifestation of overdosage would be hypotension, for which the usual treatment would be intravenous infusion of fluid. As doxazosin is highly protein bound, dialysis would not be indicated."},{"title":"การเก็บรักษา","body":"Recommended Storage: Store at 25°C (77°F), excursions permitted from 15°C to 30°C (59°F to 86°F) [see USP Controlled Room Temperature]."}]},
{"key":"enalapril maleate|ORAL","generic":"enalapril maleate","route":"ORAL","brand":null,"title":"Enalapril Maleate","set_id":"074fe718-88d8-365c-e063-6394a90a299d","effective":"20260728","sections":[{"title":"ข้อบ่งใช้","body":"Hypertension Enalapril maleate is indicated for the treatment of hypertension. Enalapril maleate is effective alone or in combination with other antihypertensive agents, especially thiazide-type diuretics. The blood pressure lowering effects of enalapril maleate and thiazides are approximately additive. Heart Failure Enalapril maleate is indicated for the treatment of symptomatic congestive heart failure, usually in combination with diuretics and digitalis. In these patients enalapril maleate improves symptoms, increases survival, and decreases the frequency of hospitalization (see CLINICAL PHARMACOLOGY, Heart Failure, Mortality Trials for details and limitations of survival trials). Asymptomatic Left Ventricular Dysfunction In clinically stable asymptomatic patients with left ventricular dysfunction (ejection fraction ≤35 percent), enalapril maleate decreases the rate of development of overt heart failure and decreases the incidence of hospitalization for heart failure (see CLINICAL PHARMACOLOGY, Heart Failure, Mortality Trials for details and limitations of survival trials). In using enalapril maleate consideration should be given to the fact that another angiotensin-converting enzyme inhibitor, captopril, has caused agranulocytosis, particularly in patients with renal impairment or collagen vascular disease, and that available data are insufficient to show that enalapril maleate does not have a similar risk (see WARNINGS, Neutropenia/Agranulocytosis ). In considering use of enalapril maleate, it should be noted that in controlled clinical trials ACE inhibitors have an effect on blood pressure that is less in black patients than in non-blacks. In addition, it should be noted that black patients receiving ACE inhibitors have been reported to have a higher incidence of angioedema compared to non-blacks (see WARNINGS, Head and Neck Angioedema )."},{"title":"ขนาดยาและวิธีใช้","body":"Hypertension In patients who are currently being treated with a diuretic, symptomatic hypotension occasionally may occur following the initial dose of enalapril maleate. The diuretic should, if possible, be discontinued for two to three days before beginning therapy with enalapril maleate to reduce the likelihood of hypotension (see WARNINGS, Hypotension ). If the patient's blood pressure is not controlled with enalapril maleate alone, diuretic therapy may be resumed. If the diuretic cannot be discontinued an initial dose of 2.5 mg should be used under medical supervision for at least two hours and until blood pressure has stabilized for at least an additional hour (see WARNINGS, Hypotension and PRECAUTIONS, Drug Interactions ). The recommended initial dose in patients not on diuretics is 5 mg once a day. Dosage should be adjusted according to blood pressure response. The usual dosage range is 10 mg to 40 mg per day administered in a single dose or two divided doses. In some patients treated once daily, the antihypertensive effect may diminish toward the end of the dosing interval. In such patients, an increase in dosage or twice daily administration should be considered. If blood pressure is not controlled with enalapril maleate alone, a diuretic may be added. Concomitant administration of enalapril maleate with potassium supplements, potassium salt substitutes, or potassium-sparing diuretics may lead to increases of serum potassium (see PRECAUTIONS ). Dosage Adjustment in Hypertensive Patients with Renal Impairment The usual dose of enalapril is recommended for patients with a creatinine clearance more than 30 mL/min (serum creatinine of up to approximately 3 mg/dL). For patients with creatinine clearance less than or equal to 30 mL/min (serum creatinine more than or equal to 3 mg/dL), the first dose is 2.5 mg once daily. The dosage may be titrated upward until blood pressure is controlled or to a maximum of 40 mg daily. Renal Status Creatinine Clearance mL/min Initial Dose mg/day Normal Renal Function >80 mL/min 5 mg Mild Impairment ≤80 >30 mL/min 5 mg Moderate to Severe Impairment ≤30 mL/min 2.5 mg Dialysis Patients See WARNINGS, Anaphylactoid Reactions during Membrane Exposure 2.5 mg on dialysis days Dosage on nondialysis days should be adjusted depending on the blood pressure response. Heart Failure Enalapril maleate is indicated for the treatment of symptomatic heart failure, usually in combination with diuretics and digitalis. …"},{"title":"ข้อห้ามใช้","body":"Enalapril maleate is contraindicated in patients who are hypersensitive to this product and in patients with a history of angioedema related to previous treatment with an angiotensin-converting enzyme inhibitor and in patients with hereditary or idiopathic angioedema. Do not coadminister aliskiren with enalapril maleate in patients with diabetes (see PRECAUTIONS, Drug Interactions ). Enalapril maleate is contraindicated in combination with a neprilysin inhibitor (e.g., sacubitril). Do not administer enalapril maleate within 36 hours of switching to or from sacubitril/valsartan, a neprilysin inhibitor (see WARNINGS, Head and Neck Angioedema )."},{"title":"คำเตือนกรอบดำ","body":"WARNING: FETAL TOXICITY See full prescribing information for complete boxed warning. When pregnancy is detected, discontinue enalapril maleate as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. (See WARNINGS: Fetal Toxicity .)"},{"title":"คำเตือนและข้อควรระวัง","body":"Anaphylactoid and Possibly Related Reactions Presumably because angiotensin-converting enzyme inhibitors affect the metabolism of eicosanoids and polypeptides, including endogenous bradykinin, patients receiving ACE inhibitors (including enalapril maleate) may be subject to a variety of adverse reactions, some of them serious. Head and Neck Angioedema Angioedema of the face, extremities, lips, tongue, glottis and/or larynx has been reported in patients treated with angiotensin-converting enzyme inhibitors, including enalapril maleate. This may occur at any time during treatment. In such cases enalapril maleate should be promptly discontinued and appropriate therapy and monitoring should be provided until complete and sustained resolution of signs and symptoms has occurred. In instances where swelling has been confined to the face and lips the condition has generally resolved without treatment, although antihistamines have been useful in relieving symptoms. Angioedema associated with laryngeal edema may be fatal. Where there is involvement of the tongue, glottis or larynx, likely to cause airway obstruction, appropriate therapy, e.g., subcutaneous epinephrine solution 1:1000 (0.3 mL to 0.5 mL) and/or measures necessary to ensure a patent airway, should be promptly provided (see ADVERSE REACTIONS ). Patients receiving coadministration of ACE inhibitor and mTOR (mammalian target of rapamycin) inhibitor (e.g., temsirolimus, sirolimus, everolimus) therapy or a neprilysin inhibitor may be at increased risk for angioedema (see PRECAUTIONS ). Intestinal Angioedema Intestinal angioedema has been reported in patients treated with ACE inhibitors. These patients presented with abdominal pain (with or without nausea or vomiting); in some cases there was no prior history of facial angioedema and C1 esterase levels were normal. The angioedema was diagnosed by procedures including abdominal CT scan or ultrasound, or at surgery, and symptoms resolved after stopping the ACE inhibitor. Intestinal angioedema should be included in the differential diagnosis of patients on ACE inhibitors presenting with abdominal pain. Patients with a history of angioedema unrelated to ACE inhibitor therapy may be at increased risk of angioedema while receiving an ACE inhibitor (see also INDICATIONS AND USAGE and CONTRAINDICATIONS ). …"},{"title":"อาการไม่พึงประสงค์","body":"Enalapril maleate has been evaluated for safety in more than 10,000 patients, including over 1000 patients treated for one year or more. Enalapril maleate has been found to be generally well tolerated in controlled clinical trials involving 2987 patients. For the most part, adverse experiences were mild and transient in nature. In clinical trials, discontinuation of therapy due to clinical adverse experiences was required in 3.3 percent of patients with hypertension and in 5.7 percent of patients with heart failure. The frequency of adverse experiences was not related to total daily dosage within the usual dosage ranges. In patients with hypertension the overall percentage of patients treated with enalapril maleate reporting adverse experiences was comparable to placebo. Hypertension Adverse experiences occurring in greater than one percent of patients with hypertension treated with enalapril maleate in controlled clinical trials are shown below. In patients treated with enalapril maleate, the maximum duration of therapy was three years; in placebo-treated patients the maximum duration of therapy was 12 weeks. Enalapril Maleate (n = 2314) Incidence (discontinuation) Placebo (n = 230) Incidence Body As A Whole Fatigue 3.0 (<0.1) 2.6 Orthostatic Effects 1.2 (<0.1) 0.0 Asthenia 1.1 (0.1) 0.9 Digestive Diarrhea 1.4 (<0.1) 1.7 Nausea 1.4 (0.2) 1.7 Nervous/Psychiatric Headache 5.2 (0.3) 9.1 Dizziness 4.3 (0.4) 4.3 Respiratory Cough 1.3 (0.1) 0.9 Skin Rash 1.4 (0.4) 0.4 Heart Failure Adverse experiences occurring in greater than one percent of patients with heart failure treated with enalapril maleate are shown below. The incidences represent the experiences from both controlled and uncontrolled clinical trials (maximum duration of therapy was approximately one year). In the placebo-treated patients, the incidences reported are from the controlled trials (maximum duration of therapy is 12 weeks). The percentage of patients with severe heart failure (NYHA Class IV) was 29 percent and 43 percent for patients treated with enalapril maleate and placebo, respectively. Enalapril Maleate (n = 673) Incidence (discontinuation) Placebo (n = 339) Incidence Body As A Whole Orthosta …"},{"title":"Drug interaction","body":"Neprilysin Inhibitors Patients taking concomitant neprilysin inhibitors may be at increased risk for angioedema (see WARNINGS ). Dual Blockade of the Renin-Angiotensin System (RAS) Dual blockade of the RAS with angiotensin receptor blockers, ACE inhibitors, or aliskiren is associated with increased risks of hypotension, hyperkalemia, and changes in renal function (including acute renal failure) compared to monotherapy. Most patients receiving the combination of two RAS inhibitors do not obtain any additional benefit compared to monotherapy. In general, avoid combined use of RAS inhibitors. Closely monitor blood pressure, renal function, and electrolytes in patients on enalapril maleate and other agents that affect the RAS. Do not coadminister aliskiren with enalapril maleate in patients with diabetes. Avoid use of aliskiren with enalapril maleate in patients with renal impairment (GFR <60 mL/min). Hypotension — Patients on Diuretic Therapy Patients on diuretics and especially those in whom diuretic therapy was recently instituted, may occasionally experience an excessive reduction of blood pressure after initiation of therapy with enalapril. The possibility of hypotensive effects with enalapril can be minimized by either discontinuing the diuretic or increasing the salt intake prior to initiation of treatment with enalapril. If it is necessary to continue the diuretic, provide close medical supervision after the initial dose for at least two hours and until blood pressure has stabilized for at least an additional hour (See WARNINGS, Hypotension and DOSAGE AND ADMINISTRATION ). Agents Causing Renin Release The antihypertensive effect of enalapril maleate is augmented by antihypertensive agents that cause renin release (e.g., diuretics). Nonsteroidal Anti-Inflammatory Agents Including Selective Cyclooxygenase-2 Inhibitors (COX-2 Inhibitors) In patients who are elderly, volume-depleted (including those on diuretic therapy), or with compromised renal function, coadministration of NSAIDs, including selective COX-2 inhibitors, with ACE inhibitors, including enalapril, may result in deterioration of renal function, including possible acute renal failure. These effects are usually reversible. Monitor renal function periodically in patients receiving enalapril and NSAID therapy. In a clinical pharmacology study, indomethacin or sulindac was administered to hypertensive patients receiving enalapril maleate. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Nursing Mothers Enalapril and enalaprilat have been detected in human breast milk. Because of the potential for serious adverse reactions in nursing infants from enalapril, a decision should be made whether to discontinue nursing or to discontinue enalapril maleate, taking into account the importance of the drug to the mother. Enalapril and enalaprilat have been detected in human breast milk. Because of the potential for serious adverse reactions in nursing infants from enalapril, a decision should be made whether to discontinue nursing or to discontinue enalapril maleate, taking into account the importance of the drug to the mother. Neonates with a History of In Utero Exposure to Enalapril Maleate If oliguria or hypotension occurs, direct attention toward support of blood pressure and renal perfusion. Exchange transfusions or dialysis may be required as a means of reversing hypotension and/or substituting for disordered renal function. Enalapril, which crosses the placenta, has been removed from neonatal circulation by peritoneal dialysis with some clinical benefit, and theoretically may be removed by exchange transfusion, although there is no experience with the latter procedure. Antihypertensive effects of enalapril maleate have been established in hypertensive pediatric patients age 1 month to 16 years. Use of enalapril maleate in these age groups is supported by evidence from adequate and well-controlled studies of enalapril maleate in pediatric and adult patients as well as by published literature in pediatric patients (see CLINICAL PHARMACOLOGY, Clinical Pharmacology in Pediatric Patients and DOSAGE AND ADMINISTRATION ). Enalapril maleate is not recommended in neonates and in pediatric patients with glomerular filtration rate <30 mL/min/1.73 m 2 , as no data are available."},{"title":"การได้รับยาเกินขนาด","body":"Limited data are available in regard to overdosage in humans. Single oral doses of enalapril above 1,000 mg/kg and ≥1,775 mg/kg were associated with lethality in mice and rats, respectively. The most likely manifestation of overdosage would be hypotension, for which the usual treatment would be intravenous infusion of normal saline solution. Enalaprilat may be removed from general circulation by hemodialysis and has been removed from neonatal circulation by peritoneal dialysis (see WARNINGS, Anaphylactoid Reactions during Membrane Exposure )."},{"title":"การเก็บรักษา","body":"Storage Store at 20° to 25°C (68° to 77°F) [see USP Controlled Room Temperature]. Keep container tightly closed. Protect from moisture. Dispense in a tight container as per USP, if product package is subdivided."}]},
{"key":"epinephrine|INTRAMUSCULAR","generic":"epinephrine","route":"INTRAMUSCULAR","brand":null,"title":"Adrenalin Vials","set_id":"28649937-8ae1-a022-e063-6394a90aebe0","effective":"20260112","sections":[{"title":"ข้อบ่งใช้","body":"Adrenalin ® is a non-selective alpha and beta adrenergic agonist indicated for: Emergency treatment of allergic reactions (Type 1), including anaphylaxis ( 1.1 ) To increase mean arterial blood pressure in adult patients with hypotension associated with septic shock ( 1.2 ) 1.1 Anaphylaxis Emergency treatment of allergic reactions (Type I), including anaphylaxis, which may result from insect stings or bites, foods, drugs, sera, diagnostic testing substances and other allergens, as well as idiopathic anaphylaxis or exercise-induced anaphylaxis. 1.2 Hypotension associated with Septic Shock Adrenalin is indicated to increase mean arterial blood pressure in adult patients with hypotension associated with septic shock."},{"title":"ขนาดยาและวิธีใช้","body":"Anaphylaxis : Adults and Children 30 kg (66 lbs) or more : 0.3 mg to 0.5 mg (0.3 mL to 0.5 mL) intramuscularly or subcutaneously into anterolateral aspect of the thigh every 5 to 10 minutes as necessary ( 2.2 ) Children 30 kg (66 lbs) or less : 0.01 mg/kg (0.01 mL/kg), up to 0.3 mg (0.3 mL), intramuscularly or subcutaneously into anterolateral aspect of the thigh every 5 to 10 minutes as necessary ( 2.2 ) Hypotension associated with septic shock: Dilute epinephrine in dextrose solution prior to infusion ( 2.3 ) Infuse epinephrine into a large vein ( 2.3 ) Intravenous infusion rate of 0.05 mcg/kg/min to 2 mcg/kg/min, titrated to achieve desired mean arterial pressure ( 2.3 ) Wean gradually ( 2.3 ) See Full Prescribing Information for instructions on dilution and administration of the injection. 2.1 General Considerations Inspect visually for particulate matter and discoloration prior to administration; solution should be clear and colorless. Do not use if the solution is colored or cloudy, or if it contains particulate matter. 2.2 Anaphylaxis Inject Adrenalin intramuscularly or subcutaneously into the anterolateral aspect of the thigh, through clothing if necessary. When administering to a child, to minimize the risk of injection related injury, hold the leg firmly in place and limit movement prior to and during an injection. The injection may be repeated every 5 to 10 minutes as necessary. For intramuscular administration, use a needle long enough (at least 1/2 inch) to ensure the injection is administered into the muscle. Monitor the patient clinically for the severity of the allergic reaction and potential cardiac effects of the drug, and repeat as needed. Do not administer repeated injections at the same site, as the resulting vasoconstriction may cause tissue necrosis. Adults and Children 30 kg (66 lbs) or more : 0.3 to 0.5 mg (0.3 to 0.5 mL) of undiluted Adrenalin administered intramuscularly or subcutaneously in the anterolateral aspect of the thigh, up to a maximum of 0.5 mg (0.5 mL) per injection, repeated every 5 to 10 minutes as necessary. Monitor clinically for reaction severity and cardiac effects. Children less than 30 kg (66 lbs) : 0.01 mg/kg (0.01 mL/kg) of undiluted Adrenalin administered intramuscularly or subcutaneously in the anterolateral aspect of the thigh, up to a maximum of 0.3 mg (0.3 mL) per injection, repeated every 5 to 10 minutes as necessary. Monitor clinically for reaction severity and cardiac effects. …"},{"title":"ข้อห้ามใช้","body":"None. None ( 4 )"},{"title":"คำเตือนและข้อควรระวัง","body":"Do not inject into buttocks, digits, hands, or feet ( 5.1 ) Avoid extravasation into tissues, which can cause local necrosis ( 5.3 ) May aggravate angina pectoris or produce ventricular arrhythmias ( 5.7 ) 5.1 Incorrect Locations of Injection for Anaphylaxis Injection into the anterolateral aspect of the thigh (vastus lateralis muscle) is the most appropriate location for administration because of its location, size, and available blood flow. Injection into (or near) smaller muscles, such as in the deltoid, is not recommended. Do not administer repeated injections of epinephrine at the same site, as the resulting vasoconstriction may cause tissue necrosis. Do not inject into buttock. Injection into the buttock may not provide effective treatment of anaphylaxis and has been associated with the development of Clostridial infections (gas gangrene). Do not inject into digits, hands, or feet. Epinephrine is a strong vasoconstrictor. Accidental injection into the digits, hands or feet may result in loss of blood flow to the affected area and tissue necrosis. 5.2 Serious Infections at the Injection Site Rare cases of serious skin and soft tissue infections, including necrotizing fasciitis and myonecrosis caused by Clostridia (gas gangrene), have been reported at the injection site following epinephrine injection for anaphylaxis. Advise patients to seek medical care if they develop signs or symptoms of infection, such as persistent redness, warmth, swelling, or tenderness, at the epinephrine injection site. 5.3 Extravasation and Tissue Necrosis with Intravenous Infusion Avoid extravasation of epinephrine into the tissues, to prevent local necrosis. When Adrenalin is administered intravenously, check the infusion site frequently for free flow. Blanching along the course of the infused vein, sometimes without obvious extravasation, may be attributed to vasa vasorum constriction with increased permeability of the vein wall, permitting some leakage. This also may progress on rare occasions to superficial slough. Hence, if blanching occurs, consider changing the infusion site at intervals to allow the effects of local vasoconstriction to subside. There is potential for gangrene in a lower extremity when infusions of catecholamine are given in an ankle vein. …"},{"title":"อาการไม่พึงประสงค์","body":"Common adverse reactions to systemically administered epinephrine include anxiety, apprehensiveness, restlessness, tremor, weakness, dizziness, sweating, palpitations, pallor, nausea and vomiting, headache, and respiratory difficulties. These symptoms occur in some persons receiving therapeutic doses of epinephrine, but are more likely to occur in patients with heart disease, hypertension, or hyperthyroidism [ see Warnings and Precautions (5.7) ] . The true incidence of adverse reactions associated with the systemic use of epinephrine is difficult to determine. Adverse reactions reported in observational trials, case reports, and studies are listed below by body system: Cardiovascular : angina, arrhythmias, hypertension, pallor, palpitations, tachyarrhythmia, tachycardia, vasoconstriction, ventricular ectopy and stress cardiomyopathy. Rapid rises in blood pressure associated with epinephrine use have produced cerebral hemorrhage, particularly in elderly patients with cardiovascular disease [ see Warnings and Precautions (5.7) ] . Neurological : disorientation, impaired memory, panic, psychomotor agitation, sleepiness, tingling. Psychiatric : anxiety, apprehensiveness, restlessness. Other : Patients with Parkinson’s disease may experience psychomotor agitation or a temporary worsening of symptoms [ see Warnings and Precautions (5.7) ] . Diabetic patients may experience transient increases in blood sugar. Injection into the buttock has resulted in cases of gas gangrene [ see Warnings and Precautions (5.1) ] . Rare cases of serious skin and soft tissue infections, including necrotizing fasciitis and myonecrosis caused by Clostridia (gas gangrene), have been reported following epinephrine injection in the thigh [ see Warnings and Precautions (5.2) ]. Common adverse reactions to systemically administered epinephrine include anxiety, tremor, weakness, dizziness, sweating, palpitations and pallor ( 6 ) To report SUSPECTED ADVERSE REACTIONS, contact Endo at 1-800-828-9393 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch ."},{"title":"Drug interaction","body":"Drugs that counter the pressor effects of epinephrine include alpha blockers, vasodilators such as nitrates, diuretics, antihypertensives and ergot alkaloids. ( 7.1 ) Drugs that potentiate the effects of epinephrine include sympathomimetics, beta blockers, tricyclic antidepressants, MAO inhibitors, COMT inhibitors, clonidine, doxapram, oxytocin, levothyroxine sodium, quinidine and certain antihistamines. ( 7.2 ) Drugs that increase the arrhythmogenic potential of epinephrine include beta blockers, cyclopropane and halogenated hydrocarbon anesthetics, antihistamines, exogenous thyroid hormones, diuretics, and cardiac glycosides. Observe for development of cardiac arrhythmias. ( 7.3 ) Potassium-depleting drugs, including corticosteroids, diuretics, and theophylline, potentiate the hypokalemic effects of epinephrine. ( 7.4 ) 7.1 Drugs Antagonizing Pressor Effects of Epinephrine α-blockers, such as phentolamine Vasodilators, such as nitrates Diuretics Antihypertensives Ergot alkaloids Phenothiazine antipsychotics 7.2 Drugs Potentiating Pressor Effects of Epinephrine Sympathomimetics β-blockers, such as propranolol Tricyclic anti-depressants Monoamine oxidase (MAO) inhibitors Catechol-O-methyl transferase (COMT) inhibitors, such as entacapone Clonidine Doxapram Oxytocin 7.3 Drugs Potentiating Arrhythmogenic Effects of Epinephrine Cardiac arrhythmias are more common among patients receiving any of the following drugs [ see Warnings and Precautions (5.7) and Adverse Reactions (6) ] . β-blockers, such as propranolol Cyclopropane or halogenated hydrocarbon anesthetics, such as halothane Antihistamines Thyroid hormones Diuretics Cardiac glycosides, such as digitalis glycosides Quinidine 7.4 Drugs Potentiating Hypokalemic Effects of Epinephrine Potassium depleting diuretics Corticosteroids Theophylline"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Prolonged experience with epinephrine use in pregnant women over several decades, based on published literature, do not identify a drug associated risk of major birth defects, miscarriage or adverse maternal or fetal outcomes. However, there are risks to the mother and fetus associated with epinephrine use during labor or delivery (see Clinical Considerations) . In animal reproduction studies, epinephrine administered by the subcutaneous route to pregnant rabbits, mice, and hamsters, during the period of organogenesis, resulted in adverse developmental effects (including gastroschisis, and embryonic lethality, and delayed skeletal ossification) at doses approximately 2 times the maximum recommended daily intramuscular, subcutaneous, or intravenous dose (see Data). The estimated background risk of major birth defects and miscarriage for the indicated population is unknown. All pregnancies have a background risk of birth defect, loss, or other adverse outcomes. In the United States general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2 to 4% and 15 to 20%, respectively. Clinical Considerations Disease-associated maternal and/or embryo/fetal risk During pregnancy, anaphylaxis can be catastrophic and can lead to hypoxic-ischemic encephalopathy and permanent central nervous system damage or death in the mother and, more commonly, in the fetus or neonate. The prevalence of anaphylaxis occurring during pregnancy is reported to be approximately 3 cases per 100,000 deliveries. Management of anaphylaxis during pregnancy is similar to management in the general population. Epinephrine is the first line-medication of choice for treatment of anaphylaxis; it should be used in the same manner in pregnant and non-pregnant patients. In conjunction with the administration of epinephrine, the patient should seek immediate medical or hospital care. Hypotension associated with septic shock is a medical emergency in pregnancy which can be fatal if left untreated. Delaying treatment in pregnant women with hypotension associated with septic shock may increase the risk of maternal and fetal morbidity and mortality. Life-sustaining therapy for the pregnant woman should not be withheld due to potential concerns regarding the effects of epinephrine on the fetus. …"},{"title":"การได้รับยาเกินขนาด","body":"of epinephrine may produce extremely elevated arterial pressure, which may result in cerebrovascular hemorrhage, particularly in elderly patients. Overdosage may also result in pulmonary edema because of peripheral vascular constriction together with cardiac stimulation. Epinephrine overdosage can also cause transient bradycardia followed by tachycardia and these may be accompanied by potentially fatal cardiac arrhythmias. Premature ventricular contractions may appear within one minute after injection and may be followed by multifocal ventricular tachycardia (prefibrillation rhythm). Subsidence of the ventricular effects may be followed by atrial tachycardia and occasionally by atrioventricular block. Myocardial ischemia and infarction, cardiomyopathy, extreme pallor and coldness of the skin, metabolic acidosis due to elevated blood lactic acid levels, and renal insufficiency have also been reported. Epinephrine is rapidly inactivated in the body and treatment following overdose with epinephrine is primarily supportive. Treatment of pulmonary edema consists of a rapidly acting alpha-adrenergic blocking drug (such as phentolamine mesylate) and respiratory support. Treatment of arrhythmias consists of administration of a beta-adrenergic blocking drug (such as propranolol). If necessary, pressor effects may be counteracted by rapidly acting vasodilators or α-adrenergic blocking drugs. If prolonged hypotension follows such measures, it may be necessary to administer another pressor drug."},{"title":"การเก็บรักษา","body":"Store between 20° to 25°C (68° to 77°F) [See USP Controlled Room Temperature] . Epinephrine is light sensitive. Protect from light and freezing. Inspect visually for particulate matter and discoloration prior to administration. Do not use the solution if it is colored or cloudy, or if it contains particulate matter."}]},
{"key":"erythromycin ethylsuccinate|ORAL","generic":"erythromycin ethylsuccinate","route":"ORAL","brand":null,"title":"Ery-Ped","set_id":"04775721-ab87-4b66-808c-d67a21032385","effective":"20231216","sections":[{"title":"ข้อบ่งใช้","body":"To reduce the development of drug-resistant bacteria and maintain the effectiveness of Ery-Ped and other antibacterial drugs, Ery-Ped should be used only to treat or prevent infections that are proven or strongly suspected to be caused by susceptible bacteria. When culture and susceptibility information are available, they should be considered in selecting or modifying antibacterial therapy. In the absence of such data, local epidemiology and susceptibility patterns may contribute to the empiric selection of therapy. Ery-Ped is indicated in the treatment of infections caused by susceptible strains of the designated organisms in the diseases listed below: Upper respiratory tract infections of mild to moderate degree caused by Streptococcus pyogenes, Streptococcus pneumoniae, or Haemophilus influenzae (when used concomitantly with adequate doses of sulfonamides, since many strains of H. influenzae are not susceptible to the erythromycin concentrations ordinarily achieved). (See appropriate sulfonamide labeling for prescribing information.) Lower-respiratory tract infections of mild to moderate severity caused by Streptococcus pneumoniae or Streptococcus pyogenes . Listeriosis caused by Listeria monocytogenes . Pertussis (whooping cough) caused by Bordetella pertussis . Erythromycin is effective in eliminating the organism from the nasopharynx of infected individuals rendering them noninfectious. Some clinical studies suggest that erythromycin may be helpful in the prophylaxis of pertussis in exposed susceptible individuals. Respiratory tract infections due to Mycoplasma pneumoniae . Skin and skin structure infections of mild to moderate severity caused by Streptococcus pyogenes or Staphylococcus aureus (resistant staphylococci may emerge during treatment). Diphtheria Infections due to Corynebacterium diphtheriae , as an adjunct to antitoxin, to prevent establishment of carriers and to eradicate the organism in carriers. Erythrasma In the treatment of infections due to Corynebacterium minutissimum . Intestinal amebiasis caused by Entamoeba histolytica (oral erythromycins only). Extraenteric amebiasis requires treatment with other agents. Acute Pelvic Inflammatory Disease Caused by Neisseria gonorrhoeae As an alternative drug in treatment of acute pelvic inflammatory disease caused by N. gonorrhoeae in female patients with a history of sensitivity to penicillin. …"},{"title":"ขนาดยาและวิธีใช้","body":"Ery-Ped (erythromycin ethylsuccinate) oral suspensions may be administered without regard to meals. Children Age, weight, and severity of the infection are important factors in determining the proper dosage. In mild to moderate infections, the usual dosage of erythromycin ethylsuccinate for children is 30 to 50 mg/kg/day in equally divided doses every 6 hours. For more severe infections this dosage may be doubled. If twice-a-day dosage is desired, one-half of the total daily dose may be given every 12 hours. Doses may also be given three times daily by administering one-third of the total daily dose every 8 hours. The following dosage schedule is suggested for mild to moderate infections: Body Weight Total Daily Dose Under 10 lbs 30-50 mg/kg/day 15-25 mg/lb/day 10 to 15 lbs 200 mg 16 to 25 lbs 400 mg 26 to 50 lbs 800 mg 51 to 100 lbs 1200 mg over 100 lbs 1600 mg Adults 400 mg erythromycin ethylsuccinate every 6 hours is the usual dose. Dosage may be increased up to 4 g per day according to the severity of the infection. If twice-a-day dosage is desired, one-half of the total daily dose may be given every 12 hours. Doses may also be given three times daily by administering one-third of the total daily dose every 8 hours. For adult dosage calculation, use a ratio of 400 mg of erythromycin activity as the ethylsuccinate to 250 mg of erythromycin activity as the stearate, base or estolate. In the treatment of streptococcal infections, a therapeutic dosage of erythromycin ethylsuccinate should be administered for at least 10 days. In continuous prophylaxis against recurrences of streptococcal infections in persons with a history of rheumatic heart disease, the usual dosage is 400 mg twice a day. For treatment of urethritis due to C. trachomatis or U. urealyticum 800 mg three times a day for 7 days. For treatment of primary syphilis Adults 48 to 64 g given in divided doses over a period of 10 to 15 days For intestinal amebiasis Adults 400 mg four times daily for 10 to 14 days. Children 30 to 50 mg/kg/day in divided doses for 10 to 14 days. For use in pertussis Although optimal dosage and duration have not been established, doses of erythromycin utilized in reported clinical studies were 40 to 50 mg/kg/day, given in divided doses for 5 to 14 days. For treatment of Legionnaires' Disease Although optimal doses have not been established, doses utilized in reported clinical data were 1.6 to 4 g daily in divided doses."},{"title":"ข้อห้ามใช้","body":"Erythromycin is contraindicated in patients with known hypersensitivity to this antibiotic. Erythromycin is contraindicated in patients taking terfenadine, astemizole, pimozide, or cisapride. (See PRECAUTIONS - Drug Interactions .) Do not use erythromycin concomitantly with HMG CoA reductase inhibitors (statins) that are extensively metabolized by CYP 3A4 (lovastatin or simvastatin), due to the increased risk of myopathy, including rhabdomyolysis."},{"title":"คำเตือนและข้อควรระวัง","body":"Hepatotoxicity There have been reports of hepatic dysfunction, including increased liver enzymes, and hepatocellular and/or cholestatic hepatitis, with or without jaundice, occurring in patients receiving oral erythromycin products. QT Prolongation Erythromycin has been associated with prolongation of the QT interval and infrequent cases of arrhythmia. Cases of torsades de pointes have been spontaneously reported during postmarketing surveillance in patients receiving erythromycin. Fatalities have been reported. Erythromycin should be avoided in patients with known prolongation of the QT interval, patients with ongoing proarrhythmic conditions such as uncorrected hypokalemia or hypomagnesemia, clinically significant bradycardia, and in patients receiving Class IA (quinidine, procainamide) or Class III (dofetilide, amiodarone, sotalol) antiarrhythmic agents. Elderly patients may be more susceptible to drug-associated effects on the QT interval. Syphilis in Pregnancy There have been reports suggesting that erythromycin does not reach the fetus in adequate concentration to prevent congenital syphilis. Infants born to women treated during pregnancy with oral erythromycin for early syphilis should be treated with an appropriate penicillin regimen. Clostridium difficile Associated Diarrhea Clostridium difficile associated diarrhea (CDAD) has been reported with use of nearly all antibacterial agents, including Ery-Ped, and may range in severity from mild diarrhea to fatal colitis. Treatment with antibacterial agents alters the normal flora of the colon leading to overgrowth of C. difficile . C. difficile produces toxins A and B which contribute to the development of CDAD. Hypertoxin producing strains of C. difficile cause increased morbidity and mortality, as these infections can be refractory to antimicrobial therapy and may require colectomy. CDAD must be considered in all patients who present with diarrhea following antibiotic use. Careful medical history is necessary since CDAD has been reported to occur over two months after the administration of antibacterial agents. If CDAD is suspected or confirmed, ongoing antibiotic use not directed against C. difficile may need to be discontinued. Appropriate fluid and electrolyte management, protein supplementation, antibiotic treatment of C. difficile, and surgical evaluation should be instituted as clinically indicated. …"},{"title":"อาการไม่พึงประสงค์","body":"The most frequent side effects of oral erythromycin preparations are gastrointestinal and are dose-related. They include nausea, vomiting, abdominal pain, diarrhea and anorexia. Symptoms of hepatitis, hepatic dysfunction and/or abnormal liver function test results may occur. (See WARNINGS section.) Onset of pseudomembranous colitis symptoms may occur during or after antibacterial treatment. (See WARNINGS .) Erythromycin has been associated with QT prolongation and ventricular arrhythmias, including ventricular tachycardia and torsades de pointes. (See WARNINGS .) Allergic reactions ranging from urticaria to anaphylaxis have occurred. Skin reactions ranging from mild eruptions to erythema multiforme, Stevens-Johnson syndrome, and toxic epidermal necrolysis have been reported rarely. There have been reports of interstitial nephritis coincident with erythromycin use. There have been rare reports of pancreatitis and convulsions. There have been isolated reports of reversible hearing loss occurring chiefly in patients with renal insufficiency and in patients receiving high doses of erythromycin."},{"title":"Drug interaction","body":"Theophylline Erythromycin use in patients who are receiving high doses of theophylline may be associated with an increase in serum theophylline levels and potential theophylline toxicity. In case of theophylline toxicity and/or elevated serum theophylline levels, the dose of theophylline should be reduced while the patient is receiving concomitant erythromycin therapy. There have been published reports suggesting that when oral erythromycin is given concurrently with theophylline there is a decrease in erythromycin serum concentrations of approximately 35%. The mechanism by which this interaction occurs is unknown. The decrease in erythromycin concentrations due to co-administration of theophylline could result in subtherapeutic concentrations of erythromycin. Hypotension, bradyarrhythmias, and lactic acidosis have been observed in patients receiving concurrent verapamil, belonging to the calcium channel blockers drug class. Concomitant administration of erythromycin and digoxin has been reported to result in elevated digoxin serum levels. There have been reports of increased anticoagulant effects when erythromycin and oral anticoagulants were used concomitantly. Increased anticoagulation effects due to interactions of erythromycin with various oral anticoagulants may be more pronounced in the elderly. Erythromycin is a substrate and inhibitor of the 3A isoform subfamily of the cytochrome p450 enzyme system (CYP3A). Coadministration of erythromycin and a drug primarily metabolized by CYP3A may be associated with elevations in drug concentrations that could increase or prolong both the therapeutic and adverse effects of the concomitant drug. Dosage adjustments may be considered, and when possible, serum concentrations of drugs primarily metabolized by CYP3A should be monitored closely in patients concurrently receiving erythromycin. The following are examples of some clinically significant CYP3A based drug interactions. Interactions with other drugs metabolized by the CYP3A isoform are also possible. The following CYP3A based drug interactions have been observed with erythromycin products in post-marketing experience: Ergotamine/dihydroergotamine Post-marketing reports indicate that co-administration of erythromycin with ergotamine or dihydroergotamine has been associated with acute ergot toxicity characterized by vasospasm and ischemia of the extremities and other tissues including the central nervous system. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Teratogenic Effects There is no evidence of teratogenicity or any other adverse effect on reproduction in female rats fed erythromycin base by oral gavage at 350 mg/kg/day (approximately twice the maximum recommended human dose on a body surface area) prior to and during mating, during gestation, and through weaning. No evidence of teratogenicity or embryotoxicity was observed when erythromycin base was given by oral gavage to pregnant rats and mice at 700 mg/kg/day and to pregnant rabbits at 125 mg/kg/day (approximately 1-3 times the maximum recommended human dose). Erythromycin is excreted in human milk. Caution should be exercised when erythromycin is administered to a nursing woman. See INDICATIONS AND USAGE and DOSAGE AND ADMINISTRATION sections. Elderly patients, particularly those with reduced renal or hepatic function, may be at increased risk for developing erythromycin-induced hearing loss. (See ADVERSE REACTIONS and DOSAGE AND ADMINISTRATION ). Elderly patients may be more susceptible to development of torsades de pointes arrhythmias than younger patients. (See WARNINGS ). Elderly patients may experience increased effects of oral anticoagulant therapy while undergoing treatment with erythromycin. (See PRECAUTIONS - Drug Interactions ). Ery-Ped 200 contains 117.5 mg (5.1 mEq) of sodium per individual dose. Ery-Ped 400 contains 117.5 mg (5.1 mEq) of sodium per individual dose. Based on the 200 mg/5 mL strength, at the usual recommended doses, adult patients would receive a total of 940 mg/day (40.8 mEq) of sodium. Based on the 400 mg/5 mL strength, at the usual recommended doses, adult patients would receive a total of 470 mg/day (20.4 mEq) of sodium. The geriatric population may respond with a blunted natriuresis to salt loading. This may be clinically important with regard to such diseases as congestive heart failure."},{"title":"การได้รับยาเกินขนาด","body":"In case of overdosage, erythromycin should be discontinued. Overdosage should be handled with the prompt elimination of unabsorbed drug and all other appropriate measures should be instituted. Erythromycin is not removed by peritoneal dialysis or hemodialysis."},{"title":"การเก็บรักษา","body":"Recommended Storage Store Ery-Ped 200 and Ery-Ped 400, prior to mixing, below 86°F (30°C). After reconstitution, Ery-Ped 200 and Ery-Ped 400 must be stored at or below 77°F (25°C) and used within 35 days; refrigeration is not required."}]},
{"key":"ferrous sulfate|ORAL","generic":"ferrous sulfate","route":"ORAL","brand":null,"title":"Ferrous Sulfate","set_id":"5514d582-19b5-4f1e-b794-f790afb8211c","effective":"20241226","sections":[{"title":"ข้อบ่งใช้","body":"SUGGESTED USE:"},{"title":"ขนาดยาและวิธีใช้","body":"DRUG INTERACTION PRECAUTION: Since oral iron products interfere with absorption of oral tetracycline antibiotics, these products should not be taken within two hours of each other."},{"title":"คำเตือนกรอบดำ","body":"WARNING: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product out of reach of children. In case of accidental overdose, call a doctor or Poison Control Center immediately."},{"title":"คำเตือนและข้อควรระวัง","body":"Do not exceed recommended dosage. The treatment of any anemic condition should be under the advice and supervision of a doctor. Occasional gastrointestinal discomfort (such as nausea) may be minimized by taking with meals. Iron-containing medication may occasionally cause constipation or diarrhea. As with any drug, if you are pregnant or nursing a baby, seek the advice of a health professional before using this product."}]},
{"key":"folic acid|ORAL","generic":"folic acid","route":"ORAL","brand":null,"title":"Folic acid","set_id":"454f9fdc-fd8c-4838-8e5b-10f4c74110dd","effective":"20210524","sections":[{"title":"ข้อบ่งใช้","body":"Folic acid is effective in the treatment of megaloblastic anemias due to a deficiency of folic acid (as may be seen in tropical or nontropical sprue) and in anemias of nutritional origin, pregnancy, infancy, or childhood."},{"title":"ขนาดยาและวิธีใช้","body":"Oral administration is preferred. Although most patients with malabsorption cannot absorb food folates, they are able to absorb folic acid given orally. Parenteral administration is not advocated but may be necessary in some individuals (e.g., patients receiving parenteral or enteral alimentation). Doses greater than 0.1 mg should not be used unless anemia due to vitamin B 12 deficiency has been ruled out or is being adequately treated with a cobalamin. Daily doses greater than 1 mg do not enhance the hematologic effect, and most of the excess is excreted unchanged in the urine. The usual therapeutic dosage in adults and children (regardless of age) is up to 1 mg daily. Resistant cases may require larger doses. When clinical symptoms have subsided and the blood picture has become normal, a daily maintenance level should be used, i.e., 0.1 mg for infants and up to 0.3 mg for children under 4 years of age, 0.4 mg for adults and children 4 or more years of age, and 0.8 mg for pregnant and lactating women, but never less than 0.1 mg/day. Patients should be kept under close supervision and adjustment of the maintenance level made if relapse appears imminent. In the presence of alcoholism, hemolytic anemia, anticonvulsant therapy, or chronic infection, the maintenance level may need to be increased."},{"title":"ข้อห้ามใช้","body":"Folic acid is contraindicated in patients who have shown previous intolerance to the drug."},{"title":"คำเตือนและข้อควรระวัง","body":"Administration of folic acid alone is improper therapy for pernicious anemia and other megaloblastic anemias in which vitamin B 12 is deficient. General Folic acid in doses above 0.1 mg daily may obscure pernicious anemia in that hematologic remission can occur while neurologic manifestations remain progressive. There is a potential danger in administering folic acid to patients with undiagnosed anemia, since folic acid may obscure the diagnosis of pernicious anemia by alleviating the hematologic manifestations of the disease while allowing the neurologic complications to progress. This may result in severe nervous system damage before the correct diagnosis is made. Adequate doses of vitamin B 12 may prevent, halt, or improve the neurologic changes caused by pernicious anemia. Drug Interactions There is evidence that the anticonvulsant action of phenytoin is antagonized by folic acid. A patient whose epilepsy is completely controlled by phenytoin may require increased doses to prevent convulsions if folic acid is given. Folate deficiency may result from increased loss of folate, as in renal dialysis and/or interference with metabolism (e.g., folic acid antagonists such as methotrexate); the administration of anticonvulsants, such as diphenylhydantoin, primidone, and barbiturates; alcohol consumption and, especially, alcoholic cirrhosis; and the administration of pyrimethamine and nitrofurantoin. False low serum and red cell folate levels may occur if the patient has been taking antibiotics, such as tetracycline, which suppress the growth of Lactobacillus casei. Carcinogenesis, Mutagenesis, Impairment of Fertility Long-term studies in animals to evaluate carcinogenic potential and studies to evaluate the mutagenic potential or effect on fertility have not been conducted. Pregnancy Teratogenic Effects Pregnancy Category A Folic acid is usually indicated in the treatment of megaloblastic anemias of pregnancy. Folic acid requirements are markedly increased during pregnancy, and deficiency will result in fetal damage (see INDICATIONS AND USAGE .). Studies in pregnant women have not shown that folic acid increases the risk of fetal abnormalities if administered during pregnancy. If the drug is used during pregnancy, the possibility of fetal harm appears remote. Because studies cannot rule out the possibility of harm, however, folic acid should be used during pregnancy only if clearly needed. …"},{"title":"อาการไม่พึงประสงค์","body":"Allergic sensitization has been reported following both oral and parenteral administration of folic acid. Folic acid is relatively nontoxic in man. Rare instances of allergic responses to folic acid preparations have been reported and have included erythema, skin rash, itching, general malaise, and respiratory difficulty due to bronchospasm. One patient experienced symptoms suggesting anaphylaxis following injection of the drug. Gastrointestinal side effects, including anorexia, nausea, abdominal distention, flatulence, and a bitter or bad taste, have been reported in patients receiving 15 mg folic acid daily for 1 month. Other side effects reported in patients receiving 15 mg daily include altered sleep patterns, difficulty in concentrating, irritability, overactivity, excitement, mental depression, confusion, and impaired judgment. Decreased vitamin B 12 serum levels may occur in patients receiving prolonged folic acid therapy. In an uncontrolled study, orally administered folic acid was reported to increase the incidence of seizures in some epileptic patients receiving phenobarbital, primidone, or diphenylhydantoin. Another investigator reported decreased diphenylhydantoin serum levels in folate-deficient patients receiving diphenylhydantoin who were treated with 5 mg or 15 mg of folic acid daily."},{"title":"Drug interaction","body":"There is evidence that the anticonvulsant action of phenytoin is antagonized by folic acid. A patient whose epilepsy is completely controlled by phenytoin may require increased doses to prevent convulsions if folic acid is given. Folate deficiency may result from increased loss of folate, as in renal dialysis and/or interference with metabolism (e.g., folic acid antagonists such as methotrexate); the administration of anticonvulsants, such as diphenylhydantoin, primidone, and barbiturates; alcohol consumption and, especially, alcoholic cirrhosis; and the administration of pyrimethamine and nitrofurantoin. False low serum and red cell folate levels may occur if the patient has been taking antibiotics, such as tetracycline, which suppress the growth of Lactobacillus casei."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Teratogenic Effects Pregnancy Category A Folic acid is usually indicated in the treatment of megaloblastic anemias of pregnancy. Folic acid requirements are markedly increased during pregnancy, and deficiency will result in fetal damage (see INDICATIONS AND USAGE .). Studies in pregnant women have not shown that folic acid increases the risk of fetal abnormalities if administered during pregnancy. If the drug is used during pregnancy, the possibility of fetal harm appears remote. Because studies cannot rule out the possibility of harm, however, folic acid should be used during pregnancy only if clearly needed. Folic acid is excreted in the milk of lactating mothers. During lactation, folic acid requirements are markedly increased; however, amounts present in human milk are adequate to fulfill infant requirements, although supplementation may be needed in low-birth-weight infants, in those who are breast-fed by mothers with folic acid deficiency (50 mcg daily), or in those with infections or prolonged diarrhea."},{"title":"การได้รับยาเกินขนาด","body":"Except during pregnancy and lactation, folic acid should not be given in therapeutic doses greater than 0.4 mg daily until pernicious anemia has been ruled out. Patients with pernicious anemia receiving more than 0.4 mg of folic acid daily who are inadequately treated with vitamin B 12 may show reversion of the hematologic parameters to normal, but neurologic manifestations due to vitamin B 12 deficiency will progress. Doses of folic acid exceeding the Recommended Dietary Allowance (RDA) should not be included in multivitamin preparations; if therapeutic amounts are necessary, folic acid should be given separately."},{"title":"การเก็บรักษา","body":"Dispense in a well-closed container with child-resistant closure. Store at 20°-25°C (68°-77°F). [see USP Controlled Room Temperature]."}]},
{"key":"furosemide|ORAL","generic":"furosemide","route":"ORAL","brand":null,"title":"Furosemide","set_id":"2a5bcf50-6d63-463a-915e-a72ea2e5f131","effective":"20260618","sections":[{"title":"ข้อบ่งใช้","body":"Edema Furosemide tablets are indicated in adults and pediatric patients for the treatment of edema associated with congestive heart failure, cirrhosis of the liver, and renal disease, including the nephrotic syndrome. Furosemide tablets are particularly useful when an agent with greater diuretic potential is desired. Hypertension Oral furosemide may be used in adults for the treatment of hypertension alone or in combination with other antihypertensive agents. Hypertensive patients who cannot be adequately controlled with thiazides will probably also not be adequately controlled with furosemide alone. Edema Furosemide tablets are indicated in adults and pediatric patients for the treatment of edema associated with congestive heart failure, cirrhosis of the liver, and renal disease, including the nephrotic syndrome. Furosemide tablets are particularly useful when an agent with greater diuretic potential is desired. Hypertension Oral furosemide may be used in adults for the treatment of hypertension alone or in combination with other antihypertensive agents. Hypertensive patients who cannot be adequately controlled with thiazides will probably also not be adequately controlled with furosemide alone."},{"title":"ขนาดยาและวิธีใช้","body":"Edema Therapy should be individualized according to patient response to gain maximal therapeutic response and to determine the minimal dose needed to maintain that response. Adults - The usual initial dose of furosemide tablets is 20 to 80 mg given as a single dose. Ordinarily a prompt diuresis ensues. If needed, the same dose can be administered 6 to 8 hours later or the dose may be increased. The dose may be raised by 20 or 40 mg and given not sooner than 6 to 8 hours after the previous dose until the desired diuretic effect has been obtained. The individually determined single dose should then be given once or twice daily (e.g., at 8 am and 2 pm). The dose of furosemide tablets may be carefully titrated up to 600 mg/day in patients with clinically severe edematous states. Edema may be most efficiently and safely mobilized by giving furosemide tablets on 2 to 4 consecutive days each week. When doses exceeding 80 mg/day are given for prolonged periods, careful clinical observation and laboratory monitoring are particularly advisable (see PRECAUTIONS: Laboratory Tests ). Geriatric Patients - In general, dose selection for the elderly patient should be cautious, usually starting at the low end of the dosing range (see PRECAUTIONS: Geriatric Use ). Pediatric Patients - The usual initial dose of oral furosemide in pediatric patients is 2 mg/kg body weight, given as a single dose. If the diuretic response is not satisfactory after the initial dose, dosage may be increased by 1 or 2 mg/kg no sooner than 6 to 8 hours after the previous dose. Doses greater than 6 mg/kg body weight are not recommended. For maintenance therapy in pediatric patients, the dose should be adjusted to the minimum effective level. Hypertension Therapy should be individualized according to the patient's response to gain maximal therapeutic response and to determine the minimal dose needed to maintain the therapeutic response. Adults - The usual initial dose of furosemide tablets for hypertension is 80 mg, usually divided into 40 mg twice a day. Dosage should then be adjusted according to response. If response is not satisfactory, add other antihypertensive agents. Changes in blood pressure must be carefully monitored when furosemide tablets are used with other antihypertensive drugs, especially during initial therapy. To prevent excessive drop in blood pressure, the dosage of other agents should be reduced by at least 50 percent when furosemide tablets are added to the regimen. …"},{"title":"ข้อห้ามใช้","body":"Furosemide tablets are contraindicated in patients with anuria and in patients with a history of hypersensitivity to furosemide."},{"title":"คำเตือนและข้อควรระวัง","body":"WARNING Furosemide is a potent diuretic which, if given in excessive amounts, can lead to a profound diuresis with water and electrolyte depletion. Therefore, careful medical supervision is required and dose and dose schedule must be adjusted to the individual patient's needs (see DOSAGE AND ADMINISTRATION ). WARNINGS In patients with hepatic cirrhosis and ascites, furosemide therapy is best initiated in the hospital. In hepatic coma and in states of electrolyte depletion, therapy should not be instituted until the basic condition is improved. Sudden alterations of fluid and electrolyte balance in patients with cirrhosis may precipitate hepatic coma; therefore, strict observation is necessary during the period of diuresis. Supplemental potassium chloride and, if required, an aldosterone antagonist is helpful in preventing hypokalemia and metabolic alkalosis. If increasing azotemia and oliguria occur during treatment of severe progressive renal disease, furosemide should be discontinued. Cases of tinnitus and reversible or irreversible hearing impairment and deafness have been reported. Reports usually indicate that furosemide ototoxicity is associated with rapid injection, severe renal impairment, the use of higher than recommended doses, hypoproteinemia or concomitant therapy with aminoglycoside antibiotics, ethacrynic acid, or other ototoxic drugs. If the physician elects to use high dose parenteral therapy, controlled intravenous infusion is advisable (for adults, an infusion rate not exceeding 4 mg furosemide per minute has been used) (see PRECAUTIONS: Drug Interactions ). General Excessive diuresis may cause dehydration and blood volume reduction with circulatory collapse and possibly vascular thrombosis and embolism, particularly in elderly patients. As with any effective diuretic, electrolyte depletion may occur during furosemide therapy, especially in patients receiving higher doses and a restricted salt intake. Hypokalemia may develop with furosemide, especially with brisk diuresis, inadequate oral electrolyte intake, when cirrhosis is present, or during concomitant use of corticosteroids, ACTH, licorice in large amounts, or prolonged use of laxatives. Digitalis therapy may exaggerate metabolic effects of hypokalemia, especially myocardial effects. …"},{"title":"อาการไม่พึงประสงค์","body":"Adverse reactions are categorized below by organ system and listed by decreasing severity. Gastrointestinal System Reactions 1. hepatic encephalopathy in patients with hepatocellular insufficiency 6. oral and gastric irritation 7. cramping 2. pancreatitis 8. diarrhea 3. jaundice (intrahepatic cholestatic jaundice) 9. constipation 4. increased liver enzymes 10. nausea 5. anorexia 11. vomiting Systemic Hypersensitivity Reactions 1. severe anaphylactic or anaphylactoid reactions (e.g., with shock) 3. interstitial nephritis 2. systemic vasculitis 4. necrotizing angiitis Central Nervous System Reactions 1. tinnitus and hearing loss 5. headache 2. paresthesias 6. blurred vision 3. vertigo 7. xanthopsia 4. dizziness Hematologic Reactions 1. aplastic anemia 5. leukopenia 2. thrombocytopenia 6. anemia 3. agranulocytosis 7. eosinophilia 4. hemolytic anemia Dermatologic-Hypersensitivity Reactions 1. toxic epidermal necrolysis 7. bullous pemphigoid 2. Stevens-Johnson Syndrome 8. purpura 3. erythema multiforme 9. fever 4. drug rash with eosinophilia and systemic symptoms 10. rash 5. acute generalized exanthematous pustulosis 11. pruritus 6. exfoliative dermatitis 12. urticaria Cardiovascular Reaction 1. Orthostatic hypotension may occur and be aggravated by alcohol, barbiturates or narcotics. 2. Increase in cholesterol and triglyceride serum levels Other Reactions 1. hyperglycemia 6. restlessness 2. glycosuria 7. urinary bladder spasm 3. hyperuricemia 8. thrombophlebitis 4. muscle spasm 9. fever 5. weakness Whenever adverse reactions are moderate or severe, furosemide dosage should be reduced or therapy withdrawn. To report SUSPECTED ADVERSE REACTIONS, contact Solco Healthcare US, LLC at 1-866-257-2597 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch."},{"title":"Drug interaction","body":"Furosemide may increase the ototoxic potential of aminoglycoside antibiotics, especially in the presence of impaired renal function. Except in life-threatening situations, avoid this combination. Furosemide should not be used concomitantly with ethacrynic acid because of the possibility of ototoxicity. Patients receiving high doses of salicylates concomitantly with furosemide, as in rheumatic disease, may experience salicylate toxicity at lower doses because of competitive renal excretory sites. There is a risk of ototoxic effects if cisplatin and furosemide are given concomitantly. In addition, nephrotoxicity of nephrotoxic drugs such as cisplatin may be enhanced if furosemide is not given in lower doses and with positive fluid balance when used to achieve forced diuresis during cisplatin treatment. Furosemide has a tendency to antagonize the skeletal muscle-relaxing effect of tubocurarine and may potentiate the action of succinylcholine. Lithium generally should not be given with diuretics because they reduce lithium's renal clearance and add a high risk of lithium toxicity. Furosemide combined with angiotensin-converting enzyme inhibitors or angiotensin II receptor blockers may lead to severe hypotension and deterioration in renal function, including renal failure. An interruption or reduction in the dosage of furosemide, angiotensin-converting enzyme inhibitors, or angiotensin receptor blockers may be necessary. Potentiation occurs with ganglionic or peripheral adrenergic blocking drugs. Furosemide may decrease arterial responsiveness to norepinephrine. However, norepinephrine may still be used effectively. Simultaneous administration of sucralfate and furosemide tablets may reduce the natriuretic and antihypertensive effects of furosemide. Patients receiving both drugs should be observed closely to determine if the desired diuretic and/or antihypertensive effect of furosemide is achieved. The intake of furosemide and sucralfate should be separated by at least two hours. In isolated cases, intravenous administration of furosemide within 24 hours of taking chloral hydrate may lead to flushing, sweating attacks, restlessness, nausea, increase in blood pressure, and tachycardia. Use of furosemide concomitantly with chloral hydrate is therefore not recommended. Phenytoin interferes directly with renal action of furosemide. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Furosemide has been shown to cause unexplained maternal deaths and abortions in rabbits at 2, 4 and 8 times the maximal recommended human dose. There are no adequate and well-controlled studies in pregnant women. Furosemide should be used during pregnancy only if the potential benefit justifies the potential risk to the fetus. Treatment during pregnancy requires monitoring of fetal growth because of the potential for higher birth weights. The effects of furosemide on embryonic and fetal development and on pregnant dams were studied in mice, rats and rabbits. Furosemide caused unexplained maternal deaths and abortions in the rabbit at the lowest dose of 25 mg/kg (2 times the maximal recommended human dose of 600 mg/day). In another study, a dose of 50 mg/kg (4 times the maximal recommended human dose of 600 mg/day) also caused maternal deaths and abortions when administered to rabbits between Days 12 and 17 of gestation. In a third study, none of the pregnant rabbits survived a dose of 100 mg/kg. Data from the above studies indicate fetal lethality that can precede maternal deaths. The results of the mouse study and one of the three rabbit studies also showed an increased incidence and severity of hydronephrosis (distention of the renal pelvis and, in some cases, of the ureters) in fetuses derived from the treated dams as compared with the incidence in fetuses from the control group. Because it appears in breast milk, caution should be exercised when furosemide is administered to a nursing mother. Furosemide may inhibit lactation. In premature infants furosemide may precipitate nephrocalcinosis/nephrolithiasis. Nephrocalcinosis/nephrolithiasis has also been observed in children under 4 years of age with no history of prematurity who have been treated chronically with furosemide. Monitor renal function, and renal ultrasonography should be considered, in pediatric patients receiving furosemide. If furosemide is administered to premature infants during the first weeks of life, it may increase the risk of persistence of patent ductus arteriosus. Pediatric Patients - The usual initial dose of oral furosemide in pediatric patients is 2 mg/kg body weight, given as a single dose. If the diuretic response is not satisfactory after the initial dose, dosage may be increased by 1 or 2 mg/kg no sooner than 6 to 8 hours after the previous dose. Doses greater than 6 mg/kg body weight are not recommended. …"},{"title":"การได้รับยาเกินขนาด","body":"The principal signs and symptoms of overdose with furosemide are dehydration, blood volume reduction, hypotension, electrolyte imbalance, hypokalemia and hypochloremic alkalosis, and are extensions of its diuretic action. The acute toxicity of furosemide has been determined in mice, rats and dogs. In all three, the oral LD 50 exceeded 1000 mg/kg body weight, while the intravenous LD 50 ranged from 300 to 680 mg/kg. The acute intragastric toxicity in neonatal rats is 7 to 10 times that of adult rats. The concentration of furosemide in biological fluids associated with toxicity or death is not known. Treatment of overdosage is supportive and consists of replacement of excessive fluid and electrolyte losses. Serum electrolytes, carbon dioxide level and blood pressure should be determined frequently. Adequate drainage must be assured in patients with urinary bladder outlet obstruction (such as prostatic hypertrophy). Hemodialysis does not accelerate furosemide elimination."},{"title":"การเก็บรักษา","body":"Store at 68° to 77°F (20° to 25°C); excursions permitted to 59° to 86°F (15° to 30°C) [see USP Controlled Room Temperature]."}]},
{"key":"gemfibrozil|ORAL","generic":"gemfibrozil","route":"ORAL","brand":null,"title":"Gemfibrozil","set_id":"75cac02c-56e3-4dfe-b1e2-4ce166b28833","effective":"20260410","sections":[{"title":"ข้อบ่งใช้","body":"Gemfibrozil Tablets are indicated as adjunctive therapy to diet for: Treatment of adult patients with very high elevations of serum triglyceride levels (Types IV and V hyperlipidemia) who present a risk of pancreatitis and who do not respond adequately to a determined dietary effort to control them. Patients who present such risk typically have serum triglycerides over 2000 mg/dL and have elevations of VLDL-cholesterol as well as fasting chylomicrons (Type V hyperlipidemia). Subjects who consistently have total serum or plasma triglycerides below 1000 mg/dL are unlikely to present a risk of pancreatitis. Gemfibrozil therapy may be considered for those subjects with triglyceride elevations between 1000 and 2000 mg/dL who have a history of pancreatitis or of recurrent abdominal pain typical of pancreatitis. It is recognized that some Type IV patients with triglycerides under 1000 mg/dL may, through dietary or alcoholic indiscretion, convert to a Type V pattern with massive triglyceride elevations accompanying fasting chylomicronemia, but the influence of gemfibrozil therapy on the risk of pancreatitis in such situations has not been adequately studied. Drug therapy is not indicated for patients with Type I hyperlipoproteinemia, who have elevations of chylomicrons and plasma triglycerides, but who have normal levels of very low density lipoprotein (VLDL). Inspection of plasma refrigerated for 14 hours is helpful in distinguishing Types I, IV, and V hyperlipoproteinemia. Reducing the risk of developing coronary heart disease only in Type IIb patients without history of or symptoms of existing coronary heart disease who have had an inadequate response to weight loss, dietary therapy, exercise, and other pharmacologic agents (such as bile acid sequestrants and nicotinic acid, known to reduce LDL- and raise HDL-cholesterol) and who have the following triad of lipid abnormalities: low HDL-cholesterol levels in addition to elevated LDL-cholesterol and elevated triglycerides (see WARNINGS , PRECAUTIONS , and CLINICAL PHARMACOLOGY ). The National Cholesterol Education Program has defined a serum HDL-cholesterol value that is consistently below 35 mg/dL as constituting an independent risk factor for coronary heart disease. Patients with significantly elevated triglycerides should be closely observed when treated with gemfibrozil. In some patients with high triglyceride levels, treatment with gemfibrozil is associated with a significant increase in LDL-cholesterol. …"},{"title":"ขนาดยาและวิธีใช้","body":"The recommended dose for adults is 1200 mg administered in two divided doses 30 minutes before the morning and evening meals (see CLINICAL PHARMACOLOGY )."},{"title":"ข้อห้ามใช้","body":"Hepatic or severe renal dysfunction, including primary biliary cirrhosis. Preexisting gallbladder disease (see WARNINGS ). Hypersensitivity to gemfibrozil. Combination therapy of gemfibrozil with simvastatin (see WARNINGS and PRECAUTIONS ). Combination therapy of gemfibrozil with repaglinide (see PRECAUTIONS ). Combination therapy of gemfibrozil with dasabuvir (see PRECAUTIONS ). Combination therapy of gemfibrozil with selexipag (see PRECAUTIONS )."},{"title":"คำเตือนกรอบดำ","body":"BOXED WARNING"},{"title":"คำเตือนและข้อควรระวัง","body":"1. Because of chemical, pharmacological, and clinical similarities between gemfibrozil and clofibrate, the adverse findings with clofibrate in two large clinical studies may also apply to gemfibrozil. In the first of those studies, the Coronary Drug Project, 1000 subjects with previous myocardial infarction were treated for five years with clofibrate. There was no difference in mortality between the clofibrate-treated subjects and 3000 placebo-treated subjects, but twice as many clofibrate-treated subjects developed cholelithiasis and cholecystitis requiring surgery. In the other study, conducted by the World Health Organization (WHO), 5000 subjects without known coronary heart disease were treated with clofibrate for five years and followed one year beyond. There was a statistically significant (44%) higher age-adjusted total mortality in the clofibrate-treated group than in a comparable placebo-treated control group during the trial period. The excess mortality was due to a 33% increase in non-cardiovascular causes, including malignancy, post-cholecystectomy complications, and pancreatitis. The higher risk of clofibrate-treated subjects for gallbladder disease was confirmed. Because of the more limited size of the Helsinki Heart Study, the observed difference in mortality from any cause between the gemfibrozil and placebo groups is not statistically significantly different from the 29% excess mortality reported in the clofibrate group in the separate WHO study at the nine year follow-up (see CLINICAL PHARMACOLOGY ). Noncoronary heart disease related mortality showed an excess in the group originally randomized to gemfibrozil primarily due to cancer deaths observed during the open-label extension. During the five year primary prevention component of the Helsinki Heart Study, mortality from any cause was 44 (2.2%) in the gemfibrozil group and 43 (2.1%) in the placebo group; including the 3.5 year follow-up period since the trial was completed, cumulative mortality from any cause was 101 (4.9%) in the gemfibrozil group and 83 (4.1%) in the group originally randomized to placebo (hazard ratio 1:20 in favor of placebo). Because of the more limited size of the Helsinki Heart Study, the observed difference in mortality from any cause between the gemfibrozil and placebo groups at Year-5 or at Year-8.5 is not statistically significantly different from the 29% excess mortality reported in the clofibrate group in the separate WHO study at the nine year follow-up. …"},{"title":"อาการไม่พึงประสงค์","body":"In the double-blind controlled phase of the primary prevention component of the Helsinki Heart Study, 2046 patients received gemfibrozil for up to five years. In that study, the following adverse reactions were statistically more frequent in subjects in the gemfibrozil group: Gemfibrozil PLACEBO (N = 2046) (N = 2035) Frequency in percent of subjects Gastrointestinal reactions 34.2 23.8 Dyspepsia 19.6 11.9 Abdominal pain 9.8 5.6 Acute appendicitis 1.2 0.6 (histologically confirmed in most cases where data were available) Atrial fibrillation 0.7 0.1 Adverse events reported by more than 1% of subjects, but without a significant difference between groups: Diarrhea 7.2 6.5 Fatigue 3.8 3.5 Nausea/Vomiting 2.5 2.1 Eczema 1.9 1.2 Rash 1.7 1.3 Vertigo 1.5 1.3 Constipation 1.4 1.3 Headache 1.2 1.1 Gallbladder surgery was performed in 0.9% of gemfibrozil and 0.5% of placebo subjects in the primary prevention component, a 64% excess, which is not statistically different from the excess of gallbladder surgery observed in the clofibrate group compared to the placebo group of the WHO study. Gallbladder surgery was also performed more frequently in the gemfibrozil group compared to the placebo group (1.9% versus 0.3%, p=0.07) in the secondary prevention component. A statistically significant increase in appendectomy in the gemfibrozil group was seen also in the secondary prevention component (6 on gemfibrozil versus 0 on placebo, p=0.014). Nervous system and special senses adverse reactions were more common in the gemfibrozil group. These included hypesthesia, paresthesias, and taste perversion. Other adverse reactions that were more common among gemfibrozil treatment group subjects but where a causal relationship was not established include cataracts, peripheral vascular disease, and intracerebral hemorrhage. From other studies it seems probable that gemfibrozil is causally related to the occurrence of MUSCULOSKELETAL SYMPTOMS (see WARNINGS ), and to ABNORMAL LIVER FUNCTION TESTS and HEMATOLOGIC CHANGES (see PRECAUTIONS ). Reports of viral and bacterial infections (common cold, cough, urinary tract infections) were more common in gemfibrozil treated patients in other controlled clinical trials of 805 patients. Additional adverse reactions that have been reported for gemfibrozil are listed below by system. …"},{"title":"Drug interaction","body":"3. Drug Interactions (A) HMG-CoA Reductase Inhibitors: The concomitant administration of gemfibrozil with simvastatin is contraindicated ( see CONTRAINDICATIONS and WARNINGS ). Avoid concomitant use of gemfibrozil with rosuvastatin. If concomitant use cannot be avoided, initiate rosuvastatin at 5 mg once daily. The dose of rosuvastatin should not exceed 10 mg once daily. The risk of myopathy and rhabdomyolysis is increased with combined gemfibrozil and HMG-CoA reductase inhibitor therapy. Myopathy or rhabdomyolysis with or without acute renal failure have been reported as early as three weeks after initiation of combined therapy or after several months (see WARNINGS ). There is no assurance that periodic monitoring of creatine kinase will prevent the occurrence of severe myopathy and kidney damage. (B) Anti-coagulants: CAUTION SHOULD BE EXERCISED WHEN WARFARIN IS GIVEN IN CONJUNCTION WITH GEMFIBROZIL. THE DOSAGE OF WARFARIN SHOULD BE REDUCED TO MAINTAIN THE PROTHROMBIN TIME AT THE DESIRED LEVEL TO PREVENT BLEEDING COMPLICATIONS. FREQUENT PROTHROMBIN DETERMINATIONS ARE ADVISABLE UNTIL IT HAS BEEN DEFINITELY DETERMINED THAT THE PROTHROMBIN LEVEL HAS STABILIZED. (C) CYP2C8 Substrates: Gemfibrozil is a strong inhibitor of CYP2C8 and may increase exposure of drugs mainly metabolized by CYP2C8 (e.g., dabrafenib, enzalutamide, loperamide, montelukast, paclitaxel, pioglitazone, rosiglitazone). Therefore, dosing reduction of drugs that are mainly metabolized by CYP2C8 enzyme may be required when gemfibrozil is used concomitantly (see WARNINGS ). Repaglinide: In healthy volunteers, co-administration with gemfibrozil (600 mg twice daily for 3 days) resulted in an 8.1-fold (range 5.5- to 15.0- fold) higher repaglinide AUC and a 28.6-fold (range 18.5- to 80.1-fold) higher repaglinide plasma concentration 7 hours after the dose. In the same study, gemfibrozil (600 mg twice daily for 3 days) + itraconazole (200 mg in the morning and 100 mg in the evening at Day 1, then 100 mg twice daily at Day 2-3) resulted in a 19.4- (range 12.9- to 24.7-fold) higher repaglinide AUC and a 70.4-fold (range 42.9- to 119.2-fold) higher repaglinide plasma concentration 7 hours after the dose. In addition, gemfibrozil alone or gemfibrozil + itraconazole prolonged the hypoglycemic effects of repaglinide. Co-administration of gemfibrozil and repaglinide increases the risk of severe hypoglycemia and is contraindicated (see CONTRAINDICATIONS ). …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"5. Pregnancy Gemfibrozil has been shown to produce adverse effects in rats and rabbits at doses between 0.5 and 3 times the human dose (based on surface area). There are no adequate and well-controlled studies in pregnant women. Gemfibrozil should be used during pregnancy only if the potential benefit justifies the potential risk to the fetus. Administration of gemfibrozil to female rats at 2 times the human dose (based on surface area) before and throughout gestation caused a dose-related decrease in conception rate, an increase in stillborns and a slight reduction in pup weight during lactation. There were also dose-related increased skeletal variations. Anophthalmia occurred, but rarely. Administration of 0.6 and 2 times the human dose (based on surface area) of gemfibrozil to female rats from gestation day 15 through weaning caused dose-related decreases in birth weight and suppressions of pup growth during lactation. Administration of 1 and 3 times the human dose (based on surface area) of gemfibrozil to female rabbits during organogenesis caused a dose-related decrease in litter size and, at the high dose, an increased incidence of parietal bone variations. 6. Nursing Mothers It is not known whether this drug is excreted in human milk. Because many drugs are excreted in human milk and because of the potential for tumorigenicity shown for gemfibrozil in animal studies, a decision should be made whether to discontinue nursing or to discontinue the drug, taking into account the importance of the drug to the mother. 10. Pediatric Use Safety and efficacy in pediatric patients have not been established."},{"title":"การได้รับยาเกินขนาด","body":"There have been reported cases of overdosage with gemfibrozil. In one case, a 7-year-old child recovered after ingesting up to 9 grams of gemfibrozil. Symptoms reported with overdosage were abdominal cramps, abnormal liver function tests, diarrhea, increased CPK, joint and muscle pain, nausea and vomiting. Symptomatic supportive measures should be taken, should an overdose occur."}]},
{"key":"glipizide|ORAL","generic":"glipizide","route":"ORAL","brand":null,"title":"Glipizide","set_id":"06fb6c56-5609-41d9-8389-eba81432218d","effective":"20260611","sections":[{"title":"ข้อบ่งใช้","body":"Glipizide tablets are indicated as an adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus."},{"title":"ขนาดยาและวิธีใช้","body":"There is no fixed dosage regimen for the management of diabetes mellitus with glipizide or any other hypoglycemic agent. In addition to the usual monitoring of urinary glucose, the patient's blood glucose must also be monitored periodically to determine the minimum effective dose for the patient; to detect primary failure, i.e., inadequate lowering of blood glucose at the maximum recommended dose of medication; and to detect secondary failure, i.e., loss of an adequate blood-glucose-lowering response after an initial period of effectiveness. Glycosylated hemoglobin levels may also be of value in monitoring the patient's response to therapy. Short-term administration of glipizide tablets may be sufficient during periods of transient loss of control in patients usually controlled well on diet. In general, glipizide tablets should be given approximately 30 minutes before a meal to achieve the greatest reduction in postprandial hyperglycemia. Initial Dose: The recommended starting dose is 5 mg, given before breakfast. Geriatric patients or those with liver disease may be started on 2.5 mg. Titration: Dosage adjustments should ordinarily be in increments of 2.5–5 mg, as determined by blood glucose response. At least several days should elapse between titration steps. If response to a single dose is not satisfactory, dividing that dose may prove effective. The maximum recommended once daily dose is 15 mg. Doses above 15 mg should ordinarily be divided and given before meals of adequate caloric content. The maximum recommended total daily dose is 40 mg. Maintenance: Some patients may be effectively controlled on a once-a-day regimen, while others show better response with divided dosing. Total daily doses above 15 mg should ordinarily be divided. Total daily doses above 30 mg have been safely given on a b.i.d. basis to long-term patients. In elderly patients, debilitated or malnourished patients, and patients with impaired renal or hepatic function, the initial and maintenance dosing should be conservative to avoid hypoglycemic reactions (see PRECAUTIONS section). Patients Receiving Insulin: As with other sulfonylurea-class hypoglycemics, many stable non-insulin-dependent diabetic patients receiving insulin may be safely placed on Glipizide tablets. …"},{"title":"ข้อห้ามใช้","body":"Glipizide tablets are contraindicated in patients with: Known hypersensitivity to the drug. Type 1 diabetes mellitus, diabetic ketoacidosis, with or without coma. This condition should be treated with insulin."},{"title":"คำเตือนและข้อควรระวัง","body":"SPECIAL WARNING ON INCREASED RISK OF CARDIOVASCULAR MORTALITY The administration of oral hypoglycemic drugs has been reported to be associated with increased cardiovascular mortality as compared to treatment with diet alone or diet plus insulin. This warning is based on the study conducted by the University Group Diabetes Program (UGDP), a long-term prospective clinical trial designed to evaluate the effectiveness of glucose-lowering drugs in preventing or delaying vascular complications in patients with non-insulin-dependent diabetes. The study involved 823 patients who were randomly assigned to one of four treatment groups ( Diabetes , 19, supp. 2: 747–830, 1970). UGDP reported that patients treated for 5 to 8 years with diet plus a fixed dose of tolbutamide (1.5 grams per day) had a rate of cardiovascular mortality approximately 2½ times that of patients treated with diet alone. A significant increase in total mortality was not observed, but the use of tolbutamide was discontinued based on the increase in cardiovascular mortality, thus limiting the opportunity for the study to show an increase in overall mortality. Despite controversy regarding the interpretation of these results, the findings of the UGDP study provide an adequate basis for this warning. The patient should be informed of the potential risks and advantages of glipizide and of alternative modes of therapy. Although only one drug in the sulfonylurea class (tolbutamide) was included in this study, it is prudent from a safety standpoint to consider that this warning may also apply to other oral hypoglycemic drugs in this class, in view of their close similarities in mode of action and chemical structure. General Macrovascular Outcomes: There have been no clinical studies establishing conclusive evidence of macrovascular risk reduction with glipizide or any other anti-diabetic drug. Renal and Hepatic Disease: The metabolism and excretion of glipizide may be slowed in patients with impaired renal and/or hepatic function. If hypoglycemia should occur in such patients, it may be prolonged and appropriate management should be instituted. Hypoglycemia: All sulfonylurea drugs are capable of producing severe hypoglycemia. Proper patient selection, dosage, and instructions are important to avoid hypoglycemic episodes. …"},{"title":"อาการไม่พึงประสงค์","body":"In U.S. and foreign controlled studies, the frequency of serious adverse reactions reported was very low. Of 702 patients, 11.8% reported adverse reactions and in only 1.5% was glipizide discontinued. Hypoglycemia: See PRECAUTIONS and OVERDOSAGE sections. Gastrointestinal: Gastrointestinal disturbances are the most common reactions. Gastrointestinal complaints were reported with the following approximate incidence: nausea and diarrhea, one in seventy; constipation and gastralgia, one in one hundred. They appear to be dose-related and may disappear on division or reduction of dosage. Cholestatic jaundice may occur rarely with sulfonylureas: glipizide should be discontinued if this occurs. Dermatologic: Allergic skin reactions including erythema, morbilliform or maculopapular eruptions, urticaria, pruritus, and eczema have been reported in about one in seventy patients. These may be transient and may disappear despite continued use of glipizide; if skin reactions persist, the drug should be discontinued. Porphyria cutanea tarda and photosensitivity reactions have been reported with sulfonylureas. Hematologic: Leukopenia, agranulocytosis, thrombocytopenia, hemolytic anemia (see PRECAUTIONS ), aplastic anemia, and pancytopenia have been reported with sulfonylureas. Metabolic: Hepatic porphyria and disulfiram-like reactions have been reported with sulfonylureas. In the mouse, glipizide pretreatment did not cause an accumulation of acetaldehyde after ethanol administration. Clinical experience to date has shown that glipizide has an extremely low incidence of disulfiram-like alcohol reactions. Endocrine Reactions: Cases of hyponatremia and the syndrome of inappropriate antidiuretic hormone (SIADH) secretion have been reported with this and other sulfonylureas. Miscellaneous: Dizziness, drowsiness, and headache have each been reported in about one in fifty patients treated with glipizide. They are usually transient and seldom require discontinuance of therapy. Laboratory Tests: The pattern of laboratory test abnormalities observed with glipizide was similar to that for other sulfonylureas. Occasional mild to moderate elevations of SGOT, LDH, alkaline phosphatase, BUN, and creatinine were noted. One case of jaundice was reported. The relationship of these abnormalities to glipizide is uncertain, and they have rarely been associated with clinical symptoms. …"},{"title":"Drug interaction","body":"The hypoglycemic action of sulfonylureas may be potentiated by certain drugs including nonsteroidal anti-inflammatory agents, some azoles, and other drugs that are highly protein bound, salicylates, sulfonamides, chloramphenicol, probenecid, coumarins, monoamine oxidase inhibitors, quinolones and beta adrenergic blocking agents. When such drugs are administered to a patient receiving glipizide, the patient should be observed closely for hypoglycemia. When such drugs are withdrawn from a patient receiving glipizide, the patient should be observed closely for loss of control. In vitro binding studies with human serum proteins indicate that glipizide binds differently than tolbutamide and does not interact with salicylate or dicumarol. However, caution must be exercised in extrapolating these findings to the clinical situation and in the use of glipizide with these drugs. Certain drugs tend to produce hyperglycemia and may lead to loss of control. These drugs include the thiazides and other diuretics, corticosteroids, phenothiazines, thyroid products, estrogens, oral contraceptives, phenytoin, nicotinic acid, sympathomimetics, calcium channel blocking drugs, and isoniazid. When such drugs are administered to a patient receiving glipizide, the patient should be closely observed for loss of control. When such drugs are withdrawn from a patient receiving glipizide, the patient should be observed closely for hypoglycemia. A potential interaction between oral miconazole and oral hypoglycemic agents leading to severe hypoglycemia has been reported. Whether this interaction also occurs with the intravenous, topical, or vaginal preparations of miconazole is not known. The effect of concomitant administration of DIFLUCAN ® (fluconazole) and glipizide has been demonstrated in a placebo-controlled crossover study in normal volunteers. All subjects received glipizide alone and following treatment with 100 mg of DIFLUCAN as a single daily oral dose for 7 days. The mean percentage increase in the glipizide AUC after fluconazole administration was 56.9% (range: 35 to 81). In studies assessing the effect of colesevelam on the pharmacokinetics of glipizide ER in healthy volunteers, reductions in glipizide AUC 0–∞ and C max of 12% and 13%, respectively were observed when colesevelam was coadministered with glipizide ER. When glipizide ER was administered 4 hours prior to colesevelam, there was no significant change in glipizide AUC 0–∞ or C max, -4% and 0%, respectively. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Although it is not known whether glipizide is excreted in human milk, some sulfonylurea drugs are known to be excreted in human milk. Because the potential for hypoglycemia in nursing infants may exist, a decision should be made whether to discontinue nursing or to discontinue the drug, taking into account the importance of the drug to the mother. If the drug is discontinued and if diet alone is inadequate for controlling blood glucose, insulin therapy should be considered. Safety and effectiveness in children have not been established. A determination has not been made whether controlled clinical studies of glipizide included sufficient numbers of subjects aged 65 and over to define a difference in response from younger subjects. Other reported clinical experience has not identified differences in responses between the elderly and younger patients. In general, dose selection for an elderly patient should be cautious, usually starting at the low end of the dosing range, reflecting the greater frequency of decreased hepatic, renal, or cardiac function, and of concomitant disease or other drug therapy."},{"title":"การได้รับยาเกินขนาด","body":"There is no well documented experience with glipizide overdosage. The acute oral toxicity was extremely low in all species tested (LD 50 greater than 4 g/kg). Overdosage of sulfonylureas, including glipizide, can produce hypoglycemia. Mild hypoglycemic symptoms without loss of consciousness or neurologic findings should be treated aggressively with oral glucose and adjustments in drug dosage and/or meal patterns. Close monitoring should continue until the physician is assured that the patient is out of danger. Severe hypoglycemic reactions with coma, seizure, or other neurological impairment occur infrequently, but constitute medical emergencies requiring immediate hospitalization. If hypoglycemic coma is diagnosed or suspected, the patient should be given a rapid intravenous injection of concentrated (50%) glucose solution. This should be followed by a continuous infusion of a more dilute (10%) glucose solution at a rate that will maintain the blood glucose at a level above 100 mg/dL. Patients should be closely monitored for a minimum of 24 to 48 hours since hypoglycemia may recur after apparent clinical recovery. Clearance of glipizide from plasma would be prolonged in persons with liver disease. Because of the extensive protein binding of glipizide, dialysis is unlikely to be of benefit."},{"title":"การเก็บรักษา","body":"RECOMMENDED STORAGE: Store at 20° to 25°C (68° to 77°F); excursions permitted to 15° to 30°C (59° to 86°F) [see USP Controlled Room Temperature]. Dispense in a tightly closed container using child resistant closure. All trademarks are the property of their respective owners. Manufactured by: Rubicon Research Private Limited Ambernath, Dist: Thane, 421506 India Distributed by: Advagen Pharma Ltd 666 Plainsboro Road Suite 605 Plainsboro, NJ 08536, US Revision:02,03/23"}]},
{"key":"guaifenesin|ORAL","generic":"guaifenesin","route":"ORAL","brand":null,"title":"Guaifenesin Extended Release","set_id":"038e1801-b978-4a2e-ae8c-8803596ec09c","effective":"20250520","sections":[{"title":"ข้อบ่งใช้","body":"helps loosen phlegm (mucus) and thin bronchial secretions to rid the bronchial passageways of bothersome mucus and make coughs more productive"},{"title":"ขนาดยาและวิธีใช้","body":"do not crush, chew, or break extended-release tablet take with a full glass of water this product can be administered without regard for the timing of meals adults and children 12 years of age and over: 1 extended-release tablet every 12 hours. Do not exceed 2 extended-release tablets in 24 hours. children under 12 years of age: do not use"},{"title":"ข้อห้ามใช้","body":"for children under 12 years of age"},{"title":"คำเตือนและข้อควรระวัง","body":"Do not use for children under 12 years of age Ask a doctor before use if you have persistent or chronic cough such as occurs with smoking, asthma, chronic bronchitis, or emphysema cough accompanied by too much phlegm (mucus) Stop use and ask a doctor if cough lasts more than 7 days, comes back, or occurs with fever, rash, or persistent headache. These could be signs of a serious illness. If pregnant or breast-feeding, ask a health professional before use. Keep out of reach of children. In case of overdose, get medical help or contact a Poison Control Center right away (1-800-222-1222). smoking, asthma, chronic bronchitis, or emphysema cough accompanied by too much phlegm (mucus) 7 days, comes back, or occurs with fever, rash, or persistent headache. These could be signs of a serious illness."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"ask a health professional before use."},{"title":"การเก็บรักษา","body":"Other information store between 68-77°F (20-25°C) TAMPER EVIDENT: DO NOT USE IF CARTON IS OPEN OR IF PRINTED SEAL ON BLISTER IS BROKEN OR MISSING."}]},
{"key":"hydralazine hydrochloride|ORAL","generic":"hydralazine hydrochloride","route":"ORAL","brand":null,"title":"HYDRALAZINE HYDROCHLORIDE","set_id":"2df51a19-a39a-0ec8-e063-6394a90a147c","effective":"20250212","sections":[{"title":"ข้อบ่งใช้","body":"Essential hypertension, alone or as an adjunct."},{"title":"ขนาดยาและวิธีใช้","body":"Initiate therapy in gradually increasing dosages; adjust according to individual response. Start with 10 mg four times daily for the first 2 to 4 days, increase to 25 mg four times daily for the balance of the first week. For the second and subsequent weeks, increase dosage to 50 mg four times daily. For maintenance, adjust dosage to the lowest effective levels. The incidence of toxic reactions, particularly the L.E. cell syndrome, is high in the group of patients receiving large doses of hydrALAZINE hydrochloride tablets. In a few resistant patients, up to 300 mg of hydrALAZINE hydrochloride tablets daily may be required for a significant antihypertensive effect. In such cases, a lower dosage of hydrALAZINE hydrochloride tablets combined with a thiazide and/or reserpine or a beta blocker may be considered. However, when combining therapy, individual titration is essential to ensure the lowest possible therapeutic dose of each drug."},{"title":"ข้อห้ามใช้","body":"Hypersensitivity to hydrALAZINE; coronary artery disease; mitral valvular rheumatic heart disease."},{"title":"คำเตือนและข้อควรระวัง","body":"In a few patients hydrALAZINE may produce a clinical picture simulating systemic lupus erythematosus including glomerulonephritis. In such patients hydrALAZINE should be discontinued unless the benefit-to-risk determination requires continued antihypertensive therapy with this drug. Symptoms and signs usually regress when the drug is discontinued but residua have been detected many years later. Long-term treatment with steroids may be necessary. (See PRECAUTIONS, Laboratory Tests .) General Myocardial stimulation produced by hydrALAZINE can cause anginal attacks and ECG changes of myocardial ischemia. The drug has been implicated in the production of myocardial infarction. It must, therefore, be used with caution in patients with suspected coronary artery disease. The “hyperdynamic” circulation caused by hydrALAZINE may accentuate specific cardiovascular inadequacies. For example, hydrALAZINE may increase pulmonary artery pressure in patients with mitral valvular disease. The drug may reduce the pressor responses to epinephrine. Postural hypotension may result from hydrALAZINE but is less common than with ganglionic blocking agents. It should be used with caution in patients with cerebral vascular accidents. In hypertensive patients with normal kidneys who are treated with hydrALAZINE, there is evidence of increased renal blood flow and a maintenance of glomerular filtration rate. In some instances where control values were below normal, improved renal function has been noted after administration of hydrALAZINE. However, as with any antihypertensive agent, hydrALAZINE should be used with caution in patients with advanced renal damage.Peripheral neuritis, evidenced by paresthesia, numbness, and tingling, has been observed. Published evidence suggests an antipyridoxine effect, and that pyridoxine should be added to the regimen if symptoms develop. Information for Patients Patients should be informed of possible side effects and advised to take the medication regularly and continuously as directed. Laboratory Tests Complete blood counts and antinuclear antibody titer determinations are indicated before and periodically during prolonged therapy with hydrALAZINE even though the patient is asymptomatic. These studies are also indicated if the patient develops arthralgia, fever, chest pain, continued malaise, or other unexplained signs or symptoms. …"},{"title":"อาการไม่พึงประสงค์","body":"Adverse reactions with hydrALAZINE are usually reversible when dosage is reduced. However, in some cases it may be necessary to discontinue the drug. The following adverse reactions have been observed, but there has not been enough systematic collection of data to support an estimate of their frequency. Common headache, anorexia, nausea, vomiting, diarrhea, palpitations, tachycardia, angina pectoris. Less Frequent Digestive: constipation, paralytic ileus. Cardiovascular hypotension, paradoxical pressor response, edema. Respiratory dyspnea. Neurologic peripheral neuritis, evidenced by paresthesia, numbness, and tingling; dizziness; tremors; muscle cramps; psychotic reactions characterized by depression, disorientation, or anxiety. Genitourinary difficulty in urination. Hematologic blood dyscrasias, consisting of reduction in hemoglobin and red cell count, leukopenia, agranulocytosis, purpura; lymphadenopathy; splenomegaly. Hypersensitive Reactions rash, urticaria, pruritus, fever, chills, arthralgia, eosinophilia, and rarely, hepatitis. Other nasal congestion, flushing, lacrimation, conjunctivitis."},{"title":"Drug interaction","body":"Drug/Drug Interactions MAO inhibitors should be used with caution in patients receiving hydrALAZINE. When other potent parenteral antihypertensive drugs, such as diazoxide, are used in combination with hydrALAZINE, patients should be continuously observed for several hours for any excessive fall in blood pressure. Profound hypotensive episodes may occur when diazoxide injection and hydrALAZINE are used concomitantly."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Teratogenic Effects Pregnancy Category C Animal studies indicate that hydrALAZINE is teratogenic in mice at 20 to 30 times the maximum daily human dose of 200 to 300 mg and possibly in rabbits at 10 to 15 times the maximum daily human dose, but that it is nonteratogenic in rats. Teratogenic effects observed were cleft palate and malformations of facial and cranial bones. There are no adequate and well-controlled studies in pregnant women. Although clinical experience does not include any positive evidence of adverse effects on the human fetus, hydraALAZINE should be used during pregnancy only if the expected benefit justifies the potential risk to the fetus. HydrALAZINE has been shown to be excreted in breast milk. Safety and effectiveness in pediatric patients have not been established in controlled clinical trials, although there is experience with the use of hydrALAZINE in pediatric patients. The usual recommended oral starting dosage is 0.75 mg/kg of body weight daily in four divided doses. Dosage may be increased gradually over the next 3 to 4 weeks to a maximum of 7.5 mg/kg or 200 mg daily."},{"title":"การได้รับยาเกินขนาด","body":"Acute Toxicity No deaths due to acute poisoning have been reported. Highest known dose survived: adults, 10 g orally. Oral LD 50 in rats: 173 and 187 mg/kg. Signs and Symptoms Signs and symptoms of overdosage include hypotension, tachycardia, headache, and generalized skin flushing. Complications can include myocardial ischemia and subsequent myocardial infarction, cardiac arrhythmia, and profound shock. Treatment There is no specific antidote. The gastric contents should be evacuated, taking adequate precautions against aspiration and for protection of the airway. An activated charcoal slurry may be instilled if conditions permit. These manipulations may have to be omitted or carried out after cardiovascular status has been stabilized, since they might precipitate cardiac arrhythmias or increase the depth of shock. Support of the cardiovascular system is of primary importance. Shock should be treated with plasma expanders. If possible, vasopressors should not be given, but if a vasopressor is required, care should be taken not to precipitate or aggravate cardiac arrhythmia. Tachycardia responds to beta blockers. Digitalization may be necessary, and renal function should be monitored and supported as required. No experience has been reported with extracorporeal or peritoneal dialysis."}]},
{"key":"hydrochlorothiazide|ORAL","generic":"hydrochlorothiazide","route":"ORAL","brand":null,"title":"Hydrochlorothiazide","set_id":"0789baef-3424-43ab-a3fb-4908172da565","effective":"20260724","sections":[{"title":"ข้อบ่งใช้","body":"Hydrochlorothiazide capsules, USP are indicated in the management of hypertension either as the sole therapeutic agent, or in combination with other antihypertensives. Unlike potassium sparing combination diuretic products, hydrochlorothiazide capsules, USP may be used in those patients in whom the development of hyperkalemia cannot be risked, including patients taking ACE inhibitors. Usage in Pregnancy: The routine use of diuretics in an otherwise healthy woman is inappropriate and exposes mother and fetus to unnecessary hazard. Diuretics do not prevent development of toxemia of pregnancy, and there is no satisfactory evidence that they are useful in the treatment of developed toxemia. Edema during pregnancy may arise from pathological causes or from the physiologic and mechanical consequences of pregnancy. Diuretics are indicated in pregnancy when edema is due to pathologic causes, just as they are in the absence of pregnancy. Dependent edema in pregnancy resulting from restriction of venous return by the expanded uterus is properly treated through elevation of the lower extremities and use of support hose; use of diuretics to lower intravascular volume in this case is illogical and unnecessary. There is hypervolemia during normal pregnancy which is harmful to neither the fetus nor the mother (in the absence of cardiovascular disease), but which is associated with edema, including generalized edema in the majority of pregnant women. If this edema produces discomfort, increased recumbency will often provide relief. In rare instances this edema may cause extreme discomfort which is not relieved by rest. In these cases a short course of diuretics may provide relief and may be appropriate."},{"title":"ขนาดยาและวิธีใช้","body":"For Control of Hypertension: The adult initial dose of hydrochlorothiazide capsules, USP is one capsule given once daily whether given alone or in combination with other antihypertensives. Total daily doses greater than 50 mg are not recommended."},{"title":"ข้อห้ามใช้","body":"Hydrochlorothiazide is contraindicated in patients with anuria. Hypersensitivity to this product or other sulfonamide derived drugs is also contraindicated."},{"title":"คำเตือนและข้อควรระวัง","body":"Acute Myopia and Secondary Angle-Closure Glaucoma: Hydrochlorothiazide, a sulfonamide, can cause an idiosyncratic reaction, resulting in acute transient myopia and acute angle-closure glaucoma. Symptoms include acute onset of decreased visual acuity or ocular pain and typically occur within hours to weeks of drug initiation. Untreated acute angle-closure glaucoma can lead to permanent vision loss. The primary treatment is to discontinue hydrochlorothiazide as rapidly as possible. Prompt medical or surgical treatments may need to be considered if the intraocular pressure remains uncontrolled. Risk factors for developing acute angle-closure glaucoma may include a history of sulfonamide or penicillin allergy. Diabetes and Hypoglycemia: Latent diabetes mellitus may become manifest and diabetic patients given thiazides may require adjustment of their insulin dose. Renal Disease: Cumulative effects of the thiazides may develop in patients with impaired renal function. In such patients, thiazides may precipitate azotemia. Electrolyte and Fluid Balance Status: In published studies, clinically significant hypokalemia has been consistently less common in patients who received 12.5 mg of hydrochlorothiazide than in patients who received higher doses. Nevertheless, periodic determination of serum electrolytes should be performed in patients who may be at risk for the development of hypokalemia. Patients should be observed for signs of fluid or electrolyte disturbances, i.e., hyponatremia, hypochloremic alkalosis, and hypokalemia and hypomagnesemia. Warning signs or symptoms of fluid and electrolyte imbalance include dryness of mouth, thirst, weakness, lethargy, drowsiness, restlessness, muscle pains or cramps, muscular fatigue, hypotension, oliguria, tachycardia, and gastrointestinal disturbances such as nausea and vomiting. Hypokalemia may develop, especially with brisk diuresis when severe cirrhosis is present, during concomitant use of corticosteroid or adrenocorticotropic hormone (ACTH) or after prolonged therapy. Interference with adequate oral electrolyte intake will also contribute to hypokalemia. Hypokalemia and hypomagnesemia can provoke ventricular arrhythmias or sensitize or exaggerate the response of the heart to the toxic effects of digitalis. Hypokalemia may be avoided or treated by potassium supplementation or increased intake of potassium rich foods. …"},{"title":"อาการไม่พึงประสงค์","body":"The adverse reactions associated with hydrochlorothiazide have been shown to be dose related. In controlled clinical trials, the adverse events reported with doses of 12.5 mg hydrochlorothiazide once daily were comparable to placebo. The following adverse reactions have been reported for doses of hydrochlorothiazide 25 mg and greater and, within each category, are listed in the order of decreasing severity. Body as a whole: Weakness. Cardiovascular: Hypotension including orthostatic hypotension (may be aggravated by alcohol, barbiturates, narcotics or antihypertensive drugs). Digestive: Pancreatitis, jaundice (intrahepatic cholestatic jaundice), diarrhea, vomiting, sialadenitis, cramping, constipation, gastric irritation, nausea, anorexia. Hematologic: Aplastic anemia, agranulocytosis, leukopenia, hemolytic anemia, thrombocytopenia. Hypersensitivity: Anaphylactic reactions, necrotizing angiitis (vasculitis and cutaneous vasculitis), respiratory distress including pneumonitis and pulmonary edema, photosensitivity, fever, urticaria, rash, purpura. Metabolic: Electrolyte imbalance (see PRECAUTIONS ), hyperglycemia, glycosuria, hyperuricemia. Musculoskeletal: Muscle spasm. Nervous System/Psychiatric: Vertigo, paresthesia, dizziness, headache, restlessness. Renal: Renal failure, renal dysfunction, interstitial nephritis (see WARNINGS ). Skin: Erythema multiforme including Stevens-Johnson syndrome, exfoliative dermatitis including toxic epidermal necrolysis, alopecia. Special Senses: Transient blurred vision, xanthopsia. Urogenital: Impotence. Whenever adverse reactions are moderate or severe, thiazide dosage should be reduced or therapy withdrawn."},{"title":"Drug interaction","body":"Alcohol, barbiturates, or narcotics: potentiation of orthostatic hypotension may occur. Antidiabetic drugs: (oral agents and insulin) dosage adjustment of the antidiabetic drug may be required. Other antihypertensive drugs: additive effect or potentiation. Cholestyramine and colestipol resins: Cholestyramine and colestipol resins bind the hydrochlorothiazide and reduce its absorption from the gastrointestinal tract by up to 85 and 43 percent, respectively. Corticosteroid, ACTH: intensified electrolyte depletion, particularly hypokalemia. Pressor amines (e.g., norepinephrine): possible decreased response to pressor amines but not sufficient to preclude their use. Skeletal muscle relaxants, nondepolarizing (e.g., tubocurarine): possible increased responsiveness to the muscle relaxant. Lithium: generally should not be given with diuretics. Diuretic agents reduce the renal clearance of lithium and greatly increase the risk of lithium toxicity. Refer to the package insert for lithium preparations before use of such preparations with hydrochlorothiazide capsules. Non-steroidal anti-inflammatory drugs: In some patients, the administration of a non-steroidal anti-inflammatory agent can reduce the diuretic, natriuretic, and antihypertensive effects of loop, potassium-sparing and thiazide diuretics. When hydrochlorothiazide capsules and non-steroidal anti-inflammatory agents are used concomitantly, the patients should be observed closely to determine if the desired effect of the diuretic is obtained. Drug/Laboratory Test Interactions: Thiazides should be discontinued before carrying out tests for parathyroid function (see PRECAUTIONS , General )."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Teratogenic Effects: Studies in which hydrochlorothiazide was orally administered to pregnant mice and rats during their respective periods of major organogenesis at doses up to 3,000 mg and 1,000 mg hydrochlorothiazide/kg, respectively, provided no evidence of harm to the fetus. There are, however, no adequate and well-controlled studies in pregnant women. Because animal reproduction studies are not always predictive of human response, this drug should be used during pregnancy only if clearly needed. Nonteratogenic Effects: Thiazides cross the placental barrier and appear in cord blood. There is a risk of fetal or neonatal jaundice, thrombocytopenia, and possibly other adverse reactions that have occurred in adults. Nursing Mothers: Thiazides are excreted in breast milk. Because of the potential for serious adverse reactions in nursing infants, a decision should be made whether to discontinue nursing or to discontinue hydrochlorothiazide, taking into account the importance of the drug to the mother. Safety and effectiveness in pediatric patients have not been established. Elderly Use: A greater blood pressure reduction and an increase in side effects may be observed in the elderly (i.e., > 65 years) with hydrochlorothiazide. Starting treatment with the lowest available dose of hydrochlorothiazide (12.5 mg) is therefore recommended. If further titration is required, 12.5 mg increments should be utilized."},{"title":"การได้รับยาเกินขนาด","body":"The most common signs and symptoms observed are those caused by electrolyte depletion (hypokalemia, hypochloremia, hyponatremia) and dehydration resulting from excessive diuresis. If digitalis has also been administered, hypokalemia may accentuate cardiac arrhythmias. In the event of overdosage, symptomatic and supportive measures should be employed. Emesis should be induced or gastric lavage performed. Correct dehydration, electrolyte imbalance, hepatic coma and hypotension by established procedures. If required, give oxygen or artificial respiration for respiratory impairment. The degree to which hydrochlorothiazide is removed by hemodialysis has not been established. The oral LD 50 of hydrochlorothiazide is greater than 10 g/kg in the mouse and rat."}]},
{"key":"hydrogen peroxide|TOPICAL","generic":"hydrogen peroxide","route":"TOPICAL","brand":null,"title":"Hydrogen Peroxide","set_id":"0fa3615b-4181-1bd8-e063-6294a90ad129","effective":"20260204","sections":[{"title":"ข้อบ่งใช้","body":"first aid to help prevent the risk of infection in minor cuts, scrapes and burns aids in the removal of phlegm, mucus, or other secretions associated with occasional sore mouth"},{"title":"ขนาดยาและวิธีใช้","body":"First aid antiseptic: clean the affected area apply a small amount of product on the affected area 1 to 3 times a day may be covered with a sterile bandage if bandaged, let dry first Oral debriding agent (oral rinse): adults and children 2 years of age and over: mix with an equal amount of water swish around in the mouth over the affected area for at least 1 minute and then spit out use up to 4 times daily after meals and at bedtime or as directed by a dentist or doctor children under 12 years of age should be supervised in the use of this product children under 2 years of age: consult a dentist or doctor"},{"title":"ข้อห้ามใช้","body":"in the eyes or apply over large areas of the body longer than 1 week unless directed by a doctor"},{"title":"คำเตือนและข้อควรระวัง","body":"For external use only wounds, animal bites or serious burns 7 days irritation, pain, or redness persists or worsens swelling, rash, or fever develops"},{"title":"อาการไม่พึงประสงค์","body":"Adverse reaction DISTRIBUTED BY: GOBRANDS, INC., PHILADELPHIA, PA 19123 ©2024 GOBRANDS, INC. Pat. D675, 101"},{"title":"การเก็บรักษา","body":"Other information keep tightly closed and at controlled room temperature. Do not shake bottle. Hold away from face when opening."}]},
{"key":"hydroxyzine hydrochloride|ORAL","generic":"hydroxyzine hydrochloride","route":"ORAL","brand":null,"title":"Hydroxyzine Hydrochloride","set_id":"3946db7c-dc2d-4329-b9ac-f003d8c6d3e1","effective":"20240105","sections":[{"title":"ข้อบ่งใช้","body":"For symptomatic relief of anxiety and tension associated with psychoneurosis and as an adjunct in organic disease states in which anxiety is manifested. Useful in the management of pruritus due to allergic conditions such as chronic urticaria and atopic and contact dermatoses and in histamine-mediated pruritus. As a sedative when used as a premedication and following general anesthesia, hydroxyzine may potentiate meperidine and barbiturates , so their use in pre-anesthetic adjunctive therapy should be modified on an individual basis. Atropine and other belladonna alkaloids are not affected by the drug. Hydroxyzine is not known to interfere with the action of digitalis in any way and it may be used concurrently with this agent. The effectiveness of hydroxyzine as an antianxiety agent for long term use, that is more than 4 months, has not been assessed by systematic clinical studies. The physician should reassess periodically the usefulness of the drug for the individual patient."},{"title":"ขนาดยาและวิธีใช้","body":"For symptomatic relief of anxiety and tension associated with psychoneurosis and as an adjunct in organic disease states in which anxiety is manifested: adults, 50 to 100 mg q.i.d.; children under 6 years, 50 mg daily in divided doses; children over 6 years, 50 to 100 mg daily in divided doses. For use in the management of pruritus due to allergic conditions such as chronic urticaria and atopic and contact dermatoses and in histamine-mediated pruritus: adults, 25 mg t.i.d. or q.i.d.; children under 6 years, 50 mg daily in divided doses; children over 6 years, 50 to 100 mg daily in divided doses. As a sedative when used as a premedication and following general anesthesia: 50 to 100 mg for adults and 0.6 mg/kg of body weight in children. When treatment is initiated by the intramuscular route of administration, subsequent doses may be administered orally. As with all potent medication, the dosage should be adjusted according to the patient’s response to therapy."},{"title":"ข้อห้ามใช้","body":"Oral hydroxyzine hydrochloride is contraindicated in patients with known hypersensitivity to hydroxyzine hydrochloride products, and in patients with known hypersensitivity to cetirizine hydrochloride or levocetirizine hydrochloride. Hydroxyzine is contraindicated in patients with a prolonged QT interval. Hydroxyzine, when administered to the pregnant mouse, rat, and rabbit induced fetal abnormalities in the rat and mouse at doses substantially above the human therapeutic range. Clinical data in human beings are inadequate to establish safety in early pregnancy. Until such data are available, hydroxyzine is contraindicated in early pregnancy. Hydroxyzine is contraindicated for patients who have shown a previous hypersensitivity to any component of this medication."},{"title":"คำเตือนและข้อควรระวัง","body":"Nursing Mothers It is not known whether this drug is excreted in human milk. Since many drugs are so excreted, hydroxyzine should not be given to nursing mothers. THE POTENTIATING ACTION OF HYDROXYZINE MUST BE CONSIDERED WHEN THE DRUG IS USED IN CONJUNCTION WITH CENTRAL NERVOUS SYSTEM DEPRESSANTS SUCH AS NARCOTICS, NON-NARCOTIC ANALGESICS AND BARBITURATES. Therefore, when central nervous system depressants are administered concomitantly with hydroxyzine their dosage should be reduced. QT Prolongation/Torsade de Pointes (TdP): Cases of QT prolongation and Torsade de Pointes have been reported during post-marketing use of hydroxyzine. The majority of reports occurred in patients with other risk factors for QT prolongation/TdP (pre-existing heart disease, electrolyte imbalances or concomitant arrhythmogenic drug use). Therefore, hydroxyzine should be used with caution in patients with risk factors for QT prolongation, congenital long QT syndrome, a family history of long QT syndrome, other conditions that predispose to QT prolongation and ventricular arrhythmia, as well as recent myocardial infarction, uncompensated heart failure, and bradyarrhythmias. Caution is recommended during the concomitant use of drugs known to prolong the QT interval. These include Class 1A (e.g., quinidine, procainamide) or Class III (e.g., amiodarone, sotalol) antiarrhythmics, certain antipsychotics (e.g., ziprasidone, iloperidone, clozapine, quetiapine, chlorpromazine), certain antidepressants (e.g., citalopram, fluoxetine), certain antibiotics (e.g., azithromycin, erythromycin, clarithromycin, gatifloxacin, moxifloxacin); and others (e.g., pentamidine, methadone, ondansetron, droperidol). Since drowsiness may occur with use of this drug, patients should be warned of this possibility and cautioned against driving a car or operating dangerous machinery while taking hydroxyzine. Patients should also be advised against the simultaneous use of other CNS depressant drugs, and cautioned that the effects of alcohol may be increased. Geriatric Use A determination has not been made whether controlled clinical studies of hydroxyzine included sufficient numbers of subjects aged 65 and over to define a difference in response from younger subjects. Other reported clinical experience has not identified differences in responses between the elderly and younger patients. …"},{"title":"อาการไม่พึงประสงค์","body":"Side effects reported with the administration of hydroxyzine hydrochloride are usually mild and transitory in nature. Anticholinergic: Dry mouth. Central Nervous System: Drowsiness is usually transitory and may disappear in a few days of continued therapy or upon reduction of dose. Involuntary motor activity including rare instances of tremor and convulsions have been reported, usually with doses considerably higher than those recommended. Clinically significant respiratory depression has not been reported at recommended doses. Cardiac System: QT prolongation, Torsade de Pointes. In postmarketing experience, the following additional undesirable effects have been reported: Body as a Whole: Allergic reaction. Nervous System: Headache. Psychiatric: Hallucination. Skin and Appendages: Oral hydroxyzine is associated with Acute Generalized Exanthematous Pustulosis (AGEP) and fixed drug eruptions in postmarketing reports; pruritus, rash, urticaria."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"It is not known whether this drug is excreted in human milk. Since many drugs are so excreted, hydroxyzine should not be given to nursing mothers. A determination has not been made whether controlled clinical studies of hydroxyzine included sufficient numbers of subjects aged 65 and over to define a difference in response from younger subjects. Other reported clinical experience has not identified differences in responses between the elderly and younger patients. In general, dose selection for an elderly patient should be cautious, usually starting at the low end of the dosing range, reflecting the greater frequency of decreased hepatic, renal or cardiac function, and of concomitant disease or other drug therapy. The extent of renal excretion of hydroxyzine has not been determined. Because elderly patients are more likely to have decreased renal function, care should be taken in dose selections. Sedating drugs may cause confusion and over sedation in the elderly; elderly patients generally should be started on low doses of hydroxyzine and observed closely."},{"title":"การได้รับยาเกินขนาด","body":"The most common manifestation of hydroxyzine overdosage is hypersedation. Other reported signs and symptoms were convulsions, stupor, nausea and vomiting. As in the management of overdosage with any drug, it should be borne in mind that multiple agents may have been taken. If vomiting has not occurred spontaneously, it should be induced. Immediate gastric lavage is also recommended. General supportive care, including frequent monitoring of the vital signs and close observation of the patient, is indicated. Hypotension, though unlikely, may be controlled with intravenous fluids and levarterenol or metaraminol. Do not use epinephrine as hydroxyzine counteracts its pressor action. Hydroxyzine overdose may cause QT prolongation and Torsade de Pointes. ECG monitoring is recommended in cases of hydroxyzine overdose. There is no specific antidote. It is doubtful that hemodialysis would be of any value in the treatment of overdosage with hydroxyzine. However, if other agents such as barbiturates have been ingested concomitantly, hemodialysis may be indicated. There is no practical method to quantitate hydroxyzine in body fluids or tissue after its ingestion or administration."},{"title":"การเก็บรักษา","body":"Storage Dispense in a tight container as defined in the USP, with a child-resistant closure (as required). Store at 20° to 25°C (68° to 77°F) [See USP Controlled Room Temperature]. KEEP THIS AND ALL MEDICATIONS OUT OF THE REACH OF CHILDREN. Manufactured In Croatia By: Pliva Hrvatska d.o.o. Zagreb, Croatia Manufactured For: Teva Pharmaceuticals USA, Inc. North Wales, PA 19454"}]},
{"key":"ibuprofen|ORAL","generic":"ibuprofen","route":"ORAL","brand":null,"title":"Ibuprofen","set_id":"0170876a-d8cd-4a2d-8397-db2acdf72ffb","effective":"20260217","sections":[{"title":"ข้อบ่งใช้","body":"Carefully consider the potential benefits and risks of Ibuprofen tablets and other treatment options before deciding to use ibuprofen. Use the lowest effective dose for the shortest duration consistent with individual patient treatment goals [see WARNINGS ]. Ibuprofen tablets are indicated for relief of the signs and symptoms of rheumatoid arthritis and osteoarthritis. Ibuprofen tablets are indicated for relief of mild to moderate pain. Ibuprofen tablets are also indicated for the treatment of primary dysmenorrhea. Controlled clinical trials to establish the safety and effectiveness of Ibuprofen tablets in children have not been conducted."},{"title":"ขนาดยาและวิธีใช้","body":"Carefully consider the potential benefits and risks of Ibuprofen Tablets, USP and other treatment options before deciding to use Ibuprofen Tablets, USP. Use the lowest effective dose for the shortest duration consistent with individual patient treatment goals [see WARNINGS ]. After observing the response to initial therapy with Ibuprofen Tablets, USP, the dose and frequency should be adjusted to suit an individual patient's needs. Do not exceed 3200 mg total daily dose. If gastrointestinal complaints occur, administer Ibuprofen tablets with meals or milk. Rheumatoid arthritis and osteoarthritis, including flare-ups of chronic disease Suggested Dosage: 1200 mg-3200 mg daily (400 mg, 600 mg or 800 mg tid or qid). Individual patients may show a better response to 3200 mg daily, as compared with 2400 mg, although in well-controlled clinical trials patients on 3200 mg did not show a better mean response in terms of efficacy. Therefore, when treating patients with 3200 mg/ day, the physician should observe sufficient increased clinical benefits to offset potential increased risk. The dose should be tailored to each patient, and may be lowered or raised depending on the severity of symptoms either at time of initiating drug therapy or as the patient responds or fails to respond. In general, patients with rheumatoid arthritis seem to require higher doses of Ibuprofen tablets than do patients with osteoarthritis. The smallest dose of Ibuprofen tablets that yields acceptable control should be employed. A linear blood level dose-response relationship exists with single doses up to 800 mg [See CLINICAL PHARMACOLOGY for effects of food on rate of absorption]. The availability of three tablet strengths facilitates dosage adjustment. In chronic conditions , a therapeutic response to therapy with Ibuprofen tablets is sometimes seen in a few days to a week but most often is observed by two weeks. After a satisfactory response has been achieved, the patient's dose should be reviewed and adjusted as required. Mild to moderate pain 400 mg every 4 to 6 hours as necessary for relief of pain. In controlled analgesic clinical trials, doses of Ibuprofen tablets greater than 400 mg were no more effective than the 400 mg dose. Dysmenorrhea For the treatment of dysmenorrhea, beginning with the earliest onset of such pain, Ibuprofen tablets should be given in a dose of 400 mg every 4 hours as necessary for the relief of pain."},{"title":"ข้อห้ามใช้","body":"Ibuprofen tablets are contraindicated in patients with known hypersensitivity to ibuprofen. Ibuprofen tablets should not be given to patients who have experienced asthma, urticaria, or allergic-type reactions after taking aspirin or other NSAIDs. Severe, rarely fatal, anaphylactic-like reactions to NSAIDs have been reported in such patients [see WARNINGS, Anaphylactoid Reactions , and PRECAUTIONS, Preexisting Asthma ]. Ibuprofen tablets are contraindicated in the setting of coronary artery bypass graft (CABG) surgery [see WARNINGS ]."},{"title":"คำเตือนกรอบดำ","body":"Cardiovascular Thrombotic Events Nonsteroidal anti-inflammatory drugs (NSAIDs) cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction and stroke, which can be fatal. This risk may occur early in treatment and may increase with duration of use. [See WARNINGS and PRECAUTIONS ]. Ibuprofen tablets are contraindicated in the setting of coronary artery bypass graft (CABG) surgery [see CONTRAINDICATIONS and WARNINGS ]. Gastrointestinal Risk NSAIDS cause an increased risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation of the stomach or intestines, which can be fatal. These events can occur at any time during use and without warning symptoms. Elderly patients are at greater risk for serious gastrointestinal events. [See WARNINGS ]."},{"title":"คำเตือนและข้อควรระวัง","body":"CARDIOVASCULAR EFFECTS Cardiovascular Thrombotic Events Clinical trials of several COX-2 selective and nonselective NSAIDs of up to three years duration have shown an increased risk of serious cardiovascular (CV) thrombotic events, including myocardial infarction (MI) and stroke, which can be fatal. Based on available data, it is unclear that the risk for CV thrombotic events is similar for all NSAIDs. The relative increase in serious CV thrombotic events over baseline conferred by NSAID use appears to be similar in those with and without known CV disease or risk factors for CV disease. However, Patients with known CV disease or risk factors had a higher absolute incidence of excess serious CV thrombotic events, due to their increased baseline rate. Some observational studies found that this increased risk of serious CV thrombotic events began as early as the first weeks of treatment. The increase in CV thrombotic risk has been observed most consistently at higher doses. To minimize the potential risk for an adverse CV event in NSAID-treated patients, use the lowest effective dose for the shortest duration possible. Physicians and patients should remain alert for the development of such events, throughout the entire treatment course, even in the absence of previous CV symptoms. Patients should be informed about the symptoms of serious CV events and the steps to take if they occur. There is no consistent evidence that concurrent use of aspirin mitigates the increased risk of serious CV thrombotic events associated with NSAID use. The concurrent use of aspirin and an NSAID, such as Ibuprofen, increase the risk of serious gastrointestinal (GI) events [see WARNINGS ]. Status Post Coronary Artery Bypass Graft (CABG) Surgery Two large, controlled clinical trials of a COX-2 selective NSAID for the treatment of pain in the first 10-14 days following CABG surgery found an increased incidence of myocardial infarction and stroke. NSAIDs are contraindicated in the setting of CABG [see CONTRAINDICATIONS ]. Post-MI Patients Observational studies conducted in the Danish National Registry have demonstrated that patients treated with NSAIDs in the post-MI period were at increased risk of reinfarction, CV-related death, and all-cause mortality beginning in the first week of treatment. In this same cohort, the incidence of death in the first year post MI was 20 per 100 person years in NSAID-treated patients compared to 12 per 100 person years in non-NSAID exposed patients. …"},{"title":"อาการไม่พึงประสงค์","body":"The most frequent type of adverse reaction occurring with Ibuprofen tablets is gastrointestinal. In controlled clinical trials the percentage of patients reporting one or more gastrointestinal complaints ranged from 4% to 16%. In controlled studies when Ibuprofen tablets were compared to aspirin and indomethacin in equally effective doses, the overall incidence of gastrointestinal complaints was about half that seen in either the aspirin- or indomethacin-treated patients. Adverse reactions observed during controlled clinical trials at an incidence greater than 1% are listed in the table. Those reactions listed in Column one encompass observations in approximately 3,000 patients. More than 500 of these patients were treated for periods of at least 54 weeks. Still other reactions occurring less frequently than 1 in 100 were reported in controlled clinical trials and from marketing experience. These reactions have been divided into two categories: Column two of the table lists reactions with therapy with Ibuprofen tablets where the probability of a causal relationship exists: for the reactions in Column three, a causal relationship with Ibuprofen tablets has not been established. Reported side effects were higher at doses of 3200 mg/day than at doses of 2400 mg or less per day in clinical trials of patients with rheumatoid arthritis. The increases in incidence were slight and still within the ranges reported in the table. Incidence Greater than 1% (but less than 3%) Probable Causal Relationship Reactions occurring in 3% to 9% of patients treated with ibuprofen tablets. (Those reactions occurring in less than 3% of the patients are unmarked.) Precise Incidence Unknown (but less than 1%) Probable Causal Relationship Reactions are classified under \"Probable Causal Relationship (PCR)\" if there has been one positive rechallenge or if three or more cases occur which might be causally related. Reactions are classified under \"Causal Relationship Unknown\" if seven or more events have been reported but the criteria for PCR have not been met. Precise Incidence Unknown (but less than 1%) Causal Relationship Unknown GASTROINTESTINAL Nausea , epigastric pain , heartburn , diarrhe …"},{"title":"Drug interaction","body":"ACE-inhibitors Reports suggest that NSAIDs may diminish the antihypertensive effect of ACE-inhibitors. This interaction should be given consideration in patients taking NSAIDs concomitantly with ACE-inhibitors. Aspirin Pharmacodynamic studies have demonstrated interference with the antiplatelet activity of aspirin when ibuprofen 400 mg, given three times daily, is administered with enteric-coated low-dose aspirin. The interaction exists even following a once-daily regimen of ibuprofen 400 mg, particularly when ibuprofen is dosed prior to aspirin. The interaction is alleviated if immediate-release low-dose aspirin is dosed at least 2 hours prior to a once-daily regimen of ibuprofen; however, this finding cannot be extended to enteric-coated low-dose aspirin [see Clinical Pharmacology/Pharmacodynamics ]. Because there may be an increased risk of cardiovascular events due to the interference of ibuprofen with the antiplatelet effect of aspirin, for patients taking low-dose aspirin for cardio protection who require analgesics, consider use of a NSAID that does not interfere with the antiplatelet effect of aspirin, or non-NSAID analgesics, where appropriate. When Ibuprofen tablets are administered with aspirin, its protein binding is reduced, although the clearance of free Ibuprofen tablets is not altered. The clinical significance of this interaction is not known; however, as with other NSAIDs, concomitant administration of ibuprofen and aspirin is not generally recommended because of the potential for increased adverse effects. Diuretics Clinical studies, as well as post marketing observations, have shown that Ibuprofen tablets can reduce the natriuretic effect-of furosemide and thiazides in some patients. This response has been attributed to inhibition of renal prostaglandin synthesis. During concomitant therapy with NSAIDs, the patient should be observed closely for signs of renal failure [see PRECAUTIONS, Renal Effects ], as well as to assure diuretic efficacy. Lithium Ibuprofen produced an elevation of plasma lithium levels and a reduction in renal lithium clearance in a study of eleven normal volunteers. The mean minimum lithium concentration increased 15% and the renal clearance of lithium was decreased by 19% during this period of concomitant drug administration. This effect has been attributed to inhibition of renal prostaglandin synthesis by ibuprofen. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Risk Summary Use of NSAIDs, including Ibuprofen tablets, can cause premature closure of the fetal ductus arteriosus and fetal renal dysfunction leading to oligohydramnios and, in some cases, neonatal renal impairment. Because of these risks, limit dose and duration of Ibuprofen tablets use between about 20 and 30 weeks of gestation, and avoid Ibuprofen tablets use at about 30 weeks of gestation and later in pregnancy [see WARNINGS; Fetal Toxicity ]. Premature Closure of Fetal Ductus Arteriosus Use of NSAIDs, including Ibuprofen tablets, at about 30 weeks gestation or later in pregnancy increases the risk of premature closure of the fetal ductus arteriosus. Oligohydramnios/Neonatal Renal Impairment Use of NSAIDs at about 20 weeks gestation or later in pregnancy has been associated with cases of fetal renal dysfunction leading to oligohydramnios, and in some cases, neonatal renal impairment. Data from observational studies regarding other potential embryofetal risks of NSAID use in women in the first or second trimesters of pregnancy are inconclusive. Reproductive studies conducted in rats and rabbits have not demonstrated evidence of developmental abnormalities. However, animal reproduction studies are not always predictive of human response. Based on animal data, prostaglandins have been shown to have an important role in endometrial vascular permeability, blastocyst implantation, and decidualization. In animal studies, administration of prostaglandin synthesis inhibitors such as Ibuprofen, resulted in increased pre- and post-implantation loss. Prostaglandins also have been shown to have an important role in fetal kidney development. In published animal studies, prostaglandin synthesis inhibitors have been reported to impair kidney development when administered at clinically relevant doses. The estimated background risk of major birth defects and miscarriage for the indicated population(s) is unknown. All pregnancies have a background risk of birth defect, loss, or other adverse outcomes. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2-4% and 15-20%, respectively. Clini …"},{"title":"การได้รับยาเกินขนาด","body":"Approximately 1½ hours after the reported ingestion of from 7 to 10 Ibuprofen tablets (400 mg), a 19-month old child weighing 12 kg was seen in the hospital emergency room, apneic and cyanotic, responding only to painful stimuli. This type of stimulus, however, was sufficient to induce respiration. Oxygen and parenteral fluids were given; a greenish-yellow fluid was aspirated from the stomach with no evidence to indicate the presence of ibuprofen. Two hours after ingestion the child's condition seemed stable; she still responded only to painful stimuli and continued to have periods of apnea lasting from 5 to 10 seconds. She was admitted to intensive care and sodium bicarbonate was administered as well as infusions of dextrose and normal saline. By four hours post-ingestion she could be aroused easily, sit by herself and respond to spoken commands. Blood level of ibuprofen was 102.9 mcg/mL approximately 8½ hours after accidental ingestion. At 12 hours she appeared to be completely recovered. In two other reported cases where children (each weighing approximately 10 kg) accidentally, acutely ingested approximately 120 mg/kg, there were no signs of acute intoxication or late sequelae. Blood level in one child 90 minutes after ingestion was 700 mcg/mL -- about 10 times the peak levels seen in absorption-excretion studies. A 19-year old male who had taken 8,000 mg of ibuprofen over a period of a few hours complained of dizziness, and nystagmus was noted. After hospitalization, parenteral hydration and three days bed rest, he recovered with no reported sequelae. In cases of acute overdosage, the stomach should be emptied by vomiting or lavage, though little drug will likely be recovered if more than an hour has elapsed since ingestion. Because the drug is acidic and is excreted in the urine, it is theoretically beneficial to administer alkali and induce diuresis. In addition to supportive measures, the use of oral activated charcoal may help to reduce the absorption and reabsorption of Ibuprofen tablets."}]},
{"key":"insulin human|SUBCUTANEOUS|humulin 70/30","generic":"insulin human","route":"SUBCUTANEOUS","brand":"humulin 70/30","title":"Humulin 70/30","set_id":"e245e0c5-b2d6-418b-baa4-1c3324292885","effective":"20260617","sections":[{"title":"ข้อบ่งใช้","body":"70/30 is a fixed ratio insulin formulation indicated to improve glycemic control in adults with diabetes mellitus. HUMULIN ® 70/30 is a mixture of insulin isophane human, an intermediate-acting human insulin, and insulin human, a short-acting insulin human, indicated to improve glycemic control in adults with diabetes mellitus. ( 1 )"},{"title":"ขนาดยาและวิธีใช้","body":"Only administer subcutaneously (in abdominal wall, thigh, upper arm, or buttocks). ( 2.1 ) Rotate injection sites to reduce risk of lipodystrophy and localized cutaneous amyloidosis. ( 2.1 ) Individualize and adjust dosage based on metabolic needs, blood glucose monitoring results and glycemic control goal. ( 2.2 ) See Full Prescribing Information for dosage adjustments due to drug interactions and patients with renal and hepatic impairment. ( 2.2 ) Administer approximately 30-45 minutes before a meal. ( 2.2 ) 2.1 Important Administration Instructions Inspect HUMULIN 70/30 visually before use. It should not contain particulate matter and should appear uniformly cloudy after mixing. Do not use HUMULIN 70/30 if particulate matter is seen. Administer HUMULIN 70/30 subcutaneously into the abdominal wall, thigh, upper arm, or buttocks. Rotate injection sites within the same region from one injection to the next to reduce the risk of lipodystrophy and localized cutaneous amyloidosis. Do not inject into areas of lipodystrophy or localized cutaneous amyloidosis [see Warnings and Precautions ( 5.2 ) and Adverse Reactions ( 6 )] . The HUMULIN 70/30 KwikPen dials in 1 unit increments. Use HUMULIN 70/30 KwikPen with caution in patients with visual impairment that may rely on audible clicks to dial their dose. Do not administer HUMULIN 70/30 intravenously and do not use in an insulin infusion pump. Do not mix HUMULIN 70/30 with any other insulins or diluents. 2.2 Dosage Information Inject HUMULIN 70/30 subcutaneously approximately 30-45 minutes before a meal. The proportion of rapid acting and long acting insulin is fixed in a premixed insulin such as HUMULIN 70/30. Independent adjustment of the basal or prandial dose is not possible when using a premixed insulin. Individualize and adjust the dosage of HUMULIN 70/30 based on the individual's metabolic needs, blood glucose monitoring results and glycemic control goal. Dosage adjustments may be needed with changes in physical activity, changes in meal patterns (i.e., macronutrient content or timing of food intake), changes in renal or hepatic function or during acute illness [see Warnings and Precautions ( 5.2 , 5.3 ), and Use in Specific Populations ( 8.6 , 8.7 )] . During changes to a patient's insulin regimen, increase the frequency of blood glucose monitoring [see Warnings and Precautions ( 5.2 )] . …"},{"title":"ข้อห้ามใช้","body":"70/30 is contraindicated: During episodes of hypoglycemia [see Warnings and Precautions ( 5.3 )], and In patients who have had hypersensitivity reactions to HUMULIN 70/30 or any of its excipients [see Warnings and Precautions ( 5.5 )] . During episodes of hypoglycemia. ( 4 ) In patients with hypersensitivity to HUMULIN 70/30 or any of its excipients. ( 4 )"},{"title":"คำเตือนและข้อควรระวัง","body":"Never share a HUMULIN 70/30 KwikPen or syringe between patients, even if the needle is changed. ( 5.1 ) Hyperglycemia or Hypoglycemia with Changes in Insulin Regimen : Make changes to a patient's insulin regimen (e.g., insulin strength, manufacturer, type, injection site or method of administration) under close medical supervision with increased frequency of blood glucose monitoring. ( 5.2 ) Hypoglycemia : May be life-threatening. Monitor blood glucose and increase monitoring frequency with changes to insulin dosage, use of glucose lowering medications, meal pattern, physical activity; in patients with renal or hepatic impairment; and in patients with hypoglycemia unawareness. ( 5.3 , 7 , 8.6 , 8.7 ) Hypoglycemia Due to Medication Errors: Accidental mix-ups between insulin products can occur. Instruct patients to check insulin labels before injection. ( 5.4 ) Hypersensitivity Reactions : May be life-threatening. Discontinue HUMULIN 70/30, monitor and treat if indicated. ( 5.5 ) Hypokalemia : May be life-threatening. Monitor potassium levels in patients at risk of hypokalemia and treat if indicated. ( 5.6 ) Fluid Retention and Heart Failure with Concomitant Use of Thiazolidinediones (TZDs) : Observe for signs and symptoms of heart failure; consider dosage reduction or discontinuation if heart failure occurs. ( 5.7 ) 5.1 Never Share a HUMULIN 70/30 KwikPen or Syringe Between Patients HUMULIN 70/30 KwikPens must never be shared between patients, even if the needle is changed. Patients using HUMULIN 70/30 vials must never share needles or syringes with another person. Sharing poses a risk for transmission of blood-borne pathogens. 5.2 Hyperglycemia or Hypoglycemia with Changes in Insulin Regimen Changes in an insulin regimen (e.g., insulin strength, manufacturer, type, injection site or method of administration) may affect glycemic control and predispose to hypoglycemia [see Warnings and Precautions ( 5.3 )] or hyperglycemia. Repeated insulin injections into areas of lipodystrophy or localized cutaneous amyloidosis have been reported to result in hyperglycemia; and a sudden change in the injection site (to an unaffected area) has been reported to result in hypoglycemia [see Adverse Reactions ( 6 )] . Make any changes to a patient's insulin regimen under close medical supervision with increased frequency of blood glucose monitoring. …"},{"title":"อาการไม่พึงประสงค์","body":"The following adverse reactions are discussed elsewhere in the labeling: Hypoglycemia [see Warnings and Precautions ( 5.3 )] . Hypoglycemia Due to Medication Errors [see Warnings and Precautions ( 5.4 )] . Hypersensitivity Reactions [see Warnings and Precautions ( 5.5 )] . Hypokalemia [see Warnings and Precautions ( 5.6 )] . The following additional adverse reactions have been identified during post-approval use of HUMULIN 70/30. Because these reactions are reported voluntarily from a population of uncertain size, it is not always possible to reliably estimate their frequency or to establish a causal relationship to drug exposure. Adverse reactions observed with insulin therapy include hypoglycemia, allergic reactions, injection site reactions, lipodystrophy, pruritus, rash, weight gain, and edema. ( 6 ) To report SUSPECTED ADVERSE REACTIONS, contact Eli Lilly and Company at 1-800-LillyRx (1-800-545-5979) or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch. Allergic Reactions Some patients taking HUMULIN 70/30 have experienced erythema, local edema, and pruritus at the site of injection. These conditions were usually self-limiting. Severe cases of generalized allergy (anaphylaxis) have been reported [see Warnings and Precautions ( 5.5 )] . Peripheral Edema Some patients taking HUMULIN 70/30 have experienced sodium retention and edema, particularly if previously poor metabolic control is improved by intensified insulin therapy. Lipodystrophy Administration of insulin subcutaneously, including HUMULIN 70/30, has resulted in lipoatrophy (depression in the skin) or lipohypertrophy (enlargement or thickening of tissue) [see Dosage and Administration ( 2.1 )] in some patients. Localized Cutaneous Amyloidosis Localized cutaneous amyloidosis at the injection site has occurred. Hyperglycemia has been reported with repeated insulin injections into areas of localized cutaneous amyloidosis; hypoglycemia has been reported with a sudden change to an unaffected injection site. Weight gain Weight gain has occurred with insulins, including HUMULIN 70/30, and has been attributed to the anabolic effects of insulin and the decrease in glycosuria. Immunogenicity Development of antibodies that react with human insulin have been observed with all insulins, including HUMULIN 70/30."},{"title":"Drug interaction","body":"Table 1: Clinically Significant Drug Interactions with HUMULIN 70/30 Drugs that May Increase the Risk of Hypoglycemia Drugs: Antidiabetic agents, ACE inhibitors, angiotensin II receptor blocking agents, disopyramide, fibrates, fluoxetine, monoamine oxidase inhibitors, pentoxifylline, pramlintide, salicylates, somatostatin analog (e.g., octreotide), and sulfonamide antibiotics Intervention: Dose adjustment and increased frequency of glucose monitoring may be required when HUMULIN 70/30 is co-administered with these drugs. Drugs that May Decrease the Blood Glucose Lowering Effect of HUMULIN 70/30 Drugs: Atypical antipsychotics (e.g., olanzapine and clozapine), corticosteroids, danazol, diuretics, estrogens, glucagon, isoniazid, niacin, oral contraceptives, phenothiazines, progestogens (e.g., in oral contraceptives), protease inhibitors, somatropin, sympathomimetic agents (e.g., albuterol, epinephrine, terbutaline), and thyroid hormones. Intervention: Dose adjustment and increased frequency of glucose monitoring may be required when HUMULIN 70/30 is co-administered with these drugs. Drugs that May Increase or Decrease the Blood Glucose Lowering Effect of HUMULIN 70/30 Drugs: Alcohol, beta-blockers, clonidine, and lithium salts. Pentamidine may cause hypoglycemia, which may sometimes be followed by hyperglycemia. Intervention: Dose adjustment and increased frequency of glucose monitoring may be required when HUMULIN 70/30 is co-administered with these drugs. Drugs that May Blunt Signs and Symptoms of Hypoglycemia Drugs: Beta-blockers, clonidine, guanethidine, and reserpine Intervention: Increased frequency of glucose monitoring may be required when HUMULIN 70/30 is co-administered with these drugs. Drugs that Affect Glucose Metabolism: Adjustment of insulin dosage may be needed. ( 7 ) Antiadrenergic Drugs (e.g., beta-blockers, clonidine, guanethidine, and reserpine): Signs and symptoms of hypoglycemia may be reduced or absent. ( 5.3 , 7 )"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Available data from published studies over decades have not established an association with human insulin use during pregnancy and major birth defects, miscarriage, or adverse maternal or fetal outcomes ( see Data). There are risks to the mother and fetus associated with poorly controlled diabetes in pregnancy ( see Clinical Considerations). Animal reproduction studies were not performed. The estimated background risk of major birth defects is 6-10% in women with pre-gestational diabetes with a HbA1c >7% and has been reported to be as high as 20-25% in women with a HbA1c >10%. The estimated background risk of miscarriage for the indicated population is unknown. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2-4% and 15-20%, respectively. Clinical Considerations Disease-associated maternal and/or embryo/fetal risk Poorly controlled diabetes in pregnancy increases the maternal risk for diabetic ketoacidosis, pre-eclampsia, spontaneous abortions, preterm delivery, and delivery complications. Poorly controlled diabetes increases the fetal risk for major birth defects, stillbirth, and macrosomia-related morbidity. Data Human Data While available studies cannot definitively establish the absence of risk, published data from retrospective studies, open-label, randomized, parallel studies and meta-analyses over decades have not established an association with human insulin use during pregnancy and major birth defects, miscarriage, or adverse maternal or fetal outcomes. All available studies have methodological limitations, including lack of blinding, unclear methods or randomization, and small sample size. 8.4 Pediatric Use The safety and effectiveness of HUMULIN 70/30 in pediatric patients have not been established. 8.5 Geriatric Use The effect of age on the pharmacokinetics and pharmacodynamics of HUMULIN 70/30 has not been studied [see Clinical Pharmacology ( 12.3 )] . Patients with advanced age using any insulin, including HUMULIN 70/30, may be at increased risk of hypoglycemia due to co-morbid disease and polypharmacy [see Warnings and Precautions ( 5.3 )] ."},{"title":"การได้รับยาเกินขนาด","body":"Excess insulin administration may cause hypoglycemia and hypokalemia [see Warnings and Precautions ( 5.3 , 5.6 )] . Mild episodes of hypoglycemia can be treated with oral glucose. Adjustments in drug dosage, meal patterns, or physical activity level may be needed. More severe episodes with coma, seizure, or neurologic impairment may be treated with a glucagon product for emergency use or concentrated intravenous glucose. Sustained carbohydrate intake and observation may be necessary because hypoglycemia may recur after apparent clinical recovery. Hypokalemia must be corrected appropriately."},{"title":"การเก็บรักษา","body":"16.2 Storage and Handling Dispense in the original sealed carton with the enclosed Instructions for Use. Protect from heat and light. Do not freeze. Do not use if it has been frozen. See Table 2 below for storage conditions. Table 2: Storage Conditions for HUMULIN 70/30 Vials and Pens a When stored at room temperature, HUMULIN 70/30 vial can only be used for a total of 31 days including both not in-use (unopened) and in-use (opened) storage time. b When stored at room temperature, HUMULIN 70/30 KwikPen can only be used for a total of 10 days including both not in-use (unopened) and in-use (opened) storage time. Not In-use (Unopened) In-use (Opened) Room Temperature (up to 86°F [30°C]) Refrigerated (36° to 46°F [2° to 8°C]) Room Temperature (up to 86°F [30°C]) Refrigerated (36° to 46°F [2° to 8°C]) 10 mL multiple-dose vial a 31 days Until expiration date 31 days 31 days 3 mL single-patient-use HUMULIN 70/30 KwikPen b 10 days Until expiration date 10 days Do not refrigerate."}]},
{"key":"isosorbide dinitrate|ORAL","generic":"isosorbide dinitrate","route":"ORAL","brand":null,"title":"Isosorbide Dinitrate","set_id":"71fdd147-a987-40b6-9f07-82d56525ceb8","effective":"20240201","sections":[{"title":"ข้อบ่งใช้","body":"Isosorbide dinitrate tablets are indicated for the prevention of angina pectoris due to coronary artery disease. The onset of action of immediate-release oral isosorbide dinitrate is not sufficiently rapid for this product to be useful in aborting an acute anginal episode."},{"title":"ขนาดยาและวิธีใช้","body":"As noted under CLINICAL PHARMACOLOGY , multiple-dose studies with ISDN and other nitrates have shown that maintenance of continuous 24-hour plasma levels results in refractory tolerance. Every dosing regimen for isosorbide dinitrate tablets must provide a daily dose-free interval to minimize the development of this tolerance. With immediate-release ISDN, it appears that one daily dose-free interval must be at least 14 hours long. As also noted under CLINICAL PHARMACOLOGY , the effects of the second and later doses have been smaller and shorter-lasting than the effects of the first. Large controlled studies with other nitrates suggest that no dosing regimen with isosorbide dinitrate tablets should be expected to provide more than about 12 hours of continuous anti-anginal efficacy per day. As with all titratable drugs, it is important to administer the minimum dose which produces the desired clinical effect. The usual starting dose of isosorbide dinitrate is 5 mg to 20 mg, two or three times daily. For maintenance therapy, 10 mg to 40 mg, two or three times daily is recommended. Some patients may require higher doses. A daily dose-free interval of at least 14 hours is advisable to minimize tolerance. The optimal interval will vary with the individual patient, dose and regimen."},{"title":"ข้อห้ามใช้","body":"Isosorbide dinitrate tablets are contraindicated in patients who are allergic to isosorbide dinitrate or any of its ingredients. Do not use isosorbide dinitrate tablets in patients who are taking certain drugs for erectile dysfunction (phosphodiesterase inhibitors), such as sildenafil, tadalafil, or vardenafil. Concomitant use can cause severe hypotension, syncope, or myocardial ischemia. Do not use isosorbide dinitrate tablets in patients who are taking the soluble guanylate cyclase stimulator riociguat. Concomitant use can cause hypotension."},{"title":"คำเตือนและข้อควรระวัง","body":"Amplification of the vasodilatory effects of isosorbide dinitrate by sildenafil can result in severe hypotension. The time course and dose dependence of this interaction have not been studied. Appropriate supportive care has not been studied, but it seems reasonable to treat this as a nitrate overdose, with elevation of the extremities and with central volume expansion. The benefits of immediate-release oral isosorbide dinitrate in patients with acute myocardial infarction or congestive heart failure have not been established. If one elects to use isosorbide dinitrate in these conditions, careful clinical or hemodynamic monitoring must be used to avoid the hazards of hypotension and tachycardia. Because the effects of oral isosorbide dinitrate are so difficult to terminate rapidly, this formulation is not recommended in these settings. General Severe hypotension, particularly with upright posture, may occur with even small doses of isosorbide dinitrate. This drug should therefore be used with caution in patients who may be volume depleted or who, for whatever reason, are already hypotensive. Hypotension induced by isosorbide dinitrate may be accompanied by paradoxical bradycardia and increased angina pectoris. Nitrate therapy may aggravate the angina caused by hypertrophic cardiomyopathy. As tolerance to isosorbide dinitrate develops, the effect of sublingual nitroglycerin on exercise tolerance, although still observable, is somewhat blunted. Some clinical trials in angina patients have provided nitroglycerin for about 12 continuous hours of every 24-hour day. During the daily dose-free interval in some of these trials, anginal attacks have been more easily provoked than before treatment, and patients have demonstrated hemodynamic rebound and decreased exercise tolerance. The importance of these observations to the routine, clinical use of immediate-release oral isosorbide dinitrate is not known. In industrial workers who have had long-term exposure to unknown (presumably high) doses of organic nitrates, tolerance clearly occurs. Chest pain, acute myocardial infarction, and even sudden death have occurred during temporary withdrawal of nitrates from these workers, demonstrating the existence of true physical dependence. Information for Patients Patients should be told that the anti-anginal efficacy of isosorbide dinitrate is strongly related to its dosing regimen, so the prescribed schedule of dosing should be followed carefully. …"},{"title":"อาการไม่พึงประสงค์","body":"Adverse reactions to isosorbide dinitrate are generally dose-related, and almost all of these reactions are the result of isosorbide dinitrate’s activity as a vasodilator. Headache, which may be severe, is the most commonly reported side effect. Headache may be recurrent with each daily dose, especially at higher doses. Transient episodes of lightheadedness, occasionally related to blood pressure changes, may also occur. Hypotension occurs infrequently, but in some patients it may be severe enough to warrant discontinuation of therapy. Syncope, crescendo angina, and rebound hypertension have been reported but are uncommon. Extremely rarely, ordinary doses of organic nitrates have caused methemoglobinemia in normal-seeming patients. Methemoglobinemia is so infrequent at these doses that further discussion of its diagnosis and treatment is deferred (see OVERDOSAGE ). Data are not available to allow estimation of the frequency of adverse reactions during treatment with isosorbide dinitrate tablets. To report SUSPECTED ADVERSE REACTIONS, contact Sandoz Inc., at 1-800-525-8747 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch."},{"title":"Drug interaction","body":"The vasodilating effects of isosorbide dinitrate may be additive with those of other vasodilators. Alcohol, in particular, has been found to exhibit additive effects of this variety. Concomitant use of isosorbide dinitrate with phosphodiesterase inhibitors in any form is contraindicated (see CONTRAINDICATIONS ). Concomitant use of isosorbide dinitrate with riociguat, a soluble guanylate cyclase stimulator, is contraindicated (see CONTRAINDICATIONS )."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"At oral doses 35 and 150 times the maximum recommended human daily dose, isosorbide dinitrate has been shown to cause a dose-related increase in embryotoxicity (increase in mummified pups) in rabbits. There are no adequate, well-controlled studies in pregnant women. Isosorbide dinitrate should be used during pregnancy only if the potential benefit justifies the potential risk to the fetus. It is not known whether isosorbide dinitrate is excreted in human milk. Because many drugs are excreted in human milk, caution should be exercised when isosorbide dinitrate is administered to a nursing woman. Safety and effectiveness in pediatric patients have not been established. Clinical studies of isosorbide dinitrate did not include sufficient numbers of subjects aged 65 and over to determine whether they respond differently from younger subjects. Other reported clinical experience has not identified differences in responses between the elderly and younger patients. In general, dose selection for an elderly patient should be cautious, usually starting at the low end of the dosing range, reflecting the greater frequency of decreased hepatic, renal, or cardiac function, and of concomitant disease or other drug therapy."},{"title":"การได้รับยาเกินขนาด","body":"Hemodynamic Effects The ill effects of isosorbide dinitrate overdose are generally the results of isosorbide dinitrate’s capacity to induce vasodilatation, venous pooling, reduced cardiac output, and hypotension. These hemodynamic changes may have protean manifestations, including increased intracranial pressure, with any or all of persistent throbbing headache, confusion, and moderate fever; vertigo; palpitations; visual disturbances; nausea and vomiting (possibly with colic and even bloody diarrhea); syncope (especially in the upright posture); air hunger and dyspnea, later followed by reduced ventilatory effort; diaphoresis, with the skin either flushed or cold and clammy; heart block and bradycardia; paralysis; coma; seizures; and death. Laboratory determinations of serum levels of isosorbide dinitrate and its metabolites are not widely available, and such determinations have, in any event, no established role in the management of isosorbide dinitrate overdose. There are no data suggesting what dose of isosorbide dinitrate is likely to be life-threatening in humans. In rats, the median acute lethal dose (LD 50 ) was found to be 1100 mg/kg. No data are available to suggest physiological maneuvers (e.g., maneuvers to change the pH of the urine) that might accelerate elimination of isosorbide dinitrate and its active metabolites. Similarly, it is not known which, if any, of these substances can usefully be removed from the body by hemodialysis. No specific antagonist to the vasodilator effects of isosorbide dinitrate is known, and no intervention has been subject to controlled studies as a therapy for isosorbide dinitrate overdose. Because the hypotension associated with isosorbide dinitrate overdose is the result of venodilatation and arterial hypovolemia, prudent therapy in this situation should be directed toward increase in central fluid volume. Passive elevation of the patient’s legs may be sufficient, but intravenous infusion of normal saline or similar fluid may also be necessary. The use of epinephrine or other arterial vasoconstrictors in this setting is likely to do more harm than good. In patients with renal disease or congestive heart failure, therapy resulting in central volume expansion is not without hazard. Treatment of isosorbide dinitrate overdose in these patients may be subtle and difficult, and invasive monitoring may be required. …"},{"title":"การเก็บรักษา","body":"Store at 20° to 25°C (68° to 77°F) [see USP Controlled Room Temperature]. Protect from moisture. Dispense in a tight, light-resistant container."}]},
{"key":"levothyroxine sodium|ORAL","generic":"levothyroxine sodium","route":"ORAL","brand":null,"title":"levothyroxine sodium","set_id":"00a4fc0b-7162-455e-8ed3-56efdbbe182e","effective":"20251001","sections":[{"title":"ข้อบ่งใช้","body":"Levothyroxine Sodium Tablets are L-thyroxine (T4) indicated for: • Hypothyroidism: As replacement therapy in primary (thyroidal), secondary (pituitary), and tertiary (hypothalamic) congenital or acquired hypothyroidism. ( 1 ) • Pituitary Thyrotropin (Thyroid-Stimulating Hormone, TSH) Suppression: As an adjunct to surgery and radioiodine therapy in the management of thyrotropin-dependent well-differentiated thyroid cancer. ( 1 ) Limitations of Use: - Not indicated for suppression of benign thyroid nodules and nontoxic diffuse goiter in iodine-sufficient patients. - Not indicated for treatment of hypothyroidism during the recovery phase of subacute thyroiditis. Hypothyroidism Levothyroxine Sodium Tablets are indicated as a replacement therapy in primary (thyroidal), secondary (pituitary), and tertiary (hypothalamic) congenital or acquired hypothyroidism. Pituitary Thyrotropin (Thyroid-Stimulating Hormone, TSH) Suppression Levothyroxine Sodium Tablets are indicated as an adjunct to surgery and radioiodine therapy in the management of thyrotropin-dependent well-differentiated thyroid cancer. Limitations of Use: • Levothyroxine Sodium Tablets are not indicated for suppression of benign thyroid nodules and nontoxic diffuse goiter in iodine-sufficient patients as there are no clinical benefits and overtreatment with Levothyroxine Sodium Tablets may induce hyperthyroidism [see Warnings and Precautions ( 5.4 )]. • Levothyroxine Sodium Tablets are not indicated for treatment of hypothyroidism during the recovery phase of subacute thyroiditis."},{"title":"ขนาดยาและวิธีใช้","body":"• Administer once daily, preferably on an empty stomach, one-half to one hour before breakfast. ( 2.1 ) • Administer at least 4 hours before or after drugs that are known to interfere with absorption. ( 2.1 ) • Evaluate the need for dose adjustments when regularly administering within one hour of certain foods that may affect absorption. ( 2.1 ) • Starting dose depends on a variety of factors, including age, body weight, cardiovascular status, and concomitant medications. Peak therapeutic effect may not be attained for 4-6 weeks. ( 2.2 ) • See full prescribing information for dosing in specific patient populations. ( 2.3 ) • Adequacy of therapy determined with periodic monitoring of TSH and/or T4 as well as clinical status. ( 2.4 ) 2.1 General Administration Information Administer Levothyroxine Sodium Tablets as a single daily dose, on an empty stomach, one-half to one hour before breakfast. Administer Levothyroxine Sodium Tablets at least 4 hours before or after drugs known to interfere with Levothyroxine Sodium Tablets absorption [see Drug Interactions ( 7.1 )] . Evaluate the need for dose adjustments when regularly administering within one hour of certain foods that may affect Levothyroxine Sodium Tablets absorption [see Drug Interactions ( 7.9 ) and Clinical Pharmacology ( 12.3 )] . Administer Levothyroxine Sodium Tablets to infants and children who cannot swallow intact tablets by crushing the tablet, suspending the freshly crushed tablet in a small amount (5 mL to 10 mL or 1 teaspoon to 2 teaspoons) of water and immediately administering the suspension by spoon or dropper. Do not store the suspension. Do not administer in foods that decrease absorption of Levothyroxine Sodium Tablets, such as soybean-based infant formula [see Drug Interactions ( 7.9 )] . 2.2 General Principles of Dosing The dose of Levothyroxine Sodium Tablets for hypothyroidism or pituitary TSH suppression depends on a variety of factors including: the patient's age, body weight, cardiovascular status, concomitant medical conditions (including pregnancy), concomitant medications, co-administered food and the specific nature of the condition being treated [see Dosage and Administration ( 2.3 ), Warnings and Precautions ( 5 ) , and Drug Interactions ( 7 )] . Dosing must be individualized to account for these factors and dose adjustments made based on periodic assessment of the patient's clinical response and laboratory parameters [see Dosage and Administration ( 2.4 )] . …"},{"title":"ข้อห้ามใช้","body":"Levothyroxine Sodium Tablets are contraindicated in patients with uncorrected adrenal insufficiency [see Warnings and Precautions ( 5.3 )] . • Uncorrected adrenal insufficiency. ( 4 )"},{"title":"คำเตือนกรอบดำ","body":"WARNING: NOT FOR TREATMENT OF OBESITY OR FOR WEIGHT LOSS Thyroid hormones, including Levothyroxine Sodium Tablets, either alone or with other therapeutic agents, should not be used for the treatment of obesity or for weight loss. In euthyroid patients, doses within the range of daily hormonal requirements are ineffective for weight reduction. Larger doses may produce serious or even life threatening manifestations of toxicity, particularly when given in association with sympathomimetic amines such as those used for their anorectic effects [see Adverse Reactions ( 6 ) , Drug Interactions ( 7.7 ) , and Overdosage ( 10 )] . WARNING: NOT FOR TREATMENT OF OBESITY OR FOR WEIGHT LOSS See full prescribing information for complete boxed warning • Thyroid hormones, including Levothyroxine Sodium Tablets should not be used for the treatment of obesity or for weight loss. • Doses beyond the range of daily hormonal requirements may produce serious or even life threatening manifestations of toxicity ( 6 , 10 )."},{"title":"คำเตือนและข้อควรระวัง","body":"• Cardiac adverse reactions in the elderly and in patients with underlying cardiovascular disease: Initiate Levothyroxine Sodium Tablets at less than the full replacement dose because of the increased risk of cardiac adverse reactions, including atrial fibrillation. ( 2.3 , 5.1 , 8.5 ) • Myxedema coma: Do not use oral thyroid hormone drug products to treat myxedema coma. ( 5.2 ) • Acute adrenal crisis in patients with concomitant adrenal insufficiency: Treat with replacement glucocorticoids prior to initiation of Levothyroxine Sodium Tablets treatment. ( 5.3 ) • Prevention of hyperthyroidism or incomplete treatment of hypothyroidism: Proper dose titration and careful monitoring is critical to prevent the persistence of hypothyroidism or the development of hyperthyroidism. ( 5.4 ) • Worsening of diabetic control: Therapy in patients with diabetes mellitus may worsen glycemic control and result in increased antidiabetic agent or insulin requirements. Carefully monitor glycemic control after starting, changing, or discontinuing thyroid hormone therapy. ( 5.5 ) • Decreased bone mineral density associated with thyroid hormone over-replacement: Over-replacement can increase bone resorption and decrease bone mineral density. Give the lowest effective dose. ( 5.6 ) 5.1 Cardiac Adverse Reactions in the Elderly and in Patients with Underlying Cardiovascular Disease Over-treatment with levothyroxine may cause an increase in heart rate, cardiac wall thickness, and cardiac contractility and may precipitate angina or arrhythmias, particularly in patients with cardiovascular disease and in elderly patients. Initiate Levothyroxine Sodium Tablets therapy in this population at lower doses than those recommended in younger individuals or in patients without cardiac disease [see Dosage and Administration ( 2.3 ) , Use in Specific Populations ( 8.5 )] . Monitor for cardiac arrhythmias during surgical procedures in patients with coronary artery disease receiving suppressive Levothyroxine Sodium Tablets therapy. Monitor patients receiving concomitant Levothyroxine Sodium Tablets and sympathomimetic agents for signs and symptoms of coronary insufficiency. If cardiac symptoms develop or worsen, reduce the Levothyroxine Sodium Tablets dose or withhold for one week and restart at a lower dose. …"},{"title":"อาการไม่พึงประสงค์","body":"associated with Levothyroxine Sodium Tablets therapy are primarily those of hyperthyroidism due to therapeutic overdosage [see Warnings and Precautions ( 5 ) , Overdosage ( 10 )] . They include the following: • General: fatigue, increased appetite, weight loss, heat intolerance, fever, excessive sweating • Central nervous system: headache, hyperactivity, nervousness, anxiety, irritability, emotional lability, insomnia • Musculoskeletal: tremors, muscle weakness, muscle spasm • Cardiovascular: palpitations, tachycardia, arrhythmias, increased pulse and blood pressure, heart failure, angina, myocardial infarction, cardiac arrest • Respiratory: dyspnea • Gastrointestinal: diarrhea, vomiting, abdominal cramps, elevations in liver function tests • Dermatologic: hair loss, flushing, rash • Endocrine: decreased bone mineral density • Reproductive: menstrual irregularities, impaired fertility Seizures have been reported rarely with the institution of levothyroxine therapy. Adverse reactions associated with Levothyroxine Sodium Tablets therapy are primarily those of hyperthyroidism due to therapeutic overdosage: arrhythmias, myocardial infarction, dyspnea, muscle spasm, headache, nervousness, irritability, insomnia, tremors, muscle weakness, increased appetite, weight loss, diarrhea, heat intolerance, menstrual irregularities, and skin rash. ( 6 ) To report SUSPECTED ADVERSE REACTIONS, contact Alvogen, Inc. at 1-866-770-3024 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch. Adverse Reactions in Children Pseudotumor cerebri and slipped capital femoral epiphysis have been reported in children receiving levothyroxine therapy. Overtreatment may result in craniosynostosis in infants and premature closure of the epiphyses in children with resultant compromised adult height. Hypersensitivity Reactions Hypersensitivity reactions to inactive ingredients have occurred in patients treated with thyroid hormone products. These include urticaria, pruritus, skin rash, flushing, angioedema, various gastrointestinal symptoms (abdominal pain, nausea, vomiting and diarrhea), fever, arthralgia, serum sickness, and wheezing. Hypersensitivity to levothyroxine itself is not known to occur."},{"title":"Drug interaction","body":"See full prescribing information for drugs that affect thyroid hormone pharmacokinetics and metabolism (e.g., absorption, synthesis, secretion, catabolism, protein binding, and target tissue response) and may alter the therapeutic response to Levothyroxine Sodium Tablets. ( 7 ) 7.1 Drugs Known to Affect Thyroid Hormone Pharmacokinetics Many drugs can exert effects on thyroid hormone pharmacokinetics and metabolism (e.g., absorption, synthesis, secretion, catabolism, protein binding, and target tissue response) and may alter the therapeutic response to Levothyroxine Sodium Tablets (see Tables 2-5 below). Table 2. Drugs That May Decrease T4 Absorption (Hypothyroidism) Potential impact: Concurrent use may reduce the efficacy of Levothyroxine Sodium Tablets by binding and delaying or preventing absorption, potentially resulting in hypothyroidism. Drug or Drug Class Effect Calcium Carbonate Ferrous Sulfate Calcium carbonate may form an insoluble chelate with levothyroxine, and ferrous sulfate likely forms a ferric-thyroxine complex. Administer Levothyroxine Sodium Tablets at least 4 hours apart from these agents. Orlistat Monitor patients treated concomitantly with orlistat and Levothyroxine Sodium Tablets for changes in thyroid function. Bile Acid Sequestrants - Colesevelam - Cholestyramine - Colestipol Ion Exchange Resins - Kayexalate - Sevelamer Bile acid sequestrants and ion exchange resins are known to decrease levothyroxine absorption. Administer Levothyroxine Sodium Tablets at least 4 hours prior to these drugs or monitor TSH levels. Other drugs: Proton Pump Inhibitors Sucralfate Antacids - Aluminum & Magnesium Hydroxides - Simethicone Gastric acidity is an essential requirement for adequate absorption of levothyroxine. Sucralfate, antacids and proton pump inhibitors may cause hypochlorhydria, affect intragastric pH, and reduce levothyroxine absorption. Monitor patients appropriately. Table 3. Drugs That May Alter T4 and Triiodothyronine (T3) Serum Transport Without Affecting Free Thyroxine (FT4) Concentration (Euthyroidism) Drug or Drug Class Effect Clofibrate Estrogen-containing oral contraceptives Estrogens (oral) Heroin / Methadone 5-Fluorouracil Mitotane Tamoxifen These drugs may increase serum thyroxine-binding globulin (TBG) concentration. Androgens / Anabolic Steroids Asparaginase Glucocorticoids Slow-Release Nicotinic Acid These drugs may decrease serum TBG concentration. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Experience with levothyroxine use in pregnant women, including data from post-marketing studies, have not reported increased rates of major birth defects or miscarriages [see Data]. There are risks to the mother and fetus associated with untreated hypothyroidism in pregnancy. Since TSH levels may increase during pregnancy, TSH should be monitored and Levothyroxine Sodium Tablets dosage adjusted during pregnancy [see Clinical Considerations] . There are no animal studies conducted with levothyroxine during pregnancy. Levothyroxine Sodium Tablets should not be discontinued during pregnancy and hypothyroidism diagnosed during pregnancy should be promptly treated. The estimated background risk of major birth defects and miscarriage for the indicated population is unknown. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2 to 4% and 15 to 20%, respectively. Clinical Considerations Disease-Associated Maternal and/or Embryo/Fetal Risk Maternal hypothyroidism during pregnancy is associated with a higher rate of complications, including spontaneous abortion, gestational hypertension, pre-eclampsia, stillbirth, and premature delivery. Untreated maternal hypothyroidism may have an adverse effect on fetal neurocognitive development. Dose Adjustments During Pregnancy and the Postpartum Period Pregnancy may increase Levothyroxine Sodium Tablets requirements. Serum TSH levels should be monitored and the Levothyroxine Sodium Tablets dosage adjusted during pregnancy. Since postpartum TSH levels are similar to preconception values, the Levothyroxine Sodium Tablets dosage should return to the pre-pregnancy dose immediately after delivery [see Dosage and Administration ( 2.3 )]. Data Human Data Levothyroxine is approved for use as a replacement therapy for hypothyroidism. There is a long experience of levothyroxine use in pregnant women, including data from post-marketing studies that have not reported increased rates of fetal malformations, miscarriages or other adverse maternal or fetal outcomes associated with levothyroxine use in pregnant women. 8.4 Pediatric Use The initial dose of Levothyroxine Sodium Tablets varies with age and body weight. Dosing adjustments are based on an assessment of the individual patient's clinical and laboratory parameters [see Dosage and Administration ( 2.3 , 2.4 )] . …"},{"title":"การได้รับยาเกินขนาด","body":"The signs and symptoms of overdosage are those of hyperthyroidism [see Warnings and Precautions ( 5 ) and Adverse Reactions ( 6 )] . In addition, confusion and disorientation may occur. Cerebral embolism, shock, coma, and death have been reported. Seizures occurred in a 3-year-old child ingesting 3.6 mg of levothyroxine. Symptoms may not necessarily be evident or may not appear until several days after ingestion of levothyroxine sodium. Reduce the Levothyroxine Sodium Tablets dose or discontinue temporarily if signs or symptoms of overdosage occur. Initiate appropriate supportive treatment as dictated by the patient's medical status. For current information on the management of poisoning or overdosage, contact the National Poison Control Center at 1-800-222-1222 or www.poison.org."},{"title":"การเก็บรักษา","body":"Storage Conditions Store at 25°C (77°F); excursions permitted to 15° C to 30° C (59° F to 86° F) [see USP Controlled Room Temperature]. Levothyroxine Sodium Tablets should be protected from light and moisture."}]},
{"key":"lidocaine hydrochloride|INFILTRATION","generic":"lidocaine hydrochloride","route":"INFILTRATION","brand":null,"title":"lidocaine hydrochloride","set_id":"46480253-29b9-4d7f-98ed-10377929026b","effective":"20260113","sections":[{"title":"ข้อบ่งใช้","body":"Lidocaine hydrochloride injection is indicated in adult and pediatric patients for the production of local or regional anesthesia or analgesia for surgery, dental, and oral surgery procedures, diagnostic and therapeutic procedures, and for obstetrical procedures. Specific concentrations and presentations of lidocaine hydrochloride injection are recommended for each type of block indicated to produce local or regional anesthesia or analgesia [see Dosage and Administration ( 2.2 )] . Lidocaine hydrochloride injection contains lidocaine, an amide local anesthetic. Lidocaine hydrochloride injection is indicated in adult and pediatric patients for the production of local or regional anesthesia or analgesia for surgery, dental, and oral surgery procedures, diagnostic and therapeutic procedures, and for obstetrical procedures. For each type of block indicated to produce local or regional anesthesia or analgesia, specific concentrations and presentations are recommended. ( 1 , 2.2 )"},{"title":"ขนาดยาและวิธีใช้","body":"See Full Prescribing Information for recommended dosages and administration information for adult and pediatric patients. 2.1 Important Dosage and Administration Information Lidocaine hydrochloride injection is not recommended for intrathecal use. Avoid use of lidocaine hydrochloride injection solutions containing antimicrobial preservatives (i.e., multiple-dose vials) for epidural or caudal anesthesia [see Warnings and Precautions ( 5.3 )] . Discard unused portion of solution not containing preservatives, i.e., those supplied in single-dose vials, following initial use. Visually inspect this product for particulate matter and discoloration prior to administration whenever solution and container permit. Lidocaine hydrochloride injection is a clear, colorless solutions. Do not administer solutions which are discolored or contain particulate matter. Parenteral drug products should be inspected visually for particulate matter and discoloration prior to administration whenever the solution and container permit. Solutions which are discolored (e.g., pinkish or darker than slightly yellow) or which contain particulate matter or precipitate should not be administered. Mixing or the prior or intercurrent use of any other local anesthetic with lidocaine hydrochloride injection is not recommended because of insufficient data on the clinical use of such mixtures. Administration Precautions Lidocaine hydrochloride injection is to be administered in carefully adjusted dosages by or under the supervision of experienced clinicians who are well versed in the diagnosis and management of dose-related toxicity and other acute emergencies which might arise from the block to be employed. Use lidocaine hydrochloride injection only if the following are immediately available: oxygen, cardiopulmonary resuscitative equipment and drugs, and the personnel resources needed for proper management of toxic reactions and related emergencies [see Warnings and Precautions ( 5.1 ), Adverse Reactions ( 6 ), and Overdosage ( 10 )]. The toxic effects of local anesthetics are additive. Monitor for neurologic and cardiovascular effects related to local anesthetic systemic toxicity when additional local anesthetics are administered with lidocaine hydrochloride injection [see Warnings and Precautions ( 5.1 ), Drug Interactions ( 7.1 ), and Overdosage ( 10 )]. …"},{"title":"ข้อห้ามใช้","body":"Lidocaine hydrochloride injection is contraindicated in patients with a known hypersensitivity to lidocaine or to any local anesthetics of the amide type or to other components of lidocaine hydrochloride injection. Known hypersensitivity to any local anesthetic agent of the amide-type or to other components of lidocaine hydrochloride injection."},{"title":"คำเตือนและข้อควรระวัง","body":"Dose-Related Toxicity : Monitor cardiovascular and respiratory vital signs and patient's state of consciousness after injection of lidocaine hydrochloride injection. ( 5.1 ) Methemoglobinemia : Cases of methemoglobinemia have been reported in association with local anesthetics use. See full prescribing information for more details on managing these risks. ( 5.2 ) Chondrolysis with Intra-Articular Infusion : Avoid Intra-articular infusions as there have been post-marketing reports of chondrolysis in patients receiving such infusion. ( 5.4 ) Allergic-Type Reactions to Sulfites in Lidocaine Hydrochloride Injection and Anaphylactic Reactions: Lidocaine hydrochloride injection without epinephrine does not contain sodium metabisulfite. ( 5.6 ) Risk of Systemic Toxicities with Unintended Intravascular or Intrathecal Injection : Unintended intravascular or intrathecal injection may be associated with systemic toxicities, including CNS or cardiorespiratory depression and coma, progression ultimately to respiratory arrest. Aspirate for blood or cerebrospinal fluid (where applicable) prior to each dose and consider using a test dose of lidocaine hydrochloride injection. ( 5.7 ) 5.1 Dose-Related Toxicity The safety and effectiveness of lidocaine hydrochloride injection depends on proper dosage, correct technique, adequate precautions, and readiness for emergencies. Careful and constant monitoring of cardiovascular and respiratory (adequacy of ventilation) vital signs and the patient's state of consciousness should be performed after injection of lidocaine hydrochloride solutions. Possible early warning signs of central nervous system (CNS) toxicity are restlessness, anxiety, incoherent speech, lightheadedness, numbness and tingling of the mouth and lips, metallic taste, tinnitus, dizziness, blurred vision, tremors, twitching, CNS depression, or drowsiness. Delay in proper management of dose-related toxicity, underventilation from any cause, and/or altered sensitivity may lead to the development of acidosis, cardiac arrest, and, possibly, death. During major regional nerve blocks, such as those of the brachial plexus or lower extremity, the patient should have an indwelling intravenous catheter to assure adequate intravenous access. Use the lowest dosage of lidocaine hydrochloride injection that results in effective anesthesia to avoid high plasma levels and serious adverse effects. …"},{"title":"อาการไม่พึงประสงค์","body":"The following clinically significant adverse reactions have been reported and described in the Warnings and Precautions section of the labeling: Dose-Related Toxicity [see Warnings and Precautions ( 5.1 )] Methemoglobinemia [see Warnings and Precautions ( 5.2 )] Chondrolysis with Intra-Articular Infusion [see Warnings and Precautions ( 5.4 )] Severe, Persistent Hypertension, Cerebrovascular Accidents, and Bradycardia Due to Drug Interactions [see Warnings and Precautions ( 5.5 )] Allergic-Type Reactions [see Warnings and Precautions ( 5.6 )] Systemic Toxicities with Unintended Intravascular or Intrathecal Injection [see Warnings and Precautions ( 5.7 )] Respiratory Arrest Following Retrobulbar Block [see Warnings and Precautions ( 5.14 )] The following adverse reactions from voluntary reports or clinical studies have been reported with lidocaine or lidocaine and epinephrine. Because many of these reactions were reported voluntarily from a population of uncertain size, it is not always possible to reliably estimate their frequency or establish a causal relationship to drug exposure. Adverse reactions to lidocaine hydrochloride injection are characteristic of those associated with other amide-type local anesthetic. A major cause of adverse reactions to this group of drugs is excessive plasma levels, which may be due to overdosage, unintentional intravascular injection, or slow metabolic degradation. The most commonly encountered acute adverse reactions that demand immediate counter measures were related to the CNS and the cardiovascular system. These adverse reactions were generally dose-related and due to high plasma levels which may have resulted from overdosage, rapid absorption from the injection site, diminished tolerance, or from unintentional intravascular injection of the local anesthetic solution. In addition to systemic does-related toxicity, unintentional intrathecal injection of drug during the intended performance of caudal or lumbar epidural block or nerve blocks near the vertebral column (especially in the head and neck region) has resulted in underventilation or apnea (“Total or High Spinal”). Also, hypertension due to loss of sympathetic tone and respiratory paralysis or underventilation due to cephalad extension of the motor level of anesthesia have occurred. This has led to secondary cardiac arrest when untreated. When used for dental injections, paresthesia of the lips, tongue, and oral tissues have been reported. …"},{"title":"Drug interaction","body":"Local Anesthetics : The toxic effects of local anesthetics are additive. Monitor for neurologic and cardiovascular effects when additional local anesthetics are administered. ( 7.1 ) Monoamine Oxidase Inhibitors and Tricyclic Antidepressants : Administration of lidocaine hydrochloride injection to patients receiving monoamine oxidase inhibitors or tricyclic antidepressants may produce severe, prolonged hypertension Concurrent use of these agents should generally be avoided. ( 5.5 , 7.2 ) Ergot-type Oxytocic Drugs : Concurrent administration of lidocaine hydrochloride injection and ergot-type oxytocic drugs may cause severe, persistent hypertension or cerebrovascular accidents. ( 5.5 , 7.3 ) Nonselective Beta-Adrenergic Antagonists : Administration of lidocaine hydrochloride injection in patients receiving nonselective beta-adrenergic antagonist may cause severe hypertension and bradycardia. Concurrent use of these agents should generally be avoided. ( 5.5 , 7.4 ) Drugs Associated with Methemoglobinemia : Patients are at increased risk of developing methemoglobinemia when concurrently exposed to nitrates, nitrites, local anesthetics, antineoplastic agents, antibiotics, antimalarials, anticonvulsants and other drugs. ( 7.5 ). Geriatric Use : Elderly patients should be given reduced doses commensurate with their age and physical condition. ( 8.5 ) Hepatic Impairment : consider reduced dosing and increased monitoring for local anesthetic systemic toxicity in patients with hepatic impairment. ( 8.6 ) 7.1 Local Anesthetics The toxic effects of local anesthetics are additive. If coadministration of other local anesthetics with lidocaine hydrochloride injection cannot be avoided, monitor patients for neurologic and cardiovascular effects related to local anesthetic systemic toxicity [see Warnings and Precautions ( 5.1 )]. 7.2 Monoamine Oxidase Inhibitors and Tricyclic Antidepressants The administration of lidocaine hydrochloride injection to patients receiving monoamine oxidase inhibitors or tricyclic antidepressants may produce severe, prolonged hypertension. Concurrent use of these agents should generally be avoided. In situations when concurrent therapy is necessary, careful monitoring of the patient's hemodynamic status is essential [see Warnings and Precautions ( 5.5 )]. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Available published data and decades of clinical use with lidocaine hydrochloride injection in pregnant women have not identified any drug-associated risk for major birth defects, miscarriage, or other adverse maternal or fetal outcomes. Local anesthetics may cause varying degrees of toxicity to the mother and fetus and adverse reactions include alterations of the central nervous system, peripheral vascular tone and cardiac function (see Clinical Considerations ). In a published animal reproduction study, pregnant rats administered lidocaine by continuous subcutaneous infusion at a dose approximately 9.6 times the maximum recommended human dose (MRHD) of 500 mg in lidocaine hydrochloride injection during the period of organogenesis resulted in lower fetal body weights [see Data ]. The estimated background risk of major birth defects and miscarriage for the indicated population is unknown. All pregnancies have a background risk of birth defects, loss, or other adverse outcomes. In the United States general population, the estimated background risks of major birth defects and miscarriage in clinically recognized pregnancies is 2% to 4% and 15% to 20%, respectively. Clinical Considerations Maternal adverse reactions Maternal hypotension has resulted from regional anesthesia. Local anesthetics produce vasodilation by blocking sympathetic nerves. Therefore, during treatment of systemic toxicity, maternal hypotension or fetal bradycardia following regional block, the parturient should be maintained in the left lateral decubitus position if possible or manual displacement of the uterus off the great vessels be accomplished. Elevating the patient's legs will also help prevent decreases in blood pressure. The fetal heart rate also should be monitored continuously, and electronic fetal monitoring is highly advisable. Labor or delivery Local anesthetics rapidly cross the placenta, and when used for epidural, paracervical, pudendal or caudal block anesthesia, can cause varying degrees of maternal, fetal and neonatal toxicity [see Clinical Pharmacology ( 12.3 )]. The incidence and degree of toxicity depend upon the procedure performed, the type and amount of drug used, and the technique of drug administration. Adverse reactions in the parturient, fetus and neonate involve alterations of the central nervous system, peripheral vascular tone and cardiac function. …"},{"title":"การได้รับยาเกินขนาด","body":"Clinical Presentation Acute emergencies from local anesthetics are generally related to high plasma levels encountered during therapeutic use of local anesthetics or to unintended subarachnoid injection of local anesthetic solution [see Warnings and Precautions ( 5.1 ) and Adverse Reactions ( 6 )]. Management The first consideration is prevention, best accomplished by careful and constant monitoring of cardiovascular and respiratory vital signs and the patient's state of consciousness after each local anesthetic injection. At the first sign of change, oxygen should be administered. The first step in the management of convulsions, as well as underventilation or apnea due to unintended subarachnoid injection of drug solution, consists of immediate attention to the maintenance of a patent airway and assisted or controlled ventilation with oxygen and a delivery system capable of permitting immediate positive airway pressure by mask. Immediately after the institution of these ventilatory measures, the adequacy of the circulation should be evaluated, keeping in mind that drugs used to treat convulsions sometimes depress the circulation when administered intravenously. Should convulsions persist despite adequate respiratory support, and if the status of the circulation permits, a benzodiazepine (such as diazepam) may be administered intravenously. The clinician should be familiar, prior to the use of local anesthetics, with these anticonvulsant drugs. Supportive treatment of circulatory depression may require administration of intravenous fluids and, when appropriate, a vasopressor as directed by the clinical situation (e.g., ephedrine). If not treated immediately, both convulsions and cardiovascular depression can result in hypoxia, acidosis, bradycardia, arrhythmias and cardiac arrest. Underventilation or apnea due to unintentional subarachnoid injection of local anesthetic solution may produce these same signs and also lead to cardiac arrest if ventilatory support is not instituted. If cardiac arrest should occur, standard cardiopulmonary resuscitative measures should be instituted. Endotracheal intubation, employing drugs and techniques familiar to the clinician, may be indicated, after initial administration of oxygen by mask, if difficulty is encountered in the maintenance of a patent airway or if prolonged ventilatory support (assisted or controlled) is indicated. …"},{"title":"การเก็บรักษา","body":"Storage Conditions Store at 20° to 25°C (68° to 77°F); excursions permitted between 15° and 30°C (59° and 86°F). [See USP Controlled Room Temperature.] Protect from light. For Single-Dose Vials: Discard unused portion. Sterile, Nonpyrogenic. The container closure is not made with natural rubber latex."}]},
{"key":"losartan potassium|ORAL","generic":"losartan potassium","route":"ORAL","brand":null,"title":"Losartan Potassium","set_id":"021cd76a-b093-4704-8410-5e7d01e20a54","effective":"20260827","sections":[{"title":"ข้อบ่งใช้","body":"Losartan potassium tablets are an angiotensin II receptor blocker (ARB) indicated for: • Treatment of hypertension, to lower blood pressure in adults and children greater than 6 years old. Lowering blood pressure reduces the risk of fatal and nonfatal cardiovascular events, primarily strokes and myocardial infarctions. (1.1) • Reduction of the risk of stroke in patients with hypertension and left ventricular hypertrophy. There is evidence that this benefit does not apply to Black patients. (1.2) • Treatment of diabetic nephropathy with an elevated serum creatinine and proteinuria in patients with type 2 diabetes and a history of hypertension. (1.3) 1.1 Hypertension Losartan potassium tablets are indicated for the treatment of hypertension in adults and pediatric patients 6 years of age and older, to lower blood pressure. Lowering blood pressure lowers the risk of fatal and nonfatal cardiovascular (CV) events, primarily strokes and myocardial infarction. These benefits have been seen in controlled trials of antihypertensive drugs from a wide variety of pharmacologic classes including losartan. Control of high blood pressure should be part of comprehensive cardiovascular risk management, including, as appropriate, lipid control, diabetes management, antithrombotic therapy, smoking cessation, exercise, and limited sodium intake. Many patients will require more than 1 drug to achieve blood pressure goals. For specific advice on goals and management, see published guidelines, such as those of the National High Blood Pressure Education Program's Joint National Committee on Prevention, Detection, Evaluation, and Treatment of High Blood Pressure (JNC). Numerous antihypertensive drugs, from a variety of pharmacologic classes and with different mechanisms of action, have been shown in randomized controlled trials to reduce cardiovascular morbidity and mortality, and it can be concluded that it is blood pressure reduction, and not some other pharmacologic property of the drugs, that is largely responsible for those benefits. The largest and most consistent cardiovascular outcome benefit has been a reduction in the risk of stroke, but reductions in myocardial infarction and cardiovascular mortality also have been seen regularly. Elevated systolic or diastolic pressure causes increased cardiovascular risk, and the absolute risk increase per mmHg is greater at higher blood pressures, so that even modest reductions of severe hypertension can provide substantial benefit. …"},{"title":"ขนาดยาและวิธีใช้","body":"Hypertension • Usual adult dose: 50 mg once daily. (2.1) • Usual pediatric starting dose: 0.7 mg per kg once daily (up to 50 mg). (2.1) Hypertensive Patients with Left Ventricular Hypertrophy • Usual starting dose: 50 mg once daily. (2.2) • Add hydrochlorothiazide 12.5 mg and/or increase losartan potassium to 100 mg followed by an increase to hydrochlorothiazide 25 mg if further blood pressure response is needed. (2.2 , 14.2) Nephropathy in Type 2 Diabetic Patients • Usual dose: 50 mg once daily. (2.3) • Increase dose to 100 mg once daily if further blood pressure response is needed. (2.3) 2.1 Hypertension Adult Hypertension The usual starting dose of losartan potassium tablets is 50 mg once daily. The dosage can be increased to a maximum dose of 100 mg once daily as needed to control blood pressure [see Clinical Studies (14.1) ]. A starting dose of 25 mg is recommended for patients with possible intravascular depletion (e.g., on diuretic therapy). Pediatric Hypertension The usual recommended starting dose is 0.7 mg per kg once daily (up to 50 mg total) administered as a tablet or a suspension [see Dosage and Administration (2.5) ]. Dosage should be adjusted according to blood pressure response. Doses above 1.4 mg per kg (or in excess of 100 mg) daily have not been studied in pediatric patients [see Clinical Pharmacology (12.3) , Clinical Studies (14.1) , and Warnings and Precautions (5.2) ]. Losartan potassium tablets are not recommended in pediatric patients less than 6 years of age or in pediatric patients with estimated glomerular filtration rate less than 30 mL/min/1.73 m 2 [see Use in Specific Populations (8.4) , Clinical Pharmacology (12.3) , and Clinical Studies (14) ]. 2.2 Hypertensive Patients with Left Ventricular Hypertrophy The usual starting dose is 50 mg of losartan potassium tablets once daily. Hydrochlorothiazide 12.5 mg daily should be added and/or the dose of losartan potassium should be increased to 100 mg once daily followed by an increase in hydrochlorothiazide to 25 mg once daily based on blood pressure response [see Clinical Studies (14.2) ]. 2.3 Nephropathy in Type 2 Diabetic Patients The usual starting dose is 50 mg once daily. The dose should be increased to 100 mg once daily based on blood pressure response [see Clinical Studies (14.3) ]. 2.4 Dosage Modifications in Patients with Hepatic Impairment In patients with mild-to-moderate hepatic impairment the recommended starting dose of losartan potassium is 25 mg once daily. …"},{"title":"ข้อห้ามใช้","body":"Losartan potassium is contraindicated: • In patients who are hypersensitive to any component of this product. • For coadministration with aliskiren in patients with diabetes. • Hypersensitivity to any component. (4) • Coadministration with aliskiren in patients with diabetes. (4)"},{"title":"คำเตือนกรอบดำ","body":"WARNING: FETAL TOXICITY When pregnancy is detected, discontinue losartan potassium as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus [see Warnings and Precautions (5.1) ]. WARNING: FETAL TOXICITY See full prescribing information for complete boxed warning. When pregnancy is detected, discontinue losartan potassium as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. (5.1)"},{"title":"คำเตือนและข้อควรระวัง","body":"• Hypotension: Correct volume or salt depletion prior to administration of losartan potassium. (5.2) • Monitor renal function and potassium in susceptible patients. (5.3 , 5.4) 5.1 Fetal Toxicity Losartan potassium can cause fetal harm when administered to a pregnant woman. Use of drugs that act on the renin-angiotensin system during the second and third trimesters of pregnancy reduces fetal renal function and increases fetal and neonatal morbidity and death. Resulting oligohydramnios can be associated with fetal lung hypoplasia and skeletal deformations. Potential neonatal adverse effects include skull hypoplasia, anuria, hypotension, renal failure, and death. When pregnancy is detected, discontinue losartan potassium as soon as possible [see Use in Specific Populations (8.1) ]. 5.2 Hypotension in Volume- or Salt-Depleted Patients In patients with an activated renin-angiotensin system, such as volume- or salt-depleted patients (e.g., those being treated with high doses of diuretics), symptomatic hypotension may occur after initiation of treatment with losartan potassium. Correct volume or salt depletion prior to administration of losartan potassium [see Dosage and Administration (2.1) ]. 5.3 Renal Function Deterioration Changes in renal function including acute renal failure can be caused by drugs that inhibit the renin angiotensin system and by diuretics. Patients whose renal function may depend in part on the activity of the renin-angiotensin system (e.g., patients with renal artery stenosis, chronic kidney disease, severe congestive heart failure, or volume depletion) may be at particular risk of developing acute renal failure on losartan potassium. Monitor renal function periodically in these patients. Consider withholding or discontinuing therapy in patients who develop a clinically significant decrease in renal function on losartan potassium [see Drug Interactions (7.3) and Use in Specific Populations (8.7) ]. 5.4 Hyperkalemia Monitor serum potassium periodically and treat appropriately. Dosage reduction or discontinuation of losartan potassium may be required [see Adverse Reactions (6.1) ]. Concomitant use of other drugs that may increase serum potassium may lead to hyperkalemia [see Drug Interactions (7.1) ]."},{"title":"อาการไม่พึงประสงค์","body":"Most common adverse reactions (incidence ≥2% and greater than placebo) are: dizziness, upper respiratory infection, nasal congestion, and back pain. (6.1) To report SUSPECTED ADVERSE REACTIONS, contact Zydus Pharmaceuticals (USA) Inc. at 1-877-993-8779 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch. 6.1 Clinical Trials Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical trials of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in practice. Hypertension Losartan potassium has been evaluated for safety in more than 3300 adult patients treated for essential hypertension and 4058 patients/subjects overall. Over 1200 patients were treated for over 6 months and more than 800 for over one year. Treatment with losartan potassium was well-tolerated with an overall incidence of adverse events similar to that of placebo. In controlled clinical trials, discontinuation of therapy for adverse events occurred in 2.3% of patients treated with losartan potassium and 3.7% of patients given placebo. In 4 clinical trials involving over 1000 patients on various doses (10 to 150 mg) of losartan potassium and over 300 patients given placebo, the adverse events that occurred in ≥2% of patients treated with losartan potassium and more commonly than placebo were: dizziness (3% vs. 2%), upper respiratory infection (8% vs. 7%), nasal congestion (2% vs. 1%), and back pain (2% vs. 1%). The following less common adverse reactions have been reported: Blood and lymphatic system disorders: Anemia. Psychiatric disorders: Depression. Nervous system disorders: Somnolence, headache, sleep disorders, paresthesia, migraine. Ear and labyrinth disorders: Vertigo, tinnitus. Cardiac disorders: Palpitations, syncope, atrial fibrillation, CVA. Respiratory, thoracic and mediastinal disorders: Dyspnea. Gastrointestinal disorders: Abdominal pain, constipation, nausea, vomiting. Skin and subcutaneous tissue disorders: Urticaria, pruritus, rash, photosensitivity. Musculoskeletal and connective tissue disorders: Myalgia, arthralgia. Reproductive system and breast disorders: Impotence. General disorders and administration site conditions: Edema. Cough Persistent dry cough (with an incidence of a few percent) has been associated with ACE-inhibitor use and in practice can be a cause of discontinuation of ACE-inhibitor therapy. …"},{"title":"Drug interaction","body":"• Agents Increasing Serum Potassium: Risk of hyperkalemia. (7.1) • Lithium: Risk of lithium toxicity. (7.2) • NSAIDs: Increased risk of renal impairment and reduced diuretic, natriuretic, and antihypertensive effects. (7.3) • Dual Inhibition of the Renin-Angiotensin System: Increased risk of renal impairment, hypotension, syncope, and hyperkalemia. (7.4) 7.1 Agents Increasing Serum Potassium Coadministration of losartan with other drugs that raise serum potassium levels may result in hyperkalemia. Monitor serum potassium in such patients. 7.2 Lithium Increases in serum lithium concentrations and lithium toxicity have been reported during concomitant administration of lithium with angiotensin II receptor antagonists. Monitor serum lithium levels during concomitant use. 7.3 Non-Steroidal Anti-Inflammatory Drugs (NSAIDs) Including Selective Cyclooxygenase-2 Inhibitors (COX-2 Inhibitors) In patients who are elderly, volume-depleted (including those on diuretic therapy), or with compromised renal function, coadministration of NSAIDs, including selective COX-2 inhibitors, with angiotensin II receptor antagonists (including losartan) may result in deterioration of renal function, including possible acute renal failure. These effects are usually reversible. Monitor renal function periodically in patients receiving losartan and NSAID therapy. The antihypertensive effect of angiotensin II receptor antagonists, including losartan, may be attenuated by NSAIDs, including selective COX-2 inhibitors. 7.4 Dual Blockade of the Renin-Angiotensin System (RAS) Dual blockade of the RAS with angiotensin receptor blockers, ACE inhibitors, or aliskiren is associated with increased risks of hypotension, syncope, hyperkalemia, and changes in renal function (including acute renal failure) compared to monotherapy. The Veterans Affairs Nephropathy in Diabetes (VA NEPHRON-D) trial enrolled 1448 patients with type 2 diabetes, elevated urinary-albumin-to-creatinine ratio, and decreased estimated glomerular filtration rate (GFR 30 to 89.9 mL/min), randomized them to lisinopril or placebo on a background of losartan therapy and followed them for a median of 2.2 years. Patients receiving the combination of losartan and lisinopril did not obtain any additional benefit compared to monotherapy for the combined endpoint of decline in GFR, end stage renal disease, or death, but experienced an increased incidence of hyperkalemia and acute kidney injury compared with the monotherapy group. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Losartan potassium can cause fetal harm when administered to a pregnant woman. Use of drugs that act on the renin-angiotensin system during the second and third trimesters of pregnancy reduces fetal renal function and increases fetal and neonatal morbidity and death. Most epidemiologic studies examining fetal abnormalities after exposure to antihypertensive use in the first trimester have not distinguished drugs affecting the renin-angiotensin system from other antihypertensive agents. When pregnancy is detected, discontinue losartan potassium as soon as possible (see Clinical Considerations). The estimated background risk of major birth defects and miscarriage for the indicated population is unknown. All pregnancies have a background risk of birth defect, loss, or other adverse outcomes. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2% to 4% and 15% to 20%, respectively. Clinical Considerations Disease-associated Maternal and/or Embryo/Fetal Risk Hypertension in pregnancy increases the maternal risk for pre-eclampsia, gestational diabetes, premature delivery, and delivery complications (e.g., need for cesarean section, post-partum hemorrhage). Hypertension increases the fetal risk for intrauterine growth restriction and intrauterine death. Pregnant women with hypertension should be carefully monitored and managed accordingly. Fetal/Neonatal Adverse Reactions Oligohydramnios in pregnant women who use drugs affecting the renin-angiotensin system in the second and third trimesters of pregnancy can result in the following: reduced fetal renal function leading to anuria and renal failure, fetal lung hypoplasia, skeletal deformations, including skull hypoplasia, hypotension, and death. In the unusual case that there is no appropriate alternative to therapy with drugs affecting the renin angiotensin system for a particular patient, apprise the mother of the potential risk to the fetus. In patients taking losartan potassium during pregnancy, perform serial ultrasound examinations to assess the intra-amniotic environment. Fetal testing may be appropriate, based on the week of gestation. If oligohydramnios is observed, discontinue losartan potassium, unless it is considered lifesaving for the mother. Patients and physicians should be aware, however, that oligohydramnios may not appear until after the fetus has sustained irreversible injury. …"},{"title":"การได้รับยาเกินขนาด","body":"Significant lethality was observed in mice and rats after oral administration of 1000 mg/kg and 2000 mg/kg, respectively, about 44 and 170 times the maximum recommended human dose on a mg/m 2 basis. Limited data are available in regard to overdosage in humans. The most likely manifestation of overdosage would be hypotension and tachycardia; bradycardia could occur from parasympathetic (vagal) stimulation. If symptomatic hypotension should occur, supportive treatment should be instituted. Neither losartan nor its active metabolite can be removed by hemodialysis."}]},
{"key":"magnesium hydroxide|ORAL","generic":"magnesium hydroxide","route":"ORAL","brand":null,"title":"Milk of Magnesia Concentrate","set_id":"2a99a1a8-a830-429f-9cfd-3f29c3d3547c","effective":"20241112","sections":[{"title":"ข้อบ่งใช้","body":"As an Antacid heartburn upset/sour stomach acid indigestion As a Laxative relieves occasional constipation (irregularity) This product usually produces bowel movement in ½ to 6 hours."},{"title":"ขนาดยาและวิธีใช้","body":"As an Antacid do not exceed the maximum recommended daily dose of 20 mL in a 24 hour period shake well before use can be taken with water mL = milliliter adults and children 12 years of age and over 5 mL (1 teaspoonful) children under 12 years of age ask a doctor As a Laxative do not exceed the maximum recommended daily dose in a 24 hour period shake well before use dose may be taken once a day preferably at bedtime, in divided doses, or as directed by a doctor. Drink a full glass (8 oz) of liquid with each dose. mL = milliliter adults and children 12 years and older 15 mL to 30 mL children under 12 years ask a doctor"},{"title":"ข้อห้ามใช้","body":"if you have ever had an allergic reaction to this product or any of its ingredients"},{"title":"คำเตือนและข้อควรระวัง","body":"Do not use if you have ever had an allergic reaction to this product or any of its ingredients Ask a doctor before use if you have kidney disease a magnesium-restricted diet stomach pain, nausea, or vomiting a sudden change in bowel habits that lasts over 14 days Ask a doctor or pharmacist before use If you are taking a prescription drug. This product may interact with certain prescription drugs. Stop use and ask a doctor if you have rectal bleeding or no bowel movement after using this product. These could be signs of a serious condition. you need to use a laxative for more than 1 week If pregnant or breast-feeding, ask a health professional before use. Keep out of reach of children. In case of overdose, get medical help or contact a Poison Control Center right away. magnesium-restricted diet stomach pain, nausea, or vomiting a sudden change in bowel habits that lasts over 14 days drug. This product may interact with certain prescription drugs. product. These could be signs of a serious condition. you need to use a laxative for more than 1 week"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"ask a health professional before use."},{"title":"การเก็บรักษา","body":"Other information each teaspoonful (5 mL) contains: magnesium 1000 mg Sodium Content: 19 mg/10 mL store at room temperature, 20° - 25°C (68° - 77°F). Avoid freezing. Milk of Magnesia Concentrate (white suspension, lemon flavored) is supplied in the following oral dosage form: NDC 0121-0940-10: 10 mL unit dose cup, in a tray of ten cups."}]},
{"key":"medroxyprogesterone acetate|INTRAMUSCULAR","generic":"medroxyprogesterone acetate","route":"INTRAMUSCULAR","brand":null,"title":"Depo-Provera","set_id":"199cf13e-0859-4a73-9b45-e700d0cd1049","effective":"20260825","sections":[{"title":"ข้อบ่งใช้","body":"Depo-Provera CI is indicated for use by females of reproductive potential to prevent pregnancy. Depo-Provera CI is a progestin indicated for use by females of reproductive potential to prevent pregnancy. ( 1 ) Limitations of Use: The use of Depo-Provera CI is not recommended as a long-term (i.e., longer than 2 years) birth control method unless other options are considered inadequate. (1, 5.1) Limitations of Use : The use of Depo-Provera CI is not recommended as a long-term (i.e., longer than 2 years) birth control method unless other options are considered inadequate [see Dosage and Administration (2.1) and Warnings and Precautions (5.1) ]."},{"title":"ขนาดยาและวิธีใช้","body":"The recommended dose is 150 mg of Depo-Provera CI every 3 months (13 weeks) administered by deep, intramuscular (IM) injection in the gluteal or deltoid muscle. ( 2.1 ) 2.1 Prevention of Pregnancy Both the 1 mL vial and the 1 mL prefilled syringe of Depo-Provera CI should be vigorously shaken just before use to ensure that the dose being administered represents a uniform suspension. The recommended dose is 150 mg of Depo-Provera CI every 3 months (13 weeks) administered by deep intramuscular (IM) injection using strict aseptic technique in the gluteal or deltoid muscle, rotating the sites with every injection. As with any IM injection, to avoid an inadvertent subcutaneous injection, body habitus should be assessed prior to each injection to determine if a longer needle is necessary particularly for gluteal IM injection. Use for longer than 2 years is not recommended (unless other birth control methods are considered inadequate) due to the impact of long-term Depo-Provera CI treatment on bone mineral density (BMD) [see Warnings and Precautions (5.1) ] . Dosage does not need to be adjusted for body weight [see Clinical Studies (14.1) ] . To ensure the patient is not pregnant at the time of the first injection, the first injection should be given ONLY during the first 5 days of a normal menstrual period or within the first 5-days post‑partum. In post‑partum mothers who exclusively breastfeed, administer Depo‑Provera CI during or after the sixth post‑partum week. If the time interval between injections is greater than 13 weeks, the physician should determine that the patient is not pregnant before administering the drug. The efficacy of Depo-Provera CI depends on adherence to the dosage schedule of administration. 2.2 Switching from Other Methods of Contraception When switching from other contraceptive methods, Depo-Provera CI should be given in a manner that ensures continuous contraceptive coverage based upon the mechanism of action of both methods, (e.g., patients switching from oral contraceptives should have their first injection of Depo-Provera CI on the day after the last active tablet or at the latest, on the day following the final inactive tablet)."},{"title":"ข้อห้ามใช้","body":"The use of Depo-Provera CI is contraindicated in the following conditions: • Active thrombophlebitis, or current or history of thromboembolic disorders, or cerebral vascular disease [see Warnings and Precautions (5.2) ] . • Known or suspected malignancy of breast [see Warnings and Precautions (5.3) ] . • Known hypersensitivity to Depo-Provera CI (medroxyprogesterone acetate) or any of its other ingredients [see Warnings and Precautions (5.6) ] . • Significant liver disease [see Warnings and Precautions (5.8) ] . • Undiagnosed vaginal bleeding [see Warnings and Precautions (5.11) ] . • Active thrombophlebitis, or current or past history of thromboembolic disorders, or cerebral vascular disease. ( 4 ) • Known or suspected malignancy of breast. ( 4 ) • Known hypersensitivity to Depo-Provera CI (medroxyprogesterone acetate or any of its other ingredients). ( 4 ) • Significant liver disease. ( 4 ) • Undiagnosed vaginal bleeding. ( 4 )"},{"title":"คำเตือนกรอบดำ","body":"WARNING: LOSS OF BONE MINERAL DENSITY • Women who use Depo-Provera Contraceptive Injection (Depo-Provera CI) may lose significant bone mineral density. Bone loss is greater with increasing duration of use and may not be completely reversible [see Warnings and Precautions (5.1) ] . • It is unknown if use of Depo-Provera CI during adolescence or early adulthood, a critical period of bone accretion, will reduce peak bone mass and increase the risk for osteoporotic fracture in later life [see Warnings and Precautions (5.1) ] . • Depo-Provera CI is not recommended as a long-term (i.e., longer than 2 years) birth control method unless other options are considered inadequate [see Indications and Usage (1) and Warnings and Precautions (5.1) ] . WARNING: LOSS OF BONE MINERAL DENSITY See full prescribing information for complete boxed warning . • Women who use Depo-Provera Contraceptive Injection (Depo-Provera CI) may lose significant bone mineral density. Bone loss is greater with increasing duration of use and may not be completely reversible. ( 5.1 ) • It is unknown if use of Depo-Provera CI during adolescence or early adulthood, a critical period of bone accretion, will reduce peak bone mass and increase the risk for osteoporotic fracture in later life. ( 5.1 ) • Depo-Provera CI is not recommended as a long-term (i.e., longer than 2 years) birth control method unless other options are considered inadequate. ( 1 , 5.1 )"},{"title":"คำเตือนและข้อควรระวัง","body":"• Thromboembolic Disorders: Discontinue Depo-Provera CI in patients who develop thrombosis. ( 5.2 ) • Cancer Risks: Monitor women with a strong family history of breast cancer carefully. ( 5.3 ) • Meningioma: Discontinue Depo-Provera CI if meningioma is diagnosed. Monitor patients for signs and symptoms of meningioma. ( 5.4 ) • Ectopic Pregnancy: Consider ectopic pregnancy if a woman using Depo-Provera CI becomes pregnant or complains of severe abdominal pain. ( 5.5 ) • Anaphylaxis and Anaphylactoid Reactions: Provide emergency medical treatment. ( 5.6 ) • Liver Function: Discontinue Depo-Provera CI if jaundice or disturbances of liver function develop. ( 5.8 ) • Carbohydrate Metabolism: Monitor diabetic patients carefully. ( 5.13 ) 5.1 Loss of Bone Mineral Density Use of Depo-Provera CI reduces serum estrogen levels and is associated with significant loss of bone mineral density (BMD). This loss of BMD is of particular concern during adolescence and early adulthood, a critical period of bone accretion. It is unknown if use of Depo-Provera CI by younger women will reduce peak bone mass and increase the risk for osteoporotic fracture in later life. A study to assess the reversibility of loss of BMD in adolescents was conducted with Depo-Provera CI. After discontinuing Depo-Provera CI in these adolescents, mean BMD loss at the total hip and femoral neck did not fully recover by 5 years (60 months) post-treatment in the sub-group of adolescents who were treated for more than 2 years [see Clinical Studies (14.3) ]. Similarly, in adults, there was only partial recovery of mean BMD at the total hip, femoral neck, and lumbar spine towards baseline by 2 years post-treatment [see Clinical Studies (14.2) ]. The use of Depo-Provera CI is not recommended as a long-term (i.e., longer than 2 years) birth control method unless other options are considered inadequate. BMD should be evaluated when a woman needs to continue to use Depo-Provera CI long-term. In adolescents, interpretation of BMD results should take into account patient age and skeletal maturity. Other birth control methods should be considered in the risk/benefit analysis for the use of Depo-Provera CI in women with osteoporosis risk factors. …"},{"title":"อาการไม่พึงประสงค์","body":"The following important adverse reactions observed with the use of Depo-Provera CI are discussed in greater detail in the Warnings and Precautions section ( 5 ): • Loss of Bone Mineral Density [see Warnings and Precautions (5.1) ] • Thromboembolic disease [see Warnings and Precautions (5.2) ] • Breast Cancer [see Warnings and Precautions (5.3) ] • Anaphylaxis and Anaphylactoid Reactions [see Warnings and Precautions (5.6) ] • Bleeding Irregularities [see Warnings and Precautions (5.11) ] • Weight Gain [see Warnings and Precautions (5.12) ] Most common adverse reactions (incidence >5%): menstrual irregularities (bleeding or spotting) 57% at 12 months, 32% at 24 months, abdominal pain/discomfort 11%, weight gain >10 lb at 24 months 38%, dizziness 6%, headache 17%, nervousness 11%, decreased libido 6%. ( 6.1 ) To report SUSPECTED ADVERSE REACTIONS, contact Pfizer Inc. at 1-800-438-1985 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch . 6.1 Clinical Trials Experience Clinical trials are conducted under widely varying conditions, therefore, adverse reaction rates observed in the clinical studies of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in practice. In the two clinical trials with Depo-Provera CI, over 3,900 women, who were treated for up to 7 years, reported the following adverse reactions, which may or may not be related to the use of Depo-Provera CI. The population studied ranges in age from 15 to 51 years, of which 46% were White, 50% Non-White, and 4.9% Unknown race. The patients received 150 mg Depo-Provera CI every 3-months (90 days). The median study duration was 13 months with a range of 1-84 months. Fifty‑eight percent of patients remained in the study after 13 months and 34% after 24 months. Table 1. Adverse Reactions that Were Reported by More than 5% of Subjects Body System Body System represented from COSTART medical dictionary. Adverse Reactions [Incidence (%)] Body as a Whole Headache (16.5%) Abdominal pain/discomfort (11.2%) Metabolic/Nutritional Increased weight >10 lb at 24 months (37.7%) Nervous Nervousness (10.8%) Dizziness (5.6%) Libido decreased (5.5%) Reproductive (Urogenital ) Menstrual irregularities: bleeding (57.3% at 12 months, 32.1% at 24 months) amenorrhea (55% at 12 months, 68% at 24 months) Table 2. Adverse Reactions that Were Reported by between 1 and 5% of Subjects Body System Body System represented from COSTART medical dictionary. …"},{"title":"Drug interaction","body":"Drugs or herbal products that induce certain enzymes, including CYP3A4, may decrease the effectiveness of contraceptive drug products. Counsel patients to use a back-up method or alternative method of contraception when enzyme inducers are used with Depo-Provera CI. ( 7.1 ) 7.1 Changes in Contraceptive Effectiveness Associated with Co-Administration of Other Products If a woman on hormonal contraceptives takes a drug or herbal product that induces enzymes, including CYP3A4, that metabolize contraceptive hormones, counsel her to use additional contraception or a different method of contraception. Drugs or herbal products that induce such enzymes may decrease the plasma concentrations of contraceptive hormones, and may decrease the effectiveness of hormonal contraceptives. Some drugs or herbal products that may decrease the effectiveness of hormonal contraceptives include: • barbiturates • bosentan • carbamazepine • felbamate • griseofulvin • oxcarbazepine • phenytoin • rifampin • St. John's wort • topiramate HIV protease inhibitors and non-nucleoside reverse transcriptase inhibitors : Significant changes (increase or decrease) in the plasma levels of progestin have been noted in some cases of co-administration of HIV protease inhibitors. Significant changes (increase or decrease) in the plasma levels of the progestin have been noted in some cases of co-administration with non-nucleoside reverse transcriptase inhibitors. Antibiotics : There have been reports of pregnancy while taking hormonal contraceptives and antibiotics, but clinical pharmacokinetic studies have not shown consistent effects of antibiotics on plasma concentrations of synthetic steroids. Consult the labeling of all concurrently-used drugs to obtain further information about interactions with hormonal contraceptives or the potential for enzyme alterations. 7.2 Laboratory Test Interactions The pathologist should be advised of progestin therapy when relevant specimens are submitted. The following laboratory tests may be affected by progestins including Depo-Provera CI: (a) Plasma and urinary steroid levels are decreased (e.g., progesterone, estradiol, pregnanediol, testosterone, cortisol). (b) Gonadotropin levels are decreased. (c) Sex-hormone-binding-globulin concentrations are decreased. (d) Protein-bound iodine and butanol extractable protein-bound iodine may increase. T 3 -uptake values may decrease. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary There is no use for contraception in pregnancy; therefore, Depo-Provera CI should be discontinued during pregnancy. Epidemiologic studies and meta‑analyses have not found an increased risk of genital or non-genital birth defects (including cardiac anomalies and limb-reduction defects) following exposure to progestins before conception or during early pregnancy. All pregnancies have a background risk of birth defect, loss, or other adverse outcomes. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2-4% and 15-20%, respectively. 8.4 Pediatric Use Depo-Provera CI is not indicated before menarche. Use of Depo-Provera CI is associated with significant loss of BMD. This loss of BMD is of particular concern during adolescence and early adulthood, a critical period of bone accretion. In adolescents, interpretation of BMD results should take into account patient age and skeletal maturity. It is unknown if use of Depo-Provera CI by younger women will reduce peak bone mass and increase the risk of osteoporotic fractures in later life. Other than concerns about loss of BMD, the safety and effectiveness are expected to be the same for postmenarchal adolescents and adult women. 8.5 Geriatric Use This product has not been studied in post-menopausal women and is not indicated in this population."},{"title":"การเก็บรักษา","body":"Vials MUST be stored upright at controlled room temperature 20° to 25°C (68° to 77°F) [see USP]."}]},
{"key":"metformin hydrochloride|ORAL","generic":"metformin hydrochloride","route":"ORAL","brand":null,"title":"Metformin Hydrochloride","set_id":"1d0b74de-ef4c-4dd2-8019-2ddb409c60b4","effective":"20260803","sections":[{"title":"ข้อบ่งใช้","body":"Metformin hydrochloride extended-release tablets are indicated as an adjunct to diet and exercise to improve glycemic control in adults and pediatric patients 10 years of age and older with type 2 diabetes mellitus. Metformin hydrochloride extended-release tablets are a biguanide indicated as an adjunct to diet and exercise to improve glycemic control in adults and pediatric patients 10 years of age and older with type 2 diabetes mellitus. ( 1 )"},{"title":"ขนาดยาและวิธีใช้","body":"Recommended Dosage in Adults and Pediatric Patients Aged 10 Years and Older: Swallow metformin hydrochloride extended-release tablets whole and never crush, cut or chew ( 2.2 ) Starting dosage: 500 mg orally once daily with the evening meal ( 2.2 ) Increase the dosage in increments of 500 mg weekly, up to a maximum dosage of 2,000 mg once daily with the evening meal ( 2.2 ) Patients receiving metformin hydrochloride immediate-release tablets may be switched to metformin hydrochloride extended-release tablets once daily at the same total daily dosage, up to 2,000 mg once daily ( 2.3 ) Recommended Dosage in Patients with Renal Impairment: Prior to initiation, assess renal function with estimated glomerular filtration rate (eGFR) ( 2.4 ) Do not use in patients with eGFR below 30 mL/minute/1.73 m 2 ( 2.4 ) Initiation is not recommended in patients with eGFR between 30 mL/minute/1.73 m 2 and 45 mL/minute/1.73 m 2 ( 2.4 ) Assess risk/benefit of continuing if eGFR falls below 45 mL/minute/1.73 m 2 ( 2.4 ) Discontinue if eGFR falls below 30 mL/minute/1.73 m 2 ( 2.4 ) Discontinuation for Iodinated Contrast Imaging Procedures: Metformin hydrochloride extended-release tablets may need to be discontinued at time of, or prior to, iodinated contrast imaging procedures ( 2.5 ) 2.2 Recommended Dosage for Metformin Hydrochloride Extended-Release Tablets in Adults and Pediatric Patients Aged 10 Years and Older with Type 2 Diabetes Mellitus Swallow metformin hydrochloride extended-release tablets whole and never crush, cut or chew. The recommended starting dosage of metformin hydrochloride extended-release tablets is 500 mg orally once daily with the evening meal. Increase the dosage in increments of 500 mg weekly on the basis of glycemic control and tolerability, up to a maximum dosage of 2,000 mg once daily with the evening meal. If glycemic control is not achieved with metformin hydrochloride extended-release tablets 2,000 mg once daily, consider a trial of metformin hydrochloride extended-release tablets 1,000 mg twice daily. If a dose of metformin hydrochloride extended-release tablets is missed, instruct patients not to take two doses the same day and to resume their usual dose of metformin hydrochloride extended-release tablets with the next schedule dose. …"},{"title":"ข้อห้ามใช้","body":"Metformin hydrochloride extended-release tablets are contraindicated in patients with: Severe renal impairment (eGFR below 30 mL/min/1.73 m 2 ) [see Warnings and Precautions (5.1) ] . Hypersensitivity to metformin. Acute or chronic metabolic acidosis, including diabetic ketoacidosis, with or without coma. Severe renal impairment (eGFR below 30 mL/min/1.73 m 2 ) ( 4 , 5.1 ) Hypersensitivity to metformin ( 4 ) Acute or chronic metabolic acidosis, including diabetic ketoacidosis, with or without coma. ( 4 )"},{"title":"คำเตือนกรอบดำ","body":"WARNING: LACTIC ACIDOSIS Postmarketing cases of metformin-associated lactic acidosis have resulted in death, hypothermia, hypotension, and resistant bradyarrhythmias. The onset of metformin-associated lactic acidosis is often subtle, accompanied only by nonspecific symptoms such as malaise, myalgias, respiratory distress, somnolence, and abdominal pain. Metformin-associated lactic acidosis was characterized by elevated blood lactate levels (> 5 mmol/Liter), anion gap acidosis (without evidence of ketonuria or ketonemia), an increased lactate/pyruvate ratio; and metformin plasma levels generally > 5 mcg/mL [see Warnings and Precautions (5.1) ]. Risk factors for metformin-associated lactic acidosis include renal impairment, concomitant use of certain drugs (e.g. carbonic anhydrase inhibitors such as topiramate), age 65 years old or greater, having a radiological study with contrast, surgery and other procedures, hypoxic states (e.g., acute congestive heart failure), excessive alcohol intake, and hepatic impairment. Steps to reduce the risk of and manage metformin-associated lactic acidosis in these high risk groups are provided [see Dosage and Administration (2.4) , Contraindications (4) , Warnings and Precautions (5.1) ] . If metformin-associated lactic acidosis is suspected, immediately discontinue metformin hydrochloride extended-release tablets and institute general supportive measures in a hospital setting. Prompt hemodialysis is recommended [see Warnings and Precautions (5.1) ]. WARNING: LACTIC ACIDOSIS See full prescribing information for complete boxed warning. Postmarketing cases of metformin-associated lactic acidosis have resulted in death, hypothermia, hypotension, and resistant bradyarrhythmias. Symptoms included malaise, myalgias, respiratory distress, somnolence, and abdominal pain. Laboratory abnormalities included elevated blood lactate levels, anion gap acidosis, increased lactate/pyruvate ratio; and metformin plasma levels generally > 5 mcg/mL. ( 5.1 ) Risk factors include renal impairment, concomitant use of certain drugs, age > 65 years old, radiological studies with contrast, surgery and other procedures, hypoxic states, excessive alcohol intake, and hepatic impairment. Steps to reduce the risk of and manage metforminassociated lactic acidosis in these high risk groups are provided in the Full Prescribing Information. …"},{"title":"คำเตือนและข้อควรระวัง","body":"Lactic Acidosis: See boxed warning . ( 5.1 ) Vitamin B 12 Deficiency: Metformin may lower vitamin B 12 levels. Measure hematological parameters annually and vitamin B 12 at 2 to 3 year intervals and manage any abnormalities. ( 5.2 ) Hypoglycemia with Concomitant Use with Insulin and Insulin Secretagogues: Increased risk of hypoglycemia when used in combination with insulin and/or an insulin secretagogue. Lower dose of insulin or insulin secretagogue may be required ( 5.3 ) 5.1 Lactic Acidosis There have been postmarketing cases of metformin-associated lactic acidosis, including fatal cases. These cases had a subtle onset and were accompanied by nonspecific symptoms such as malaise, myalgias, abdominal pain, respiratory distress, or increased somnolence; however, hypotension and resistant bradyarrhythmias have occurred with severe acidosis. Metforminassociated lactic acidosis was characterized by elevated blood lactate concentrations (> 5 mmol/L), anion gap acidosis (without evidence of ketonuria or ketonemia), and an increased lactate: pyruvate ratio; metformin plasma levels were generally > 5 mcg/mL. Metformin decreases liver uptake of lactate increasing lactate blood levels which may increase the risk of lactic acidosis, especially in patients at risk. If metformin-associated lactic acidosis is suspected, general supportive measures should be instituted promptly in a hospital setting, along with immediate discontinuation of metformin hydrochloride extended-release tablets. In metformin hydrochloride extended-release tablets treated patients with a diagnosis or strong suspicion of lactic acidosis, prompt hemodialysis is recommended to correct the acidosis and remove accumulated metformin (metformin hydrochloride is dialyzable with a clearance of up to 170 mL/min under good hemodynamic conditions). Hemodialysis has often resulted in reversal of symptoms and recovery. Educate patients and their families about the symptoms of lactic acidosis and, if these symptoms occur, instruct them to discontinue metformin hydrochloride extended-release tablets and report these symptoms to their healthcare provider. For each of the known and possible risk factors for metformin-associated lactic acidosis, recommendations to reduce the risk of and manage metformin-associated lactic acidosis are provided below: Renal impairment — The postmarketing metformin-associated lactic acidosis cases primarily occurred in patients with significant renal impairment. …"},{"title":"อาการไม่พึงประสงค์","body":"The following adverse reactions are also discussed elsewhere in the labeling: Lactic Acidosis [see Boxed Warning and Warnings and Precautions (5.1) ] Vitamin B 12 Deficiency [see Warnings and Precautions (5.2) ] Hypoglycemia [see Warnings and Precautions (5.3) ] For metformin hydrochloride extended-release tablets, the most common adverse reactions (> 5.0%) are diarrhea, nausea/vomiting, flatulence, asthenia, indigestion, abdominal discomfort, and headache. ( 6.1 ) To report SUSPECTED ADVERSE REACTIONS, contact Precision Dose, Inc. at 1-800-397-9228 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch 6.1 Clinical Studies Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical trials of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in practice. Metformin Hydrochloride Extended-Release Tablets In placebo-controlled trials, in adults with type 2 diabetes mellitus, 781 patients were administered metformin hydrochloride extended-release tablets. Adverse reactions reported in greater than 5% of the metformin hydrochloride extended-release tablets patients, and that were more common in metformin hydrochloride extended-release tablets - than placebo-treated patients, are listed in Table 1. Table 1: Adverse Reactions from Clinical Trials of Metformin Hydrochloride Extended-Release Tablets Occurring > 5% and More Common than Placebo in Adults with Type 2 Diabetes Mellitus Metformin Hydrochloride Extended-Release Tablets (n = 781) Placebo (n = 195) Diarrhea 10% 3% Nausea/Vomiting 7% 2% Diarrhea led to discontinuation of metformin hydrochloride extended-release tablets in 0.6% of patients. Additionally, the following adverse reactions were reported in ≥ 1.0% to ≤ 5.0% of metformin hydrochloride extended-release tablets patients and were more commonly reported with metformin hydrochloride extended-release tablets than placebo: abdominal pain, constipation, distention abdomen, dyspepsia/heartburn, flatulence, dizziness, headache, upper respiratory infection, taste disturbance. 6.2 Postmarketing Experience The following adverse reactions have been identified during post approval use of metformin. Because these reactions are reported voluntarily from a population of uncertain size, it is not always possible to reliably estimate their frequency or establish a causal relationship to drug exposure. …"},{"title":"Drug interaction","body":"Table 2 presents clinically significant drug interactions with metformin hydrochloride extended-release tablets. Table 2: Clinically Significant Drug Interactions with Metformin Hydrochloride Extended-Release Tablets Carbonic Anhydrase Inhibitors Clinical Impact: Carbonic anhydrase inhibitors frequently cause a decrease in serum bicarbonate and induce non-anion gap, hyperchloremic metabolic acidosis. Concomitant use of these drugs with metformin hydrochloride extended-release tablets may increase the risk for lactic acidosis. Intervention: Consider more frequent monitoring of these patients. Examples: Topiramate, zonisamide, acetazolamide or dichlorphenamide. Drugs that Reduce Metformin Hydrochloride Extended-Release Tablets Clearance Clinical Impact: Concomitant use of drugs that interfere with common renal tubular transport systems involved in the renal elimination of metformin (e.g., organic cationic transporter-2 [OCT2] / multidrug and toxin extrusion [MATE] inhibitors) could increase systemic exposure to metformin and may increase the risk for lactic acidosis [see Clinical Pharmacology (12.3) ]. Intervention: Consider the benefits and risks of concomitant use with metformin hydrochloride extended-release tablets. Examples: Ranolazine, vandetanib, dolutegravir, and cimetidine. Alcohol Clinical Impact: Alcohol is known to potentiate the effect of metformin on lactate metabolism. Intervention: Warn patients against excessive alcohol intake while receiving metformin hydrochloride extended-release tablets. Insulin Secretagogues or Insulin Clinical Impact: Coadministration of metformin hydrochloride extended-release tablets with an insulin secretagogue (e.g., sulfonylurea) or insulin may increase the risk of hypoglycemia. Intervention: Patients receiving an insulin secretagogue or insulin may require lower doses of the insulin secretagogue or insulin. Drugs Affecting Glycemic Control Clinical Impact: Certain drugs tend to produce hyperglycemia and may lead to loss of glycemic control. Intervention: When such drugs are administered to a patient receiving metformin hydrochloride extended-release tablets, observe the patient closely for loss of blood glucose control. When such drugs are withdrawn from a patient receiving metformin hydrochloride extended-release tablets, observe the patient closely for hypoglycemia. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Limited data with metformin hydrochloride extended-release tablets in pregnant women are not sufficient to determine a drug-associated risk for major birth defects or miscarriage. Published studies with metformin use during pregnancy have not reported a clear association with metformin and major birth defect or miscarriage risk [see Data ]. There are risks to the mother and fetus associated with poorly controlled diabetes mellitus in pregnancy [see Clinical Considerations ]. No adverse developmental effects were observed when metformin was administered to pregnant Sprague Dawley rats and rabbits during the period of organogenesis at doses up to 2- and 5-times, respectively, a 2,550 mg clinical dose, based on body surface area [see Data ]. The estimated background risk of major birth defects is 6% to 10% in women with pre-gestational diabetes mellitus with an HbA1C > 7 and has been reported to be as high as 20% to 25% in women with a HbA1C > 10. The estimated background risk of miscarriage for the indicated population is unknown. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2% to 4% and 15% to 20%, respectively. Clinical Considerations Disease-associated maternal and/or embryo/fetal risk Poorly-controlled diabetes mellitus in pregnancy increases the maternal risk for diabetic ketoacidosis, pre-eclampsia, spontaneous abortions, preterm delivery, stillbirth and delivery complications. Poorly controlled diabetes mellitus increases the fetal risk for major birth defects, stillbirth, and macrosomia related morbidity. Data Human Data Published data from post-marketing studies have not reported a clear association with metformin and major birth defects, miscarriage, or adverse maternal or fetal outcomes when metformin was used during pregnancy. However, these studies cannot definitely establish the absence of any metformin-associated risk because of methodological limitations, including small sample size and inconsistent comparator groups. Animal Data Metformin hydrochloride did not adversely affect development outcomes when administered to pregnant rats and rabbits at doses up to 600 mg/kg/day. This represents an exposure of about 2 and 5 times a 2,550 mg clinical dose based on body surface area comparisons for rats and rabbits, respectively. Determination of fetal concentrations demonstrated a partial placental barrier to metformin. …"},{"title":"การได้รับยาเกินขนาด","body":"In the event of an overdose with metformin hydrochloride extended-release tablets, consider contacting the Poison Help line (1-800-222-1222) or a medical toxicologist for additional overdosage management recommendations. Overdose of metformin hydrochloride has occurred, including ingestion of amounts greater than 50 grams. Hypoglycemia was reported in approximately 10% of cases, but no causal association with metformin has been established. Lactic acidosis has been reported in approximately 32% of metformin overdose cases [see Warnings and Precautions (5.1) ] . Metformin is dialyzable with a clearance of up to 170 mL/min under good hemodynamic conditions. Therefore, hemodialysis may be useful for removal of accumulated drug from patients in whom metformin overdosage is suspected."},{"title":"การเก็บรักษา","body":"16.2 Storage Store at 20° to 25°C (68° to 77°F); excursions permitted from 15° to 30°C (59° to 86°F). [See USP Controlled Room Temperature.] Dispense in light-resistant containers."}]},
{"key":"methyl salicylate|TOPICAL","generic":"methyl salicylate","route":"TOPICAL","brand":null,"title":"Methyl Salicylate 10%","set_id":"11a6d22a-1a7a-4c76-b873-fffd00ac4b54","effective":"20260428","sections":[{"title":"ข้อบ่งใช้","body":"Temporarily relieves aches & pains of muscles & joints associated with: Strains Sprains Simple Backache Arthritis Bruises"},{"title":"ขนาดยาและวิธีใช้","body":"Adults and Children 10 years of age and older: only use one patch at a time clean and dry affected area remove patch from backing film and apply to skin (see illustration) apply 1 patch to the affective area of intact skin up to 36 hours. do not use more than 2 patches per day do not use for more than 3 days in a row the used patch should be removed from the skin when a new one is applied"},{"title":"คำเตือนและข้อควรระวัง","body":"​For external use only Stomach bleeding warning: This product contains an NSAID, which may cause stomach bleeding. The chance is small but higher if you: are age 60 or older have had stomach ulcers or bleeding problems take a blood thinning (anticoagulant) or steroid drug take other drugs containing as NSAID (aspirin, ibuprofen, naproxen, or others) have 3 or more alcoholic drinks every day while using this product Do not use on the face or rashes on wounds or damaged skin if allergic to aspirin or other NSAIDs with a heating pad when sweating (such as from exercise or heat) any patch from a pouch that has been open for 14 or more days right before or after heat surgery Ask a doctor before use if you are allergic to topical products the stomach bleeding warning applies to you you are taking a diuretic you have high blood pressure, heart disease or kidney disease When using this product wash hands after applying or removing patch. Avoid contact with eyes. If eye contact occurs, rinse thoroughly with the water. the risk of heart attack or stroke may increase if you use more than directed or for longer than directed. Stop use and ask a doctor if stomach pain or upset gets worse or lasts you feel faint, vomit blood or have bloody or black stools, These are signs of stomach bleeding. rash, itching or skin irritation develops condition worsens symptoms last for more than 3 days symptoms clear up and occur again within a few days. If pregnant or breast-feeding, ask a doctor before use while breast-feeding and during the first 6 months of pregnancy. Do not use during the last 3 months of pregnancy because it may cause problems in the unborn child or complications during delivery. Keep out of reach of children. if put in mouth, get medical help or contact a Poison Control right away. Package not child resistant. Dispose of the used patches after folding sticky ends together. patch. Avoid contact with eyes. If eye contact occurs, rinse thoroughly with the water. the risk of heart attack or stroke may increase if you use more than directed or for longer than directed. faint, vomit blood or have bloody or black stools, These are signs of stomach bleeding. rash, itching or skin irritation develops condition worsens symptoms last for more than 3 days symptoms clear up and occur again within a few days."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"ask a doctor before use while breast-feeding and during the first 6 months of pregnancy. Do not use during the last 3 months of pregnancy because it may cause problems in the unborn child or complications during delivery."},{"title":"การเก็บรักษา","body":"Other information Store at 20-25°C (68-77°F) Avoid storing product in direct sunlight Protect product from excessive moisture Some individuals may not experience pain relief until several hours after applying the patch"}]},
{"key":"methyldopa|ORAL","generic":"methyldopa","route":"ORAL","brand":null,"title":"Methyldopa","set_id":"9e22e1d8-04ec-4b67-92ea-b09c706f2703","effective":"20250328","sections":[{"title":"ข้อบ่งใช้","body":"Hypertension."},{"title":"ขนาดยาและวิธีใช้","body":"Adults : Initiation of Therapy : The usual starting dosage of methyldopa tablets is 250 mg two to three times a day in the first 48 hours. The daily dosage then may be increased or decreased, preferably at intervals of not less than 2 days, until an adequate response is achieved. To minimize the sedation, start dosage increases in the evening. By adjustment of dosage, morning hypotension may be prevented without sacrificing control of afternoon blood pressure. When methyldopa tablets are given to patients on other antihypertensives, the dose of these agents may need to be adjusted to effect a smooth transition. When methyldopa tablets are given with anti-hypertensives other than thiazides, the initial dosage of methyldopa tablets should be limited to 500 mg daily in divided doses; when methyldopa tablets are added to a thiazide, the dosage of thiazide need not be changed. Maintenance of Therapy : The usual daily dosage of methyldopa tablets is 500 mg to 2 g in two to four doses. Although occasional patients have responded to higher doses, the maximum recommended daily dosage is 3 g. Once an effective dosage range is attained, a smooth blood pressure response occurs in most patients in 12 to 24 hours. Since methyldopa has a relatively short duration of action, withdrawal is followed by return of hypertension usually within 48 hours. This is not complicated by an overshoot of blood pressure. Occasionally tolerance may occur, usually between the second and third month of therapy. Adding a diuretic or increasing the dosage of methyldopa frequently will restore effective control of blood pressure. A thiazide may be added at any time during methyldopa therapy and is recommended if therapy has not been started with a thiazide or if effective control of blood pressure cannot be maintained on 2 g of methyldopa daily. Methyldopa is largely excreted by the kidney and patients with impaired renal function may respond to smaller doses. Syncope in older patients may be related to an increased sensitivity and advanced arteriosclerotic vascular disease. This may be avoided by lower doses. Pediatric Patients : Initial dosage is based on 10 mg/kg of body weight daily in two to four doses. The daily dosage then is increased or decreased until an adequate response is achieved. The maximum dosage is 65 mg/kg or 3 g daily, whichever is less. (See PRECAUTIONS: Pediatric Use .)"},{"title":"ข้อห้ามใช้","body":"Methyldopa is contraindicated in patients: – with active hepatic disease, such as acute hepatitis and active cirrhosis. – with liver disorders previously associated with methyldopa therapy (see WARNINGS ). – with hypersensitivity to any component of this product. – on therapy with monoamine oxidase (MAO) inhibitors."},{"title":"คำเตือนและข้อควรระวัง","body":"It is important to recognize that a positive Coombs test, hemolytic anemia, and liver disorders may occur with methyldopa therapy. The rare occurrences of hemolytic anemia or liver disorders could lead to potentially fatal complications unless properly recognized and managed. Read this section carefully to understand these reactions. With prolonged methyldopa therapy, 10% to 20% of patients develop a positive direct Coombs test which usually occurs between 6 and 12 months of methyldopa therapy. Lowest incidence is at daily dosage of 1 g or less. This on rare occasions may be associated with hemolytic anemia, which could lead to potentially fatal complications. One cannot predict which patients with a positive direct Coombs test may develop hemolytic anemia. Prior existence or development of a positive direct Coombs test is not in itself a contraindication to use of methyldopa. If a positive Coombs test develops during methyldopa therapy, the physician should determine whether hemolytic anemia exists and whether the positive Coombs test may be a problem. For example, in addition to a positive direct Coombs test there is less often a positive indirect Coombs test which may interfere with cross matching of blood. Before treatment is started, it is desirable to do a blood count (hematocrit, hemoglobin, or red cell count) for a baseline or to establish whether there is anemia. Periodic blood counts should be done during therapy to detect hemolytic anemia. It may be useful to do a direct Coombs test before therapy and at 6 and 12 months after the start of therapy. If Coombs-positive hemolytic anemia occurs, the cause may be methyldopa and the drug should be discontinued. Usually the anemia remits promptly. If not, corticosteroids may be given and other causes of anemia should be considered. If the hemolytic anemia is related to methyldopa, the drug should not be reinstituted. When methyldopa causes Coombs positivity alone or with hemolytic anemia, the red cell is usually coated with gamma globulin of the lgG (gamma G) class only. The positive Coombs test may not revert to normal until weeks to months after methyldopa is stopped. Should the need for transfusion arise in a patient receiving methyldopa, both a direct and an indirect Coombs test should be performed. In the absence of hemolytic anemia, usually only the direct Coombs test will be positive. A positive direct Coombs test alone will not interfere with typing or cross matching. …"},{"title":"อาการไม่พึงประสงค์","body":"Sedation, usually transient, may occur during the initial period of therapy or whenever the dose is increased. Headache, asthenia, or weakness may be noted as early and transient symptoms. However, significant adverse effects due to methyldopa have been infrequent and this agent usually is well tolerated. The following adverse reactions have been reported and, within each category, are listed in order of decreasing severity. Cardiovascular : Aggravation of angina pectoris, congestive heart failure, prolonged carotid sinus hypersensitivity, orthostatic hypotension (decrease daily dosage), edema or weight gain, bradycardia. Digestive : Pancreatitis, colitis, vomiting, diarrhea, sialadenitis, sore or “black” tongue, nausea, constipation, distension, flatus, dryness of mouth. Endocrine : Hyperprolactinemia. Hematologic : Bone marrow depression, leukopenia, granulocytopenia, thrombocytopenia, hemolytic anemia; positive tests for antinuclear antibody, LE cells, and rheumatoid factor, positive Coombs test. Hepatic : Liver disorders including hepatitis, jaundice, abnormal liver function tests (see WARNINGS ). Hypersensitivity : Myocarditis, pericarditis, vasculitis, lupus-like syndrome, drug-related fever, eosinophilia. Nervous System/Psychiatric : Parkinsonism, Bell’s palsy, decreased mental acuity, involuntary choreoathetotic movements, symptoms of cerebrovascular insufficiency, psychic disturbances including nightmares and reversible mild psychoses or depression, headache, sedation, asthenia or weakness, dizziness, light-headedness, paresthesias. Metabolic : Rise in BUN. Musculoskeletal : Arthralgia, with or without joint swelling; myalgia. Respiratory : Nasal stuffiness. Skin : Toxic epidermal necrolysis, rash. Urogenital : Amenorrhea, breast enlargement, gynecomastia, lactation, impotence, decreased libido. To report SUSPECTED ADVERSE REACTIONS, contact Rising Pharma Holdings, Inc. at 1-844-874-7464 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch."},{"title":"Drug interaction","body":"When methyldopa is used with other antihypertensive drugs, potentiation of antihypertensive effect may occur. Patients should be followed carefully to detect side reactions or unusual manifestations of drug idiosyncrasy. Patients may require reduced doses of anesthetics when on methyldopa. If hypotension does occur during anesthesia, it usually can be controlled by vasopressors. The adrenergic receptors remain sensitive during treatment with methyldopa. When methyldopa and lithium are given concomitantly, the patient should be carefully monitored for symptoms of lithium toxicity. Read the circular for lithium preparations. Several studies demonstrate a decrease in the bioavailability of methyldopa when it is ingested with ferrous sulfate or ferrous gluconate. This may adversely affect blood pressure control in patients treated with methyldopa. Coadministration of methyldopa with ferrous sulfate or ferrous gluconate is not recommended. Monoamine oxidase (MAO) inhibitors: See CONTRAINDICATIONS ."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Teratogenic Effects . Reproduction studies performed with methyldopa at oral doses up to 1000 mg/kg in mice, 200 mg/kg in rabbits and 100 mg/kg in rats revealed no evidence of harm to the fetus. These doses are 16.6 times, 3.3 times and 1.7 times, respectively, the maximum daily human dose when compared on the basis of body weight; 1.4 times, 1.1 times and 0.2 times, respectively, when compared on the basis of body surface area; calculations assume a patient weight of 50 kg. There are, however, no adequate and well-controlled studies in pregnant women in the first trimester of pregnancy. Because animal reproduction studies are not always predictive of human response, methyldopa should be used during pregnancy only if clearly needed. Published reports of the use of methyldopa during all trimesters indicate that if this drug is used during pregnancy the possibility of fetal harm appears remote. In five studies, three of which were controlled, involving 332 pregnant hypertensive women, treatment with methyldopa was associated with an improved fetal outcome. The majority of these women were in the third trimester when methyldopa therapy was begun. In one study, women who had begun methyldopa treatment between weeks 16 and 20 of pregnancy gave birth to infants whose average head circumference was reduced by a small amount (34.2 ± 1.7 cm vs. 34.6 ± 1.3 cm [mean ± 1 S.D.]). Long-term follow-up of 195 (97.5%) of the children born to methyldopa-treated pregnant women (including those who began treatment between weeks 16 and 20) failed to uncover any significant adverse effect on the children. At 4 years of age, the developmental delay commonly seen in children born to hypertensive mothers was less evident in those whose mothers were treated with methyldopa during pregnancy than those whose mothers were untreated. The children of the treated group scored consistently higher than the children of the untreated group on five major indices of intellectual and motor development. At age 7 and one-half, developmental scores and intelligence indices showed no significant differences in children of treated or untreated hypertensive women. Methyldopa appears in breast milk. Therefore, caution should be exercised when methyldopa is given to a nursing woman. There are no well-controlled clinical trials in pediatric patients. …"},{"title":"การได้รับยาเกินขนาด","body":"Acute overdosage may produce acute hypotension with other responses attributable to brain and gastrointestinal malfunction (excessive sedation, weakness, bradycardia, dizziness, light-headedness, constipation, distention, flatus, diarrhea, nausea, vomiting). In the event of overdosage, symptomatic and supportive measures should be employed. When ingestion is recent, gastric lavage or emesis may reduce absorption. When ingestion has been earlier, infusions may be helpful to promote urinary excretion. Otherwise, management includes special attention to cardiac rate and output, blood volume, electrolyte balance, paralytic ileus, urinary function and cerebral activity. Sympathomimetic drugs [e.g., levarterenol, epinephrine, ARAMINE ®† (Metaraminol Bitartrate)] may be indicated. Methyldopa is dialyzable. The oral LD 50 of methyldopa is greater than 1.5 g/kg in both the mouse and the rat."}]},
{"key":"metoprolol tartrate|ORAL","generic":"metoprolol tartrate","route":"ORAL","brand":null,"title":"Metoprolol Tartrate","set_id":"028b6e4a-1597-4d21-89d0-0bbbad21efa8","effective":"20260727","sections":[{"title":"ข้อบ่งใช้","body":"Metoprolol tartrate tablets are a beta-adrenergic blocker indicated for the treatment of: Hypertension, to lower blood pressure. Lowering blood pressure reduces the risk of fatal and non-fatal cardiovascular events, primarily strokes and myocardial infarctions. ( 1.1 ) Angina Pectoris. ( 1.2 ) Myocardial Infarction, to reduce the risk of cardiovascular mortality when used in conjunction with intravenous metoprolol therapy in patients with definite or suspected acute myocardial infarction in hemodynamically stable patients. ( 1.3 ) 1.1 Hypertension Metoprolol tartrate tablets are indicated for the treatment of hypertension in adult patients, to lower blood pressure. Lowering blood pressure lowers the risk of fatal and non-fatal cardiovascular events, primarily strokes and myocardial infarctions. These benefits have been seen in controlled trials of antihypertensive drugs from a wide variety of pharmacologic classes including metoprolol. Control of high blood pressure should be part of comprehensive cardiovascular risk management, including, as appropriate, lipid control, diabetes management, antithrombotic therapy, smoking cessation, exercise, and limited sodium intake. Many patients will require more than 1 drug to achieve blood pressure goals. For specific advice on goals and management, see published guidelines, such as those of the National High Blood Pressure Education Program’s Joint National Committee on Prevention, Detection, Evaluation, and Treatment of High Blood Pressure (JNC). Numerous antihypertensive drugs, from a variety of pharmacologic classes and with different mechanisms of action, have been shown in randomized controlled trials to reduce cardiovascular morbidity and mortality, and it can be concluded that it is blood pressure reduction, and not some other pharmacologic property of the drugs, that is largely responsible for those benefits. The largest and most consistent cardiovascular outcome benefit has been a reduction in the risk of stroke, but reductions in myocardial infarction and cardiovascular mortality also have been seen regularly. Elevated systolic or diastolic pressure causes increased cardiovascular risk, and the absolute risk increase per mmHg is greater at higher blood pressures, so that even modest reductions of severe hypertension can provide substantial benefit. …"},{"title":"ขนาดยาและวิธีใช้","body":"Administer once daily with food or after a meal. Titrate at weekly or longer intervals as needed and tolerated. ( 2 ) Hypertension: Recommended starting dosage is 100 mg daily, in single or divided doses. ( 2.1 ) Angina Pectoris: Recommended starting dosage is 100 mg daily, given as two divided doses. ( 2.2 ) Myocardial Infarction: The starting dosage depends upon tolerance of intravenous metoprolol, see full prescribing information. ( 2.3 ) 2.1 Hypertension Individualize the dosage of metoprolol tartrate tablets. Metoprolol tartrate tablets should be taken with or immediately following meals. The usual initial dosage is 100 mg daily in single or divided doses. Adjust dosage at weekly (or longer) intervals until optimum blood pressure reduction is achieved. In general, the maximum effect of any given dosage level will be apparent after 1 week of therapy. The effective dosage range of metoprolol tartrate tablets is 100 mg to 450 mg per day. Dosages above 450 mg per day have not been studied. While once-daily dosing can maintain a reduction in blood pressure throughout the day, lower doses (especially 100 mg) may not maintain a full effect at the end of the 24-hour period. Larger or more frequent daily doses may be required. Measure blood pressure near the end of the dosing interval to determine whether satisfactory control is being maintained throughout the day. 2.2 Angina Pectoris The dosage of metoprolol tartrate tablets should be individualized. Metoprolol tartrate tablets should be taken with or immediately following meals. The usual initial dosage is 100 mg daily, given in two divided doses. Gradually increase the dosage at weekly intervals until optimum clinical response has been obtained or there is a pronounced slowing of the heart rate. The effective dosage range of metoprolol tartrate tablets is 100 to 400 mg per day. Dosages above 400 mg per day have not been studied. If treatment is to be discontinued, reduce the dosage gradually over a period of 1 to 2 weeks [see Warnings and Precautions (5.1) ]. 2.3 Myocardial Infarction See prescribing information of intravenous metoprolol for dosage instructions for intravenous therapy. In patients who tolerate the full intravenous dose, initiate metoprolol tartrate tablets, 50 mg every 6 hours, 15 minutes after the last intravenous dose of metoprolol and continue for 48 hours. In the case of intolerance, reduce dose to 25 mg and administer for 48 hours. …"},{"title":"ข้อห้ามใช้","body":"Metoprolol tartrate tablets are contraindicated in severe bradycardia, second- or third-degree heart block, cardiogenic shock, systolic blood pressure <100, decompensated heart failure, sick sinus syndrome (unless a permanent pacemaker is in place), and in patients who are hypersensitive to any component of this product. Known hypersensitivity to product components. ( 4 ) Severe bradycardia: Greater than first degree heart block, or sick sinus syndrome without a pacemaker. ( 4 ) Cardiogenic shock or decompensated heart failure. ( 4 )"},{"title":"คำเตือนและข้อควรระวัง","body":"Abrupt cessation may exacerbate myocardial ischemia. ( 5.1 ) Heart Failure: Worsening cardiac failure may occur. ( 5.2 ) Bronchospastic Disease: Avoid beta-blockers. ( 5.3 ) Pheochromocytoma: Initiate therapy with an alpha blocker. ( 5.4 ) Major Surgery: Avoid initiation of high-dose extended-release metoprolol in patients undergoing non-cardiac surgery. Do not routinely withdraw chronic beta-blocker therapy prior to surgery. ( 5.5 , 6.1 ) Diabetes: May mask symptoms of hypoglycemia. ( 5.6 ) Thyrotoxicosis: Abrupt withdrawal in patients with thyrotoxicosis might precipitate a thyroid storm. ( 5.7 ) Peripheral Vascular Disease: Can aggravate symptoms of arterial insufficiency. ( 5.9 ) 5.1 Abrupt Cessation of Therapy Following abrupt cessation of therapy with certain beta-blocking agents, exacerbations of angina pectoris and, in some cases, myocardial infarction have occurred. When discontinuing chronically administered metoprolol, particularly in patients with ischemic heart disease, gradually reduce the dosage over a period of 1 to 2 weeks and monitor the patient. If angina markedly worsens or acute coronary ischemia develops, promptly reinstate metoprolol, and take measures appropriate for the management of unstable angina. Warn patients not to interrupt therapy without their physician’s advice. Because coronary artery disease is common and may be unrecognized, avoid abruptly discontinuing metoprolol in patients treated only for hypertension. 5.2 Heart Failure Worsening cardiac failure may occur during up-titration of metoprolol. If such symptoms occur, increase diuretics and restore clinical stability before advancing the dose of metoprolol [see Dosage and Administration (2) ]. It may be necessary to lower the dose of metoprolol or temporarily discontinue it. Such episodes do not preclude subsequent successful titration of metoprolol. 5.3 Bronchospastic Disease Patients with bronchospastic disease, should in general, not receive beta-blockers, including metoprolol. Because of its relative beta 1 cardio-selectivity, however, metoprolol may be used in patients with bronchospastic disease who do not respond to, or cannot tolerate, other antihypertensive treatment. Because beta 1 -selectivity is not absolute, use the lowest possible dose of metoprolol. Bronchodilators, including beta 2 -agonists, should be readily available or administered concomitantly [see Dosage and Administration (2) ]. …"},{"title":"อาการไม่พึงประสงค์","body":"The following adverse reactions are described elsewhere in labeling: Worsening angina or myocardial infarction [see Warnings and Precautions (5) ] Worsening heart failure [see Warnings and Precautions (5) ]. Worsening AV block [see Contraindications (4) ]. ­Most common adverse reactions: tiredness, dizziness, depression, shortness of breath, bradycardia, hypotension, diarrhea, pruritus, rash. ( 6.1 ) To report SUSPECTED ADVERSE REACTIONS, contact Aurobindo Pharma USA, Inc. at 1-866-850-2876 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch. 6.1 Clinical Trials Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical trials of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in practice. Hypertension and Angina Most adverse effects have been mild and transient. Central Nervous System: Tiredness and dizziness have occurred in about 10% of patients. Depression has been reported in about 5 of 100 patients. Mental confusion and short-term memory loss have been reported. Headache, nightmares, and insomnia have also been reported. Cardiovascular: Shortness of breath and bradycardia have occurred in approximately 3% of patients. Cold extremities; arterial insufficiency, usually of the Raynaud type; palpitations; heart failure exacerbations; peripheral edema; and hypotension have been reported in about 1% of patients. Gangrene in patients with pre-existing severe peripheral circulatory disorders has also been reported. [see Contraindications (4) and Warnings and Precautions (5.2) ]. Respiratory: Wheezing (bronchospasm) and dyspnea have been reported in about 1% of patients [see Warnings and Precautions (5.3) ] . Rhinitis has also been reported. Gastrointestinal: Diarrhea has occurred in about 5% of patients. Nausea, dry mouth, gastric pain, constipation, flatulence, and heartburn have been reported in about 1% of patients. Vomiting was a common occurrence. Hypersensitive Reactions: Pruritus or rash have occurred in about 5% of patients. Photosensitivity and worsening of psoriasis has been reported. Miscellaneous: Peyronie’s disease, musculoskeletal pain, blurred vision, and tinnitus has been reported. Myocardial Infarction In general, the adverse reactions observed in trials with metoprolol in MI are consistent with the hypertension and angina experience. …"},{"title":"Drug interaction","body":"Catecholamine-depleting drugs may have an additive effect when given with beta-blocking agents. ( 7.1 ) Patients may be unresponsive to the usual doses of epinephrine used to treat allergic reaction. ( 7.2 ) CYP2D6 Inhibitors are likely to increase metoprolol concentration. ( 7.3 ) Concomitant use of glycosides, clonidine, and diltiazem and verapamil with beta-blockers can increase the risk of bradycardia. ( 7.4 ) Beta-blockers including metoprolol, may exacerbate the rebound hypertension that can follow the withdrawal of clonidine. ( 7.4 ) 7.1 Catecholamine Depleting Drugs Catecholamine depleting drugs (e.g., reserpine, monoamine oxidase (MAO) inhibitors) may have an additive effect when given with beta-blocking agents. Observe patients treated with metoprolol plus a catecholamine depletor for evidence of hypotension or marked bradycardia, which may produce vertigo, syncope, or postural hypotension. 7.2 Epinephrine While taking beta-blockers, patients with a history of severe anaphylactic reactions to a variety of allergens may be more reactive to repeated challenge and may be unresponsive to the usual doses of epinephrine used to treat an allergic reaction. 7.3 CYP2D6 Inhibitors Drugs that are strong inhibitors of CYP2D6 such as quinidine, fluoxetine, paroxetine, and propafenone were shown to double metoprolol concentrations. While there is no information about moderate or weak inhibitors, these too are likely to increase metoprolol concentration. Increases in plasma concentration decrease the cardioselectivity of metoprolol [see Clinical Pharmacology (12.3) ]. Monitor patients closely, when the combination cannot be avoided. 7.4 Negative Chronotropes Digitalis glycosides, clonidine, diltiazem and verapamil slow atrioventricular conduction and decrease heart rate. Concomitant use with beta-blockers can increase the risk of bradycardia. If clonidine and a beta-blocker, such as metoprolol are coadministered, withdraw the beta-blocker several days before the gradual withdrawal of clonidine because beta-blockers may exacerbate the rebound hypertension that can follow the withdrawal of clonidine. If replacing clonidine by beta-blocker therapy, delay the introduction of beta-blockers for several days after clonidine administration has stopped ."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Available data from published observational studies have not demonstrated an association of adverse developmental outcomes with maternal use of metoprolol during pregnancy ( see Data). Untreated hypertension and myocardial infarction during pregnancy can lead to adverse outcomes for the mother and the fetus (see Clinical Considerations). In animal reproduction studies, metoprolol has been shown to increase post-implantation loss and decrease neonatal survival in rats at oral dosages of 500 mg/kg/day, approximately 11 times the daily dose of 450 mg in a 60-kg patient on a mg/m 2 basis. All pregnancies have a background risk of birth defect, loss, or other adverse outcomes. The estimated background risk of major birth defects and miscarriage for the indicated population is unknown. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2 to 4% and 15 to 20%, respectively. Clinical consideration Disease-associated maternal and/or embryo/fetal risk Hypertension in pregnancy increases the maternal risk for pre-eclampsia, gestational diabetes, premature delivery, and delivery complications (e.g., need for cesarean section, and post-partum hemorrhage). Hypertension increases the fetal risk for intrauterine growth restriction and intrauterine death. Pregnant women with hypertension should be carefully monitored and managed accordingly. Fetal/Neonatal adverse reactions Metoprolol crosses the placenta. Neonates born to mothers who are receiving metoprolol during pregnancy, may be at risk for hypotension, hypoglycemia, bradycardia, and respiratory depression. Observe neonates and manage accordingly. Data Human Data Data from published observational studies did not demonstrate an association of major congenital malformations and use of metoprolol in pregnancy. The published literature has reported inconsistent findings of intrauterine growth retardation, preterm birth and perinatal mortality with maternal use of metoprolol during pregnancy; however, these studies have methodological limitations hindering interpretation. Methodological limitations include retrospective design, concomitant use of other medications, and other unadjusted confounders that may account for the study findings including the underlying disease in the mother. These observational studies cannot definitely establish or exclude any drug-associated risk during pregnancy. …"},{"title":"การได้รับยาเกินขนาด","body":"Signs and Symptoms - Overdosage of metoprolol may lead to severe bradycardia, hypotension, and cardiogenic shock. Clinical presentation can also include: atrioventricular block, heart failure, bronchospasm, hypoxia, impairment of consciousness/coma, nausea and vomiting. Treatment – Consider treating the patient with intensive care. Patients with myocardial infarction or heart failure may be prone to significant hemodynamic instability. Beta-blocker overdose may result in significant resistance to resuscitation with adrenergic agents, including beta-agonists. On the basis of the pharmacologic actions of metoprolol, employ the following measures. Hemodialysis is unlikely to make a useful contribution to metoprolol elimination [see Clinical Pharmacology (12.3) ]. Bradycardia: Evaluate the need for atropine, adrenergic-stimulating drugs or pacemaker to treat bradycardia and conduction disorders. Hypotension: Treat underlying bradycardia. Consider intravenous vasopressor infusion, such as dopamine or norepinephrine. Heart failure and shock: May be treated when appropriate with suitable volume expansion, injection of glucagon (if necessary, followed by an intravenous infusion of glucagon), intravenous administration of adrenergic drugs such as dobutamine, with α 1 receptor agonistic drugs added in presence of vasodilation. Bronchospasm: Can usually be reversed by bronchodilators."}]},
{"key":"metronidazole|ORAL","generic":"metronidazole","route":"ORAL","brand":null,"title":"Metronidazole","set_id":"4e1ac737-c353-4764-bd35-dc844e75b562","effective":"20260610","sections":[{"title":"ข้อบ่งใช้","body":"Symptomatic Trichomoniasis. Metronidazole tablets are indicated for the treatment of T. vaginalis infection in females and males when the presence of the trichomonad has been confirmed by appropriate laboratory procedures (wet smears and/or cultures). Asymptomatic Trichomoniasis . Metronidazole tablets are indicated in the treatment of asymptomatic T. vaginalis infection in females when the organism is associated with endocervicitis, cervicitis, or cervical erosion. Since there is evidence that presence of the trichomonad can interfere with accurate assessment of abnormal cytological smears, additional smears should be performed after eradication of the parasite. Treatment of Asymptomatic Sexual Partners. T. vaginalis infection is a venereal disease. Therefore, asymptomatic sexual partners of treated patients should be treated simultaneously if the organism has been found to be present, in order to prevent reinfection of the partner. The decision as to whether to treat an asymptomatic male partner who has a negative culture or one for whom no culture has been attempted is an individual one. In making this decision, it should be noted that there is evidence that a woman may become reinfected if her sexual partner is not treated. Also, since there can be considerable difficulty in isolating the organism from the asymptomatic male carrier, negative smears and cultures cannot be relied upon in this regard. In any event, the sexual partner should be treated with metronidazole tablets in cases of reinfection. Amebiasis. Metronidazole tablets are indicated in the treatment of acute intestinal amebiasis (amebic dysentery) and amebic liver abscess. In amebic liver abscess, metronidazole tablet therapy does not obviate the need for aspiration or drainage of pus. Anaerobic Bacterial Infections. Metronidazole tablets are indicated in the treatment of serious infections caused by susceptible anaerobic bacteria. Indicated surgical procedures should be performed in conjunction with metronidazole tablet therapy. In a mixed aerobic and anaerobic infection, antimicrobials appropriate for the treatment of the aerobic infection should be used in addition to metronidazole tablets. INTRA-ABDOMINAL INFECTIONS, including peritonitis, intra-abdominal abscess, and liver abscess, caused by Bacteroides species including the B. fragilis group (B. fragilis, B. distasonis, B. ovatus, B. thetaiotaomicron, B. …"},{"title":"ขนาดยาและวิธีใช้","body":"Trichomoniasis: In the Female: One-day treatment − two grams of metronidazole tablets, given either as a single dose or in two divided doses of one gram each, given in the same day. Seven-day course of treatment - 250 mg three times daily for seven consecutive days. There is some indication from controlled comparative studies that cure rates as determined by vaginal smears and signs and symptoms, may be higher after a seven-day course of treatment than after a one-day treatment regimen. The dosage regimen should be individualized. Single-dose treatment can assure compliance, especially if administered under supervision, in those patients who cannot be relied on to continue the seven-day regimen. A seven-day course of treatment may minimize reinfection by protecting the patient long enough for the sexual contacts to obtain appropriate treatment. Further, some patients may tolerate one treatment regimen better than the other. Pregnant patients should not be treated during the first trimester (see CONTRAINDICATIONS ). In pregnant patients for whom alternative treatment has been inadequate, the one-day course of therapy should not be used, as it results in higher serum levels which can reach the fetal circulation (see PRECAUTIONS , Pregnancy ). When repeat courses of the drug are required, it is recommended that an interval of four to six weeks elapse between courses and that the presence of the trichomonad be reconfirmed by appropriate laboratory measures. Total and differential leukocyte counts should be made before and after re-treatment. In the Male: Treatment should be individualized as it is for the female. Amebiasis Adults: For acute intestinal amebiasis (acute amebic dysentery): 750 mg orally three times daily for 5 to 10 days. For amebic liver abscess: 500 mg or 750 mg orally three times daily for 5 to 10 days. Pediatric patients: 35 to 50 mg/kg/24 hours, divided into three doses, orally for 10 days. Anaerobic Bacterial Infections In the treatment of most serious anaerobic infections, intravenous metronidazole is usually administered initially. The usual adult oral dosage is 7.5 mg/kg every six hours (approx. 500 mg for a 70-kg adult). A maximum of 4 g should not be exceeded during a 24-hour period. The usual duration of therapy is 7 to 10 days; however, infections of the bone and joint, lower respiratory tract, and endocardium may require longer treatment. …"},{"title":"ข้อห้ามใช้","body":"Hypersensitivity Metronidazole tablets are contraindicated in patients with a prior history of hypersensitivity to metronidazole or other nitroimidazole derivatives. In patients with trichomoniasis, metronidazole tablets are contraindicated during the first trimester of pregnancy (see PRECAUTIONS ). Psychotic Reaction with Disulfiram Use of oral metronidazole is associated with psychotic reactions in alcoholic patients who were using disulfiram concurrently. Do not administer metronidazole to patients who have taken disulfiram within the last two weeks (see PRECAUTIONS , Drug Interactions ). Interaction with Alcohol Use of oral metronidazole is associated with a disulfiram-like reaction to alcohol, including abdominal cramps, nausea, vomiting, headaches, and flushing. Discontinue consumption of alcohol or products containing propylene glycol during and for at least three days after therapy with metronidazole (see PRECAUTIONS , Drug Interactions ). Cockayne Syndrome Metronidazole Tablets are contraindicated in patients with Cockayne syndrome. Severe irreversible hepatotoxicity/acute liver failure with fatal outcomes have been reported after initiation of metronidazole in patients with Cockayne syndrome (see ADVERSE REACTIONS ). Hypersensitivity Metronidazole tablets are contraindicated in patients with a prior history of hypersensitivity to metronidazole or other nitroimidazole derivatives. In patients with trichomoniasis, metronidazole tablets are contraindicated during the first trimester of pregnancy (see PRECAUTIONS ). Psychotic Reaction with Disulfiram Use of oral metronidazole is associated with psychotic reactions in alcoholic patients who were using disulfiram concurrently. Do not administer metronidazole to patients who have taken disulfiram within the last two weeks (see PRECAUTIONS , Drug Interactions ). Interaction with Alcohol Use of oral metronidazole is associated with a disulfiram-like reaction to alcohol, including abdominal cramps, nausea, vomiting, headaches, and flushing. Discontinue consumption of alcohol or products containing propylene glycol during and for at least three days after therapy with metronidazole (see PRECAUTIONS , Drug Interactions ). Cockayne Syndrome Metronidazole Tablets are contraindicated in patients with Cockayne syndrome. Severe irreversible hepatotoxicity/acute liver failure with fatal outcomes have been reported after initiation of metronidazole in patients with Cockayne syndrome (see ADVERSE REACTIONS )."},{"title":"คำเตือนกรอบดำ","body":"WARNING Metronidazole has been shown to be carcinogenic in mice and rats (See PRECAUTIONS ). Unnecessary use of the drug should be avoided. Its use should be reserved for the conditions described in the INDICATIONS AND USAGE section below."},{"title":"คำเตือนและข้อควรระวัง","body":"Hypersensitivity Reactions Hypersensitivity reactions including severe cutaneous adverse reactions (SCARs) can be serious and potentially life threatening (see ADVERSE REACTIONS ). Severe Cutaneous Adverse Reactions Severe cutaneous adverse reactions (SCARs) including toxic epidermal necrolysis (TEN), Stevens-Johnson syndrome (SJS), drug reaction with eosinophilia and systemic symptoms (DRESS), and acute generalized exanthematous pustulosis (AGEP) have been reported with the use of metronidazole. Symptoms can be serious and potentially life threatening. If symptoms or signs of SCARs develop, discontinue metronidazole immediately and institute appropriate therapy. Central and Peripheral Nervous System Effects Encephalopathy and peripheral neuropathy: Cases of encephalopathy and peripheral neuropathy (including optic neuropathy) have been reported with metronidazole. Encephalopathy has been reported in association with cerebellar toxicity characterized by ataxia, dizziness, and dysarthria. CNS lesions seen on MRI have been described in reports of encephalopathy. CNS symptoms are generally reversible within days to weeks upon discontinuation of metronidazole. CNS lesions seen on MRI have also been described as reversible. Peripheral neuropathy, mainly of sensory type has been reported and is characterized by numbness or paresthesia of an extremity. Convulsive seizures have been reported in patients treated with metronidazole. Aseptic meningitis: Cases of aseptic meningitis have been reported with metronidazole. Symptoms can occur within hours of dose administration and generally resolve after metronidazole therapy is discontinued. The appearance of abnormal neurologic signs and symptoms demands the prompt evaluation of the benefit/risk ratio of the continuation of therapy (see ADVERSE REACTIONS ). Central and Peripheral Nervous System Effects Encephalopathy and peripheral neuropathy: Cases of encephalopathy and peripheral neuropathy (including optic neuropathy) have been reported with metronidazole. Encephalopathy has been reported in association with cerebellar toxicity characterized by ataxia, dizziness, and dysarthria. CNS lesions seen on MRI have been described in reports of encephalopathy. CNS symptoms are generally reversible within days to weeks upon discontinuation of metronidazole. CNS lesions seen on MRI have also been described as reversible. …"},{"title":"อาการไม่พึงประสงค์","body":"The following reactions have been reported during treatment with metronidazole: Central Nervous System: The most serious adverse reactions reported in patients treated with metronidazole have been convulsive seizures, encephalopathy, aseptic meningitis, optic and peripheral neuropathy, the latter characterized mainly by numbness or paresthesia of an extremity. Since persistent peripheral neuropathy has been reported in some patients receiving prolonged administration of metronidazole, patients should be specifically warned about these reactions and should be told to stop the drug and report immediately to their physicians if any neurologic symptoms occur. In addition, patients have reported headache, syncope, dizziness, vertigo, incoordination, ataxia, tinnitus, hearing impairment, hearing loss, confusion, dysarthria, irritability, depression, weakness, and insomnia (see WARNINGS ). Gastrointestinal: The most common adverse reactions reported have been referable to the gastrointestinal tract, particularly nausea, sometimes accompanied by headache, anorexia, and occasionally vomiting; diarrhea; epigastric distress; and abdominal cramping and constipation. Mouth : A sharp, unpleasant metallic taste is not unusual. Furry tongue, glossitis, and stomatitis have occurred; these may be associated with a sudden overgrowth of Candida which may occur during therapy. Dermatologic: Dermatitis bullous, fixed drug eruption, erythematous rash and pruritus. Hematopoietic : Reversible neutropenia (leukopenia); rarely, reversible thrombocytopenia. Cardiovascular : QT prolongation has been reported, particularly when metronidazole was administered with drugs with the potential for prolonging the QT interval. Flattening of the T-wave may be seen in electrocardiographic tracings. Hypersensitivity : Toxic epidermal necrolysis (TEN), Stevens-Johnson Syndrome (SJS), drug reaction with eosinophilia and systemic symptoms (DRESS), acute generalized exanthematous pustulosis (AGEP) (see WARNINGS ), urticaria, erythematous rash, flushing, nasal congestion, dryness of the mouth (or vagina or vulva), and fever. Renal : Dysuria, cystitis, polyuria, incontinence, and a sense of pelvic pressure. Instances of darkened urine have been reported by approximately one patient in 100,000. Although the pigment which is probably responsible for this phenomenon has not been positively identified, it is almost certainly a metabolite of metronidazole and seems to have no clinical significance. …"},{"title":"Drug interaction","body":"Disulfiram Psychotic reactions have been reported in alcoholic patients who are using metronidazole and disulfiram concurrently. Metronidazole should not be given to patients who have taken disulfiram within the last two weeks (see CONTRAINDICATIONS ). Alcoholic Beverages Abdominal cramps, nausea, vomiting, headaches, and flushing may occur if alcoholic beverages or products containing propylene glycol are consumed during or following metronidazole therapy (see CONTRAINDICATIONS ). Warfarin and other Oral Anticoagulants Metronidazole has been reported to potentiate the anticoagulant effect of warfarin and other oral coumarin anticoagulants, resulting in a prolongation of prothrombin time. When metronidazole is prescribed for patients on this type of anticoagulant therapy, prothrombin time and INR should be carefully monitored. Lithium In patients stabilized on relatively high doses of lithium, short-term metronidazole therapy has been associated with elevation of serum lithium and, in a few cases, signs of lithium toxicity. Serum lithium and serum creatinine levels should be obtained several days after beginning metronidazole to detect any increase that may precede clinical symptoms of lithium intoxication. Busulfan Metronidazole has been reported to increase plasma concentrations of busulfan, which can result in an increased risk for serious busulfan toxicity. Metronidazole should not be administered concomitantly with busulfan unless the benefit outweighs the risk. If no therapeutic alternatives to metronidazole are available, and concomitant administration with busulfan is medically needed, frequent monitoring of busulfan plasma concentration should be performed and the busulfan dose should be adjusted accordingly. Drugs that Inhibit CYP450 Enzymes The simultaneous administration of drugs that decrease microsomal liver enzyme activity, such as cimetidine, may prolong the half-life and decrease plasma clearance of metronidazole. Drugs that Induce CYP450 Enzymes The simultaneous administration of drugs that induce microsomal liver enzymes, such as phenytoin or phenobarbital, may accelerate the elimination of metronidazole, resulting in reduced plasma levels; impaired clearance of phenytoin has also been reported. Drugs that Prolong the QT interval QT prolongation has been reported, particularly when metronidazole was administered with drugs with the potential for prolonging the QT interval. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Teratogenic Effects: There are no adequate and well controlled studies of metronidazole in pregnant women. There are published data from case-control studies, cohort studies, and 2 meta-analyses that include more than 5,000 pregnant women who used metronidazole during pregnancy. Many studies included first trimester exposures. One study showed an increased risk of cleft lip, with or without cleft palate, in infants exposed to metronidazole in-utero ; however, these findings were not confirmed. In addition, more than ten randomized placebo-controlled clinical trials enrolled more than 5,000 pregnant women to assess the use of antibiotic treatment (including metronidazole) for bacterial vaginosis on the incidence of preterm delivery. Most studies did not show an increased risk for congenital anomalies or other adverse fetal outcomes following metronidazole exposure during pregnancy. Three studies conducted to assess the risk of infant cancer following metronidazole exposure during pregnancy did not show an increased risk; however, the ability of these studies to detect such a signal was limited. Metronidazole crosses the placental barrier and its effects on the human fetal organogenesis are not known. Reproduction studies have been performed in rats, rabbits, and mice at doses similar to the maximum recommended human dose based on body surface area comparisons. There was no evidence of harm to the fetus due to metronidazole. Metronidazole is present in human milk at concentrations similar to maternal serum levels, and infant serum levels can be close to or comparable to infant therapeutic levels. There are no data on the effects of metronidazole on milk production. Animal studies have shown the potential for tumorigenicity after oral metronidazole was administered chronically to rats and mice (see PRECAUTIONS , Carcinogenesis, Mutagenesis, Impairment of Fertility). This drug is not intended to be administered chronically; therefore, the clinical relevance of the findings of the animal studies is unclear. The developmental and health benefits of breastfeeding should be considered along with the mother’s clinical need for metronidazole and any potential adverse effects on the breastfed infant from metronidazole or from the underlying maternal condition. Alternatively, a nursing mother may choose to pump and discard human milk for the duration of metronidazole therapy, and for 48 hours after the last dose and feed her infant stored human milk or formula. …"},{"title":"การได้รับยาเกินขนาด","body":"Single oral doses of metronidazole, up to 15 g, have been reported in suicide attempts and accidental overdoses. Symptoms reported include nausea, vomiting, and ataxia. Oral metronidazole has been studied as a radiation sensitizer in the treatment of malignant tumors. Neurotoxic effects, including seizures and peripheral neuropathy, have been reported after 5 to 7 days of doses of 6 to 10.4 g every other day. Treatment of Overdosage: There is no specific antidote for metronidazole overdose; therefore, management of the patient should consist of symptomatic and supportive therapy."},{"title":"การเก็บรักษา","body":"Storage and Stability: Store at 20° to 25°C (68° to 77°F) [see USP Controlled Room Temperature]. Protect from light. Dispense in a tight, light-resistant container as defined in the USP, with a child-resistant closure (as required). Distributed by: Avet Pharmaceuticals Inc. East Brunswick, NJ 08816, USA. 1-866-901-DRUG (3784) Packaged and Distributed by: MAJOR® PHARMACEUTICALS Indianapolis, IN 46268 USA Refer to package label for Distributor's NDC Number Distributed By: Cardinal Health Dublin, OH 43017 L58113510825 Revised: 07/2024 200192 Avet logo"}]},
{"key":"naproxen|ORAL","generic":"naproxen","route":"ORAL","brand":null,"title":"Naproxen","set_id":"000155a8-709c-44e5-a75f-cd890f3a7caf","effective":"20260129","sections":[{"title":"ข้อบ่งใช้","body":"Naproxen tablets and naproxen sodium tablets are indicated for: the relief of the signs and symptoms of: • rheumatoid arthritis • osteoarthritis • ankylosing spondylitis • Polyarticular Juvenile Idiopathic Arthritis Naproxen tablets and naproxen sodium tablets are also indicated for: the relief of signs and symptoms of: • tendonitis • bursitis • acute gout the management of: • pain • primary dysmenorrhea Naproxen tablets and naproxen sodium tablets are non-steroidal anti-inflammatory drugs indicated for: the relief of the signs and symptoms of: • rheumatoid arthritis • osteoarthritis • ankylosing spondylitis • polyarticular juvenile idiopathic arthritis Naproxen tablets and naproxen sodium tablets are also indicated for: the relief of signs and symptoms of: • tendonitis • bursitis • acute gout the management of: • pain • primary dysmenorrhea"},{"title":"ขนาดยาและวิธีใช้","body":"Use the lowest effective dosage for shortest duration consistent with individual patient treatment goals. ( 2.1 ) Rheumatoid Arthritis, Osteoarthritis, and Ankylosing Spondylitis Naproxen tablets 250 mg (one-half tablet) 500 mg twice daily Naproxen sodium tablets 275 mg (one-half tablet) 550 mg twice daily The dose may be adjusted up or down depending on the clinical response of the patient. In patients who tolerate lower doses well, the dose may be increased to naproxen 1500 mg/ day for up to 6 months. Polyarticular Juvenile Idiopathic Arthritis Naproxen tablets may not allow for the flexible dose titration needed in pediatric patients with polyarticular juvenile idiopathic arthritis. A liquid formulation may be more appropriate. Recommended total daily dose of naproxen is approximately 10 mg/kg given in 2 divided doses. Dosing with naproxen tablets is not appropriate for children weighing less than 50 kilograms. Management of Pain, Primary Dysmenorrhea, and Acute Tendonitis and Bursitis Recommended starting dose 550 mg of naproxen sodium as naproxen sodium tablets followed by 550 mg every 12 hours or 275 mg every 6 to 8 hours as required. The initial total daily dose should not exceed 1375 mg of naproxen sodium. Thereafter, the total daily dose should not exceed 1100 mg of naproxen sodium. Naproxen sodium tablets are recommended for the management of acute painful conditions when prompt onset of pain relief is desired. Acute Gout Recommended starting dose 750 mg of naproxen tablets followed by 250 mg every 8 hours until the attack has subsided. Naproxen sodium tablets may also be used at a starting dose of 825 mg followed by 275 mg every 8 hours. 2.1 General Dosing Instructions Carefully consider the potential benefits and risks of naproxen tablets and naproxen sodium tablets and other treatment options before deciding to use naproxen tablets and naproxen sodium tablets. Use the lowest effective dose for the shortest duration consistent with individual patient treatment goals [ see Warnings and Precautions ( 5 ) ]. After observing the response to initial therapy with naproxen tablets or naproxen sodium tablets, the dose and frequency should be adjusted to suit an individual patient’s needs. Naproxen-containing products such as naproxen and naproxen sodium tablets, and other naproxen products should not be used concomitantly since they all circulate in the plasma as the naproxen anion. …"},{"title":"ข้อห้ามใช้","body":"Naproxen tablets and naproxen sodium tablets are contraindicated in the following patients: • Known hypersensitivity (e.g., anaphylactic reactions and serious skin reactions) to naproxen or any components of the drug product [ see Warnings and Precautions ( 5.7 , 5.9 ) ] • History of asthma, urticaria, or other allergic-type reactions after taking aspirin or other NSAIDs. Severe, sometimes fatal, anaphylactic reactions to NSAIDs have been reported in such patients [ see Warnings and Precautions ( 5.7 , 5.8 ) ] • In the setting of coronary artery bypass graft (CABG) surgery [ see Warnings and Precautions ( 5.1 ) ] • Known hypersensitivity to naproxen or any components of the drug product ( 4 ) • History of asthma, urticaria, or other allergic-type reactions after taking aspirin or other NSAIDs ( 4 ) • In the setting of CABG surgery ( 4 )"},{"title":"คำเตือนกรอบดำ","body":"WARNING: RISK OF SERIOUS CARDIOVASCULAR AND GASTROINTESTINAL EVENTS Cardiovascular Thrombotic Events • Nonsteroidal anti-inflammatory drugs (NSAIDs) cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction and stroke, which can be fatal. This risk may occur early in treatment and may increase with duration of use [ see Warnings and Precautions ( 5.1 ) ]. • Naproxen tablets and naproxen sodium tablets are contraindicated in the setting of coronary artery bypass graft (CABG) surgery [ see Contraindications ( 4 ), Warnings and Precautions ( 5.1 ) ]. Gastrointestinal Bleeding, Ulceration, and Perforation • NSAIDs cause an increased risk of serious gastrointestinal (GI) adverse events including bleeding, ulceration, and perforation of the stomach or intestines, which can be fatal. These events can occur at any time during use and without warning symptoms. Elderly patients and patients with a prior history of peptic ulcer disease and/or GI bleeding are at greater risk for serious GI events [ see Warnings and Precautions ( 5.2 ) ]. WARNING: RISK OF SERIOUS CARDIOVASCULAR AND GASTROINTESTINAL EVENTS See full prescribing information for complete boxed warning. • Nonsteroidal anti-inflammatory drugs (NSAIDs) cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction and stroke, which can be fatal. This risk may occur early in treatment and may increase with duration of use. ( 5.1 ) • Naproxen tablets and naproxen sodium tablets are contraindicated in the setting of coronary artery bypass graft (CABG) surgery. ( 4 , 5.1 ) • NSAIDs cause an increased risk of serious gastrointestinal (GI) adverse events including bleeding, ulceration, and perforation of the stomach or intestines, which can be fatal. These events can occur at any time during use and without warning symptoms. Elderly patients and patients with a prior history of peptic ulcer disease and/or GI bleeding are at greater risk for serious GI events. ( 5.2 )"},{"title":"คำเตือนและข้อควรระวัง","body":"Hepatotoxicity : Inform patients of warning signs and symptoms of hepatotoxicity. Discontinue if abnormal liver tests persist or worsen or if clinical signs and symptoms of liver disease develop. ( 5.3 ) Hypertension : Patients taking some antihypertensive medications may have impaired response to these therapies when taking NSAIDs. Monitor blood pressure. ( 5.4 , 7 ) Heart Failure and Edema: Avoid use of naproxen tablets and naproxen sodium tablets in patients with severe heart failure unless benefits are expected to outweigh risk of worsening heart failure. ( 5.5 ) Renal Toxicity : Monitor renal function in patients with renal or hepatic impairment, heart failure, dehydration, or hypovolemia. Avoid use of naproxen tablets and naproxen sodium tablets in patients with advanced renal disease unless benefits are expected to outweigh risk of worsening renal function. ( 5.6 ) Anaphylactic Reactions: Seek emergency help if an anaphylactic reaction occurs. ( 5.7 ) Exacerbation of Asthma Related to Aspirin Sensitivity: Naproxen tablets and naproxen sodium tablets are contraindicated in patients with aspirin-sensitive asthma. Monitor patients with preexisting asthma (without aspirin sensitivity). ( 5.8 ) Serious Skin Reactions : Discontinue naproxen tablets and naproxen sodium tablets at first appearance of skin rash or other signs of hypersensitivity. ( 5.9 ) Drug Reaction with Eosinophilia and Systemic Symptoms (DRESS): Discontinue and evaluate clinically ( 5.10 ). Fetal Toxicity: Limit use of NSAIDs, including naproxen tablets and naproxen sodium tablets, between about 20 to 30 weeks in pregnancy due to the risk of oligohydramnios/fetal dysfunction. Avoid use of NSAIDs in women at about 30 weeks gestation and later in pregnancy due to the risks of oligohydramnios/fetal renal dysfunction and premature closure of the fetal ductus arteriosus. ( 5.11 , 8.1 ) Hematologic Toxicity : Monitor hemoglobin or hematocrit in patients with any signs or symptoms of anemia. ( 5.12 , 7 ) 5.1 Cardiovascular Thrombotic Events Clinical trials of several COX-2 selective and nonselective NSAIDs of up to three years duration have shown an increased risk of serious cardiovascular (CV) thrombotic events, including myocardial infarction (MI) and stroke, which can be fatal. Based on available data, it is unclear that the risk for CV thrombotic events is similar for all NSAIDs. …"},{"title":"อาการไม่พึงประสงค์","body":"The following adverse reactions are discussed in greater detail in other sections of the labeling: • Cardiovascular Thrombotic Events [ see Warnings and Precautions ( 5.1 ) ] • GI Bleeding, Ulceration, and Perforation [ see Warnings and Precautions ( 5.2 ) ] • Hepatotoxicity [ see Warnings and Precautions ( 5.3 ) ] • Hypertension [ see Warnings and Precautions ( 5.4 ) ] • Heart Failure and Edema [ see Warnings and Precautions ( 5.5 ) ] • Renal Toxicity and Hyperkalemia [ see Warnings and Precautions ( 5.6 ) ] • Anaphylactic Reactions [ see Warnings and Precautions ( 5.7 ) ] • Serious Skin Reactions [ see Warnings and Precautions ( 5.9 ) ] • Hematologic Toxicity [ see Warnings and Precautions ( 5.12 ) ] Most common adverse reactions to naproxen were dyspepsia, abdominal pain, nausea, headache, rash, ecchymosis, and edema. ( 6.1 ) To report SUSPECTED ADVERSE REACTIONS, contact Glenmark Pharmaceuticals Inc., USA at 1 (888) 721-7115 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch. 6.1 Clinical Trials Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical trials of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in practice. Adverse reactions reported in controlled clinical trials in 960 patients treated for rheumatoid arthritis or osteoarthritis are listed below. In general, reactions in patients treated chronically were reported 2 to 10 times more frequently than they were in short-term studies in the 962 patients treated for mild to moderate pain or for dysmenorrhea. The most frequent complaints reported related to the gastrointestinal tract. A clinical study found gastrointestinal reactions to be more frequent and more severe in rheumatoid arthritis patients taking daily doses of 1500 mg naproxen compared to those taking 750 mg naproxen. In controlled clinical trials with about 80 pediatric patients and in well-monitored, open-label studies with about 400 pediatric patients with polyarticular juvenile idiopathic arthritis treated with naproxen, the incidence of rash and prolonged bleeding times were greater, the incidence of gastrointestinal and central nervous system reactions were about the same, and the incidence of other reactions were lower in pediatric patients than in adults. …"},{"title":"Drug interaction","body":"See Table 1 for clinically significant drug interactions with naproxen. Table 1: Clinically Significant Drug Interactions with naproxen Drugs That Interfere with Hemostasis Clinical Impact: • Naproxen and anticoagulants such as warfarin have a synergistic effect on bleeding. The concomitant use of naproxen and anticoagulants have an increased risk of serious bleeding compared to the use of either drug alone. • Serotonin release by platelets plays an important role in hemostasis. Case-control and cohort epidemiological studies showed that concomitant use of drugs that interfere with serotonin reuptake and an NSAID may potentiate the risk of bleeding more than an NSAID alone. Intervention: Monitor patients with concomitant use of naproxen tablets or naproxen sodium tablets with anticoagulants (e.g., warfarin), antiplatelet agents (e.g., aspirin), selective serotonin reuptake inhibitors (SSRIs), and serotonin norepinephrine reuptake inhibitors (SNRIs) for signs of bleeding [ see Warnings and Precautions ( 5.12 ) ]. Aspirin Clinical Impact: A pharmacodynamic (PD) study has demonstrated an interaction in which lower dose naproxen (220mg/day or 220mg twice daily) interfered with the antiplatelet effect of low-dose immediate-release aspirin, with the interaction most marked during the washout period of naproxen ( see 12.2 Pharmacodynamics) . There is reason to expect that the interaction would be present with prescription doses of naproxen or with enteric-coated low-dose aspirin; however, the peak interference with aspirin function may be later than observed in the PD study due to the longer washout period. Controlled clinical studies showed that the concomitant use of NSAIDs and analgesic doses of aspirin does not produce any greater therapeutic effect than the use of NSAIDs alone. In a clinical study, the concomitant use of an NSAID and aspirin was associated with a significantly increased incidence of GI adverse reactions as compared to use of the NSAID alone [ see Warnings and Precautions ( 5.2 ) ]. Intervention: Because there may be an increased risk of cardiovascular events following discontinuation of naproxen due to the interference with the antiplatelet effect of aspirin during the washout period, for patients taking low-dose aspirin for cardioprotection who require intermittent analgesics, consider use of an NSAID that does not interfere with the antiplatelet effect of aspirin, or non-NSAID analgesics where appropriate. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Use of NSAIDs, including naproxen tablets and naproxen sodium tablets, can cause premature closure of the fetal ductus arteriosus and fetal renal dysfunction leading to oligohydramnios and, in some cases, neonatal renal impairment. Because of these risks, limit dose and duration of naproxen tablets or naproxen sodium tablets use between about 20 and 30 weeks of gestation, and avoid naproxen tablets and naproxen sodium tablets use at about 30 weeks of gestation and later in pregnancy (see Clinical Considerations, Data). Premature Closure of Fetal Ductus Arteriosus Use of NSAIDs, including naproxen tablets and naproxen sodium tablets, at about 30 weeks gestation or later in pregnancy increases the risk of premature closure of the fetal ductus arteriosus. Oligohydramnios/Neonatal Renal Impairment Use of NSAIDs at about 20 weeks gestation or later in pregnancy has been associated with cases of fetal renal dysfunction leading to oligohydramnios, and in some cases, neonatal renal impairment. Data from observational studies regarding other potential embryofetal risks of NSAID use in women in the first or second trimesters of pregnancy are inconclusive. In animal reproduction studies in rats, rabbits, and mice no evidence of teratogenicity or fetal harm when naproxen was administered during the period of organogenesis at doses 0.13, 0.26, and 0.6 times the maximum recommended human daily dose of 1500 mg/day, respectively [ see Data ]. Based on animal data, prostaglandins have been shown to have an important role in endometrial vascular permeability, blastocyst implantation, and decidualization. In animal studies, administration of prostaglandin synthesis inhibitors such as naproxen, resulted in increased pre-and post-implantation loss. Prostaglandins also have been shown to have an important role in fetal kidney development. In published animal studies, prostaglandin synthesis inhibitors have been reported to impair kidney development when administered at clinically relevant doses. The estimated background risk of major birth defects and miscarriage for the indicated population(s) is unknown. All pregnancies have a background risk of birth defect, loss, or other adverse outcomes. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2% to 4% and 15% to 20%, respectively. …"},{"title":"การได้รับยาเกินขนาด","body":"Symptoms following acute NSAID overdosages have been typically limited to lethargy, drowsiness, nausea, vomiting, and epigastric pain, which have been generally reversible with supportive care. Gastrointestinal bleeding has occurred. Hypertension, acute renal failure, respiratory depression, and coma have occurred, but were rare [ see Warnings and Precautions ( 5.1 , 5.2 ) ].Because naproxen sodium may be rapidly absorbed, high and early blood levels should be anticipated. A few patients have experienced convulsions, but it is not clear whether or not these were drug-related. It is not known what dose of the drug would be life threatening [ see Warnings and Precautions ( 5.1 , 5.2 , 5.4 , 5.6 ) ]. Manage patients with symptomatic and supportive care following an NSAID overdosage. There are no specific antidotes. Consider emesis and/or activated charcoal (60 to 100 grams in adults, 1 to 2 grams per kg of body weight in pediatric patients) and/or osmotic cathartic in symptomatic patients seen within four hours of ingestion or in patients with a large overdosage (5 to 10 times the recommended dosage). Forced diuresis, alkalinization of urine, hemodialysis, or hemoperfusion may not be useful due to high protein binding. For additional information about overdosage treatment contact a poison control center (1-800-222-1222)."}]},
{"key":"nifedipine|ORAL","generic":"nifedipine","route":"ORAL","brand":null,"title":"nifedipine","set_id":"1df07edb-630d-4c70-a68c-bdbc607ce850","effective":"20260113","sections":[{"title":"ข้อบ่งใช้","body":"I. Vasospastic Angina Nifedipine Extended-Release Tablets, USP are indicated for the management of vasospastic angina confirmed by any of the following criteria: 1) classical pattern of angina at rest accompanied by ST segment elevation, 2) angina or coronary artery spasm provoked by ergonovine, or 3) angiographically demonstrated coronary artery spasm. In those patients who have had angiography, the presence of significant fixed obstructive disease is not incompatible with the diagnosis of vasospastic angina, provided that the above criteria are satisfied. Nifedipine Extended-Release Tablets, USP may also be used where the clinical presentation suggests a possible vasospastic component, but where vasospasm has not been confirmed, e.g., where pain has a variable threshold on exertion, or in unstable angina where electrocardiographic findings are compatible with intermittent vasospasm, or when angina is refractory to nitrates and/or adequate doses of beta blockers. II. Chronic Stable Angina (Classical Effort-Associated Angina) Nifedipine Extended-Release Tablets, USP are indicated for the management of chronic stable angina (effort-associated angina) without evidence of vasospasm in patients who remain symptomatic despite adequate doses of beta blockers and/or organic nitrates or who cannot tolerate those agents. In chronic stable angina (effort-associated angina), nifedipine has been effective in controlled trials of up to eight weeks duration in reducing angina frequency and increasing exercise tolerance, but confirmation of sustained effectiveness and evaluation of long-term safety in these patients is incomplete. Controlled studies in small numbers of patients suggest concomitant use of nifedipine and beta-blocking agents may be beneficial in patients with chronic stable angina, but available information is not sufficient to predict with confidence the effects of concurrent treatment, especially in patients with compromised left ventricular function or cardiac conduction abnormalities. When introducing such concomitant therapy, care must be taken to monitor blood pressure closely, since severe hypotension can occur from the combined effects of the drugs (see WARNINGS ). III. Hypertension Nifedipine Extended-Release Tablets, USP are indicated for the treatment of hypertension, to lower blood pressure. Lowering blood pressure reduces the risk of fatal and nonfatal cardiovascular events, primarily strokes and myocardial infarctions. …"},{"title":"ขนาดยาและวิธีใช้","body":"Dosage must be adjusted according to each patient’s needs. Therapy for either hypertension or angina should be initiated with 30 or 60 mg once daily. Nifedipine Extended-Release Tablets, USP should be swallowed whole and should not be bitten or divided. In general, titration should proceed over a 7–14 day period so that the physician can fully assess the response to each dose level and monitor blood pressure before proceeding to higher doses. Since steady-state plasma levels are achieved on the second day of dosing, titration may proceed more rapidly, if symptoms so warrant, provided the patient is assessed frequently. Titration to doses above 120 mg are not recommended. Angina patients controlled on nifedipine capsules alone or in combination with other antianginal medications may be safely switched to Nifedipine Extended-Release Tablets, USP at the nearest equivalent total daily dose (e.g., 30 mg t.i.d. of nifedipine capsules may be changed to 90 mg once daily of Nifedipine Extended-Release Tablets, USP). Subsequent titration to higher or lower doses may be necessary and should be initiated as clinically warranted. Experience with doses greater than 90 mg in patients with angina is limited. Therefore, doses greater than 90 mg should be used with caution and only when clinically warranted. Avoid co-administration of nifedipine with grapefruit juice (see CLINICAL PHARMACOLOGY and PRECAUTIONS: Other Interactions ). No “rebound effect” has been observed upon discontinuation of nifedipine extended-release tablets. However, if discontinuation of nifedipine is necessary, sound clinical practice suggests that the dosage should be decreased gradually with close physician supervision. Care should be taken when dispensing Nifedipine Extended-Release Tablets, USP to assure that the extended-release dosage form has been prescribed."},{"title":"ข้อห้ามใช้","body":"Known hypersensitivity reaction to nifedipine."},{"title":"คำเตือนและข้อควรระวัง","body":"Excessive Hypotension Although in most angina patients the hypotensive effect of nifedipine is modest and well tolerated, occasional patients have had excessive and poorly tolerated hypotension. These responses have usually occurred during initial titration or at the time of subsequent upward dosage adjustment, and may be more likely in patients on concomitant beta blockers. Severe hypotension and/or increased fluid volume requirements have been reported in patients receiving nifedipine together with a beta-blocking agent who underwent coronary artery bypass surgery using high dose fentanyl anesthesia. The interaction with high dose fentanyl appears to be due to the combination of nifedipine and a beta blocker, but the possibility that it may occur with nifedipine alone, with low doses of fentanyl, in other surgical procedures, or with other narcotic analgesics cannot be ruled out. In nifedipine-treated patients where surgery using high dose fentanyl anesthesia is contemplated, the physician should be aware of these potential problems and, if the patient’s condition permits, sufficient time (at least 36 hours) should be allowed for nifedipine to be washed out of the body prior to surgery. The following information should be taken into account in those patients who are being treated for hypertension as well as angina: Increased Angina and/or Myocardial Infarction Rarely, patients, particularly those who have severe obstructive coronary artery disease, have developed well documented increased frequency, duration and/or severity of angina or acute myocardial infarction on starting nifedipine or at the time of dosage increase. The mechanism of this effect is not established. Beta Blocker Withdrawal It is important to taper beta blockers if possible, rather than stopping them abruptly before beginning nifedipine. Patients recently withdrawn from beta blockers may develop a withdrawal syndrome with increased angina, probably related to increased sensitivity to catecholamines. Initiation of nifedipine treatment will not prevent this occurrence and on occasion has been reported to increase it. Congestive Heart Failure Rarely, patients, usually receiving a beta blocker, have developed heart failure after beginning nifedipine. Patients with tight aortic stenosis may be at greater risk for such an event, as the unloading effect of nifedipine would be expected to be of less benefit, owing to the fixed impedance to flow across the aortic valve in these patients. …"},{"title":"อาการไม่พึงประสงค์","body":"ADVERSE EXPERIENCES Over 1000 patients from both controlled and open trials with nifedipine extended-release tablets in hypertension and angina were included in the evaluation of adverse experiences. All side effects reported during nifedipine extended-release tablet therapy were tabulated independent of their causal relation to medication. The most common side effect reported with nifedipine extended-release tablet was edema which was dose related and ranged in frequency from approximately 10% to about 30% at the highest dose studied (180 mg). Other common adverse experiences reported in placebo-controlled trials include: Adverse Effect Nifedipine Extended-Release Tablet (%) (N=707) Placebo (%) (N=266) Headache 15.8 9.8 Fatigue 5.9 4.1 Dizziness 4.1 4.5 Constipation 3.3 2.3 Nausea 3.3 1.9 Of these, only edema and headache were more common in nifedipine extended-release tablet patients than placebo patients. The following adverse reactions occurred with an incidence of less than 3.0%. With the exception of leg cramps, the incidence of these side effects was similar to that of placebo alone. Body as a Whole/Systemic: asthenia, flushing, pain Cardiovascular: palpitations Central Nervous System: insomnia, nervousness, paresthesia, somnolence Dermatologic: pruritus, rash Gastrointestinal: abdominal pain, diarrhea, dry mouth, dyspepsia, flatulence Musculoskeletal: arthralgia, leg cramps Respiratory: chest pain (nonspecific), dyspnea Urogenital: impotence, polyuria Other adverse reactions were reported sporadically with an incidence of 1.0% or less. These include: Body as a Whole/Systemic: face edema, fever, hot flashes, malaise, periorbital edema, rigors Cardiovascular: arrhythmia, hypotension, increased angina, tachycardia, syncope Central Nervous System: anxiety, ataxia, decreased libido, depression, hypertonia, hypoesthesia, migraine, paroniria, tremor, vertigo Dermatologic: alopecia, increased sweating, urticaria, purpura Gastrointestinal: eructation, gastroesophageal reflux, gum hyperplasia, melena, vomiting, weight increase Musculoskeletal: back pain, gout, myalgias Respiratory: coughing, epistaxis, upper respiratory tract infection, respiratory disorder, sinusitis Special Senses: abnormal lacrimation, abnormal vision, taste perversion, tinnitus Urogenital/Reproductive: breast pain, dysuria, hematuria, nocturia Adverse experiences which occurred in less than 1 in 1000 patients cannot be distinguished from concurrent disease states or medications. …"},{"title":"Drug interaction","body":"Beta-adrenergic blocking agents: (see INDICATIONS AND USAGE and WARNINGS .) Experience in over 1400 patients with nifedipine capsules in a noncomparative clinical trial has shown that concomitant administration of nifedipine and beta-blocking agents is usually well tolerated, but there have been occasional literature reports suggesting that the combination may increase the likelihood of congestive heart failure, severe hypotension, or exacerbation of angina. Long-acting Nitrates: Nifedipine may be safely co-administered with nitrates, but there have been no controlled studies to evaluate the antianginal effectiveness of this combination. Digitalis: Administration of nifedipine with digoxin increased digoxin levels in nine of twelve normal volunteers. The average increase was 45%. Another investigator found no increase in digoxin levels in thirteen patients with coronary artery disease. In an uncontrolled study of over two hundred patients with congestive heart failure during which digoxin blood levels were not measured, digitalis toxicity was not observed. Since there have been isolated reports of patients with elevated digoxin levels, it is recommended that digoxin levels be monitored when initiating, adjusting, and discontinuing nifedipine to avoid possible over- or under-digitalization. Coumarin Anticoagulants: There have been rare reports of increased prothrombin time in patients taking coumarin anticoagulants to whom nifedipine was administered. However, the relationship to nifedipine therapy is uncertain. Cimetidine: A study in six healthy volunteers has shown a significant increase in peak nifedipine plasma levels (80%) and area-under-the-curve (74%), after a one week course of cimetidine at 1000 mg per day and nifedipine at 40 mg per day. Ranitidine produced smaller, non-significant increases. The effect may be mediated by the known inhibition of cimetidine on hepatic cytochrome P-450, the enzyme system probably responsible for the first-pass metabolism of nifedipine. If nifedipine therapy is initiated in a patient currently receiving cimetidine, cautious titration is advised. Nifedipine is metabolized by CYP3A4. Co-administration of nifedipine with phenytoin, an inducer of CYP3A4, lowers the systemic exposure to nifedipine by approximately 70%. Avoid co-administration of nifedipine with phenytoin or any known CYP3A4 inducer or consider an alternative antihypertensive therapy. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Nifedipine has been shown to produce teratogenic findings in rats and rabbits, including digital anomalies similar to those reported for phenytoin. Digital anomalies have been reported to occur with other members of the dihydropyridine class and are possibly a result of compromised uterine blood flow. Nifedipine administration was associated with a variety of embryotoxic, placentotoxic, and fetotoxic effects, including stunted fetuses (rats, mice, rabbits), rib deformities (mice), cleft palate (mice), small placentas and underdeveloped chorionic villi (monkeys), embryonic and fetal deaths (rats, mice, rabbits), and prolonged pregnancy/decreased neonatal survival (rats; not evaluated in other species). On a mg/kg basis, all of the doses associated with the teratogenic embryotoxic or fetotoxic effects in animals were higher (5 to 50 times) than the maximum recommended human dose of 120 mg/day. On a mg/m 2 basis, some doses were higher and some were lower than the maximum recommended human dose, but all are within an order of magnitude of it. The doses associated with placentotoxic effects in monkeys were equivalent to or lower than the maximum recommended human dose on a mg/m 2 basis. There are no adequate and well-controlled studies in pregnant women. Nifedipine Extended-Release Tablets, USP should be used during pregnancy only if the potential benefit justifies the potential risk. Lactation: Nifedipine is transferred through breast milk. Nifedipine Extended-Release Tablets, USP should be used during breast-feeding only if the potential benefit justifies the potential risk. Safety and effectiveness in pediatric patients have not been established. Geriatric Use: Age appears to have a significant effect on the pharmacokinetics of nifedipine. The clearance is decreased resulting in a higher AUC in the elderly. These changes are not due to changes in renal function (see CLINICAL PHARMACOLOGY, Pharmacokinetics )."},{"title":"การได้รับยาเกินขนาด","body":"Experience with nifedipine overdosage is limited. Generally, overdosage with nifedipine leading to pronounced hypotension calls for active cardiovascular support, including monitoring of cardiovascular and respiratory function, elevation of extremities, judicious use of calcium infusion, pressor agents, and fluids. Clearance of nifedipine would be expected to be prolonged in patients with impaired liver function. Since nifedipine is highly protein-bound, dialysis is not likely to be of any benefit. There has been one reported case of massive overdosage with nifedipine extended-release tablets. The main effects of ingestion of approximately 4800 mg of nifedipine extended-release tablet in a young man attempting suicide as a result of cocaine-induced depression was initial dizziness, palpitations, flushing, and nervousness. Within several hours of ingestion, nausea, vomiting, and generalized edema developed. No significant hypotension was apparent at presentation, 18 hours post-ingestion. Electrolyte abnormalities consisted of a mild, transient elevation of serum creatinine, and modest elevations of LDH and CPK, but normal SGOT. Vital signs remained stable, no electrocardiographic abnormalities were noted, and renal function returned to normal within 24 to 48 hours with routine supportive measures alone. No prolonged sequelae were observed. The effect of a single 900 mg ingestion of nifedipine capsules in a depressed anginal patient also on tricyclic antidepressants was loss of consciousness within 30 minutes of ingestion, and profound hypotension, which responded to calcium infusion, pressor agents, and fluid replacement. A variety of ECG abnormalities were seen in this patient with a history of bundle branch block, including sinus bradycardia and varying degrees of AV block. These dictated the prophylactic placement of a temporary ventricular pacemaker, but otherwise resolved spontaneously. Significant hyperglycemia was seen initially in this patient, but plasma glucose levels rapidly normalized without further treatment. A young hypertensive patient with advanced renal failure ingested 280 mg of nifedipine capsules at one time, with resulting marked hypotension responding to calcium infusion and fluids. No AV conduction abnormalities, arrhythmias, or pronounced changes in heart rate were noted, nor was there any further deterioration in renal function."},{"title":"การเก็บรักษา","body":"Store at 20˚C to 25˚C (68˚F to 77˚F), excursions permitted between 15˚C and 30˚C (59˚F and 86˚F) [see USP Controlled Room Temperature]. Protect from moisture and humidity. Manufactured for: ELITE Pharmaceutical Solution, Inc. Manufactured by: Patheon Pharmaceuticals Inc. 2110 E Galbraith Rd Cincinnati, Ohio 45237 Revised October 2021"}]},
{"key":"pioglitazone hydrochloride|ORAL","generic":"pioglitazone hydrochloride","route":"ORAL","brand":null,"title":"PIOGLITAZONE HYDROCHLORIDE","set_id":"29073b0a-1d7e-4354-87c7-e764106978d8","effective":"20260106","sections":[{"title":"ข้อบ่งใช้","body":"Monotherapy and Combination Therapy Pioglitazone tablets are indicated as an adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus in multiple clinical settings [see Clinical Studies (14) ] . Important Limitations of Use Pioglitazone tablets exert its antihyperglycemic effect only in the presence of endogenous insulin. Pioglitazone tablets should not be used to treat type 1 diabetes or diabetic ketoacidosis, as it would not be effective in these settings. Use caution in patients with liver disease [see Warnings and Precautions (5.3) ] . Pioglitazone is a thiazolidinedione and an agonist for peroxisome proliferator-activated receptor (PPAR) gamma indicated as an adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus in multiple clinical settings. ( 1, 14) Important Limitations of Use: Not for treatment of type 1 diabetes or diabetic ketoacidosis. ( 1 )"},{"title":"ขนาดยาและวิธีใช้","body":"Initiate pioglitazone tablets at 15 mg or 30 mg once daily. Limit initial dose to 15 mg once daily in patients with NYHA Class I or II heart failure. (2.1) If there is inadequate glycemic control, the dose can be increased in 15 mg increments up to a maximum of 45 mg once daily. (2.1) Obtain liver tests before starting pioglitazone tablets. If abnormal, use caution when treating with pioglitazone tablets, investigate the probable cause, treat (if possible) and follow appropriately. Monitoring liver tests while on pioglitazone tablets are not recommended in patients without liver disease. ( 5.3 ) 2.1 Recommendations for All Patients Pioglitazone tablets should be taken once daily and can be taken without regard to meals. The recommended starting dose for patients without congestive heart failure is 15 mg or 30 mg once daily. The recommended starting dose for patients with congestive heart failure (NYHA Class I or II) is 15 mg once daily. The dose can be titrated in increments of 15 mg up to a maximum of 45 mg once daily based on glycemic response as determined by HbA1c. After initiation of pioglitazone tablets or with dose increase, monitor patients carefully for adverse reactions related to fluid retention such as weight gain, edema, and signs and symptoms of congestive heart failure [see Boxed Warning and Warnings and Precautions (5.5) ] . Liver tests (serum alanine and aspartate aminotransferases, alkaline phosphatase, and total bilirubin) should be obtained prior to initiating pioglitazone tablets. Routine periodic monitoring of liver tests during treatment with pioglitazone tablets are not recommended in patients without liver disease. Patients who have liver test abnormalities prior to initiation of pioglitazone tablets or who are found to have abnormal liver tests while taking pioglitazone tablets should be managed as described under Warnings and Precautions [see Warnings and Precautions (5.3) and Clinical Pharmacology (12.3) ] . 2.2 Concomitant Use with an Insulin Secretagogue or Insulin If hypoglycemia occurs in a patient co-administered pioglitazone tablets and an insulin secretagogue (e.g., sulfonylurea), the dose of the insulin secretagogue should be reduced. If hypoglycemia occurs in a patient co-administered pioglitazone tablets and insulin, the dose of insulin should be decreased by 10% to 25%. Further adjustments to the insulin dose should be individualized based on glycemic response. …"},{"title":"ข้อห้ามใช้","body":"Initiation in patients with established NYHA Class III or IV heart failure [see Boxed Warning ]. Use in patients with known hypersensitivity to pioglitazone or any other component of pioglitazone tablets. Initiation in patients with established New York Heart Association (NYHA) Class III or IV heart failure [see Boxed Warning ] . (4) Use in patients with known hypersensitivity to pioglitazone or any other component of pioglitazone tablets. (4)"},{"title":"คำเตือนกรอบดำ","body":"WARNING: CONGESTIVE HEART FAILURE Thiazolidinediones, including pioglitazone , cause or exacerbate congestive heart failure in some patients [see Warnings and Precautions (5.1) ] . After initiation of pioglitazone , and after dose increases, monitor patients carefully for signs and symptoms of heart failure (e.g., excessive, rapid weight gain, dyspnea, and/or edema). If heart failure develops, it should be managed according to current standards of care and discontinuation or dose reduction of pioglitazone must be considered. Pioglitazone is not recommended in patients with symptomatic heart failure. Initiation of pioglitazone in patients with established New York Heart Association (NYHA) Class III or IV heart failure is contraindicated [see Contraindications (4) and Warnings and Precautions (5.1) ] . WARNING: CONGESTIVE HEART FAILURE See full prescribing information for complete boxed warning. Thiazolidinediones, including pioglitazone, cause or exacerbate congestive heart failure in some patients. (5.1) After initiation of pioglitazone, and after dose increases, monitor patients carefully for signs and symptoms of heart failure (e.g., excessive, rapid weight gain, dyspnea, and/or edema). If heart failure develops, it should be managed according to current standards of care and discontinuation or dose reduction of pioglitazone must be considered. (5.1) Pioglitazone is not recommended in patients with symptomatic heart failure. (5.1) Initiation of pioglitazone in patients with established New York Heart Association (NYHA) Class III or IV heart failure is contraindicated. (4 , 5.1)"},{"title":"คำเตือนและข้อควรระวัง","body":"Congestive heart failure: Fluid retention may occur and can exacerbate or lead to congestive heart failure. Combination use with insulin and use in congestive heart failure NYHA Class I and II may increase risk. Monitor patients for signs and symptoms. (5.1) Hypoglycemia: When used with insulin or an insulin secretagogue, a lower dose of the insulin or insulin secretagogue may be needed to reduce the risk of hypoglycemia. (5.2) Hepatic effects: Postmarketing reports of hepatic failure, sometimes fatal. Causality cannot be excluded. If liver injury is detected, promptly interrupt pioglitazone and assess patient for probable cause, then treat cause if possible, to resolution or stabilization. Do not restart pioglitazone if liver injury is confirmed and no alternate etiology can be found. (5.3) Bladder cancer: May increase the risk of bladder cancer. Do not use in patients with active bladder cancer. Use caution when using in patients with a prior history of bladder cancer. (5.4) Edema: Dose-related edema may occur. (5.5) Fractures: Increased incidence in female patients. Apply current standards of care for assessing and maintaining bone health. (5.6) Macular edema: Postmarketing reports. Recommend regular eye exams in all patients with diabetes according to current standards of care with prompt evaluation for acute visual changes. (5.7) Macrovascular outcomes: There have been no clinical studies establishing conclusive evidence of macrovascular risk reduction with pioglitazone. ( 5.8 ) 5.1 Congestive Heart Failure Pioglitazone, like other thiazolidinediones, can cause dose-related fluid retention when used alone or in combination with other antidiabetic medications and is most common when pioglitazone is used in combination with insulin. Fluid retention may lead to or exacerbate congestive heart failure. Patients should be observed for signs and symptoms of congestive heart failure. If congestive heart failure develops, it should be managed according to current standards of care and discontinuation or dose reduction of pioglitazone must be considered [see Boxed Warning , Contraindications (4) , and Adverse Reactions (6.1) ] . 5.2 Hypoglycemia Patients receiving pioglitazone in combination with insulin or other antidiabetic medications (particularly insulin secretagogues such as sulfonylureas) may be at risk for hypoglycemia. …"},{"title":"อาการไม่พึงประสงค์","body":"The following serious adverse reactions are discussed elsewhere in the labeling: Congestive heart failure [see Boxed Warning and Warnings and Precautions (5.1) ] Edema [see Warnings and Precautions (5.5) ] Fractures [see Warnings and Precautions (5.6) ] Most common adverse reactions (≥5%) are upper respiratory tract infection, headache, sinusitis, myalgia, and pharyngitis. (6.1) To report SUSPECTED ADVERSE REACTIONS, contact Aurobindo Pharma USA, Inc. at 1-866-850-2876 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch . 6.1 Clinical Trials Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical trials of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in practice. Over 8500 patients with type 2 diabetes have been treated with pioglitazone in randomized, double-blind, controlled clinical trials, including 2605 patients with type 2 diabetes and macrovascular disease treated with pioglitazone in the PROactive clinical trial. In these trials, over 6000 patients have been treated with pioglitazone for six months or longer, over 4500 patients have been treated with pioglitazone for one year or longer, and over 3000 patients have been treated with pioglitazone for at least two years. In six pooled 16- to 26-week placebo-controlled monotherapy and 16- to 24-week add-on combination therapy trials, the incidence of withdrawals due to adverse events was 4.5% for patients treated with pioglitazone and 5.8% for comparator-treated patients. The most common adverse events leading to withdrawal were related to inadequate glycemic control, although the incidence of these events was lower (1.5%) with pioglitazone than with placebo (3%). In the PROactive trial, the incidence of withdrawals due to adverse events was 9% for patients treated with pioglitazone and 7.7% for placebo-treated patients. Congestive heart failure was the most common serious adverse event leading to withdrawal occurring in 1.3% of patients treated with pioglitazone and 0.6% of patients treated with placebo. Common Adverse Events: 16- to 26-Week Monotherapy Trials A summary of the incidence and type of common adverse events reported in three pooled 16- to 26-week placebo-controlled monotherapy trials of pioglitazone is provided in Table 1. …"},{"title":"Drug interaction","body":"Strong CYP2C8 inhibitors (e.g., gemfibrozil) increase pioglitazone concentrations. Limit pioglitazone dose to 15 mg daily. (2.3 , 7.1) CYP2C8 inducers (e.g., rifampin) may decrease pioglitazone concentrations. (7.2) Topiramate may decrease pioglitazone concentrations. ( 7.3 ) 7.1 Strong CYP2C8 Inhibitors An inhibitor of CYP2C8 (e.g., gemfibrozil) significantly increases the exposure (area under the serum concentration-time curve or AUC) and half-life (t 1/2 ) of pioglitazone. Therefore, the maximum recommended dose of pioglitazone is 15 mg daily if used in combination with gemfibrozil or other strong CYP2C8 inhibitors [see Dosage and Administration (2.3) and Clinical Pharmacology (12.3) ]. 7.2 CYP2C8 Inducers An inducer of CYP2C8 (e.g., rifampin) may significantly decrease the exposure (AUC) of pioglitazone. Therefore, if an inducer of CYP2C8 is started or stopped during treatment with pioglitazone, changes in diabetes treatment may be needed based on clinical response without exceeding the maximum recommended daily dose of 45 mg for pioglitazone [see Clinical Pharmacology (12.3) ] . 7.3 Topiramate A decrease in the exposure of pioglitazone and its active metabolites were noted with concomitant administration of pioglitazone and topiramate [see Clinical Pharmacology (12.3) ] . The clinical relevance of this decrease is unknown; however, when pioglitazone and topiramate are used concomitantly, monitor patients for adequate glycemic control."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Limited data with pioglitazone in pregnant women are not sufficient to determine a drug-associated risk for major birth defects or miscarriage. There are risks to the mother and fetus associated with poorly controlled diabetes in pregnancy [see Clinical Considerations] . In animal reproduction studies, no adverse developmental effects were observed when pioglitazone was administered to pregnant rats and rabbits during organogenesis at exposures up to 5- and 35-times the 45 mg clinical dose, respectively, based on body surface area [see Data] . The estimated background risk of major birth defects is 6 to 10% in women with pre-gestational diabetes with a HbA1c >7 and has been reported to be as high as 20 to 25% in women with a HbA1c >10. The estimated background risk of miscarriage for the indicated population is unknown. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2 to 4% and 15 to 20%, respectively. Clinical Considerations Disease-associated maternal and/or embryo/fetal risk Poorly controlled diabetes in pregnancy increases the maternal risk for diabetic ketoacidosis, pre-eclampsia, spontaneous abortions, preterm delivery, still birth and delivery complications. Poorly controlled diabetes increases the fetal risk for major birth defects, still birth, and macrosomia related morbidity. Data Animal Data Pioglitazone administered to pregnant rats during organogenesis did not cause adverse developmental effects at a dose of 20 mg/kg (~5-times the 45 mg clinical dose), but delayed parturition and reduced embryofetal viability at 40 and 80 mg/kg, or ≥9-times the 45 mg clinical dose, by body surface area. In pregnant rabbits administered pioglitazone during organogenesis, no adverse developmental effects were observed at 80 mg/kg (~35-times the 45 mg clinical dose), but reduced embryofetal viability at 160 mg/kg, or ~69-times the 45 mg clinical dose, by body surface area. When pregnant rats received pioglitazone during late gestation and lactation, delayed postnatal development, attributed to decreased body weight, occurred in offspring at maternal doses of 10 mg/kg and above or ≥2 times the 45 mg clinical dose, by body surface area. …"},{"title":"การได้รับยาเกินขนาด","body":"During controlled clinical trials, one case of overdose with pioglitazone was reported. A male patient took 120 mg per day for four days, then 180 mg per day for seven days. The patient denied any clinical symptoms during this period. In the event of overdosage, appropriate supportive treatment should be initiated according to the patient’s clinical signs and symptoms."}]},
{"key":"povidone-iodine|TOPICAL","generic":"povidone-iodine","route":"TOPICAL","brand":null,"title":"First Aid Antiseptic","set_id":"193292da-390b-4430-91b1-1d159ac50507","effective":"20260219","sections":[{"title":"ข้อบ่งใช้","body":"first aid to help prevent the risk of infection in: minor cuts scrapes burns"},{"title":"ขนาดยาและวิธีใช้","body":"clean the affected area apply a small amount of this product on the area 1 to 3 times daily may be covered with a sterile bandage if bandaged, let dry first"},{"title":"ข้อห้ามใช้","body":"in the eyes or aply over large areas of the body longer than 1 week unless directed by a doctor"},{"title":"คำเตือนและข้อควรระวัง","body":"For external use only wounds, animal bites, or serious burns worse"},{"title":"อาการไม่พึงประสงค์","body":"Adverse Reaction DISTRIBUTED BY MEIJER DISTRIBUTION, INC. GRAND RAPIDS, MI 49544 www.meijer.com OUR QUALITY GUARANTEE The Meijer Family www.meijer.com/satisfaction PID 314823"},{"title":"การเก็บรักษา","body":"Other information store between 15°-30°C (59°-86°F)"}]},
{"key":"propranolol hydrochloride|ORAL","generic":"propranolol hydrochloride","route":"ORAL","brand":null,"title":"Propranolol Hydrochloride","set_id":"015b5e4f-3228-4259-b419-e0e49694a058","effective":"20250919","sections":[{"title":"ข้อบ่งใช้","body":"Hypertension Propranolol Hydrochloride Extended-Release Capsules, USP, are indicated in the management of hypertension. They may be used alone or used in combination with other antihypertensive agents, particularly a thiazide diuretic. Propranolol Hydrochloride Extended-Release Capsules, USP, are not indicated in the management of hypertensive emergencies. Angina Pectoris Due to Coronary Atherosclerosis Propranolol Hydrochloride Extended-Release Capsules, USP, are indicated to decrease angina frequency and increase exercise tolerance in patients with angina pectoris. Migraine Propranolol Hydrochloride Extended-Release Capsules, USP, are indicated for the prophylaxis of common migraine headache. The efficacy of propranolol in the treatment of a migraine attack that has started has not been established, and propranolol is not indicated for such use. Hypertrophic Subaortic Stenosis Propranolol Hydrochloride Extended-Release Capsules, USP, improve NYHA functional class in symptomatic patients with hypertrophic subaortic stenosis."},{"title":"ขนาดยาและวิธีใช้","body":"General Propranolol Hydrochloride Extended-Release Capsules, USP, provide propranolol hydrochloride in a sustained-release capsule for administration once daily. If patients are switched from propranolol hydrochloride tablets to Propranolol Hydrochloride Extended-Release Capsules, USP, care should be taken to assure that the desired therapeutic effect is maintained. Propranolol Hydrochloride Extended-Release Capsules, USP, should not be considered a simple mg-for-mg substitute for propranolol hydrochloride tablets. Propranolol Hydrochloride Extended-Release Capsules, USP, have different kinetics and produces lower blood levels. Retitration may be necessary, especially to maintain effectiveness at the end of the 24-hour dosing interval. Hypertension The usual initial dosage is 80 mg Propranolol Hydrochloride Extended-Release Capsules, USP, once daily, whether used alone or added to a diuretic. The dosage may be increased to 120 mg once daily or higher until adequate blood pressure control is achieved. The usual maintenance dosage is 120 to 160 mg once daily. In some instances a dosage of 640 mg may be required. The time needed for full hypertensive response to a given dosage is variable and may range from a few days to several weeks. Angina Pectoris Starting with 80 mg Propranolol Hydrochloride Extended-Release Capsules, USP, once daily, dosage should be gradually increased at three- to seven-day intervals until optimal response is obtained. Although individual patients may respond at any dosage level, the average optimal dosage appears to be 160 mg once daily. In angina pectoris, the value and safety of dosage exceeding 320 mg per day have not been established. If treatment is to be discontinued, reduce dosage gradually over a period of a few weeks (see WARNINGS ). Migraine The initial oral dose is 80 mg Propranolol Hydrochloride Extended-Release Capsules, USP, once daily. The usual effective dose range is 160 to 240 mg once daily. The dosage may be increased gradually to achieve optimal migraine prophylaxis. If a satisfactory response is not obtained within four to six weeks after reaching the maximal dose, Propranolol Hydrochloride Extended-Release Capsules, USP, therapy should be discontinued. It may be advisable to withdraw the drug gradually over a period of several weeks depending on the patient's age, comorbidity, and dose of Propranolol Hydrochloride Extended-Release Capsules, USP. …"},{"title":"ข้อห้ามใช้","body":"Propranolol is contraindicated in 1) cardiogenic shock; 2) sinus bradycardia and greater than first-degree block; 3) bronchial asthma; and 4) in patients with known hypersensitivity to propranolol hydrochloride."},{"title":"คำเตือนกรอบดำ","body":"Angina Pectoris There have been reports of exacerbation of angina and, in some cases, myocardial infarction, following abrupt discontinuance of propranolol therapy. Therefore, when discontinuance of propranolol is planned, the dosage should be gradually reduced over at least a few weeks, and the patient should be cautioned against interruption or cessation of therapy without the physician's advice. If propranolol therapy is interrupted and exacerbation of angina occurs, it usually is advisable to reinstitute propranolol therapy and take other measures appropriate for the management of unstable angina pectoris. Since coronary artery disease may be unrecognized, it may be prudent to follow the above advice in patients considered at risk of having occult atherosclerotic heart disease who are given propranolol for other indications."},{"title":"คำเตือนและข้อควรระวัง","body":"Angina Pectoris There have been reports of exacerbation of angina and, in some cases, myocardial infarction, following abrupt discontinuance of propranolol therapy. Therefore, when discontinuance of propranolol is planned, the dosage should be gradually reduced over at least a few weeks, and the patient should be cautioned against interruption or cessation of therapy without the physician's advice. If propranolol therapy is interrupted and exacerbation of angina occurs, it usually is advisable to reinstitute propranolol therapy and take other measures appropriate for the management of unstable angina pectoris. Since coronary artery disease may be unrecognized, it may be prudent to follow the above advice in patients considered at risk of having occult atherosclerotic heart disease who are given propranolol for other indications. Hypersensitivity and Skin Reactions Hypersensitivity reactions, including anaphylactic/anaphylactoid reactions, have been associated with the administration of propranolol (see ADVERSE REACTIONS ). Cutaneous reactions, including Stevens-Johnson Syndrome, toxic epidermal necrolysis, exfoliative dermatitis, erythema multiforme, and urticaria, have been reported with use of propranolol (see ADVERSE REACTIONS ). Cardiac Failure Sympathetic stimulation may be a vital component supporting circulatory function in patients with congestive heart failure, and its inhibition by beta blockade may precipitate more severe failure. Although beta-blockers should be avoided in overt congestive heart failure, some have been shown to be highly beneficial when used with close follow-up in patients with a history of failure who are well compensated and are receiving diuretics as needed. Beta-adrenergic blocking agents do not abolish the inotropic action of digitalis on heart muscle. In Patients without a History of Heart Failure , continued use of beta-blockers can, in some cases, lead to cardiac failure. Nonallergic Bronchospasm (e.g., Chronic Bronchitis, Emphysema) In general, patients with bronchospastic lung disease should not receive beta-blockers. Propranolol should be administered with caution in this setting since it may provoke a bronchial asthmatic attack by blocking bronchodilation produced by endogenous and exogenous catecholamine stimulation of beta-receptors. …"},{"title":"อาการไม่พึงประสงค์","body":"The following adverse events were observed and have been reported in patients using propranolol. Cardiovascular Bradycardia; congestive heart failure; intensification of AV block; hypotension; paresthesia of hands; thrombocytopenic purpura; arterial insufficiency, usually of the Raynaud type. Central Nervous System Light-headedness; mental depression manifested by insomnia, lassitude, weakness, fatigue; catatonia; visual disturbances; hallucinations; vivid dreams; an acute reversible syndrome characterized by disorientation for time and place, short-term memory loss, emotional lability, slightly clouded sensorium, and decreased performance on neuropsychometrics. For immediate release formulations, fatigue, lethargy, and vivid dreams appear dose related. Gastrointestinal: Nausea, vomiting, epigastric distress, abdominal cramping, diarrhea, constipation, mesenteric arterial thrombosis, ischemic colitis. Allergic: Hypersensitivity reactions, including anaphylactic/anaphylactoid reactions; pharyngitis and agranulocytosis; erythematous rash; fever combined with aching and sore throat; laryngospasm; respiratory distress. Respiratory: Bronchospasm. Hematologic: Agranulocytosis, nonthrombocytopenic purpura, thrombocytopenic purpura. Autoimmune: Systemic lupus erythematosus (SLE). Skin and Mucous Membranes: Stevens-Johnson Syndrome, toxic epidermal necrolysis, dry eyes, exfoliative dermatitis, erythema multiforme, urticaria, alopecia, SLE-like reactions, and psoriasiform rashes. Oculomucocutaneous syndrome involving the skin, serous membranes, and conjunctivae reported for a beta-blocker (practolol) have not been associated with propranolol. Genitourinary: Male impotence; Peyronie's disease."},{"title":"Drug interaction","body":"Caution should be exercised when Propranolol Hydrochloride Extended-Release Capsules, USP, are administered with drugs that have an affect on CYP2D6, 1A2, or 2C19 metabolic pathways. Co-administration of such drugs with propranolol may lead to clinically relevant drug interactions and changes on its efficacy and/or toxicity (see Drug Interactions in PHARMACOKINETICS AND DRUG METABOLISM ). Alcohol when used concomitantly with propranolol, may increase plasma levels of propranolol."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Pregnancy Category C In a series of reproductive and developmental toxicology studies, propranolol was given to rats by gavage or in the diet throughout pregnancy and lactation. At doses of 150 mg/kg/day, but not at doses of 80 mg/kg/day (equivalent to the MRHD on a body surface area basis), treatment was associated with embryotoxicity (reduced litter size and increased resorption rates) as well as neonatal toxicity (deaths). Propranolol hydrochloride also was administered (in the feed) to rabbits (throughout pregnancy and lactation) at doses as high as 150 mg/kg/day (about 5 times the maximum recommended human oral daily dose). No evidence of embryo or neonatal toxicity was noted. There are no adequate and well-controlled studies in pregnant women. Intrauterine growth retardation, small placentas, and congenital abnormalities have been reported in neonates whose mothers received propranolol during pregnancy. Neonates whose mothers are receiving propranolol at parturition have exhibited bradycardia, hypoglycemia and/or respiratory depression. Adequate facilities for monitoring such infants at birth should be available. Propranolol Hydrochloride Extended-Release Capsules, USP, should be used during pregnancy only if the potential benefit justifies the potential risk to the fetus. Propranolol is excreted in human milk. Caution should be exercised when Propranolol Hydrochloride Extended-Release Capsules, USP, are administered to a nursing woman. Safety and effectiveness of propranolol in pediatric patients have not been established. Bronchospasm and congestive heart failure have been reported coincident with the administration of propranolol therapy in pediatric patients. Clinical studies of Propranolol Hydrochloride Extended-Release Capsules, USP, did not include sufficient numbers of subjects aged 65 and over to determine whether they respond differently from younger subjects. Other reported clinical experience has not identified differences in responses between the elderly and younger patients. In general, dose selection for an elderly patient should be cautious, usually starting at the low end of the dosing range, reflecting the greater frequency of the decreased hepatic, renal or cardiac function, and of concomitant disease or other drug therapy."},{"title":"การได้รับยาเกินขนาด","body":"Propranolol is not significantly dialyzable. In the event of overdosage or exaggerated response, the following measures should be employed: General If ingestion is or may have been recent, evacuate gastric contents, taking care to prevent pulmonary aspiration. Supportive Therapy Hypotension and bradycardia have been reported following propranolol overdose and should be treated appropriately. Glucagon can exert potent inotropic and chronotropic effects and may be particularly useful for the treatment of hypotension or depressed myocardial function after a propranolol overdose. Glucagon should be administered as 50-150 mcg/kg intravenously followed by continuous drip of 1-5 mg/hour for positive chronotropic effect. Isoproterenol, dopamine or phosphodiesterase inhibitors may also be useful. Epinephrine, however, may provoke uncontrolled hypertension. Bradycardia can be treated with atropine or isoproterenol. Serious bradycardia may require temporary cardiac pacing. The electrocardiogram, pulse, blood pressure, neurobehavioral status and intake and output balance must be monitored. Isoproterenol and aminophylline may be used for bronchospasm."},{"title":"การเก็บรักษา","body":"Store at 20° to 25°C (68° to 77°F); excursions permitted to 15° to 30°C (59° to 86°F) [see USP Controlled Room Temperature]. Protect from light, moisture, freezing, and excessive heat. FOR YOUR PROTECTION: Do not use if blister is torn or broken. Propranolol Hydrochloride Extended-Release Capsules, USP, a DIFFUCAPS ® drug delivery product, manufactured by Adare Pharmaceuticals, Inc. You can also ask your doctor or pharmacist for information about Propranolol Hydrochloride Extended-Release Capsules, USP that is written for healthcare professionals. For more information about the drug product, call 1-800-367-3395 or go to www.breckenridgepharma.com. For more information about the packaging or labeling, call American Health Packaging at 1‐800‐707‐4621."}]},
{"key":"propylthiouracil|ORAL","generic":"propylthiouracil","route":"ORAL","brand":null,"title":"Propylthiouracil","set_id":"b0c23a2c-b250-4c0d-9b2a-c1483faa2ca0","effective":"20260825","sections":[{"title":"ข้อบ่งใช้","body":"Propylthiouracil is indicated: in patients with Graves’ disease with hyperthyroidism or toxic multinodular goiter who are intolerant of methimazole and for whom surgery or radioactive iodine therapy is not an appropriate treatment option to ameliorate symptoms of hyperthyroidism in preparation for thyroidectomy or radioactive iodine therapy in patients who are intolerant of methimazole"},{"title":"ขนาดยาและวิธีใช้","body":"Propylthiouracil is administered orally. The total daily dosage is usually given in 3 equal doses at approximately 8-hour intervals. Adults The initial dose is 300 mg daily. In patients with severe hyperthyroidism, very large goiters, or both, the initial dose may be increased to 400 mg daily; an occasional patient will require 600 to 900 mg daily initially. The usual maintenance dose is 100 to 150 mg daily. Pediatric Patients Propylthiouracil is generally not recommended for use in the pediatric patient population except in rare instances in which other alternative therapies are not appropriate options. Studies evaluating appropriate dosing regimen have not been conducted in the pediatric population although general practice would suggest initiation of therapy in patients 6 years or older at a dosage of 50 mg daily with careful upward titration based on clinical response and evaluation of TSH and free T4 levels. Although cases of severe liver injury have been reported with doses as low as 50 mg/day, most cases were associated with doses of 300 mg/day and higher. Geriatric Patients Clinical studies of propylthiouracil did not include sufficient numbers of subjects aged 65 or over to determine whether they respond differently from younger subjects. Other reported clinical experience has not identified differences in responses between the elderly and younger patients. In general, dose selection for an elderly patient should be cautious reflecting the greater frequency of decreased hepatic, renal, or cardiac function, and of concomitant disease or other drug therapy."},{"title":"ข้อห้ามใช้","body":"Propylthiouracil is contraindicated in patients who have demonstrated hypersensitivity to the drug or any of the other product components."},{"title":"คำเตือนกรอบดำ","body":"WARNING Severe liver injury and acute liver failure, in some cases fatal, have been reported in patients treated with propylthiouracil. These reports of hepatic reactions include cases requiring liver transplantation in adult and pediatric patients. Propylthiouracil should be reserved for patients who cannot tolerate methimazole and in whom radioactive iodine therapy or surgery are not appropriate treatments for the management of hyperthyroidism. Propylthiouracil may be the treatment of choice when an antithyroid drug is indicated during or just prior to the first trimester of pregnancy (see Warnings and Precautions )."},{"title":"คำเตือนและข้อควรระวัง","body":"Liver Toxicity Liver injury resulting in liver failure, liver transplantation, or death, has been reported with propylthiouracil therapy in adult and pediatric patients. No cases of liver failure have been reported with the use of methimazole in pediatric patients. For this reason, propylthiouracil is not recommended for pediatric patients except when methimazole is not well-tolerated and surgery or radioactive iodine therapy are not appropriate therapies. Biochemical monitoring of liver function (bilirubin, alkaline phosphatase) and hepatocellular integrity (ALT, AST) is not expected to attenuate the risk of severe liver injury due to its rapid and unpredictable onset. Patients should be informed of the risk of liver failure. Patients should be instructed to report any symptoms of hepatic dysfunction (anorexia, pruritus, right upper quadrant pain, etc.), particularly in the first six months of therapy. When these symptoms occur, propylthiouracil should be discontinued immediately and liver function tests and ALT and AST levels obtained. Use in Pregnancy There are cases of liver injury, including liver failure and death, in women treated with propylthiouracil during pregnancy. Two reports of in utero exposure with liver failure and death of a newborn have been reported. If propylthiouracil is used during pregnancy, or if the patient becomes pregnant while taking propylthiouracil, the patient should be warned of the rare potential hazard to the mother and fetus of liver damage. Propylthiouracil crosses the placenta and can cause fetal goiter and cretinism when administered to a pregnant woman (see Precautions, Pregnancy ). After the first trimester of pregnancy, the use of an alternative antithyroid medication may be advisable (see Precautions, Pregnancy ). Agranulocytosis Agranulocytosis occurs in approximately 0.2% to 0.5% of patients and is a potentially life-threatening side effect of propylthiouracil therapy. Agranulocytosis typically occurs within the first 3 months of therapy. Patients should be instructed to immediately report any symptoms suggestive of agranulocytosis, such as fever or sore throat. Leukopenia, thrombocytopenia, and aplastic anemia (pancytopenia) may also occur. Propylthiouracil should be discontinued if agranulocytosis, aplastic anemia (pancytopenia) is suspected, and the patient's bone marrow indices should be obtained. …"},{"title":"อาการไม่พึงประสงค์","body":"The following adverse reactions have been reported with the use of propylthiouracil. Because these events generally come from voluntary reporting from a population of uncertain size, it is not possible to reliably estimate their frequency or establish a causal relationship to drug exposure. Severe adverse reactions include liver injury presenting as hepatitis, liver failure necessitating liver transplantation or resulting in death (see WARNINGS ). Inhibition of myelopoiesis (agranulocytosis, granulopenia, aplastic anemia, and thrombocytopenia), drug fever, a lupus-like syndrome (including splenomegaly and vasculitis), periarteritis, hypoprothrombinemia, and bleeding have been reported. Nephritis, glomerulonephritis, interstitial pneumonitis, exfoliative dermatitis, and erythema nodosum have also been reported. There are reports of a vasculitis associated with the presence of anti-neutrophilic cytoplasmic antibodies (ANCA), resulting in severe complications and death (see WARNINGS ). There have been rare reports of serious hypersensitivity reactions (e.g., Stevens Johnson syndrome and toxic epidermal necrolysis) in patients treated with propylthiouracil. Other adverse reactions include skin rash, uticaria, nausea, vomiting, epigastric distress, arthralgia, paresthesias, loss of taste, taste perversion, abnormal loss of hair, myalgia, headache, pruritus, drowsiness, neuritis, edema, vertigo, skin pigmentation, jaundice, sialadenopathy, and lymphadenopathy."},{"title":"Drug interaction","body":"Anticoagulants (oral) : Due to the potential inhibition of vitamin K activity by propylthiouracil, the activity of oral anticoagulants (e.g., warfarin) may be increased; additional monitoring of PT/INR should be considered, especially before surgical procedures. Beta-adrenergic blocking agents: Hyperthyroidism may cause an increased clearance of beta blockers with a high extraction ratio. A reduced dose of beta-adrenergic blockers may be needed when a hyperthyroid patient becomes euthyroid. Digitalis glycosides: Serum digitalis levels may be increased when hyperthyroid patients on a stable digitalis glycoside regimen become euthyroid; a reduced dose of digitalis glycosides may be needed. Theophylline: Theophylline clearance may decrease when hyperthyroid patients on a stable theophylline regimen become euthyroid; a reduced dose of theophylline may be needed."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Use in Pregnancy There are cases of liver injury, including liver failure and death, in women treated with propylthiouracil during pregnancy. Two reports of in utero exposure with liver failure and death of a newborn have been reported. If propylthiouracil is used during pregnancy, or if the patient becomes pregnant while taking propylthiouracil, the patient should be warned of the rare potential hazard to the mother and fetus of liver damage. Propylthiouracil crosses the placenta and can cause fetal goiter and cretinism when administered to a pregnant woman (see Precautions, Pregnancy ). After the first trimester of pregnancy, the use of an alternative antithyroid medication may be advisable (see Precautions, Pregnancy ). Pregnancy Pregnancy Category D. See WARNINGS . In pregnant women with untreated or inadequately treated Graves’ disease, there is an increased risk of adverse events of maternal heart failure, spontaneous abortion, preterm birth, stillbirth and fetal or neonatal hyperthyroidism. If propylthiouracil is used during pregnancy, or if the patient becomes pregnant while taking propylthiouracil, the patient should be warned of the rare potential hazard to the mother and fetus of liver damage. Because propylthiouracil crosses placental membranes and can induce goiter and cretinism in the developing fetus, it is important that a sufficient, but not excessive, dose be given during pregnancy. In many pregnant women, the thyroid dysfunction diminishes as the pregnancy proceeds; consequently a reduction of dosage may be possible. In some instances, antithyroid therapy can be discontinued several weeks or months prior to delivery. Since methimazole may be associated with the rare development of fetal abnormalities propylthiouracil may be the preferred agent during the first trimester of pregnancy. Given the potential for maternal hepatotoxicity from propylthiouracil, it may be preferable to switch from propylthiouracil to methimazole for the second and third trimesters during pregnancy. Propylthiouracil is present in breast milk to a small extent and therefore likely results in clinically insignificant doses to the nursing infant. In one study, nine lactating women were administered 400 mg of propylthiouracil by mouth. The mean amount of propylthiouracil excreted during 4 hours after drug administration was 0.025% of the administered dose. …"},{"title":"การได้รับยาเกินขนาด","body":"Signs and Symptoms Nausea, vomiting, epigastric distress, headache, fever, arthralgia, pruritus, edema, and pancytopenia. Agranulocytosis is the most serious effect. Rarely, exfoliative dermatitis, hepatitis, neuropathies or CNS stimulation or depression may occur. No information is available on the following: LD 50 ; concentration of propylthiouracil in biologic fluids associated with toxicity and/or death; the amount of drug in a single dose usually associated with symptoms of overdosage; or the amount of propylthiouracil in a single dose likely to be life-threatening. Treatment To obtain up-to-date information about the treatment of overdose, a good resource is the certified Regional Poison Control Center. In managing overdosage, consider the possibility of multiple drug overdoses, interaction among drugs, and unusual drug kinetics in the patient. In the event of an overdose, appropriate supportive treatment should be initiated as dictated by the patient’s medical status."}]},
{"key":"silver sulfadiazine|TOPICAL","generic":"silver sulfadiazine","route":"TOPICAL","brand":null,"title":"SILVER SULFADIAZINE","set_id":"7a6a9590-9983-46ff-ae5c-fe95f4e16cb8","effective":"20251226","sections":[{"title":"ข้อบ่งใช้","body":"Silver Sulfadiazine Cream 1% is a topical antimicrobial drug indicated as an adjunct for the prevention and treatment of wound sepsis in patients with second- and third-degree burns."},{"title":"ขนาดยาและวิธีใช้","body":"Prompt institution of appropriate regimens for care of the burned patient is of prime importance and includes the control of shock and pain. The burn wounds are then cleansed and debrided, and silver sulfadiazine cream 1% is applied under sterile conditions. The burn areas should be covered with silver sulfadiazine cream 1% at all times. The cream should be applied once to twice daily to a thickness of approximately 1/16 inch. Whenever necessary, the cream should be reapplied to any areas from which it has been removed by patient activity. Administration may be accomplished in minimal time because dressings are not required. However, if individual patient requirements make dressings necessary, they may be used. Reapply immediately after hydrotherapy. Treatment with silver sulfadiazine cream 1% should be continued until satisfactory healing has occurred, or until the burn site is ready for grafting. The drug should not be withdrawn from the therapeutic regimen while there remains the possibility of infection except if a significant adverse reaction occurs."},{"title":"ข้อห้ามใช้","body":"Silver Sulfadiazine Cream 1% is contraindicated in patients who are hypersensitive to silver sulfadiazine or any of the other ingredients in the preparation. Because sulfonamide therapy is known to increase the possibility of kernicterus, silver sulfadiazine cream 1% should not be used on pregnant women approaching or at term, on premature infants, or on newborn infants during the first 2 months of life."},{"title":"คำเตือนและข้อควรระวัง","body":"Absorption of silver sulfadiazine varies depending upon the percent of body surface area and the extent of the tissue damage. Although few have been reported, it is possible that any adverse reaction associated with sulfonamides may occur. Some of the reactions, which have been associated with sulfonamides, are as follows: blood dyscrasias including agranulocytosis, aplastic anemia, thrombocytopenia, leukopenia, and hemolytic anemia; dermatologic and allergic reactions, including life-threatening cutaneous reactions [Stevens-Johnson syndrome (SJS), toxic epidermal necrolysis (TEN) and exfoliative dermatitis]; gastrointestinal reactions; hepatitis and hepatocellular necrosis; CNS reactions; and toxic nephrosis. There is potential cross-sensitivity between silver sulfadiazine and other sulfonamides. If allergic reactions attributable to treatment with silver sulfadiazine occur, continuation of therapy must be weighed against the potential hazards of the particular allergic reaction. Fungal proliferation in and below the eschar may occur. However, the incidence of clinically reported fungal superinfection is low. The use of silver sulfadiazine cream 1% in some cases of glucose-6-phosphate dehydrogenase-deficient individuals may be hazardous, as hemolysis may occur. General If hepatic and renal functions become impaired and elimination of drug decreases, accumulation may occur, and discontinuation of silver sulfadiazine cream 1% should be weighed against the therapeutic benefit being achieved. In considering the use of topical proteolytic enzymes in conjunction with silver sulfadiazine cream 1%, the possibility should be noted that silver may inactivate such enzymes. Silver Sulfadiazine Cream 1% is for topical use only. Avoid contact of silver sulfadiazine cream 1% with the eye. Laboratory Tests In the treatment of burn wounds involving extensive areas of the body, the serum sulfa concentrations may approach adult therapeutic levels (8 mg% to 12 mg%). Therefore, in these patients it would be advisable to monitor serum sulfa concentrations. Renal function should be carefully monitored and the urine should be checked for sulfa crystals. Absorption of the propylene glycol vehicle has been reported to affect serum osmolality, which may affect the interpretation of laboratory tests. …"},{"title":"อาการไม่พึงประสงค์","body":"Several cases of transient leukopenia have been reported in patients receiving silver sulfadiazine therapy. 1,2,3 Leukopenia associated with silver sulfadiazine administration is primarily characterized by decreased neutrophil count. Maximal white blood cell depression occurs within 2 to 4 days of initiation of therapy. Rebound to normal leukocyte levels follows onset within 2 to 3 days. Recovery is not influenced by continuation of silver sulfadiazine therapy. An increased incidence of leukopenia has been reported in patients treated concurrently with cimetidine. Other infrequently occurring events include skin necrosis, erythema multiforme, skin discoloration, burning sensation, rashes, and interstitial nephritis. Reduction in bacterial growth after application of topical antibacterial agents has been reported to permit spontaneous healing of deep partial-thickness burns by preventing conversion of the partial thickness to full thickness by sepsis. However, reduction in bacterial colonization has caused delayed separation, in some cases necessitating escharotomy in order to prevent contracture."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Teratogenic Effects. A reproductive study has been performed in rabbits at doses up to three to ten times the concentration of silver sulfadiazine in silver sulfadiazine cream 1% and has revealed no evidence of harm to the fetus due to silver sulfadiazine. There are, however, no adequate and well-controlled studies in pregnant women. Because animal reproduction studies are not always predictive of human response, this drug should be used during pregnancy only if clearly justified, especially in pregnant women approaching or at term (see CONTRAINDICATIONS ). It is not known whether silver sulfadiazine is excreted in human milk. However, sulfonamides are known to be excreted in human milk, and all sulfonamide derivatives are known to increase the possibility of kernicterus. Because of the possibility for serious adverse reactions in nursing infants from sulfonamides, a decision should be made whether to discontinue nursing or to discontinue the drug, taking into account the importance of the drug to the mother. Safety and effectiveness in pediatric patients have not been established (see CONTRAINDICATIONS ). Of the total number of subjects in clinical studies of silver sulfadiazine cream 1%, seven percent were 65 years of age and over. No overall differences in safety or effectiveness were observed between these subjects and younger subjects, and other reported clinical experience has not identified differences in responses between the elderly and younger patients, but greater sensitivity of some older individuals cannot be ruled out."},{"title":"การเก็บรักษา","body":"Store at Controlled Room Temperature 20° to 25°C (68° to 77°F)."}]},
{"key":"simethicone|ORAL","generic":"simethicone","route":"ORAL","brand":null,"title":"Simethicone","set_id":"0f9639fa-e1d0-460d-bc46-714a01cd9811","effective":"20241121","sections":[{"title":"ข้อบ่งใช้","body":"for relief of: bloating pressure fullness stuffed feeling commonly referred to as gas"},{"title":"ขนาดยาและวิธีใช้","body":"adults: swallow with water 1 or 2 softgels as needed after meals or at bedtime do not exceed 4 softgels per day unless directed by doctor"},{"title":"คำเตือนและข้อควรระวัง","body":"Stop use and ask a doctor if condition persists. If pregnant or breast-feeding, ask a health care professional before use. Keep out of reach of children. In case of overdose, get medical help or contact a Poison Control Center right away. persists."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"ask a health care professional before use."},{"title":"การได้รับยาเกินขนาด","body":"In case of overdose, get medical help or contact a Poison Control Center right away."},{"title":"การเก็บรักษา","body":"Other information store at controlled room temperature 15°-30°C (59°-86°F) protect from heat and moisture do not use if imprinted safety seal under cap is broken or missing"}]},
{"key":"simvastatin|ORAL","generic":"simvastatin","route":"ORAL","brand":null,"title":"SIMVASTATIN","set_id":"00896fff-081d-4553-be8c-1999a8a73dda","effective":"20260226","sections":[{"title":"ข้อบ่งใช้","body":"Simvastatin tablets USP are indicated: To reduce the risk of total mortality by reducing risk of coronary heart disease death, non-fatal myocardial infarction and stroke, and the need for coronary and non-coronary revascularization procedures in adults with established coronary heart disease, cerebrovascular disease, peripheral vascular disease, and/or diabetes, who are at high risk of coronary heart disease events. As an adjunct to diet to reduce low-density lipoprotein cholesterol (LDL-C): In adults with primary hyperlipidemia. In adults and pediatric patients aged 10 years and older with heterozygous familial hypercholesterolemia (HeFH). As an adjunct to other LDL-C-lowering therapies to reduce LDL-C in adults with homozygous familial hypercholesterolemia (HoFH). As an adjunct to diet for the treatment of adults with: Primary dysbetalipoproteinemia. Hypertriglyceridemia. Simvastatin tablets USP are an HMG-CoA reductase inhibitor indicated: To reduce the risk of total mortality by reducing risk of coronary heart disease death, non-fatal myocardial infarction and stroke, and the need for coronary and non-coronary revascularization procedures in adults with established coronary heart disease, cerebrovascular disease, peripheral vascular disease, and/or diabetes, who are at high risk of coronary heart disease events. As an adjunct to diet to reduce low-density lipoprotein cholesterol (LDL-C): In adults with primary hyperlipidemia. In adults and pediatric patients aged 10 years and older with heterozygous familial hypercholesterolemia (HeFH). As an adjunct to other LDL-C-lowering therapies to reduce LDL-C in adults with homozygous familial hypercholesterolemia (HoFH). As an adjunct to diet for the treatment of adults with: Primary dysbetalipoproteinemia. Hypertriglyceridemia."},{"title":"ขนาดยาและวิธีใช้","body":"Important Dosage and Administration Information : ( 1 ) Take simvastatin tablets USP orally once daily in the evening. Maximum recommended dosage is simvastatin tablets USP 40 mg once daily. An 80 mg daily dosage of simvastatin tablets USP is restricted to patients who have been taking simvastatin tablets USP 80 mg daily chronically (e.g., for 12 months or more) without evidence of muscle toxicity. For patients that require a high-intensity statin or are unable to achieve their LDL-C goal receiving simvastatin tablets USP 40 mg daily, prescribe alternative LDL-C lowering treatment. Assess LDL-C when clinically appropriate, as early as 4 weeks after initiating, and adjust the dosage if necessary. Adults : Recommended dosage is 20 mg to 40 mg once daily. ( 2.2 ) Pediatric Patients Aged 10 Years and Older with HeFH : Recommended dosage is 10 mg to 40 mg once daily. ( 2.3 ) Patients with Severe Renal Impairment : Recommended starting dosage is simvastatin 5 mg once daily. ( 2.4 , 8.6 ) See full prescribing information for simvastatin tablets USP dosage modifications due to drug interactions. ( 2.5 ) 2.1 Important Dosage and Administration Information Take simvastatin tablets USP orally once daily in the evening. The maximum recommended dosage is simvastatin tablets USP 40 mg once daily [see DOSAGE AND ADMINISTRATION ( 2.2 , 2.3 )]. An 80 mg daily dosage of simvastatin tablets USP is restricted to patients who have been taking simvastatin tablets USP 80 mg daily chronically (e.g., for 12 months or more) without evidence of muscle toxicity [see WARNINGS AND PRECAUTIONS ( 5.1 )]. If as dose is missed, take the missed dose as soon as possible. Do not double the next dose. For patients that require a high-intensity statin or are unable to achieve their LDL-C goal receiving simvastatin tablets USP 40 mg daily, prescribe alternative LDL-C-lowering treatment. Assess LDL-C when clinically appropriate, as early as 4 weeks after initiating simvastatin tablets USP, and adjust the dosage if necessary. 2.2 Recommended Dosage in Adult Patients The recommended dosage range of simvastatin tablets USP is 20 mg to 40 mg once daily 2.3 Recommended Dosage in Pediatric Patients 10 Years of Age and Older with HeFH The recommended dosage range of simvastatin tablets USP is 10 mg to 40 mg daily. …"},{"title":"ข้อห้ามใช้","body":"Simvastatin is contraindicated in the following conditions: Concomitant use of strong CYP3A4 inhibitors (select azole anti-fungals, macrolide antibiotics, anti-viral medications, and nefazodone) [see DRUG INTERACTIONS ( 7.1 )]. Concomitant use of cyclosporine, danazol or gemfibrozil [see DRUG INTERACTIONS ( 7.1 )]. Acute liver failure or decompensated cirrhosis [see WARNINGS AND PRECAUTIONS ( 5.3 )] Hypersensitivity to simvastatin or any excipients in simvastatin tablets USP. Hypersensitivity reactions, including anaphylaxis, angioedema and Stevens-Johnson syndrome, have been reported [see ADVERSE REACTIONS ( 6.2 )] Concomitant use of strong CYP3A4 inhibitors (select azole anti-fungals, macrolide antibiotics, anti-viral medications, and nefazodone) ( 4 , 7.1 ) Concomitant use of cyclosporine, danazol or gemfibrozil ( 4 , 7.1 ) Acute liver failure or decompensated cirrhosis ( 4 , 5.3 ) Hypersensitivity to simvastatin or any excipient in simvastatin tablets USP ( 4 , 6.2 )"},{"title":"คำเตือนและข้อควรระวัง","body":"Myopathy and Rhabdomyolysis: Risk factors include age 65 years or greater, uncontrolled hypothyroidism, renal impairment, concomitant use with certain other drugs, and higher simvastatin dosage. Chinese patients may be at higher risk for myopathy. Discontinue simvastatin if markedly elevated CK levels occur or myopathy is diagnosed or suspected. Temporarily discontinue simvastatin in patients experiencing an acute or serious condition at high risk of developing renal failure secondary to rhabdomyolysis. Inform patients of the risk of myopathy and rhabdomyolysis when starting or increasing simvastatin dosage. Instruct patients to promptly report unexplained muscle pain, tenderness, or weakness, particularly if accompanied by malaise or fever. ( 5.1 , 7.1 , 8.5 , 8.6 , 8.8 ) Immune-Mediated Necrotizing Myopathy (IMNM): Rare reports of IMNM, an autoimmune myopathy, have been reported. Discontinue simvastatin if IMNM is suspected. ( 5.2 ) Hepatic Dysfunction: Increases in serum transaminases have occurred, some persistent. Rare reports of fatal and non-fatal hepatic failure have occurred. Consider testing liver enzyme before initiating therapy and as clinically indicated thereafter. If serious hepatic injury with clinical symptoms and/or hyperbilirubinemia or jaundice occurs, promptly discontinue simvastatin. ( 4 , 5.3 , 8.7 ) 5.1 Myopathy and Rhabdomyolysis Simvastatin may cause myopathy and rhabdomyolysis. Acute kidney injury secondary to myoglobinuria and rare fatalities have occurred as a result of rhabdomyolysis in patients treated with statins, including simvastatin. In clinical studies of 24,747 simvastatin -treated patients with a median follow-up of 4 years, the incidence of myopathy, defined as unexplained muscle weakness, pain, or tenderness accompanied by creatinine kinase (CK) increases greater than ten times the upper limit of normal (10xULN), were approximately 0.03%, 0.08%, and 0.61% in patients treated with simvastatin 20 mg, 40 mg, and 80 mg daily, respectively. In another clinical study of 12,064 simvastatin -treated patients (with a history of myocardial infarction) with a mean follow-up of 6.7 years, the incidences of myopathy in patients taking simvastatin 20 mg and 80 mg daily were approximately 0.02% and 0.9%, respectively. The incidences of rhabdomyolysis (defined as myopathy with a CK >40xULN) in patients taking simvastatin 20 mg and 80 mg daily were approximately 0% and 0.4%, respectively [see ADVERSE REACTIONS ( 6.1 )]. …"},{"title":"อาการไม่พึงประสงค์","body":"The following important adverse reactions are described below and elsewhere in the labeling: Myopathy and Rhabdomyolysis [see WARNINGS AND PRECAUTIONS ( 5.1 )] Immune-Mediated Necrotizing Myopathy [see WARNINGS AND PRECAUTIONS ( 5.2 )] Hepatic Dysfunction [see WARNINGS AND PRECAUTIONS ( 5.3 )] Increases in HbA1c and Fasting Serum Glucose Levels [see WARNINGS AND PRECAUTIONS ( 5.4 )] Most common adverse reactions (incidence ≥5%) are: upper respiratory infection, headache, abdominal pain, constipation, and nausea. ( 6.1 ) To report SUSPECTED ADVERSE REACTIONS, contact Lupin Pharmaceuticals, Inc. at 1-800-399-2561 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch . 6.1 Clinical Trials Experience Because clinical studies are conducted under widely varying conditions, adverse reaction rates observed in the clinical studies of a drug cannot be directly compared to rates in the clinical studies of another drug and may not reflect the rates observed in practice. In clinical studies, 2,423 adult patients were exposed to simvastatin with a median duration of follow-up of approximately 18 months. The most commonly reported adverse reactions (incidence ≥5%) in these simvastatin clinical studies were: upper respiratory infections (9%), headache (7%), abdominal pain (7%), constipation (7%), and nausea (5%). Overall, 1.4% of patients discontinued simvastatin due to adverse reactions. The most common adverse reactions that led to discontinuation were: gastrointestinal disorders (0.5%), myalgia (0.1%), and arthralgia (0.1%). In a Cardiovascular Outcomes Study (the Scandinavian Simvastatin Survival Study [Study 4S]), adult patients (age range 35-71 years, 19% women, 100% Caucasians) were treated with 20-40 mg per day of simvastatin or placebo over a median of 5.4 years [see CLINICAL STUDIES ( 14 )] ; adverse reactions reported in ≥2% of patients and at a rate greater than placebo are shown in Table 1. Table 1 : Adverse Reactions Reported ≥2% of Patients Treated with Simvastatin and Greater than Placebo in Study 4S % Placebo (N = 2,223) % Simvastatin (N = 2,221) Bronchitis 6.3 6.6 Abdominal pain 5.8 5.9 Atrial fibrillation 5.1 5.7 Gastritis 3.9 4.9 Eczema 3.0 4.5 Vertigo 4.2 4.5 Dia …"},{"title":"Drug interaction","body":"See full prescribing information for details regarding concomitant use of simvastatin with other drugs or grapefruit juice that increase the risk of myopathy and rhabdomyolysis. ( 2.5 , 7.1 ) Coumarin Anticoagulants: Obtain INR before simvastatin initiation and monitor INR during simvastatin dosage initiation or adjustment. ( 7.2 ) Digoxin: During simvastatin initiation, monitor digoxin levels. ( 7.2 ) 7.1 Drug Interactions that Increase the Risk of Myopathy and Rhabdomyolysis with Simvastatin Simvastatin is a substrate of CYP3A4 and of the transport protein OATP1B1. Simvastatin exposure can be significantly increased with concomitant administration of inhibitors of CYP3A4 and OATP1B1. Table 2 includes a list of drugs that increase the risk of myopathy and rhabdomyolysis when used concomitantly with simvastatin and instructions for preventing or managing them [see WARNINGS AND PRECAUTIONS ( 5.1 ) AND CLINICAL PHARMACOLOGY ( 12.3 )] . Table 2: Drug Interactions that Increase the Risk of Myopathy and Rhabdomyolysis with Simvastatin Strong CYP3A4 inhibitors Clinical Impact: Simvastatin is a substrate of CYP3A4. Concomitant use of strong CYP3A4 inhibitors with simvastatin increases simvastatin exposure and increases the risk of myopathy and rhabdomyolysis, particularly with higher simvastatin dosages. Intervention: Concomitant use of strong CYP3A4 inhibitors with Simvastatin is contraindicated [see CONTRAINDICATIONS ( 4 )] . If treatment with a CYP3A4 inhibitor is unavoidable, suspend simvastatin during the course of strong CYP3A4 inhibitor treatment. Examples: Select azole anti-fungals (e.g., itraconazole, ketoconazole, posaconazole, and voriconazole), select macrolide antibiotics (e.g., erythromycin and clarithromycin), select HIV protease inhibitors (e.g., nelfinavir, ritonavir, and darunavir/ritonavir), select HCV protease inhibitors (e.g., boceprevir and telaprevir), cobicistat-containing products, and nefazodone. Cyclosporine, Danazol, or Gemfibrozil Clinical Impact: The risk of myopathy and rhabdomyolysis is increased with concomitant use of cyclosporine, danazol, or gemfibrozil with simvastatin. Gemfibrozil may cause myopathy when given alone. Intervention: Concomitant use of cyclosporine, danazol, or gemfibrozil with simvastatin is contraindicated [see CONTRAINDICATIONS ( 4 )] . …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Discontinue simvastatin when pregnancy is recognized. Alternatively, consider the ongoing therapeutic needs of the individual patient. Simvastatin decreases synthesis of cholesterol and possibly other biologically active substances derived from cholesterol; therefore, simvastatin may cause fetal harm when administered to pregnant patients based on the mechanism of action [see CLINICAL PHARMACOLOGY ( 12.1 )] . In addition, treatment of hyperlipidemia is not generally necessary during pregnancy. Atherosclerosis is a chronic process and the discontinuation of lipid-lowering drugs during pregnancy should have little impact on the outcome of long-term therapy of primary hyperlipidemia for most patients. Available data from case series and prospective and retrospective observational cohort studies over decades of use with statins in pregnant women have not identified a drug-associated risk of major congenital malformations. Published data from prospective and retrospective observational cohort studies with simvastatin use in pregnant women are insufficient to determine if there is a drug-associated risk of miscarriage (see Data). In animal reproduction studies, no adverse developmental effects were observed in pregnant rats or rabbits orally administered simvastatin during the period of organogenesis at doses that resulted in 2.5 and 2 times, respectively, the human exposure at the maximum recommended human dosage of 80 mg/day, based on body surface area (mg/m 2 ) (see DATA) . The estimated background risk of major birth defects and miscarriage for the indicated population is unknown. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2 to 4% and 15 to 20%, respectively. Data Human Data: A Medicaid cohort linkage study of 1152 statin-exposed pregnant women compared to 886,996 controls did not find a significant teratogenic effect from maternal use of statins in the first trimester of pregnancy, after adjusting for potential confounders – including maternal age, diabetes mellitus, hypertension, obesity, and alcohol and tobacco use – using propensity score-based methods. The relative risk of congenital malformations between the group with statin use and the group with no statin use in the first trimester was 1.07 (95% confidence interval 0.85 to 1.37) after controlling for confounders, particularly pre-existing diabetes mellitus. …"},{"title":"การได้รับยาเกินขนาด","body":"No specific antidotes for simvastatin are known. Contact Poison Control (1-800-222-1222) for latest recommendations."}]},
{"key":"sodium bicarbonate|ORAL","generic":"sodium bicarbonate","route":"ORAL","brand":null,"title":"Sodium Bicarbonate 10 gr. (650 mg)","set_id":"0a0cc46d-372e-4175-932a-065e82d8d353","effective":"20260413","sections":[{"title":"ข้อบ่งใช้","body":"relieves acid indigestion heartburn sour stomach upset stomach associated with these symptoms"},{"title":"ขนาดยาและวิธีใช้","body":"do not use the maximum dosage for more than 2 weeks tablets may be swallowed whole or dissolved in water prior to use adults 60 years of age and over: 1-2 tablets every 4 hours, not more than 12 tablets in 24 hours adults under 60 years of age: 1-4 tablets every 4 hours, not more than 24 tablets in 24 hours"},{"title":"ข้อห้ามใช้","body":"Do not take more than 24 tablets for adults up to 60 years of age (or 12 tablets for adults 60 years of age and older) in a 24-hour period nor use maximum dosage for more than 2 weeks, except under the advice and supervision of a physician."},{"title":"คำเตือนและข้อควรระวัง","body":"Do not take more than 24 tablets for adults up to 60 years of age (or 12 tablets for adults 60 years of age and older) in a 24-hour period nor use maximum dosage for more than 2 weeks, except under the advice and supervision of a physician. Ask a doctor before use if you have a sodium restricted diet. Ask a doctor or pharmacist before use if you are taking a prescription drug. Antacids may interact with certain prescription drugs. Stop use and ask a doctor if symptoms last more than 2 weeks. If pregnant or breast feeding, ask a health professional before use. Keep out of reach of children. In case of overdose, get medical help or contact a Poison Control Center (1-800-222-1222) immediately. diet. Ask a doctor or pharmacist before use if you are taking a prescription drug. Antacids may interact with certain prescription drugs. 2 weeks."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"If pregnant or breast feeding, ask a health professional before use."},{"title":"การเก็บรักษา","body":"Other information each tablet contains: sodium 178 mg (7.74 mEq) store at room temperature 15º-30ºC (59º-86°F)"}]},
{"key":"sodium chloride|INTRAVENOUS","generic":"sodium chloride","route":"INTRAVENOUS","brand":null,"title":"Sodium chloride","set_id":"239a5af1-7498-480f-862c-ab7c3d89d183","effective":"20240521","sections":[{"title":"ข้อบ่งใช้","body":"Intravenous solutions containing sodium chloride are indicated for parenteral replenishment of fluid and sodium chloride as required by the clinical condition of the patient."},{"title":"ขนาดยาและวิธีใช้","body":"The dose is dependent upon the age, weight and clinical condition of the patient. Additives may be incompatible. Consult with pharmacist, if available. When introducing additives, use aseptic technique, mix thoroughly and do not store. Parenteral drug products should be inspected visually for particulate matter and discoloration prior to administration, whenever solution and container permit (see PRECAUTIONS )."},{"title":"ข้อห้ามใช้","body":"None known."},{"title":"คำเตือนและข้อควรระวัง","body":"0.45% Sodium chloride injection should be used with great care, if at all, in patients with congestive heart failure, severe renal insufficiency and in clinical states in which there exists edema with sodium retention. The intravenous administration of 0.45% Sodium chloride injection can cause fluid and/or solute overloading resulting in dilution of serum electrolyte concentrations, overhydration, congested states or pulmonary edema. The risk of dilutive states is inversely proportional to the electrolyte concentration of the injections. The risk of solute overload causing congested states with peripheral and pulmonary edema is directly proportional to the electrolyte concentrations of the injections. In patients with diminished renal function, administration of 0.45% Sodium chloride injection may result in sodium retention. General Do not use plastic containers in series connections. Such use could result in air embolism due to residual air being drawn from the primary container before administration of the fluid from the secondary container is completed. Pressurizing intravenous solutions contained in flexible plastic containers to increase flow rates can result in air embolism if the residual air in the container is not fully evacuated prior to administration. Use of a vented intravenous administration set with the vent in the open position could result in air embolism. Vented intravenous administration sets with the vent in the open position should not be used with flexible plastic containers. Laboratory Tests Clinical evaluation and periodic laboratory determinations are necessary to monitor changes in fluid balance, electrolyte concentrations and acid-base balance during prolonged parenteral therapy or whenever the condition of the patient warrants such evaluation. Drug Interactions Caution must be exercised in the administration of 0.45% Sodium chloride injection to patients receiving corticosteroids or corticotropin. Carcinogenesis, Mutagenesis, Impairment of Fertility Studies have not been performed with 0.45% Sodium chloride injection to evaluate the potential for carcinogenesis, mutagenesis or impairment of fertility. Pregnancy Teratogenic Effects Pregnancy Category C Animal reproduction studies have not been conducted with 0.45% Sodium chloride injection. It is also not known whether 0.45% Sodium chloride injection can cause fetal harm when administered to a pregnant woman or can affect reproduction capacity. …"},{"title":"อาการไม่พึงประสงค์","body":"Reactions which may occur because of the solution or the technique of administration include febrile response, infection at the site of injection, venous thrombosis or phlebitis extending from the site of injection, extravasation and hypervolemia. If an adverse reaction does occur, discontinue the infusion, evaluate the patient, institute appropriate therapeutic countermeasures and save the remainder of the fluid for examination if deemed necessary. In addition to the above listed adverse reactions hyponatremia has been reported for 0.45% Sodium chloride injection (see Pediatric Use )."},{"title":"Drug interaction","body":"Caution must be exercised in the administration of 0.45% Sodium chloride injection to patients receiving corticosteroids or corticotropin."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Teratogenic Effects Pregnancy Category C Animal reproduction studies have not been conducted with 0.45% Sodium chloride injection. It is also not known whether 0.45% Sodium chloride injection can cause fetal harm when administered to a pregnant woman or can affect reproduction capacity. 0.45% Sodium chloride injection should be given to a pregnant woman only if clearly needed. It is not known whether this drug is excreted in human milk. Because many drugs are excreted in human milk, caution should be exercised when 0.45% Sodium chloride injection is administered to a nursing mother. The use of 0.45% Sodium chloride injection in pediatric patients is based on clinical practice. Plasma electrolyte concentrations should be closely monitored in the pediatric population as this population may have impaired ability to regulate fluids and electrolytes. The infusion of hypotonic fluids (0.45% Sodium chloride injection) together with the non-osmotic secretion of ADH may result in hyponatremia in patients with acute volume depletion. Hyponatremia can lead to headache, nausea, seizures, lethargy, coma, cerebral edema and death, therefore acute symptomatic hyponatremic encephalopathy is considered a medical emergency. Clinical studies of 0.45% Sodium chloride injection did not include sufficient numbers of subjects aged 65 and over to determine whether they respond differently from younger subjects. Other reported clinical experience has not identified differences in responses between elderly and younger patients. In general, dose selection for an elderly patient should be cautious, usually starting at the low end of the dosing range, reflecting the greater frequency of decreased hepatic, renal, or cardiac function, and of concomitant disease or drug therapy. This drug is known to be substantially excreted by the kidney, and the risk of toxic reactions to this drug may be greater in patients with impaired renal function. Because elderly patients are more likely to have decreased renal function, care should be taken in dose selection, and it may be useful to monitor renal function. Do not administer unless solution is clear and container is undamaged. Discard unused portion."},{"title":"การได้รับยาเกินขนาด","body":"In the event of overhydration or solute overload, re-evaluate the patient and institute appropriate corrective measures (see WARNINGS , PRECAUTIONS , and ADVERSE REACTIONS )."},{"title":"การเก็บรักษา","body":"STORE AT: 20 ° to 25 °C ( 68 ° to 77 °F) [see USP Controlled Room Temperature]. Protect from freezing. The container closure is not made with natural rubber latex. Non-PVC, Non-DEHP, Sterile. Manufactured for: Lake Zurich, IL 60047 www.fresenius-kabi.com/us Issued: October 2021 Fresenius Kabi Logo"}]},
{"key":"sodium chloride|IRRIGATION","generic":"sodium chloride","route":"IRRIGATION","brand":null,"title":"Sodium Chloride","set_id":"0d59a04a-32e6-485b-b638-a1e6c09e9642","effective":"20250709","sections":[{"title":"ข้อบ่งใช้","body":"0.9% Sodium Chloride Irrigation USP is indicated for all general irrigation, washing, rinsing and dilution purposes which permit use of a sterile, nonpyrogenic electrolyte solution."},{"title":"ขนาดยาและวิธีใช้","body":"As required for irrigation. When used as a diluent, or vehicle for other drugs, the drug manufacturer’s recommendations should be followed. Some additives may be incompatible. Consult with pharmacist. When introducing additives, use aseptic techniques. Mix thoroughly. Do not store. Solutions should be inspected visually for particulate matter and discoloration prior to administration, whenever solution and container permits."},{"title":"ข้อห้ามใช้","body":"0.9% Sodium Chloride Irrigation USP is not for injection by usual parenteral routes. An electrolyte solution should not be used for irrigation during electrosurgical procedures."},{"title":"คำเตือนและข้อควรระวัง","body":"FOR IRRIGATION ONLY. NOT FOR INJECTION. Irrigating fluids have been demonstrated to enter the systemic circulation in relatively large volumes; thus, irrigation solutions must be regarded as systemic drugs. Absorption of large amounts can cause fluid and/or solute overload resulting in dilution of serum electrolyte concentrations, overhydration, congested states or pulmonary edema. The risk of dilutional states is inversely proportional to the electrolyte concentrations of the administered parenteral solutions. The risk of solute overload causing congested states with peripheral and pulmonary edema is directly proportional to the electrolyte concentration. Do not warm above 150°F (66°C). After opening container, its contents should be used promptly to minimize the possibility of bacterial growth or pyrogen formation. Discard unused portion of irrigating solution since it contains no preservatives. General Use aseptic technique when preparing and administering sterile irrigation solutions. Use only if solution is clear and container and seal are intact. Do not use for irrigation that may result in absorption of large amounts of fluid into the blood. Caution should be observed when the solution is used for continuous irrigation or allowed to “dwell” inside body cavities because of possible absorption into the blood stream and the production of circulatory overload. When used for irrigation via appropriate irrigation equipment, the administration set should be attached promptly. Unused portions should be discarded and a fresh container of appropriate size used for the start up of each cycle or repeat procedure. For repeated irrigations of urethral catheters, a separate container should be used for each patient. Laboratory Tests Clinical evaluation and periodic laboratory determinations are necessary to monitor changes in fluid balance, electrolyte concentrations, and acid-base balance after prolonged irrigation, when fluid absorption is suspected, or whenever the condition of the patient warrants such evaluation. Drug Interactions Some additives may be incompatible. Consult with pharmacist. When introducing additives, use aseptic technique. Mix thoroughly. Do not store. Carcinogenesis, Mutagenesis, Impairment of Fertility Studies with 0.9% Sodium Chloride Irrigation USP have not been performed to evaluate carcinogenic potential, mutagenic potential, or effects on fertility. …"},{"title":"อาการไม่พึงประสงค์","body":"Possible adverse effects arising from the irrigation of body cavities, tissues, or indwelling catheters and tubes can be minimized when proper procedures are followed. Displaced catheters or drainage tubes can lead to irrigation or infiltration of unintended structures or cavities. Excessive volume or pressure during irrigation of closed cavities may cause undue distension or disruption of tissues. Accidental contamination from careless technique may transmit infection. If an adverse reaction does occur, discontinue administration of the irrigant, evaluate the patient, institute appropriate therapeutic countermeasures, and save the remainder of the fluid for examination if deemed necessary."},{"title":"Drug interaction","body":"Some additives may be incompatible. Consult with pharmacist. When introducing additives, use aseptic technique. Mix thoroughly. Do not store."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"– Teratogenic Effects Animal reproduction studies have not been conducted with 0.9% Sodium Chloride Irrigation USP. It is also not known whether 0.9% Sodium Chloride Irrigation USP can cause fetal harm when administered to a pregnant woman or can affect reproduction capacity. 0.9% Sodium Chloride Irrigation USP should be given to a pregnant woman only if clearly needed. It is not known whether this drug is excreted in human milk. Because many drugs are excreted in human milk, caution should be exercised when 0.9% Sodium Chloride Irrigation USP is administered to a nursing woman. The safety and effectiveness of 0.9% Sodium Chloride Irrigation USP in pediatric patients have not been established. Its limited use in pediatric patients has been inadequate to fully define proper dosage and limitations for use. Clinical studies of 0.9% Sodium Chloride Irrigation USP did not include a sufficient number of patients age 65 years and over to determine whether they respond differently from younger subjects. In general, dose selection for an elderly patient should be cautious, usually starting at the low end of the dosing range, reflecting the greater frequency of decreased hepatic, renal, or cardiac function, and of concomitant disease or other drug therapy. This drug is known to be substantially excreted by the kidney, and the risk of toxic reactions to this drug may be greater in patients with impaired renal function. Because elderly patients are more likely to have decreased renal function, care should be taken in dose selection, and it may be useful to monitor renal function. Frequent laboratory determinations and clinical evaluations are recommended to monitor changes in blood glucose, electrolyte concentrations, and renal function."},{"title":"การได้รับยาเกินขนาด","body":"In the event of overhydration or solute overload, reevaluate the patient’s condition, and institute appropriate corrective treatment. Intravascular volume overload may respond to hemodialysis. See WARNINGS , PRECAUTIONS , and ADVERSE REACTIONS ."}]},
{"key":"spironolactone|ORAL","generic":"spironolactone","route":"ORAL","brand":null,"title":"Spironolactone","set_id":"3487305c-25a6-4e82-923c-3e4dd638c988","effective":"20260528","sections":[{"title":"ข้อบ่งใช้","body":"Spironolactone is an aldosterone antagonist indicated for: The treatment of NYHA Class III–IV heart failure and reduced ejection fraction to increase survival, manage edema, and to reduce the need for hospitalization for heart failure ( 1.1 ). Use as an add-on therapy for the treatment of hypertension, to lower blood pressure. Lowering blood pressure reduces the risk of fatal and nonfatal cardiovascular events, primarily strokes and myocardial infarctions ( 1.2 ). The management of edema in adult patients who are cirrhotic when edema is not responsive to fluid and sodium restrictions and in the setting of nephrotic syndrome when treatment of the underlying disease, restriction of fluid and sodium intake, and the use of other diuretics produce an inadequate response ( 1.3 ). Treatment of primary hyperaldosternism for: ( 1.4 ) Short-term preoperative treatment Long-term maintenance for patients with discrete aldosterone-producing adrenal adenomas who are not candidates for surgery and patients with bilateral micro or macronodular adrenal hyperplasia 1.1 Heart Failure Spironolactone tablets are indicated for treatment of NYHA Class III–IV heart failure and reduced ejection fraction to increase survival, manage edema, and reduce the need for hospitalization for heart failure. Spironolactone tablets are usually administered in conjunction with other heart failure therapies. 1.2 Hypertension Spironolactone tablets are indicated as add-on therapy for the treatment of hypertension, to lower blood pressure in patients who are not adequately controlled on other agents. Lowering blood pressure reduces the risk of fatal and nonfatal cardiovascular events, primarily strokes and myocardial infarctions. These benefits have been seen in controlled trials of antihypertensive drugs from a wide variety of pharmacologic classes. Control of high blood pressure should be part of comprehensive cardiovascular risk management, including, as appropriate, lipid control, diabetes management, antithrombotic therapy, smoking cessation, exercise, and limited sodium intake. Many patients will require more than one drug to achieve blood pressure goals. For specific advice on goals and management, see published guidelines, such as those of the National High Blood Pressure Education Program's Joint National Committee on Prevention, Detection, Evaluation, and Treatment of High Blood Pressure (JNC). …"},{"title":"ขนาดยาและวิธีใช้","body":"Heart Failure: Initiate treatment at 25 mg once daily ( 2.2 ). Hypertension: Initiate treatment at 25 to 100 mg daily in either single or divided doses ( 2.3 ). Edema: Initiate therapy in a hospital setting and titrate slowly. The recommended initial daily dose is 100 mg in single or divided doses ( 2.4 ). Primary hyperaldosteronism: Initiate treatment at 100 to 400 mg in preparation for surgery. In patients unsuitable for surgery use the lowest effective dosage determined for the individual patient ( 2.5 ). 2.1 General Considerations Spironolactone tablets can be taken with or without food, but should be taken consistently with respect to food [see Clinical Pharmacology (12.3) ] . 2.2 Treatment of Heart Failure In patients with serum potassium ≤5.0 mEq/L and eGFR >50 mL/min/1.73 m 2 , initiate treatment at 25 mg once daily. Patients who tolerate 25 mg once daily may have their dosage increased to 50 mg once daily as clinically indicated. Patients who develop hyperkalemia on 25 mg once daily may have their dosage reduced to 25 mg every other day [see Warnings and Precautions (5.1) ] . In patients with an eGFR between 30 and 50 mL/min/1.73 m 2 , consider initiating therapy at 25 mg every other day because of the risk of hyperkalemia [see Use in Specific Populations (8.6) ]. 2.3 Treatment of Essential Hypertension The recommended initial daily dose is 25 to 100 mg of spironolactone tablets administered in either single or divided doses is recommended. Dosage can be titrated at two-week intervals. Doses greater than 100 mg/day generally do not provide additional reductions in blood pressure. 2.4 Treatment of Edema In patients with cirrhosis, initiate therapy in a hospital setting and titrate slowly [see Use in Specific Populations (8.7) ] . The recommended initial daily dosage is 100 mg of spironolactone tablets administered in either single or divided doses, but may range from 25 to 200 mg daily. When given as the sole agent for diuresis, administer for at least five days before increasing dose to obtain desired effect. 2.5 Treatment of Primary Hyperaldosteronism Administer spironolactone tablets in doses of 100 to 400 mg daily in preparation for surgery. For patients who are considered unsuitable for surgery, spironolactone tablets can be used as long-term maintenance therapy at the lowest effective dosage determined for the individual patient."},{"title":"ข้อห้ามใช้","body":"Spironolactone tablets are contraindicated in the patients with: Hyperkalemia Addison's disease Concomitant use of eplerenone Spironolactone tablets are contraindicated in patients with ( 4 ): Hyperkalemia Addison's disease Concomitant use of eplerenone"},{"title":"คำเตือนและข้อควรระวัง","body":"Hyperkalemia: Monitor serum potassium within one week of initiation and regularly thereafter ( 5.1 ). Hypotension and Worsening Renal Function: Monitor volume status and renal function periodically ( 5.2 ). Electrolyte and Metabolic Abnormalities: Monitor serum electrolytes, uric acid and blood glucose periodically ( 5.3 ). Gynecomastia: Spironolactone can cause gynecomastia ( 5.4 ). 5.1 Hyperkalemia Spironolactone can cause hyperkalemia. This risk is increased by impaired renal function or concomitant potassium supplementation, potassium-containing salt substitutes or drugs that increase potassium, such as angiotensin converting enzyme inhibitors and angiotensin receptor blockers [see Drug Interactions (7.1) ] . Monitor serum potassium within 1 week of initiation or titration of spironolactone and regularly thereafter. More frequent monitoring may be needed when spironolactone is given with other drugs that cause hyperkalemia or in patients with impaired renal function. If hyperkalemia occurs, decrease the dose or discontinue spironolactone and treat hyperkalemia. 5.2 Hypotension and Worsening Renal Function Excessive diuresis may cause symptomatic dehydration, hypotension and worsening renal function, particularly in salt-depleted patients or those taking angiotensin converting enzyme inhibitors and angiotensin II receptor blockers. Worsening of renal function can also occur with concomitant use of nephrotoxic drugs (e.g., aminoglycosides, cisplatin, and NSAIDs). Monitor volume status and renal function periodically. 5.3 Electrolyte and Metabolic Abnormalities In addition to causing hyperkalemia, spironolactone can cause hyponatremia, hypomagnesemia, hypocalcemia, hypochloremic alkalosis, and hyperglycemia. Asymptomatic hyperuricemia can occur and rarely gout is precipitated. Monitor serum electrolytes, uric acid and blood glucose periodically. 5.4 Gynecomastia Spironolactone can cause gynecomastia. In The Randomized Spironolactone Evaluation Study, patients with heart failure treated with a mean dose of 26 mg of spironolactone once daily, about 9% of the male subjects developed gynecomastia. The risk of gynecomastia increases in a dose-dependent manner with an onset that varies widely from 1 to 2 months to over a year. Gynecomastia is usually reversible."},{"title":"อาการไม่พึงประสงค์","body":"The following clinically significant adverse reactions are described elsewhere in the labeling: Hyperkalemia [see Warnings and Precautions (5.1) ] Hypotension and Worsening Renal Function [see Warnings and Precautions (5.2) ] Electrolyte and Metabolic Abnormalities [see Warnings and Precautions (5.3) ] Gynecomastia [see Warnings and Precautions (5.4 ] Impaired neurological function/ coma in patients with hepatic impairment, cirrhosis and ascites [see Use in Specific Populations (8.7) ] The following adverse reactions associated with the use of spironolactone were identified in clinical trials or postmarketing reports. Because these reactions were reported voluntarily from a population of uncertain size, it is not always possible to estimate their frequency, reliably, or to establish a causal relationship to drug exposure. Digestive: Gastric bleeding, ulceration, gastritis, diarrhea and cramping, nausea, vomiting. Reproductive: Decreased libido, inability to achieve or maintain erection, irregular menses or amenorrhea, postmenopausal bleeding, breast and nipple pain. Hematologic: Leukopenia (including agranulocytosis), thrombocytopenia. Hypersensitivity: Fever, urticaria, maculopapular or erythematous cutaneous eruptions, anaphylactic reactions, vasculitis. Metabolism: Hyperkalemia, electrolyte disturbances [see Warnings and Precautions (5.1 , 5.3) ] , hyponatremia, hypovolemia. Musculoskeletal : Leg cramps. Nervous system/psychiatric: Lethargy, mental confusion, ataxia, dizziness, headache, drowsiness. Liver/biliary: A very few cases of mixed cholestatic/hepatocellular toxicity, with one reported fatality, have been reported with spironolactone administration. Renal: Renal dysfunction (including renal failure). Skin: Stevens-Johnson Syndrome (SJS), toxic epidermal necrolysis (TEN), drug rash with eosinophilia and systemic symptoms (DRESS), alopecia, pruritis. The most common adverse reaction with spironolactone treatment is gynecomastia ( 5.4 , 6 ). To report SUSPECTED ADVERSE REACTIONS, contact Accord Healthcare, Inc. at 1866-941-7875 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch ."},{"title":"Drug interaction","body":"Agents increasing serum potassium: Concomitant administration can lead to hyperkalemia ( 5.1 , 7.1 ). Lithium: Increased risk of lithium toxicity ( 7.2 ). NSAIDs: May reduce the diuretic, natriuretic and antihypertensive effect of spironolactone ( 7.3 ). Digoxin: spironolactone can interfere with radioimmunologic assays of digoxin exposure ( 7.4 ). Cholestyramine: Hyperkalemic metabolic acidosis has been reported with concomitant use ( 7.5 ). Acetylsalicylic Acid (ASA): ASA may reduce the efficacy of spironolactone ( 7.6 ). Abiraterone: May increase prostate-specific antigen (PSA) levels ( 7.7 ). 7.1 Drugs and Supplements Increasing Serum Potassium Concomitant administration of spironolactone with potassium supplementation or drugs that can increase potassium may lead to severe hyperkalemia. In general, discontinue potassium supplementation in heart failure patients who start spironolactone [see Warnings and Precautions (5.1) and Clinical Pharmacology (12.3) ] . Check serum potassium levels when ACE inhibitor or ARB therapy is altered in patients receiving spironolactone. Examples of drugs that can increase potassium include: ACE inhibitors angiotensin receptor blockers non-steroidal anti-inflammatory drugs (NSAIDs) heparin and low molecular weight heparin trimethoprim 7.2 Lithium Like other diuretics, spironolactone reduces the renal clearance of lithium, thus increasing the risk of lithium toxicity. Monitor lithium levels periodically when spironolactone is coadministered [see Clinical Pharmacology (12.3) ] . 7.3 Nonsteroidal Anti-Inflammatory Drugs (NSAIDs) In some patients, the administration of an NSAID can reduce the diuretic, natriuretic, and antihypertensive effect of diuretics. Therefore, when spironolactone and NSAIDs are used concomitantly, monitor closely to determine if the desired effect of the diuretic is obtained [see Clinical Pharmacology (12.3) ] . 7.4 Digoxin Spironolactone and its metabolites interfere with radioimmunoassays for digoxin and increase the apparent exposure to digoxin. It is unknown to what extent, if any, spironolactone may increase actual digoxin exposure. In patients taking concomitant digoxin, use an assay that does not interact with spironolactone. 7.5 Cholestyramine Hyperkalemic metabolic acidosis has been reported in patients given spironolactone concurrently with cholestyramine. 7.6 Acetylsalicylic Acid Acetylsalicylic acid may reduce the efficacy of spironolactone. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"8.1 Pregnancy Risk Summary Based on mechanism of action and findings in animal studies, spironolactone may affect sex differentiation of the male during embryogenesis (see Data ) . Rat embryofetal studies report feminization of male fetuses and endocrine dysfunction in females exposed to spironolactone in utero. Limited available data from published case reports and case series did not demonstrate an association of major malformations or other adverse pregnancy outcomes with spironolactone . There are risks to the mother and fetus associated with heart failure, cirrhosis and poorly controlled hypertension during pregnancy (see Clinical Considerations ) . Because of the potential risk to the male fetus due to anti-androgenic properties of spironolactone and animal data, avoid spironolactone in pregnant women or advise a pregnant woman of the potential risk to a male fetus. The estimated background risk of major birth defects and miscarriage for the indicated population is unknown. All pregnancies have a background risk of birth defect, loss or other adverse outcomes. In the U.S. general population, the estimated background risk of major birth defects and miscarriage in clinically recognized pregnancies is 2% to 4% and 15% to 20%, respectively. Clinical Considerations Disease-Associated Maternal and/or Embryo/Fetal Risk Pregnant women with congestive heart failure are at increased risk for preterm birth. Stroke volume and heart rate increase during pregnancy, increasing cardiac output, especially during the first trimester. Clinical classification of heart disease may worsen with pregnancy and lead to maternal death. Closely monitor pregnant patients for destabilization of their heart failure. Pregnant women with symptomatic cirrhosis generally have poor outcomes including hepatic failure, variceal hemorrhage, preterm delivery, fetal growth restriction and maternal death. Outcomes are worse with coexisting esophageal varices. Pregnant women with cirrhosis of the liver should be carefully monitored and managed accordingly. Hypertension in pregnancy increases the maternal risk for pre-eclampsia, gestational diabetes, premature delivery, and delivery complications (e.g., need for cesarean section, and post-partum hemorrhage). Hypertension increases the fetal risk for intrauterine growth restriction and intrauterine death. Data Animal Data Teratology studies with spironolactone have been carried out in mice and rabbits at doses of up to 20 mg/kg/day. …"},{"title":"การได้รับยาเกินขนาด","body":"The oral LD 50 of spironolactone is greater than 1000 mg/kg in mice, rats, and rabbits. Acute overdosage of spironolactone may be manifested by drowsiness, mental confusion, maculopapular or erythematous rash, nausea, vomiting, dizziness, or diarrhea. Rarely, instances of hyponatremia, hyperkalemia, or hepatic coma may occur in patients with severe liver disease, but these are unlikely due to acute overdosage. Hyperkalemia may occur, especially in patients with impaired renal function. Treatment: Induce vomiting or evacuate the stomach by lavage. There is no specific antidote. Treatment is supportive to maintain hydration, electrolyte balance, and vital functions. Patients who have renal impairment may develop hyperkalemia. In such cases, discontinue spironolactone."},{"title":"การเก็บรักษา","body":"Store at 20° to 25°C (68° to 77°F) [See USP Controlled Room Temperature] Protect from light. Dispense in tight, Light-resistant containers."}]},
{"key":"sulfamethoxazole and trimethoprim|ORAL","generic":"sulfamethoxazole and trimethoprim","route":"ORAL","brand":null,"title":"Sulfamethoxazole and Trimethoprim","set_id":"08500fcb-dbec-4ac2-91c3-189d27907ec0","effective":"20260717","sections":[{"title":"ข้อบ่งใช้","body":"To reduce the development of drug-resistant bacteria and maintain the effectiveness of sulfamethoxazole and trimethoprim tablets and other antibacterial drugs, sulfamethoxazole and trimethoprim tablets should be used only to treat or prevent infections that are proven or strongly suspected to be caused by susceptible bacteria. When culture and susceptibility information are available, they should be considered in selecting or modifying antibacterial therapy. In the absence of such data, local epidemiology and susceptibility patterns may contribute to empiric selection of therapy. Urinary Tract Infections For the treatment of urinary tract infections due to susceptible strains of the following organisms: Escherichia coli, Klebsiella species, Enterobacter species, Morganella morganii, Proteus mirabilis and Proteus vulgaris. It is recommended that initial episodes of uncomplicated urinary tract infections be treated with a single effective antibacterial agent rather than the combination. Acute Otitis Media For the treatment of acute otitis media in pediatric patients due to susceptible strains of Streptococcus pneumoniae or Haemophilus influenzae when in the judgment of the physician sulfamethoxazole and trimethoprim offers some advantage over the use of other antimicrobial agents. To date, there are limited data on the safety of repeated use of sulfamethoxazole and trimethoprim tablets in pediatric patients under two years of age. Sulfamethoxazole and trimethoprim tablets are not indicated for prophylactic or prolonged administration in otitis media at any age. Acute Exacerbations of Chronic Bronchitis in Adults For the treatment of acute exacerbations of chronic bronchitis due to susceptible strains of Streptococcus pneumoniae or Haemophilus influenzae when a physician deems that sulfamethoxazole and trimethoprim tablets could offer some advantage over the use of a single antimicrobial agent. Shigellosis For the treatment of enteritis caused by susceptible strains of Shigella flexneri and Shigella sonnei when antibacterial therapy is indicated. Pneumocystis jirovecii Pneumonia For the treatment of documented Pneumocystis jirovecii pneumonia and for prophylaxis against P. jirovecii pneumonia in individuals who are immunosuppressed and considered to be at an increased risk of developing P. jirovecii pneumonia. Traveler's Diarrhea in Adults For the treatment of traveler's diarrhea due to susceptible strains of enterotoxigenic E.coli."},{"title":"ขนาดยาและวิธีใช้","body":"Sulfamethoxazole and trimethoprim tablets are contraindicated in pediatric patients less than 2 months of age. Urinary Tract Infections and Shigellosis in Adults and Pediatric Patients, and Acute Otitis Media in Children: Adults: The usual adult dosage in the treatment of urinary tract infections is 1 sulfamethoxazole and trimethoprim DS (double strength) tablet or 2 sulfamethoxazole and trimethoprim tablets every 12 hours for 10 to 14 days. An identical daily dosage is used for 5 days in the treatment of shigellosis. Children: The recommended dose for children with urinary tract infections or acute otitis media is 40 mg/kg sulfamethoxazole and 8 mg/kg trimethoprim per 24 hours, given in two divided doses every 12 hours for 10 days. An identical daily dosage is used for 5 days in the treatment of shigellosis. The following table is a guideline for the attainment of this dosage: Children 2 months of age or older: Weight Dose–every 12 hours lb kg Tablets 22 10 – 44 20 1 66 30 1½ 88 40 2 or 1 DS tablet For Patients with Impaired Renal Function: When renal function is impaired, a reduced dosage should be employed using the following table: Creatinine Clearance (mL/min) Recommended Dosage Regimen Above 30 Usual standard regimen 15–30 ½ the usual regimen Below 15 Use not recommended Acute Exacerbations of Chronic Bronchitis in Adults: The usual adult dosage in the treatment of acute exacerbations of chronic bronchitis is 1 sulfamethoxazole and trimethoprim DS (double strength) tablet or 2 sulfamethoxazole and trimethoprim tablets every 12 hours for 14 days. Pneumocystis jirovecii Pneumonia: Treatment: Adults and Children: The recommended dosage for treatment of patients with documented Pneumocystis jirovecii pneumonia is 75 to 100 mg/kg sulfamethoxazole and 15 to 20 mg/kg trimethoprim per 24 hours given in equally divided doses every 6 hours for 14 to 21 days. 12 The following table is a guideline for the upper limit of this dosage: Weight Dose–every 6 hours lb kg Tablets 18 8 – 35 16 1 53 24 1½ 70 32 2 or 1 DS tablet 88 40 2½ 106 48 3 or 1½ DS tablets 141 64 4 or 2 DS tablets 176 80 5 or 2½ DS tablets For the lower limit dose (75 mg/kg sulfamethoxazole and 15 mg/kg trimethoprim per 24 hours) administer 75% of the dose in the above table. Prophylaxis: Adults: The recommended dosage for prophylaxis in adults is 1 sulfamethoxazole and trimethoprim DS (double strength) tablet daily. …"},{"title":"ข้อห้ามใช้","body":"Sulfamethoxazole and trimethoprim tablets are contraindicated in the following situations: • known hypersensitivity to trimethoprim or sulfonamides • history of drug-induced immune thrombocytopenia with use of trimethoprim and/or sulfonamides • documented megaloblastic anemia due to folate deficiency • pediatric patients less than 2 months of age • marked hepatic damage • severe renal insufficiency when renal function status cannot be monitored • • concomitant administration with dofetilide (see PRECAUTIONS )."},{"title":"คำเตือนและข้อควรระวัง","body":"Embryofetal Toxicity Some epidemiologic studies suggest that exposure to sulfamethoxazole and trimethoprim during pregnancy may be associated with an increased risk of congenital malformations, particularly neural tube defects, cardiovascular malformations, urinary tract defects, oral clefts, and club foot. If sulfamethoxazole and trimethoprim is used during pregnancy, or if the patient becomes pregnant while taking this drug, the patient should be advised of the potential hazards to the fetus (see PRECAUTIONS ). Hypersensitivity and Other Serious or Fatal Reactions Fatalities and serious adverse reactions including severe cutaneous adverse reactions (SCARs) including Stevens-Johnson syndrome, toxic epidermal necrolysis, drug reaction with eosinophilia and systemic symptoms (DRESS), acute febrile neutrophilic dermatosis (AFND), acute generalized erythematous pustulosis (AGEP); fulminant hepatic necrosis; agranulocytosis, aplastic anemia and other blood dyscrasias; acute and delayed lung injury; anaphylaxis and circulatory shock have occurred with the administration of sulfamethoxazole and trimethoprim products, including sulfamethoxazole and trimethoprim (see ADVERSE REACTIONS ). Hypersensitivity Reactions of the Respiratory Tract Cough, shortness of breath and pulmonary infiltrates potentially representing hypersensitivity reactions of the respiratory tract have been reported in association with sulfamethoxazole and trimethoprim treatment. Respiratory Failure Other severe pulmonary adverse reactions occurring within days to week of sulfamethoxazole and trimethoprim initiation and resulting in prolonged respiratory failure requiring mechanical ventilation or extracorporeal membrane oxygenation (ECMO), lung transplantation or death have also been reported in patients and otherwise healthy individuals treated with sulfamethoxazole and trimethoprim products. Circulatory Shock Circulatory shock with fever, severe hypotension, and confusion requiring intravenous fluid resuscitation and vasopressors has occurred within minutes to hours of re-challenge with sulfamethoxazole and trimethoprim products, including sulfamethoxazole and trimethoprim, in patients with history of recent (days to weeks) exposure to sulfamethoxazole and trimethoprim. Management of Hypersensitivity and Other Serious Reactions Sulfamethoxazole and trimethoprim should be discontinued at the first appearance of skin rash or any sign of a serious adverse reaction. …"},{"title":"อาการไม่พึงประสงค์","body":"The following adverse reactions associated with the use of sulfamethoxazole and trimethoprim were identified in clinical trials, postmarketing or published reports. Because some of these reactions were reported voluntarily from a population of uncertain size, it is not always possible to reliably estimate their frequency or establish a causal relationship to drug exposure. The most common adverse reactions are gastrointestinal disturbances (nausea, vomiting, anorexia) and allergic skin reactions (such as rash and urticaria). Fatalities and serious adverse reactions, including severe cutaneous adverse reactions (SCARs), including Stevens-Johnson syndrome, toxic epidermal necrolysis, drug reaction with eosinophilia and systemic symptoms (DRESS), acute febrile neutrophilic dermatosis (AFND), acute generalized erythematous pustulosis (AGEP); fulminant hepatic necrosis; agranulocytosis, aplastic anemia and other blood dyscrasias; acute and delayed lung injury; anaphylaxis and circulatory shock have occurred with the administration of sulfamethoxazole and trimethoprim products, including sulfamethoxazole and trimethoprim (see WARNINGS ). Hematologic: Agranulocytosis, aplastic anemia, thrombocytopenia, leukopenia, neutropenia, hemolytic anemia, megaloblastic anemia, hypoprothrombinemia, methemoglobinemia, eosinophilia, thrombotic thrombocytopenic purpura, idiopathic thrombocytopenic purpura. Allergic Reactions/Immune: Stevens-Johnson syndrome, toxic epidermal necrolysis, anaphylaxis, allergic myocarditis, erythema multiforme, exfoliative dermatitis, angioedema, drug fever, chills, Henoch-Schoenlein purpura, serum sickness-like syndrome, generalized allergic reactions, generalized skin eruptions, photosensitivity, conjunctival and scleral injection, pruritus, urticaria, rash, periarteritis nodosa, hemophagocytic lymphohistiocytosis (HLH), systemic lupus erythematosus, drug reaction with eosinophilia and systemic symptoms (DRESS), acute generalized erythematous pustulosis (AGEP), and acute febrile neutrophilic dermatosis (AFND) (see WARNINGS ). Gastrointestinal: Hepatitis (including cholestatic jaundice and hepatic necrosis), elevation of serum transaminase and bilirubin, pseudomembranous enterocolitis, pancreatitis, stomatitis, glossitis, nausea, emesis, abdominal pain, diarrhea, anorexia. …"},{"title":"Drug interaction","body":"Potential for Sulfamethoxazole and Trimethoprim to Affect Other Drugs Trimethoprim is an inhibitor of CYP2C8 as well as OCT2 transporter. Sulfamethoxazole is an inhibitor of CYP2C9. Avoid coadministration of sulfamethoxazole and trimethoprim with drugs that are substrates of CYP2C8 and 2C9 or OCT2. Table 1: Drug Interactions with Sulfamethoxazole and Trimethoprim Drug(s) Recommendation Comments Diuretics Avoid concurrent use In elderly patients concurrently receiving certain diuretics, primarily thiazides, an increased incidence of thrombocytopenia with purpura has been reported. Warfarin Monitor prothrombin time and INR It has been reported that sulfamethoxazole and trimethoprim may prolong the prothrombin time in patients who are receiving the anticoagulant warfarin (a CYP2C9 substrate). This interaction should be kept in mind when sulfamethoxazole and trimethoprim is given to patients already on anticoagulant therapy, and the coagulation time should be reassessed. Phenytoin Monitor serum phenytoin levels Sulfamethoxazole and trimethoprim may inhibit the hepatic metabolism of phenytoin (a CYP2C9 substrate). Sulfamethoxazole and trimethoprim, given at a common clinical dosage, increased the phenytoin half-life by 39% and decreased the phenytoin metabolic clearance rate by 27%. When administering these drugs concurrently, one should be alert for possible excessive phenytoin effect. Methotrexate Avoid concurrent use Sulfonamides can also displace methotrexate from plasma protein binding sites and can compete with the renal transport of methotrexate, thus increasing free methotrexate concentrations. Cyclosporine Avoid concurrent use There have been reports of marked but reversible nephrotoxicity with coadministration of sulfamethoxazole and trimethoprim and cyclosporine in renal transplant recipients. Digoxin Monitor serum digoxin levels Increased digoxin blood levels can occur with concomitant sulfamethoxazole and trimethoprim therapy, especially in elderly patients. Indomethacin Avoid concurrent use Increased sulfamethoxazole blood levels may occur in patients who are also receiving indomethacin. Pyrimethamine Avoid concurrent use Occasional reports suggest that patients receiving pyrimethamine as malaria prophylaxis in doses exceeding 25 mg weekly may develop megaloblastic anemia if sulfamethoxazole and trimethoprim is prescribed. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"While there are no large, well-controlled studies on the use of sulfamethoxazole and trimethoprim in pregnant women, Brumfitt and Pursell, 11 in a retrospective study, reported the outcome of 186 pregnancies during which the mother received either placebo or sulfamethoxazole and trimethoprim. The incidence of congenital abnormalities was 4.5% (3 of 66) in those who received placebo and 3.3% (4 of 120) in those receiving sulfamethoxazole and trimethoprim. There were no abnormalities in the 10 children whose mothers received the drug during the first trimester. In a separate survey, Brumfitt and Pursell also found no congenital abnormalities in 35 children whose mothers had received oral sulfamethoxazole and trimethoprim at the time of conception or shortly thereafter. Because sulfamethoxazole and trimethoprim may interfere with folic acid metabolism, sulfamethoxazole and trimethoprim should be used during pregnancy only if the potential benefit justifies the potential risk to the fetus. Teratogenic Effects Human Data While there are no large prospective, well controlled studies in pregnant women and their babies, some retrospective epidemiologic studies suggest an association between first trimester exposure to sulfamethoxazole and trimethoprim with an increased risk of congenital malformations, particularly neural tube defects, cardiovascular abnormalities, urinary tract defects, oral clefts, and club foot. These studies, however, were limited by the small number of exposed cases and the lack of adjustment for multiple statistical comparisons and confounders. These studies are further limited by recall, selection, and information biases, and by limited generalizability of their findings. Lastly, outcome measures varied between studies, limiting cross-study comparisons. Alternatively, other epidemiologic studies did not detect statistically significant associations between sulfamethoxazole and trimethoprim exposure and specific malformations. Animal Data In rats, oral doses of either 533 mg/kg sulfamethoxazole or 200 mg/kg trimethoprim produced teratologic effects manifested mainly as cleft palates. These doses are approximately 5 and 6 times the recommended human total daily dose on a body surface area basis. In two studies in rats, no teratology was observed when 512 mg/kg of sulfamethoxazole was used in combination with 128 mg/kg of trimethoprim. …"},{"title":"การได้รับยาเกินขนาด","body":"Acute The amount of a single dose of sulfamethoxazole and trimethoprim that is either associated with symptoms of overdosage or is likely to be life-threatening has not been reported. Signs and symptoms of overdosage reported with sulfonamides include anorexia, colic, nausea, vomiting, dizziness, headache, drowsiness and unconsciousness. Pyrexia, hematuria and crystalluria may be noted. Blood dyscrasias and jaundice are potential late manifestations of overdosage. Signs of acute overdosage with trimethoprim include nausea, vomiting, dizziness, headache, mental depression, confusion and bone marrow depression. General principles of treatment include the institution of gastric lavage or emesis, forcing oral fluids, and the administration of intravenous fluids if urine output is low and renal function is normal. Acidification of the urine will increase renal elimination of trimethoprim. The patient should be monitored with blood counts and appropriate blood chemistries, including electrolytes. If a significant blood dyscrasia or jaundice occurs, specific therapy should be instituted for these complications. Peritoneal dialysis is not effective and hemodialysis is only moderately effective in eliminating sulfamethoxazole and trimethoprim. Chronic Use of sulfamethoxazole and trimethoprim at high doses and/or for extended periods of time may cause bone marrow depression manifested as thrombocytopenia, leukopenia and/or megaloblastic anemia. If signs of bone marrow depression occur, the patient should be given leucovorin 5 to 15 mg daily until normal hematopoiesis is restored."}]},
{"key":"theophylline|ORAL","generic":"theophylline","route":"ORAL","brand":null,"title":"Theophylline","set_id":"56fc2167-ceb6-4e3e-8ff7-5e400dfbd533","effective":"20260129","sections":[{"title":"ข้อบ่งใช้","body":"Theophylline is indicated for the treatment of the symptoms and reversible airflow obstruction associated with chronic asthma and other chronic lung diseases, e.g., emphysema and chronic bronchitis."},{"title":"ขนาดยาและวิธีใช้","body":"Theophylline 400 or 600 mg extended-release tablets can be taken once a day in the morning or evening. It is recommended that theophylline extended-release tablets be taken with meals. Patients should be advised that if they choose to take theophylline extended-release tablets with food it should be taken consistently with food and if they take it in a fasted condition it should routinely be taken fasted. It is important that the product whenever dosed be dosed consistently with or without food. Theophylline extended-release tablets are not to be chewed or crushed because it may lead to a rapid release of theophylline with the potential for toxicity. The tablet may be split. Infrequently, patients receiving theophylline extended-release tablets 400 or 600 mg may pass an intact matrix tablet in the stool or via colostomy. These matrix tablets usually contain little or no residual theophylline. Stabilized patients, 12 years of age or older, who are taking an immediate-release or controlled-release theophylline product may be transferred to once-daily administration of 400 mg or 600 mg theophylline extended-release tablets on a mg-for-mg basis. It must be recognized that the peak and trough serum theophylline levels produced by the once-daily dosing may vary from those produced by the previous product and/or regimen. General Considerations The steady-state peak serum theophylline concentration is a function of the dose, the dosing interval, and the rate of theophylline absorption and clearance in the individual patient. Because of marked individual differences in the rate of theophylline clearance, the dose required to achieve a peak serum theophylline concentration in the 10 to 20 mcg/mL range varies fourfold among otherwise similar patients in the absence of factors known to alter theophylline clearance (e.g., 400 to 1600 mg/day in adults <60 years old and 10 to 36 mg/kg/day in children 1 to 9 years old). For a given population there is no single theophylline dose that will provide both safe and effective serum concentrations for all patients. Administration of the median theophylline dose required to achieve a therapeutic serum theophylline concentration in a given population may result in either sub-therapeutic or potentially toxic serum theophylline concentrations in individual patients. …"},{"title":"ข้อห้ามใช้","body":"Theophylline extended-release tablets are contraindicated in patients with a history of hypersensitivity to theophylline or other components in the product."},{"title":"คำเตือนและข้อควรระวัง","body":"Concurrent Illness Theophylline should be used with extreme caution in patients with the following clinical conditions due to the increased risk of exacerbation of the concurrent condition: Active peptic ulcer disease Seizure disorders Cardiac arrhythmias (not including bradyarrhythmias) Conditions That Reduce Theophylline Clearance There are several readily identifiable causes of reduced theophylline clearance. If the total daily dose is not appropriately reduced in the presence of these risk factors, severe and potentially fatal theophylline toxicity can occur. Careful consideration must be given to the benefits and risks of theophylline use and the need for more intensive monitoring of serum theophylline concentrations in patients with the following risk factors: Age Neonates (term and premature) Children <1 year Elderly (>60 years) Concurrent Diseases Acute pulmonary edema Congestive heart failure Cor-pulmonale Fever; ≥102° for 24 hours or more; or lesser temperature elevations for longer periods Hypothyroidism Liver disease; cirrhosis, acute hepatitis Reduced renal function in infants <3 months of age Sepsis with multi-organ failure Shock Cessation of Smoking Drug Interactions: Adding a drug that inhibits theophylline metabolism (e.g., cimetidine, erythromycin, tacrine) or stopping a concurrently administered drug that enhances theophylline metabolism (e.g., carbamazepine, rifampin). (See PRECAUTIONS , Drug Interactions , Table II ). When Signs or Symptoms of Theophylline Toxicity Are Present Whenever a patient receiving theophylline develops nausea or vomiting, particularly repetitive vomiting, or other signs or symptoms consistent with theophylline toxicity (even if another cause may be suspected), additional doses of theophylline should be withheld and a serum theophylline concentration measured immediately. Patients should be instructed not to continue any dosage that causes adverse effects and to withhold subsequent doses until the symptoms have resolved, at which time the healthcare professional may instruct the patient to resume the drug at a lower dosage (see DOSAGE AND ADMINISTRATION , Dosing Guidelines, Table VI ). Dosage Increases Increases in the …"},{"title":"อาการไม่พึงประสงค์","body":"Adverse reactions associated with theophylline are generally mild when peak serum theophylline concentrations are <20 mcg/mL and mainly consist of transient caffeine-like adverse effects such as nausea, vomiting, headache, and insomnia. When peak serum theophylline concentrations exceed 20 mcg/mL, however, theophylline produces a wide range of adverse reactions including persistent vomiting, cardiac arrhythmias, and intractable seizures which can be lethal (see OVERDOSAGE ). The transient caffeine-like adverse reactions occur in about 50% of patients when theophylline therapy is initiated at doses higher than recommended initial doses (e.g., >300 mg/day in adults and >12 mg/kg/day in children beyond >1 year of age). During the initiation of theophylline therapy, caffeine-like adverse effects may transiently alter patient behavior, especially in school age children, but this response rarely persists. Initiation of theophylline therapy at a low dose with subsequent slow titration to a predetermined age-related maximum dose will significantly reduce the frequency of these transient adverse effects (see DOSAGE AND ADMINISTRATION , Table V ). In a small percentage of patients (<3% of children and <10% of adults) the caffeine-like adverse effects persist during maintenance therapy, even at peak serum theophylline concentrations within the therapeutic range (i.e., 10 to 20 mcg/mL). Dosage reduction may alleviate the caffeine-like adverse effects in these patients, however, persistent adverse effects should result in a reevaluation of the need for continued theophylline therapy and the potential therapeutic benefit of alternative treatment. Other adverse reactions that have been reported at serum theophylline concentrations <20 mcg/mL include diarrhea, irritability, restlessness, fine skeletal muscle tremors, and transient diuresis. In patients with hypoxia secondary to COPD, multifocal atrial tachycardia and flutter have been reported at serum theophylline concentrations ≥15 mcg/mL. There have been a few isolated reports of seizures at serum theophylline concentrations <20 mcg/mL in patients with an underlying neurological disease or in elderly patients. The occurrence of seizures in elderly patients with serum theophylline concentrations <20 mcg/mL may be secondary to decreased protein binding resulting in a larger proportion of the total serum theophylline concentration in the pharmacologically active unbound form. …"},{"title":"Drug interaction","body":"Adding a drug that inhibits theophylline metabolism (e.g., cimetidine, erythromycin, tacrine) or stopping a concurrently administered drug that enhances theophylline metabolism (e.g., carbamazepine, rifampin). (See PRECAUTIONS , Drug Interactions , Table II ). Drug Interactions Theophylline interacts with a wide variety of drugs. The interaction may be pharmacodynamic, i.e., alterations in the therapeutic response to theophylline or another drug or occurrence of adverse effects without a change in serum theophylline concentration. More frequently, however, the interaction is pharmacokinetic, i.e., the rate of theophylline clearance is altered by another drug resulting in increased or decreased serum theophylline concentrations. Theophylline only rarely alters the pharmacokinetics of other drugs. The drugs listed in Table II have the potential to produce clinically significant pharmacodynamic or pharmacokinetic interactions with theophylline. The information in the “Effect” column of Table II assumes that the interacting drug is being added to a steady-state theophylline regimen. If theophylline is being initiated in a patient who is already taking a drug that inhibits theophylline clearance (e.g., cimetidine, erythromycin), the dose of theophylline required to achieve a therapeutic serum theophylline concentration will be smaller. Conversely, if theophylline is being initiated in a patient who is already taking a drug that enhances theophylline clearance (e.g., rifampin), the dose of theophylline required to achieve a therapeutic serum theophylline concentration will be larger. Discontinuation of a concomitant drug that increases theophylline clearance will result in accumulation of theophylline to potentially toxic levels, unless the theophylline dose is appropriately reduced. Discontinuation of a concomitant drug that inhibits theophylline clearance will result in decreased serum theophylline concentrations, unless the theophylline dose is appropriately increased. The drugs listed in Table III have either been documented not to interact with theophylline or do not produce a clinically significant interaction (i.e., <15% change in theophylline clearance). The listing of drugs in Tables II and III are current as of February 9, 1995. New interactions are continuously being reported for theophylline, especially with new chemical entities. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Teratogenic Effects: Category C In studies in which pregnant mice, rats and rabbits were dosed during the period of organogenesis, theophylline produced teratogenic effects. In studies with mice, a single intraperitoneal dose at and above 100 mg/kg (approximately equal to the maximum recommended oral dose for adults on a mg/m 2 basis) during organogenesis produced cleft palate and digital abnormalities. Micromelia, micrognathia, clubfoot, subcutaneous hematoma, open eyelids, and embryolethality were observed at doses that are approximately 2 times the maximum recommended oral dose for adults on a mg/m 2 basis. In a study with rats dosed from conception through organogenesis, an oral dose of 150 mg/kg/day (approximately 2 times the maximum recommended oral dose for adults on a mg/m 2 basis) produced digital abnormalities. Embryolethality was observed with a subcutaneous dose of 200 mg/kg/day (approximately 4 times the maximum recommended oral dose for adults on a mg/m 2 basis). In a study in which pregnant rabbits were dosed throughout organogenesis, an intravenous dose of 60 mg/kg/day (approximately 2 times the maximum recommended oral dose for adults on a mg/m 2 basis), which caused the death of one doe and clinical signs in others, produced cleft palate and was embryolethal. Doses at and above 15 mg/kg/day (less than the maximum recommended oral dose for adults on a mg/m 2 basis) increased the incidence of skeletal variations. There are no adequate and well-controlled studies in pregnant women. Theophylline should be used during pregnancy only if the potential benefit justifies the potential risk to the fetus. Theophylline is excreted into breast milk and may cause irritability or other signs of mild toxicity in nursing human infants. The concentration of theophylline in breast milk is about equivalent to the maternal serum concentration. An infant ingesting a liter of breast milk containing 10 to 20 mcg/mL of theophylline per day is likely to receive 10 to 20 mg of theophylline per day. Serious adverse effects in the infant are unlikely unless the mother has toxic serum theophylline concentrations. Theophylline is safe and effective for the approved indications in pediatric patients. The maintenance dose of theophylline must be selected with caution in pediatric patients since the rate of theophylline clearance is highly variable across the pediatric age range (see CLINICAL PHARMACOLOGY , Table I , WARNINGS , and DOSAGE AND ADMINISTRATION , Table V ). …"},{"title":"การได้รับยาเกินขนาด","body":"General The chronicity and pattern of theophylline overdosage significantly influences clinical manifestations of toxicity, management and outcome. There are two common presentations: (1) acute overdose , i.e., ingestion of a single large excessive dose (>10 mg/kg), as occurs in the context of an attempted suicide or isolated medication error, and (2) chronic overdosage , i.e., ingestion of repeated doses that are excessive for the patient’s rate of theophylline clearance. The most common causes of chronic theophylline overdosage include patient or caregiver error in dosing, healthcare professional prescribing of an excessive dose or a normal dose in the presence of factors known to decrease the rate of theophylline clearance, and increasing the dose in response to an exacerbation of symptoms without first measuring the serum theophylline concentration to determine whether a dose increase is safe. Severe toxicity from theophylline overdose is a relatively rare event. In one health maintenance organization, the frequency of hospital admissions for chronic overdosage of theophylline was about 1 per 1000 person-years exposure. In another study, among 6000 blood samples obtained for measurement of serum theophylline concentration, for any reason, from patients treated in an emergency department, 7% were in the 20 to 30 mcg/mL range and 3% were >30 mcg/mL. Approximately two-thirds of the patients with serum theophylline concentrations in the 20 to 30 mcg/mL range had one or more manifestations of toxicity while >90% of patients with serum theophylline concentrations >30 mcg/mL were clinically intoxicated. Similarly, in other reports, serious toxicity from theophylline is seen principally at serum concentrations >30 mcg/mL. Several studies have described the clinical manifestations of theophylline overdose and attempted to determine the factors that predict life-threatening toxicity. In general, patients who experience an acute overdose are less likely to experience seizures than patients who have experienced a chronic overdosage, unless the peak serum theophylline concentration is >100 mcg/mL. After a chronic overdosage, generalized seizures, life-threatening cardiac arrhythmias, and death may occur at serum theophylline concentrations >30 mcg/mL. …"},{"title":"การเก็บรักษา","body":"Store at 25°C (77°F); excursions permitted between 15°C to 30°C (59°F to 86°F). Dispense in a tight, light-resistant container. Distributed by: Glenmark Pharmaceuticals Inc., USA Elmwood Park, NJ 07407 Questions? 1 (888) 721-7115 www.glenmarkpharma-us.com August 2025 logo"}]},
{"key":"triamcinolone acetonide|DENTAL","generic":"triamcinolone acetonide","route":"DENTAL","brand":null,"title":"Triamcinolone Acetonide","set_id":"2548307e-8d36-4a63-862b-f2af7856104e","effective":"20251001","sections":[{"title":"ข้อบ่งใช้","body":"Triamcinolone Acetonide Dental Paste USP, 0.1% is indicated for adjunctive treatment and for the temporary relief of symptoms associated with oral inflammatory lesions and ulcerative lesions resulting from trauma."},{"title":"ขนาดยาและวิธีใช้","body":"Press a small dab (about 1/4 inch) to the lesion until a thin film develops. A larger quantity may be required for coverage of some lesions. For optimal results use only enough to coat the lesion with a thin film. Do not rub in. Attempting to spread this preparation may result in granular, gritty sensation and cause it to crumble. After application, however, a smooth, slippery film develops. The preparation should be applied at bedtime to permit steroid contact with the lesion throughout the night. Depending on the severity of symptoms, it may be necessary to apply the preparation two or three times a day, preferably after meals. If significant repair or regeneration has not occurred in seven days, further investigation is advisable."},{"title":"ข้อห้ามใช้","body":"Triamcinolone acetonide dental paste is contraindicated in those patients with a history of hypersensitivity to any of the components of the preparation; it is also contraindicated in the presence of fungal, viral, or bacterial infections of the mouth or throat."},{"title":"คำเตือนและข้อควรระวัง","body":"General Triamcinolone acetonide dental paste may cause local adverse reactions. If irritation develops, triamcinolone acetonide dental paste should be discontinued and appropriate therapy instituted. Allergic contact sensitization with corticosteroids is usually diagnosed by observing failure to heal rather than noting a clinical exacerbation as with most topical products not containing corticosteroids. Such an observation should be corroborated with appropriate diagnostic patch testing. If concomitant mucosal infections are present or develop, an appropriate antifungal or antibacterial agent should be used. If a favorable response does not occur promptly, use of triamcinolone acetonide dental paste should be discontinued until the infection has been adequately controlled. If significant regeneration or repair of oral tissues has not occurred in seven days, additional investigation into the etiology of the oral lesion is advised. Systemic absorption of topical corticosteroids has produced reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, manifestations of Cushing's syndrome, hyperglycemia, glucosuria, and other adverse effects known to occur with parenterally-administered steroid preparations; therefore, it may be advisable to periodically evaluate patients on prolonged therapy with corticosteroid-containing dental pastes for evidence of HPA axis suppression (see PRECAUTIONS, Laboratory Tests ). If HPA axis suppression is noted, an attempt should be made to withdraw the drug or to reduce the frequency of application. Recovery of HPA axis function is generally prompt and complete upon discontinuation of therapy. Information for the Patient Patients using topical corticosteroids should receive the following information and instructions: 1. This medication is to be used as directed by the physician or dentist. It is for oral use only; it is not intended for ophthalmic or dermatological use. 2. Patients should be advised not to use this medication for any disorder other than for which it was prescribed. 3. Patients should report any signs of adverse reactions. 4. As with other corticosteroids, therapy should be discontinued when control is achieved. If no improvement is seen within 2 weeks, contact the physician or dentist. Laboratory Tests A urinary free cortisol test and ACTH stimulation test may be helpful in evaluating HPA axis suppression. …"},{"title":"อาการไม่พึงประสงค์","body":"The following local adverse reactions may occur with corticosteroid-containing dental pastes: burning, itching, irritation, dryness, blistering or peeling not present prior to therapy, perioral dermatitis, allergic contact dermatitis, maceration of the oral mucosa, secondary infection, and atrophy of the oral mucosa. Also, see PRECAUTIONS for potential effects of systemic absorption. To report SUSPECTED ADVERSE REACTINS, contact Sun Pharmaceutical Industries, Inc., at 1-866-923-4914 or FDA at 1-800-FDA-1088 or www.fda.gov/medwatch."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Category C Teratogenic effects Triamcinolone acetonide has been shown to induce teratogenic effects in several species. In mice and rabbits, triamcinolone acetonide induced an increased incidence of cleft palate at dosages of approximately 120 µg/kg/day and 24 µg/kg/day, respectively (approximately 12 times and 10 times the amount in a typical daily human dose of triamcinolone acetonide dental paste when compared following normalization of the data on the basis of body surface area estimates, respectively). In monkeys, triamcinolone acetonide induced cranial skeletal malformations at the lowest dosage studied (500 µg/kg/day), which was approximately 200 times the amount in a typical daily human dose of triamcinolone acetonide dental paste when compared following normalization of the data on the basis of body surface area estimates. There are no adequate and well-controlled studies in pregnant women. However, a retrospective analysis of birth defects among children born to mothers that used drugs of the same class as triamcinolone acetonide dental paste (corticosteroids) during pregnancy found an approximately 3 times increased incidence of cleft palate. Triamcinolone acetonide dental paste should be used during pregnancy only if the potential benefit justifies the potential risk to the fetus. It is not known whether oral application of corticosteroids could result in sufficient systemic absorption to produce detectable quantities in breast milk. Caution should be exercised when corticosteroid-containing dental pastes are prescribed for a nursing woman. The safety and efficacy of triamcinolone acetonide dental paste in children is unknown. Pediatric patients may demonstrate greater susceptibility to topical corticosteroid-induced HPA axis suppression and Cushing's Syndrome than mature patients because of a larger skin surface area to body weight ratio. Administration of corticosteroid-containing dental pastes to children should be limited to the least amount compatible with an effective therapeutic regimen. Chronic corticosteroid therapy may interfere with the growth and development of children. Clinical studies of triamcinolone acetonide dental paste did not include sufficient numbers of subjects age 65 and older to determine whether they respond differently from younger subjects. Other reported clinical experience has not identified differences in responses between the elderly and younger patients."},{"title":"การเก็บรักษา","body":"Storage Keep tightly closed. Store at 20° to 25°C (68° to 77°F) [see USP Controlled Room Temperature]."}]},
{"key":"triamcinolone acetonide|TOPICAL","generic":"triamcinolone acetonide","route":"TOPICAL","brand":null,"title":"Triamcinolone Acetonide","set_id":"0844a8f0-116d-40f6-8462-cccd6bcefc8a","effective":"20260327","sections":[{"title":"ข้อบ่งใช้","body":"Topical corticosteroids are indicated for the relief of the inflammatory and pruritic manifestations of corticosteroid-responsive dermatoses."},{"title":"ขนาดยาและวิธีใช้","body":"Topical corticosteroids are generally applied to the affected area as a thin film from two to four times daily depending on the severity of the condition. Occlusive dressing may be used for the management of psoriasis or recalcitrant conditions. If an infection develops, the use of occlusive dressing should be discontinued and appropriate antimicrobial therapy instituted."},{"title":"ข้อห้ามใช้","body":"Topical corticosteroids are contraindicated in those patients with a history of hypersensitivity to any of the components of the preparations."},{"title":"คำเตือนและข้อควรระวัง","body":"General - Systemic absorption of topical corticosteroids has produced reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, manifestations of Cushing’s syndrome, hyperglycemia, and glucosuria in some patients. Conditions which augment systemic absorption include the application of the more potent steroids, use over large surface areas, prolonged use, and the addition of occlusive dressings. Therefore, patients receiving a large dose of a potent topical steroid applied to a large surface area or under an occlusive dressing should be evaluated periodically for evidence of HPA axis suppression by using the urinary free cortisol and ACTH stimulation tests. If HPA axis suppression is noted, an attempt should be made to withdraw the drug, to reduce the frequency of application, or to substitute a less potent steroid. Recovery of HPA axis function is generally prompt and complete upon discontinuation of the drug. Infrequently, signs and symptoms of steroid withdrawal may occur, requiring supplemental systemic corticosteroids. Children may absorb proportionally larger amounts of topical corticosteroids and thus be more susceptible to systemic toxicity (see PRECAUTIONS-Pediatric Use ). If irritation develops, topical corticosteroids should be discontinued and appropriate therapy instituted. In the presence of dermatological infections, the use of an appropriate antifungal or antibacterial agent should be instituted. If a favorable response does not occur promptly, the corticosteroid should be discontinued until the infection has been adequately controlled. Information for Patients Patients using topical corticosteroids should receive the following information and instructions: 1. This medication is to be used as directed by the physician. It is for external use only. Avoid contact with the eyes. 2. Patients should be advised not to use this medication for any disorder other than for which it was prescribed. 3. The treated skin area should not be bandaged or otherwise covered or wrapped as to be occlusive unless directed by the physician. 4. Patients should report any signs of local adverse reactions especially under occlusive dressing. 5. Parents of pediatric patients should be advised not to use tight-fitting diapers or plastic pants on a child being treated in the diaper area, as these garments may constitute occlusive dressings. …"},{"title":"อาการไม่พึงประสงค์","body":"The following local adverse reactions are reported infrequently with topical corticosteroids, but may occur more frequently with the use of occlusive dressings. These reactions are listed in an approximate decreasing order of occurrence: burning, itching, irritation, dryness, folliculitis, hypertrichosis, acneiform eruptions, hypopigmentation, perioral dermatitis, allergic contact dermatitis, maceration of the skin, secondary infection, skin atrophy, striae and miliaria."},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Teratogenic Effects: Pregnancy Category C - Corticosteroids are generally teratogenic in laboratory animals when administered systemically at relatively low dosage levels. The more potent corticosteroids have been shown to be teratogenic after dermal application in laboratory animals. There are no adequate and well-controlled studies in pregnant women on the teratogenic effects from topically applied corticosteroids. Therefore, topical corticosteroids should be used during pregnancy only if the potential benefit justifies the potential risk to the fetus. Drugs of this class should not be used extensively on pregnant patients, in large amounts, or for prolonged periods of time. - It is not known whether topical administration of corticosteroids could result in sufficient systemic absorption to produce detectable quantities in breast milk. Systemically administered corticosteroids are secreted into breast milk in quantities not likely to have a deleterious effect on the infant. Nevertheless, caution should be exercised when topical corticosteroids are administered to a nursing woman. - Pediatric patients may demonstrate greater susceptibility to topical corticosteroid-induced HPA axis suppression and Cushing’s syndrome than mature patients because of a larger skin surface area to body weight ratio. Hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing’s syndrome, and intracranial hypertension have been reported in children receiving topical corticosteroids. Manifestations of adrenal suppression in children include linear growth retardation, delayed weight gain, low plasma cortisol levels, and absence of response to ACTH stimulation. Manifestations of intracranial hypertension include bulging fontanelles, headaches, and bilateral papilledema. Administration of topical corticosteroids to children should be limited to the least amount compatible with an effective therapeutic regimen. Chronic corticosteroid therapy may interfere with the growth and development of children."},{"title":"การได้รับยาเกินขนาด","body":"Topically applied corticosteroids can be absorbed in sufficient amounts to produce systemic effects (see PRECAUTIONS )."},{"title":"การเก็บรักษา","body":"STORAGE Store at 20-25°C (68-77°F) [see USP Controlled Room Temperature]. Manufactured By Padagis ® Yeruham, Israel Distributed By Padagis ® Allegan, MI 49010 • www.padagis.com Rev 01-23 2N700 RC PH1"}]},
{"key":"verapamil hydrochloride|ORAL","generic":"verapamil hydrochloride","route":"ORAL","brand":null,"title":"VERAPAMIL HYDROCHLORIDE","set_id":"ed182ebe-8299-4680-9dea-ef79d30db683","effective":"20260818","sections":[{"title":"ข้อบ่งใช้","body":"Verapamil hydrochloride extended-release tablets is indicated for the treatment of hypertension, to lower blood pressure. Lowering blood pressure reduces the risk of fatal and nonfatal cardiovascular events, primarily strokes and myocardial infarctions. These benefits have been seen in controlled trials of antihypertensive drugs from a wide variety of pharmacologic classes including this drug. Control of high blood pressure should be part of comprehensive cardiovascular risk management, including, as appropriate, lipid control, diabetes management, antithrombotic therapy, smoking cessation, exercise, and limited sodium intake. Many patients will require more than one drug to achieve blood pressure goals. For specific advice on goals and management, see published guidelines, such as those of the National High Blood Pressure Education Program's Joint National Committee on Prevention, Detection, Evaluation, and Treatment of High Blood Pressure (JNC). Numerous antihypertensive drugs, from a variety of pharmacologic classes and with different mechanisms of action, have been shown in randomized controlled trials to reduce cardiovascular morbidity and mortality, and it can be concluded that it is blood pressure reduction, and not some other pharmacologic property of the drugs, that is largely responsible for those benefits. The largest and most consistent cardiovascular outcome benefit has been a reduction in the risk of stroke, but reductions in myocardial infarction and cardiovascular mortality also have been seen regularly. Elevated systolic or diastolic pressure causes increased cardiovascular risk, and the absolute risk increase per mmHg is greater at higher blood pressures, so that even modest reductions of severe hypertension can provide substantial benefit. Relative risk reduction from blood pressure reduction is similar across populations with varying absolute risk, so the absolute benefit is greater in patients who are at higher risk independent of their hypertension (for example, patients with diabetes or hyperlipidemia), and such patients would be expected to benefit from more aggressive treatment to a lower blood pressure goal. Some antihypertensive drugs have smaller blood pressure effects (as monotherapy) in black patients, and many antihypertensive drugs have additional approved indications and effects (e.g., on angina, heart failure, or diabetic kidney disease). These considerations may guide selection of therapy."},{"title":"ขนาดยาและวิธีใช้","body":"Essential hypertension: The dose of verapamil hydrochloride extended-release tablets should be individualized by titration and the drug should be administered with food. Initiate therapy with 180 mg of sustained-release verapamil HCl, verapamil hydrochloride extended-release tablets, given in the morning. Lower initial doses of 120 mg a day may be warranted in patients who may have an increased response to verapamil (eg, the elderly or small people). Upward titration should be based on therapeutic efficacy and safety evaluated weekly and approximately 24 hours after the previous dose. The antihypertensive effects of verapamil hydrochloride extended-release tablets are evident within the first week of therapy. If adequate response is not obtained with 180 mg of verapamil hydrochloride extended-release tablets, the dose may be titrated upward in the following manner: a) 240 mg each morning, b) 180 mg each morning plus 180 mg each evening; or 240 mg each morning plus 120 mg each evening, c) 240 mg every 12 hours When switching from immediate-release verapamil hydrochloride tablets to verapamil hydrochloride extended-release tablets, the total daily dose in milligrams may remain the same."},{"title":"ข้อห้ามใช้","body":"Verapamil HCl extended-release tablets are contraindicated in: 1.Severe left ventricular dysfunction (see WARNINGS ) 2.Hypotension (systolic pressure less than 90 mm Hg) or cardiogenic shock 3.Sick sinus syndrome (except in patients with a functioning artificial ventricular pacemaker) 4.Second- or third-degree AV block (except in patients with a functioning artificial ventricular pacemaker) 5.Patients with atrial flutter or atrial fibrillation and an accessory bypass tract (eg, Wolff-Parkinson-White, Lown-Ganong-Levine syndromes) (see WARNINGS ) 6.Patients with known hypersensitivity to verapamil hydrochloride"},{"title":"คำเตือนและข้อควรระวัง","body":"Heart failure: Verapamil has a negative inotropic effect, which in most patients is compensated by its afterload reduction (decreased systemic vascular resistance) properties without a net impairment of ventricular performance. In clinical experience with 4,954 patients, 87 (1.8%) developed congestive heart failure or pulmonary edema. Verapamil should be avoided in patients with severe left ventricular dysfunction (eg, ejection fraction less than 30%) or moderate to severe symptoms of cardiac failure and in patients with any degree of ventricular dysfunction if they are receiving a beta-adrenergic blocker (see PRECAUTIONS , Drug interactions ). Patients with milder ventricular dysfunction should, if possible, be controlled with optimum doses of digitalis and/or diuretics before verapamil treatment. (Note interactions with digoxin under PRECAUTIONS ) Hypotension: Occasionally, the pharmacologic action of verapamil may produce a decrease in blood pressure below normal levels, which may result in dizziness or symptomatic hypotension. The incidence of hypotension observed in 4,954 patients enrolled in clinical trials was 2.5%. In hypertensive patients, decreases in blood pressure below normal are unusual. Tilt-table testing (60 degrees) was not able to induce orthostatic hypotension. Elevated liver enzymes: Elevations of transaminases with and without concomitant elevations in alkaline phosphatase and bilirubin have been reported. Such elevations have sometimes been transient and may disappear even in the face of continued verapamil treatment. Several cases of hepatocellular injury related to verapamil have been proven by rechallenge; half of these had clinical symptoms (malaise, fever, and/or right upper quadrant pain) in addition to elevation of SGOT, SGPT, and alkaline phosphatase. Periodic monitoring of liver function in patients receiving verapamil is therefore prudent. Accessory bypass tract (Wolff-Parkinson-White or Lown-Ganong-Levine): Some patients with paroxysmal and/or chronic atrial fibrillation or atrial flutter and a coexisting accessory AV pathway have developed increased antegrade conduction across the accessory pathway bypassing the AV node, producing a very rapid ventricular response or ventricular fibrillation after receiving intravenous verapamil (or digitalis). …"},{"title":"อาการไม่พึงประสงค์","body":"Serious adverse reactions are uncommon when verapamil therapy is initiated with upward dose titration within the recommended single and total daily dose. See WARNINGS for discussion of heart failure, hypotension, elevated liver enzymes, AV block, and rapid ventricular response. Reversible (upon discontinuation of verapamil) non-obstructive, paralytic ileus has been infrequently reported in association with the use of verapamil. The following reactions to orally administered verapamil occurred at rates greater than 1.0% or occurred at lower rates but appeared clearly drug-related in clinical trials in 4,954 patients: Constipation 7.3% Dyspnea 1.4% Dizziness 3.3% Bradycardia Nausea 2.7% (HR <50/min) 1.4% Hypotension 2.5% AV block Headache 2.2% (total 1°, 2°, 3°) 1.2% Edema 1.9% (2° and 3°) 0.8% CHF, Pulmonary Rash 1.2% edema 1.8% Flushing 0.6% Fatigue 1.7% Elevated liver enzymes (see WARNINGS ) In clinical trials related to the control of ventricular response in digitalized patients who had atrial fibrillation or flutter, ventricular rates below 50/min at rest occurred in 15% of patients and asymptomatic hypotension occurred in 5% of patients. The following reactions, reported in 1% or less of patients, occurred under conditions (open trials, marketing experience) where a causal relationship is uncertain; they are listed to alert the physician to a possible relationship: Cardiovascular: angina pectoris, atrioventricular dissociation, chest pain, claudication, myocardial infarction, palpitations, purpura (vasculitis), syncope. Digestive system: diarrhea, dry mouth, gastrointestinal distress, gingival hyperplasia. Hemic and lymphatic: ecchymosis or bruising. Nervous system: cerebrovascular accident, confusion, equilibrium disorders, insomnia, muscle cramps, paresthesia, psychotic symptoms, shakiness, somnolence. Skin: arthralgia and rash, exanthema, hair loss, hyperkeratosis, macules, sweating, urticaria, Stevens-Johnson syndrome, erythema multiforme. Special senses: blurred vision, tinnitus. Urogenital: gynecomastia, galactorrhea/hyperprolactinemia, increased urination, spotty menstruation, impotence. Treatment of acute cardiovascular adverse reactions: The frequency of cardiovascular adverse reactions that require therapy is rare; hence, experience with their treatment is limited. …"},{"title":"Drug interaction","body":"Cytochrome inducers/inhibitors: In vitro metabolic studies indicate that verapamil is metabolized by cytochrome P450 CYP3A4, CYP1A2, CYP2C8, CYP2C9, and CYP2C18. Clinically significant interactions have been reported with inhibitors of CYP3A4 (e.g., erythromycin, ritonavir) causing elevation of plasma levels of verapamil while inducers of CYP3A4 (e.g., rifampin) have caused a lowering of plasma levels of verapamil. HMG-CoA reductase inhibitors: The use of HMG-CoA reductase inhibitors that are CYP3A4 substrates in combination with verapamil has been associated with reports of myopathy/rhabdomyolysis. Co-administration of multiple doses of 10 mg of verapamil with 80 mg simvastatin resulted in exposure to simvastatin 2.5-fold that following simvastatin alone. Limit the dose of simvastatin in patients on verapamil to 10 mg daily. Limit the daily dose of lovastatin to 40 mg. Lower starting and maintenance doses of other CYP3A4 substrates (e.g., atorvastatin) may be required as verapamil may increase the plasma concentration of these drugs. Ivabradine: Concurrent use of verapamil increases exposure to ivabradine and may exacerbate bradycardia and conduction disturbances. Avoid co-administration of verapamil and ivabradine. Beta-blockers: Concomitant therapy with beta-adrenergic blockers and verapamil may result in additive negative effects on heart rate, atrioventricular conduction and/or cardiac contractility. The combination of sustained-release verapamil and beta-adrenergic blocking agents has not been studied. However, there have been reports of excessive bradycardia and AV block, including complete heart block, when the combination has been used for the treatment of hypertension. For hypertensive patients, the risks of combined therapy may outweigh the potential benefits. The combination should be used only with caution and close monitoring. Asymptomatic bradycardia (36 beats/min) with a wandering atrial pacemaker has been observed in a patient receiving concomitant timolol (a beta-adrenergic blocker) eyedrops and oral verapamil. A decrease in metoprolol and propranolol clearance has been observed when either drug is administered concomitantly with verapamil. A variable effect has been seen when verapamil and atenolol were given together. Digitalis: Clinical use of verapamil in digitalized patients has shown the combination to be well tolerated if digoxin doses are properly adjusted. …"},{"title":"การใช้ในหญิงตั้งครรภ์/ให้นมบุตร เด็ก ผู้สูงอายุ","body":"Reproduction studies have been performed in rabbits and rats at oral doses up to 1.5 (15 mg/kg/day) and 6 (60 mg/kg/day) times the human oral daily dose, respectively, and have revealed no evidence of teratogenicity. In the rat, however, this multiple of the human dose was embryocidal and retarded fetal growth and development, probably because of adverse maternal effects reflected in reduced weight gains of the dams. This oral dose has also been shown to cause hypotension in rats. There are no adequate and well-controlled studies in pregnant women. Because animal reproduction studies are not always predictive of human response, this drug should be used during pregnancy only if clearly needed. Verapamil crosses the placental barrier and can be detected in umbilical vein blood at delivery. Verapamil is excreted in human milk. Because of the potential for adverse reactions in nursing infants from verapamil, nursing should be discontinued while verapamil is administered. Safety and efficacy of verapamil hydrochloride extended-release tablets in pediatric patients below the age of 18 years have not been established."},{"title":"การได้รับยาเกินขนาด","body":"Overdose with verapamil may lead to pronounced hypotension, bradycardia, and conduction system abnormalities (eg, junctional rhythm with AV dissociation and high degree AV block, including asystole). Other symptoms secondary to hypoperfusion (eg, metabolic acidosis, hyperglycemia, hyperkalemia, renal dysfunction, and convulsions) may be evident. Treat all verapamil overdoses as serious and maintain observation for at least 48 hours (especially verapamil hydrochloride extended-release tablets), preferably under continuous hospital care. Delayed pharmacodynamic consequences may occur with the sustained-release formulation. Verapamil is known to decrease gastrointestinal transit time. In overdose, verapamil hydrochloride extended-release tablets have occasionally been reported to form concretions within the stomach or intestines. These concretions have not been visible on plain radiographs of the abdomen, and no medical means of gastrointestinal emptying is of proven efficacy in removing them. Endoscopy might reasonably be considered in cases of massive overdose when symptoms are unusually prolonged. Treatment of overdosage should be supportive. Beta-adrenergic stimulation or parenteral administration of calcium solutions may increase calcium ion flux across the slow channel and have been used effectively in treatment of deliberate overdosage with verapamil. Continued treatment with large doses of calcium may produce a response. In a few reported cases, overdose with calcium channel blockers that was initially refractory to atropine became more responsive to this treatment when the patients received large doses (close to 1 g/hr for more than 24 hr) of calcium chloride. Verapamil cannot be removed by hemodialysis. Clinically significant hypotensive reactions or high degree AV block should be treated with vasopressor agents or cardiac pacing, respectively. Asystole should be handled by the usual measures including cardiopulmonary resuscitation."},{"title":"การเก็บรักษา","body":"Storage Store at 20° to 25°C (68° to 77°F); excursions permitted between 15° to 30°C (59° to 86°F) [See USP Controlled Room Temperature] and protect from light and moisture. Dispense in tight, light-resistant containers."}]}
